window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_001"]={"n":"屈大均","dyn":"清","poems":[{"t":"天边","f":"七言绝句","c":["天边明月迥含霜，夜夜哀笳怨望乡。","一片愁心与鸿雁，秋风吹不到衡阳。"]},{"t":"两过三峡桥上作 其二","f":"七言绝句","c":["二十四潭争一桥，惊泉喷薄几时消。","一山瀑布归三峡，小小天风作海潮。"]},{"t":"云州秋望 其一","f":"五言律诗","c":["白草黄羊外，空闻觱篥哀。","遥寻苏武庙，不上李陵台。","风助群鹰击，云随万马来。","关前无数柳，一夜落龙堆。"]},{"t":"壬戌清明作","f":"七言律诗","c":["朝作轻寒暮作阴，愁中不觉已春深。","落花有泪因风雨，啼鸟无情自古今。","故国江山徒梦寐，中华人物又销沉。","龙蛇四海归无所，寒食年年怆客心。"]},{"t":"江皋 其四","f":"五言律诗","c":["翠微春更湿，烟雨欲无山。","白鹭一溪影，桃花何处湾。","渔村疏竹外，古渡夕阳间。","田父不相识，相随谷口还。"]},{"t":"秣陵","f":"五言律诗","c":["牛首开天阙，龙冈抱帝宫。","六朝春草里，万井落花中。","访旧乌衣少，听歌《玉树》空。","如何亡国恨，尽在大江东。"]},{"t":"读陈胜传","f":"五言律诗","c":["闾左称雄日，渔阳适戍人。","王侯宁有种，竿木足亡秦。","大义呼豪杰，先声仗鬼神。","驱除功第一，汉将可谁伦。"]},{"t":"登罗浮绝顶奉同蒋王二大夫作","f":"五言古诗","c":["霃霃太古云，至今未开辟。","山气日汹涌，随风洒精液。","触石生洪波，微茫在咫尺。","登山若浮海，舟航即轻策。","浮山复浮去，与罗万里隔。","仅馀玉女峰，娟娟在肘腋。","蓬莱无根蒂，左股长为客。","铁桥苦拘系，峰峰合体魄。","一气胶漆之，洞天在肝膈。","雷风吐噏时，氤氲相损益。","峨峨在虚无，荡踏难留迹。","如何太华山，乃为巨灵擘。","便道通句曲，大天有阡陌。","玉笥一南窍，日月暗相射。","朱明本火府，草木多纯赤。","朱竹含葳蕤，红翠美毛翮。","南禺亦丹穴，凤族以千百。","口衔芙莲花，纷纷堕瑶席。","珠尾若扬麾，往来拂巾舄。","麻姑何秀峙，散发至腰脊。","上下飞峰间，不肯相扶掖。","筋力尽青冥，渐与空天迫。","微躯若鸿毛，顺风思一掷。","衫袖即飙车，不用浮丘伯。","神明自鼓舞，鸾鹤惟所择。","便携二大夫，八极恣挥斥。","神仙虽惝恍，此中有窟宅。","真道苦无言，与天日相索。","聪明乃尘垢，陶铸有微责。","虽复游无穷，亦自悲人役。","神山有离合，依依且朝夕。","鳖首或浮沉，广大日以积。","弥缝费造化，随波恐流易。","分水一泉源，自天通地脉。","瀑布纵横飞，与海相潮汐。","天鸡一咿喔，扶桑已半白。","海日长三丈，玄黄始一隙。","光明未丽天，外体己赫赫。","摇荡二石楼，烧空如琥珀。","生长旸谷傍，郁仪日亲炙。","中夜已寅宾，导引成肥硕。","咸池灼欲焦，沧凉吾自适。","一下曜真台，人间愁踧踖。","百虑生黄埃，世务婴繁剧。","三山居水下，船交苦风逆。","斋去童男女，三千良可惜。","罗浮即方丈，甘心自古昔。","南岳一佐命，仙卿此注籍。","大夫代天工，于此宜区画。","虽无封禅书，名山望润泽。"]},{"t":"长亭怨慢","f":"古风","c":["记烧烛、雁门高处。","积雪封城，冻云迷路。","添尽香煤，紫貂相拥、夜深语。","苦寒如许，难和尔、凄凉句。","一片望乡愁，饮不醉，垆头驼乳。","无处，问长城旧主，但见武灵遗墓。","沙飞似箭，乱穿向，草中狐兔。","那能使、口北关南、更重作，并州门户。","且莫吊沙场，收拾秦弓归去。"]},{"t":"念奴娇 秣陵吊古","f":"古风","c":["萧条如此，更何须、苦忆江南佳丽。","花柳何曾迷六代，只为春光能醉。","玉笛风朝，金笳霜夕，吹得天憔悴。","秦淮波浅，忍含如此清泪。","任尔燕子无情，飞归故国，又怎忘兴替。","虎踞龙盘那得久，莫又苍苍王气。","灵谷梅花，蒋山松树，未识何年岁。","石人犹在，问君多少能记。"]},{"t":"浣溪沙","f":"七言古诗","c":["一片花含一片愁。","愁随江水不东流。","飞飞长傍景阳楼。","六代只馀芳草在，三园空有乳莺留。","白门容易白人头。"]},{"t":"浣溪沙 杜鹃","f":"七言古诗","c":["血洒春山尽作花。","花残人影未还家。","声声只是为天涯。","有恨朱楼当凤阙，无穷青冢在龙沙。","催归不得恨琵琶。"]},{"t":"梦江南 六首 其一","f":"古风","c":["悲落叶，叶叶落当春。","岁岁叶飞还有叶，年年人去更无人。","红带泪痕新。"]},{"t":"梦江南 六首 其二","f":"古风","c":["悲落叶，叶落绝归期。","纵使归来花满树，新枝不是旧时枝。","且逐水流迟。"]},{"t":"梦江南 六首 其六","f":"古风","c":["红茉莉，穿作一花梳。","金缕抽残蝴蝶茧，钗头立尽凤凰雏。","肯忆故人姝。"]},{"t":"紫萸香慢 送雁","f":"古风","c":["恨沙蓬、偏随人转，更怜雾柳难青。","问征鸿南向，几时暖，返龙庭。","正有无边烟雪，与鲜飙千里，送度长城。","向并门少待，白首牧羝人，正海上，手携李卿。","秋声。","宿定还惊。","愁里月、不分明。","又哀笳四起，衣砧断续，终夜伤情。","跨羊小儿争射，恁能到、白蘋汀。","尽长天、遍排人字，逆风飞去，毛羽随处飘零，书寄未成。"]},{"t":"虞美人","f":"古风","c":["无风亦向朱栏舞，情为君王苦。","乌江不渡为红颜。","忍使香魂无主独东还。","春含古血看犹暖。","巧作红深浅。","花前休唱楚人歌，恐惹英雄又唤奈虞何。"]},{"t":"潇湘神 零陵作 三首 其三","f":"古风","c":["潇水深，湘水深。","双双流水逐臣心。","潇水不如湘水好，将愁送去洞庭阴。"]},{"t":"潇湘神 零陵作 三首 其一","f":"古风","c":["潇水流，湘水流，三闾愁接二妃愁。","潇碧湘蓝虽两色，鸳鸯总作一天秋。"]},{"t":"潇湘神 零陵作 三首 其二","f":"古风","c":["潇水长，湘水长。","三湘最苦是潇湘。","无限泪痕斑竹上，幽兰更作二妃香。"]},{"t":"满庭芳 满城惜别","f":"古风","c":["金粟堆边，冰蒲水畔，紫骝迢递迎来。","月中惊见，光艳似云开。","桑落沾唇半醉，将长笛，弄向秦台。","天明去，挥鞭岸曲，愁杀渡人催。","徘徊。","空叹惜，桃花易嫁，凤子难媒。","和香雨氤氲，飞作尘埃。","坠井银瓶永绝，谁复取、仙液盈杯。","应知尔，三春绣阁，幽寂委苍苔。"]},{"t":"浪淘沙 春草","f":"古风","c":["嫩绿似罗裙。","寸寸销魂。","春心抽尽为王孙。","不分东风吹渐老，色映黄昏。","蝴蝶不留痕。","飞过烟村。","红藏几点落花魂。","雨过苔边人不见，湿欲生云。"]},{"t":"一落索","f":"古风","c":["杜宇催春从汝。","莫催人去。","人留即是好春留，更一任、风和雨。","怕见游丝飞絮。","为伊无主。","落花争似泪花红，只滴在、分襟处。"]},{"t":"离亭燕","f":"古风","c":["渐到鹧鸪多处。","愁作一天烟雨。","芳草可怜千万里，长共夕阳无主。","且莫返乡关，已有断魂飞去。","云际片帆难驻。","江上一竿谁许。","空妒白鸥来复往，恁得分他毛羽。","掩泪似春山，终日濛濛洲渚。"]},{"t":"调笑令 四首 其二","f":"古风","c":["芳草。","芳草。","生向江南太蚤。","连天一片春愁。","不管王孙泪流。","流泪。","流泪。","点点桃花又坠。"]},{"t":"江城梅花引","f":"古风","c":["黄花和我满头霜。","怕重阳。","又重阳。","不分早梅，还与斗寒香。","老去看花如雾里，被花恼，一枝枝，总断肠。","断肠。","断肠。","苦参商。","夜已长。","天已凉。","一叶一叶，落不尽、悲似潇湘。","那得罗浮、清梦到兰房。","明月笑人眠太早，飞去也，影徘徊，尚半床。"]},{"t":"过大梁作","f":"五言古诗","c":["浮云无归心，黄河无安流。","神鱼腾紫雾，苍鹰击高秋。","类此雄豪士，滔滔事远游。","远游欲何之，驱马登商丘。","朝与侯嬴饮，暮为朱亥留。","悲风起梁园，白草鸣飕飕。","挥鞭控鸣镝，龙骑如星流。","超山逐群鱼，穿云落两鹜。","归来宴吹台，酣舞双吴钩。","惊沙翳白日，垂涕向神州。","徒怀匹夫谅，未报百王雠。","红颜渐欲变，岁月空悠悠。"]},{"t":"与诸兄弟饮射作","f":"五言古诗","c":["鲤鱼何盘盘，瓠叶何幡幡。","弟兄相燕饮，其乐如新昏。","户庭无外侮，弦歌有馀閒。","人生无几何，骨肉相好难。","兄友而弟恭，所以承亲欢。","亲欢承不足，张侯在中谷。","兄射中熊罴，弟射中鸿鹄。","鸿鹄比其翼，熊罴同其力。"]},{"t":"孤竹吟","f":"五言古诗","c":["我行踰万里，徬徨思故乡。","黄鹄虽失所，不从燕雀翔。","驾言登孤竹，东北望边疆。","惊沙如白雪，杀气为严霜。","游子一何微，落叶同飘飏。","独智世不容，接舆久徉狂。","神龙为蟭螟，白刃莫能伤。","大义劫天下，汤武诚不祥。","夷齐忧无臣，叩马空忼慷。","白日何昭昭，浮云复茫茫。","吁嗟命之衰，挥涕归首阳。"]},{"t":"古意 其一","f":"五言古诗","c":["妾有大秦珠，尝含明月姿。","明月亏有时，妾珠光不移。","朝悬妆镜台，暮系红罗衣。","君心不可照，持此委沙泥。","愿得青鸾鸟，衔将赠宓妃。"]},{"t":"答陈宛平 其一","f":"五言古诗","c":["与子结交初，有如天上月。","三五光未满，已忧蟾兔阙。","浮云不在多，蔽亏在毫发。","沐浴天河水，金波期不没。","君为启明东，我为长庚西。","与月相终始，黾勉至晨鸡。"]},{"t":"送从弟无极归里 其三","f":"五言古诗","c":["云中有二老，采薇何从容。","洞房隐青岩，卉木交蒙茏。","处幽含圣神，被我太古风。","我祖蹈云天，窈窕相追从。","《离骚》合经术，规谏心无穷。","子其玩微词，追琢为楚风。","谗邪譬云蜕，君子喻虬龙。","金相而玉质，惊采开童蒙。"]},{"t":"送从弟无极归里 其二","f":"五言古诗","c":["重华托神仙，解体升九疑。","离宫若云浮，欲陟无天梯。","垂衣接万灵，弃我独如遗。","茕茕在中野，熊罴鸣相追。","弟兄贵急难，骨肉无乖离。","子能禦外侮，羁旅吾何悲。","今朝途路穷，双凫忽分飞。","商飙吹白云，怅望徒沾衣。"]},{"t":"琵琶行赠蒲衣子","f":"古风","c":["王郎好音能琵琶，千态万恨归边沙。","明妃紫台作胡语，公主乌孙思汉家。","慷慨惟凭马上乐，凄凉岂必军中笳。","新声鼓出好词曲，三日一调劳红牙。","古词元人百杂剧，新曲《牡丹》兼《浣纱》。","伯龙红友供繁弄，酒酣一唱三咨嗟。","改调高弹飒风雨，攒点忽似更虾蟆。","手搊口歌声若一，丝肉粉飘如飞花。","小声吹裂漆筚篥，大声掺乱渔阳挝。","自矜琵琶与琴应，眩精骇耳非淫哇。","一一晖音合清浊，上腔下柱同整斜。","十指绝光若惊电，双袖奋影争流霞。","乱击空中白翎雀，横奔塞上拳毛騧。","毛血淋漓尽挥洒，又如胡汉相纷拿。","大雷小雷响四迸，天惊石破愁女娲。","儿女呢呢不得语，恩怨尔汝潜相加。","缓调平弦有时倦，掩抑奇态嫌■?。","联绵断续转呜咽，又如縆瑟悲瓠巴。","一激一昂真当泣，哀歌销尽情萌芽。","鹍弦石槽兼铁拨，翻嫌古法多喧哗。","逢君但乞《飞龙引》，发扬蹈厉除奸邪。","镇西更作《大道曲》，罗襦胡床临闉阇。","阮咸凄锵竹林下，风流岂似居琅琊。","我今烦冤神越散，《大招》须君为景差。","不然节奏尽传我，十调五调成豪奢。","一枚昨致惠文妇，槽用香楠连木瓜。","得曹左手裴右手，亦可持慰吾秦嘉。","琵琶弟子君多少，中有几人颜如荼。","枫香定移西楼女，鞋带可记杨家娃。","得君琵琶诸楔子，鼙婆旧谱宁足誇。","梳山音律此一种，教坊买断倾金车。","王郎王郎尔莫苦，埋忧国腹如丹砂。","天际真人既有此，北窗肢脚殊风华。"]},{"t":"王不庵作卧龙松歌为予寿诗以酬之","f":"七言古诗","c":["黄山山上多怪松，半生石笋半芙蓉。","芙蓉石笋亦松变，有一不变为卧龙。","龙本无形以神化，真形往往与松同。","龙之隐者但高卧，人不见龙见髯翁。","髯翁鳞甲多怒决，柯如苍铜枝屈铁。","引根十丈始作干，干虽千年似萌蘖。","霹雳横将偃盖倾，蛟螭争向轮囷结。","夜光有火出空心，日炙多膏流断节。","一枝一干一尺蠖，求信且复依岩穴。","山僧写图贻我看，王子作歌含凄咽。","尺寸得空自盘攫，纵横穿土苦羁绁。","峨峨千尺乃无势，幸因奇丑免摧折。","五鬣短短少波涛，声似风雷畜未泄。","苦心爱此一树怪，自少摩挲至大耋。","蹒跚尚有尊足存，支离乃是鬼神设。","臃肿何须规矩中，斧柯且喜薪蒸绝。","虽然久垫非泥蟠，撑出丹崖作遗孑。","石破天惊自小时，后凋凭尔存孤蘖。","本是轩皇昔所种，平泽至今乍明灭。","当年且战且学仙，霜根留得玄黄血。","灌溉颇用朱砂泉，滋润微凝太古雪。","浮丘无力治拘挛，容成有意引寥泬。","黄山诸松此最古，儿孙万万丹台列。","卧者天渊自高深，立者栋梁久颠蹶。","君指此松为予寿，意在不材能蹩躠。","蝼蚁频容蚀茯苓，藤萝一任为瓜瓞。","松黄落地成古苔，松子满天低可缀。","君在黄山亦一松，莫教化石存榾柮。","一松孤作老人峰，秦汉来封久不屑。","卧龙复有扰龙好，缭绕数峰出巀嵲。","一松飞作天生桥，一松倒生更奇谲。","烦君添作四松图，置我松间长用拙。"]},{"t":"摄山秋夕作","f":"五言律诗","c":["秋林无静树，叶落鸟频惊。","一夜疑风雨，不知山月生。","松门开积翠，潭水入空明。","渐觉天鸡晓，披衣念远征。"]},{"t":"太华作 其一","f":"五言律诗","c":["仙掌三峰立，天门半壁扃。","莲花围白帝，玉井出明星。","横度苍龙磴，高歌落雁亭。","河山襟带尽，两戒据天经。"]},{"t":"太华作 其二","f":"五言律诗","c":["昨夜闻长笛，依稀鸾凤音。","三峰吹落月，一半驻空林。","人道水帘里，玉姜时弄琴。","神仙不可接，怅望白云深。"]},{"t":"钓台","f":"五言律诗","c":["富春山万叠，雪映钓台青。","予若桐江月，长随汉客星。","寒猿吟石壁，白鹭落沙汀。","渔父频招手，回舟入杳冥。"]},{"t":"鲁连台","f":"五言律诗","c":["一笑无秦帝，飘然向澥东。","谁能排大难，不屑计奇功。","古戍三秋雁，高台万木风。","从来天下士，只在布衣中。"]},{"t":"自白下至槜李与诸子约游山阴","f":"五言律诗","c":["最恨秦淮柳，长条复短条。","秋风吹落叶，一夜别南朝。","范蠡湖边客，相将荡画桡。","言寻大禹穴，直渡浙江潮。"]},{"t":"人日衡阳道中","f":"五言律诗","c":["人日雪霏霏，孤舟上翠微。","帆随南岳转，雁背碧湘飞。","知己惟长剑，还家复短衣。","猿声如送客，薄暮更依依。"]},{"t":"汉口","f":"五言律诗","c":["汉口清秋夜，云霞寒亦稀。","新潮随月满，落叶带萤飞。","白首难孤往，青山欲早归。","凭谁报慈母，游子有寒衣。"]},{"t":"淮阴侯 其一","f":"五言律诗","c":["淮阴当未遇，一饭亦无才。","天欲王孙饿，人惭漂母哀。","钓鱼城下去，带剑市中来。","笑谓晨炊者，英雄被尔催。"]},{"t":"淮阴侯 其二","f":"五言律诗","c":["艰难惟一饭，天肯与王孙。","草昧多如此，英雄不忍言。","汉兴因妇女，臣节在壶飧。","谁分宫前草，离离是血痕。"]},{"t":"舟入新兴江将访柴子有作","f":"七言律诗","c":["不知江口水声分，舟入千岩只为君。","春尽林香犹作瘴，雨馀山气未成云。","白鱼捕处禽多翠，甘草衔时鹿有群。","咫尺松杉烟霭隔，一峰长啸万峰闻。"]},{"t":"山阴作","f":"七言绝句","c":["秋霜一夜凋榆柳，马上征夫最早寒。","边女不须歌入塞，故乡明月梦中看。"]},{"t":"秋夕黄陵作","f":"七言绝句","c":["秋夕江潭寐不成，林空乌鹊亦多惊。","风吹不尽潇湘叶，散作天边秋雨声。"]},{"t":"客雁门作","f":"七言绝句","c":["三年作客傍滹沱，听尽哀笳出塞歌。","白发不惊明镜满，秋霜只怨雁门多。"]},{"t":"柬赵子实 其六","f":"七言绝句","c":["双泪天山洒翠微，生憎鸿雁入关飞。","望乡空上昭君墓，一片牛羊共夕晖。"]},{"t":"江上望南岳 其二","f":"七言绝句","c":["五峰雪作九江水，回雁晴连岳麓云。","未到朱陵仙洞口，钟声已隔碧湘闻。"]},{"t":"放歌行为潘子寿","f":"七言古诗","c":["丈夫五十发未白，痛饮狂歌真可惜。","神仙富贵两蹉跎，徒作诸侯一宾客。","尉佗城南十月时，梅花开早菊花迟。","与君往往谈王霸，笑杀当垆娇女儿。","我在山中无素业，清高亦与屠沽接。","道成不肯居神仙，气使翻然作游侠。","英雄自古一浮云，求道应从鸾鹤群。","有金且买东方妾，有酒且醉信陵君。","纵心写意无不可，声色之中知是我。","天生我辈自长生，不似二豪为蜾裸。"]},{"t":"钟山 其一","f":"七言律诗","c":["高高双巘削屏风，紫翠晴飞万井中。","一自轩皇成宝鼎，遂开天阙作玄宫。","千秋龙虎归真主，六代烟花送狡童。","岁岁貂珰驰传至，樱桃春荐思无穷。"]},{"t":"钟山 其二","f":"七言律诗","c":["苍苍辇路但斜晖，月出衣冠事已非。","六代松楸辞玉殿，中峰阴雨见龙旂。","蛮奴小队呼鹰过，汉女春魂化燕归。","多少哀笳吹不散，五云犹绕御床飞。"]},{"t":"紫蒙","f":"七言律诗","c":["紫蒙近接黄花戍，黑水斜穿白草军。","一道渝关兼扼海，双峰碣石故干云。","天生飞将都无用，人是长城独不闻。","愁绝辽西征战后，两河燐火暮纷纷。"]},{"t":"秋夕别岑公","f":"五言绝句","c":["一片他乡月，秋光亦苦辛。","每从风雨后，来照别离人。"]},{"t":"子夜歌 其二","f":"五言绝句","c":["荧荧桃李花，薄命寄君掌。","河水虽东流，河鱼自西上。"]},{"t":"归风词 其一","f":"七言绝句","c":["南越轻绡似碧云，裁为飞燕御风裙。","中流舞罢将仙去，万岁千秋复就君。"]},{"t":"霍州道中","f":"七言绝句","c":["太岳青苍接太行，河汾襟带势何长。","白云冉冉随行客，春草茫茫入战场。"]},{"t":"咏怀 其一","f":"五言古诗","c":["至人握大象，长为天下君。","澄潭龙不见，嘘气成风云。","维彼蒲衣子，渊玄莫能伦。","朝隐泰山霞，暮游洪河津。","仁义乃蘧庐，逍遥葆其真。","春雷惊百卉，阊阖涣波鳞。","时哉无与言，天倪一何神。"]},{"t":"咏怀 其二","f":"五言古诗","c":["猿猴依杞楠，后羿不能射。","至人与天游，鼋鼍皆默化。","利剑决浮云，玄珠烛长夜。","许繇乃尧师，土苴治天下。","得鱼忘敝笱，骖螭任高驾。","圣智贵潜行，毋使大盗假。","悬瓢松树间，风吹流泉泻。","哀彼尘垢子，死生如传舍。"]},{"t":"咏怀 其三","f":"五言古诗","c":["亭亭南澥云，变化如游龙。","朝冠扶桑日，暮舍阊阖风。","光彩何荧荧，降我药珠宫。","感子相羽翼，飘飖至崆峒。","获睹轩辕帝，心华开鸿濛。","万象无遁形，来朝宝镜中。","双成为舞女，子晋为歌童。","游戏太虚庭，谁能知所终。"]},{"t":"咏怀 其四","f":"五言古诗","c":["驷马尚可縻，去日苦难追。","平生履虎尾，慷慨将何为。","转蓬如车轮，随风西北吹。","故乡路辽远，瞻望涕涟而。","子房久辟谷，颜如朝霞披。","白龙何蜿蜿，与我游天池。","功业嗟未建，下民方调饥。","洁身乃小节，谁能混鸱夷。","蝉蜕王侯尊，聊且从吾师。"]},{"t":"咏怀 其五","f":"五言古诗","c":["庆卿为燕使，任侠不爱身。","当时偕渐离，势必歼强秦。","委肉饿虎蹊，为谋徒苦辛。","用兵贵无形，窈冥如鬼神。","风云张羽翼，龙蛇效屈伸。","尚父有韬钤，变化存乎人。","我昔观鱼复，八阵如星陈。","江波激雄怒，巨石高嶙峋。","玉女守其门，风后旋其轮。","嗟哉先哲心，精微谁能臻。"]},{"t":"咏怀 其六","f":"五言古诗","c":["仲秋寒节至，游子无衣裳。","憀慄此何气，中人如斧戕。","阴阳日交战，龙血纷玄黄。","上天徒暴怒，雷霆曾无伤。","务光久沉渊，有穷登为王。","予其忍玩世，君臣有大纲。","宁当猛虎步，不随鸿鹄翔。","勉哉疾固心，四澥聊徬徨。"]},{"t":"咏怀 其七","f":"五言古诗","c":["薛公三千客，半是剑伎人。","惜无王霸略，西向终事秦。","上兵贵战德，训练宜精勤。","八阵本无形，混沌如天轮。","苟能准河图，出没惊鬼神。","离离九皇星，光悬紫薇门。","阳春而肃杀，一气秉其钧。","予其钦若哉，遑敢懈晨昏。"]},{"t":"咏怀 其八","f":"五言古诗","c":["仙人空桐子，变化如阴阳。","朝霞一膏沐，神光流未央。","忘身故委蛇，八极纷翱翔。","伊予从之游，矫掌承玉浆。","日月如贯珠，吐纳养其黄。","庄生化蝴蝶，相遇鸿濛乡。","羽翼何葳蕤，餐花临扶桑。","东澥涌其波，浮云四飞扬。","尧轩去已久，斯民多忧伤。","苟非姑射人，谁能应帝王。","薄言税吾驾，深山垂衣裳。"]},{"t":"咏怀 其九","f":"五言古诗","c":["出门操天弧，吾将射四方。","豺狼日争食，旷野无人行。","民生各有乐，好修予为常。","桃李羞同华，日月思齐光。","曜灵久翳景，丽天谁文章。","晞发凭天门，北斗斟琼浆。","虽非丹山鸾，愿巢阿阁旁。","雌雄三十六，和呜宣祯祥。"]},{"t":"咏怀 其十","f":"五言古诗","c":["乘云何踟蹰，山中难久居。","营营魂九逝，长夜怀忧虞。","披衣起鸣琴，宫商惨不舒。","听者非佳人，鸱鸮纷詈予。","上天降霜露，岁寒谁欢娱。","硕果不可食，琼华化为荼。","俯仰涕沾膺，何时旋故都。"]},{"t":"咏怀 其十一","f":"五言古诗","c":["遥遥望故乡，魂魄所从始。","狐死必首丘，远游今安止。","嵩丘春载阳，三花何旎旎。","时无雒川妃，谁发予琼齿。","有鸟自南来，丹翎纷不理。","雄鸠虽巧言，苟合中诚耻。","茕独夫何言，临流泪如水。"]},{"t":"咏怀 其十二","f":"五言古诗","c":["吾剑虽短兵，其疾如电光。","回旋应规矩，恍惚双龙翔。","今天降丧乱，日月颠其行。","重华命百神，迎我朱陵冈。","林峦亘千里，沅湘流汤汤。","山鬼纷媚人，前驱从两狼。","忠诚夙所立，九死吾何伤。"]},{"t":"咏怀 其十三","f":"五言古诗","c":["长鲸吹海波，百川皆倒流。","江妃何夭矫，持我归蓬丘。","昊天方降威，潜伏为良猷。","舍我朱离天，来宅寒门幽。","坟羊共藏井，腾蛇与相纠。","君子贵知几，柔顺其无忧。"]},{"t":"咏怀 其十四","f":"五言古诗","c":["萋萋女贞木，变化何葳蕤。","含此少阴精，隆冬叶不萎。","夫何一佳人，怀忠适见疑。","神灵附太山，攀条吟以悲。","天边有匏瓜，流光照我姿。","笃志慕陶婴，苟合非所期。","百川自东逝，北辰无转移。"]},{"t":"咏怀 其十五","f":"五言古诗","c":["大块鼓噫气，众窍为怒号。","予口实兴戎，纵横变离骚。","顾盻无四海，遑能媚其曹。","泰山郁嵯峨，黄河流滔滔。","丈夫无死生，万物等鸿毛。"]},{"t":"咏怀 其十六","f":"五言古诗","c":["予幼好骐骥，万里思横行。","白起不辱君，忠君爱其名。","弓燥而手柔，秋天猎秦城。","信行直如弦，贤豪不我轻。","后骑甘泉宫，前军细柳营。","风飘大胡笳，呜呜如龙鸣。"]},{"t":"咏怀 其十七","f":"五言古诗","c":["少年学神仙，披发罗浮戏。","麻姑爱玉颜，为作芙蓉髻。","簪以明月珠，拂以红罗帨。","吹笛东南峰，紫鸾来嘒嘒。","欢娱曾几时，人世苦流离。","君为空中云，我为机上丝。","将丝系浮云，缠绵安可期。","悠悠望蓬山，终古长相思。"]},{"t":"过涿州作","f":"五言古诗","c":["树木何飕飕，黄云千里愁。","日月争驱驰，民生谁获休。","置酒华阳馆，五鼎烹肥牛。","太子捧金卮，美人弹箜篌。","数石不得醉，悲歌恨仇雠。","歌舞欢未终，将军刎其头。","惊风起燕台，滹沱咽不流。","男儿得死所，其重如山丘。","白刃若春风，功名非所求。"]},{"t":"燕市篇","f":"五言古诗","c":["日月忽不淹，功名行蹉跎。","神怒色不变，吾何如荆轲。","名随朝露晞，体与蜉蝣化。","嗟尔世上人，悠悠一何多。","驱车临幽州，褰裳涉滹沱。","渐离为击筑，田光和悲歌。","四顾莽无人，泪下随风沙。","英雄无私雠，燕秦终不和。","持此七尺身，为君湛太阿。"]},{"t":"绥德城下作","f":"五言古诗","c":["白日何萧条，边声吹枯桑。","浮云终不归，随风四飞扬。","言登赫连台，万里望西羌。","匈奴多种落，纷纷如牛羊。","白骨委蓬蒿，谁知是国殇。","向夕闻芦笳，泪沾铁裲裆。","立发而虎视，何当吞八荒。","大刀搏白虹，长箭指天狼。","月照戍楼中，不寐空徬徨。","男儿有气节，安得思故乡。"]},{"t":"大同感叹","f":"五言古诗","c":["杀气满天地，日月难为光。","嗟尔苦寒子，结发在战场。","为谁饥与渴，葛屦践严霜。","朝辞大同城，暮宿青燐傍。","花门多暴虐，人命如牛羊。","膏血溢槽中，马饮毛生光。","鞍上一红颜，琵琶声惨伤。","肌肉苦无多，何以充君粮。","踟蹰赴刀俎，自惜凝脂香。"]},{"t":"赠朱士稚","f":"五言古诗","c":["神虬乐泥蟠，鸿鹄安紫荆。","飞腾亦何难，所贵忘吾形。","子房久破产，一身如浮萍。","英雄不失路，何以成功名。","高歌送君酒，词采郁纵横。","神仙尔何愚，犹未齐死生。","明月在沧海，光华虚复盈。","毋怀千岁忧，酣放聊沉冥。","天地一尘垢，吾心独太清。"]},{"t":"示李总戎","f":"五言古诗","c":["人生非麋鹿，安能恋山林。","翩翩裘马子，四澥求知音。","一呼疮痍起，戈矛夙所任。","许君以驰驱，杀身毋沉吟。","宁食猛虎肉，莫伤壮士心。","壮士昔穷贱，一饭酬千金。","功名有反覆，英雄难陆沉。","苟不达王命，弓藏悲良深。","愚哉万人敌，叹息为淮阴。"]},{"t":"送陈十七","f":"五言古诗","c":["匹夫为大侠，吾慕鲁朱家。","翩翩四公子，贤豪奚足誇。","猛士处贫贱，神鱼困泥沙。","金鳞三十六，惨淡含朝霞。","变化虽有时，奈此寒与饥。","恩害日相生，欲报贵无私。","暴虎而冯河，英雄所不为。","五贼在心中，运之如璇玑。","去矣陈孺子，冠玉何权奇。","天下在鼎俎，宰割其随时。"]},{"t":"赠万生","f":"五言古诗","c":["寡妇得丹穴，礼抗万乘君。","百尺怀清台，煌煌巴水滨。","丈夫无货财，为德将何因。","观时得权变，白圭诚智人。","东南市玉帛，西北贸马牛。","为君富敌国，五行运其筹。","握土成黄金，丹诀藏浮丘。","关中日转饷，地利如川流。","功名何赫赫，谁知文终侯。"]},{"t":"与诸公别于西陵","f":"五言古诗","c":["浮云何瀰瀰，导我将何之。","徘徊西陵路，与子搴江蓠。","江蓠久不芳，佳人无衣裳。","烹鱼贵神鼎，酌醴宜鸾觞。","鸾觞君不御，别恨吴天长。","参辰日错行，龙虎不相望。","我无四澥罗，何以获鸳鸯。","楚歌为羽声，壮心空低昂。","君子握神器，小人重文章。","去去且挥手，久要愿不忘。"]},{"t":"寄陈黄门","f":"五言古诗","c":["美人游四海，滔滔伤不归。","鼋鼍衔左黪，中流援者谁。","我欲拔剑去，路长无粮资。","人马皆饥豗，徬徨泪濡衣。","驾言陟高冈，顺风呼所期。","吾子白衣冠，呜咽前致辞。","丈夫怀心胆，报德当乘时。","母以天年终，聂政今何依。","众人鸟兽散，弃我忽如遗。","逝将衽金革，与子同驱驰。","但视沧浪天，莫顾黄口儿。"]},{"t":"寿母 其一","f":"五言古诗","c":["我生遘丧乱，周游悲道穷。","发肤虽至昵，相依不克终。","子春难全归，豫让靡成功。","仰辜昊天德，俯愧白华躬。","兹辰介春醴，瓶罍无光容。","捧土塞盟津，吹琯回条风。","微志苟不移，庶可慰尸饔。"]},{"t":"寿母 其二","f":"五言古诗","c":["朱陵有药市，我父为韩康。","东王教服食，仙去路渺茫。","远瞻松槚上，近察几筵傍。","神灵何倏忽，令母早年孀。","白鹤思令威，黄鹄悲陶婴。","悠悠圣善心，与我旻天长。","母子相流连，如月在沧浪。","沧浪水清彻，所以娱娥光。"]},{"t":"寿母 其三","f":"五言古诗","c":["母寒裁复裈，儿寒持熨斗。","隆冬天雨霜，清苦徒相守。","偕隐似绵山，躬耕无谷口。","今朝逢令辰，何以介眉寿。","凿冰取嘉鱼，采兰为肥牡。","堂堂予处子，被褐怀琼玖。","不义如浮云，岂足娱诸舅。"]},{"t":"寿母 其四","f":"五言古诗","c":["青松冒霜雪，岁寒希阳春。","仰绝高天覆，俯凭坤厚仁。","婉娈怀袖间，蔼如狐白温。","尸鸠未均养，所嗟俱贫辛。","长息刺绣文，次息倚市门。","终岁何劬劬，钱刀无一存。","龙绡匪冬衣，燕麦匪朝餐。","徒持孺子颜，嬉笑相承欢。"]},{"t":"寿母 其五","f":"五言古诗","c":["葳蕤三珠树，上有孤凤凰。","凝神慕姑射，尧舜如秕糠。","大子歌离骚，中子进椒浆。","小子射白鹿，为脯陈高堂。","勤劳文伯母，勖以追圭璋。","日抱金乌飞，月怀灵兔翔。","精华相呼噏，为命与天臣。"]},{"t":"寿母 其六","f":"五言古诗","c":["西王有青鸟，奉使何温恭。","朝登麻姑台，戴胜相随从。","中妇献缃襦，小妇调丝桐。","阿母乐欣欣，饮酒颜鲜红。","兰花结萱草，千叶开芙蓉。","念我托神仙，不昏如青童。","幽幽匏瓜星，独处银河东。"]},{"t":"寿母 其七","f":"五言古诗","c":["罗浮五色鸟，绛翎是君王。","生男为鸿鹄，生女为鸳鸯。","嗟余有两妹，口噤难衔将。","风雨日漂摇，尝忧巢穴伤。","侯光方赁舂，令晖日缝裳。","穷苦不遭时，令母怆中肠。","婿贫若珠玉，女淑宜糟糠。","庶几抱潜德，来共拜嘉庆。"]},{"t":"寿母 其八","f":"五言古诗","c":["神龙何光彩，乘道而浮游。","非阴复非阳，归我太清居。","暮如蓬海月，为母掌中珠。","朝如扶桑霞，为母身上襦。","天下乃尘垢，真人色不渝。","虽无人爵荣，其乐如华胥。","愿亲且安坐，清琴听徐徐。"]},{"t":"赠友 其一","f":"五言古诗","c":["与君生南溟，嘘噏雄百川。","海波如连山，天地争回旋。","蓬壶在鳖背，踟蹰未登仙。","念此下民咨，干戈方缠绵。","大禹股无毛，仲尼席屡迁。","至人贵拯物，俾世无颠连。","鸟兽与同群，松乔胡足贤。"]},{"t":"赠友 其二","f":"五言古诗","c":["玄云无定体，应龙不常仪。","昨日髡为奴，今朝冠有绥。","贤者重其死，与世聊委蛇。","委蛇夫如何，有亲方餔糜。","登高呼我友，来同季女饥。","君为爨下桐，我作薪中葵。","持兹忧患身，柔顺同文箕。","有鳏昔在下，雷雨终弗迷。","聊陈衾与裯，同寝待鸣鸡。"]},{"t":"赠友 其三","f":"五言古诗","c":["秋霜何凛冽，孤凤寒无衣。","摛藻如云霞，五经徒纷披。","微言在糟粕，千秋知者希。","子志在春秋，我学惟蓍龟。","阴阳道所贵，生杀其乘时。","丹青亦寓言，游艺聊自嬉。","浩荡象天形，山川相蔽亏。","为余貌山鬼，窈窕含忧思。","灵修在毫素，终古见光仪。"]},{"t":"赠友 其四","f":"五言古诗","c":["三闾多微言，游仙托荒诞。","追琢风谏心，光彩争云汉。","离骚能好色，九章多怨叹。","洋洋变风雅，发愤成波澜。","苟非宋玉招，精魂方越散。"]},{"t":"赠友 其五","f":"五言古诗","c":["神农削鸿梧，以合天人和。","嗟余半死根，摧藏在山阿。","蒙周生浊世，滑稽扬其波。","湘累亦寓言，荒淫为九歌。","变易吾仪容，云气象嵯峨。","日月尚有瑕，丘陵亦孔讹。","称文虽渺小，其旨咸包罗。","夫子诚知音，悯我如韩娥。","行云如可遏，更奏采菱荷。"]},{"t":"送从弟无极归里 其一","f":"五言古诗","c":["白云忽改容，愀凄若风雨。","黄龙何宛蟺，相追在洲渚。","同气不相离，庶几吾与汝。","与汝怀芬芳，离骚绳祖武。","崇兰恶无实，相将树稷黍。","泰山易崩颓，相将保鸿羽。","成仁即神仙，韩终非所许。","愿言守儒术，毋坠先人绪。"]},{"t":"题云台峰 其一","f":"五言古诗","c":["雄雷何霹雳，雌雷鸣依依。","阴阳相回薄，渊默不能持。","发愤为春秋，空文思垂辉。","轩辕在华岳，排天往陈辞。","天梯何险艰，十步九逶迤。","匍卜苍龙背，拘牵玉女衣。","绠短玉井长，寒浆难疗饥。","白帝觞百神，邀我云台嬉。"]},{"t":"题云台峰 其二","f":"五言古诗","c":["抠衣上云台，磴道何盘纡。","死生寄微繘，逡巡青壁隅。","神气虽不变，四体挛以拘。","阴井仰穿空，阳霤伏行虚。","仙人遥见笑，戚施与蘧蒢。","寥廓忽无天，穷高至奥区。","巨灵厌大朴，雕崿为芙蕖。","吾将反浑沌，与帝合灵符。"]},{"t":"猛虎词","f":"五言古诗","c":["朝负角弓出，暮负角弓归。","猛虎何斑斑，欲射怜其儿。","惟虎尚有儿，惟人乃无妃。","雄刀鸣床东，雌刀跃床西。","雷雨何冥冥，兰灯惨其辉。","徬徨起中夜，恩怨交心脾。","牝鸡方司晨，令我倒裳衣。","裳衣且莫倒，奋发当有时。"]},{"t":"赠陆氏及其从子","f":"五言古诗","c":["凄凄天上星，与我俱沉冥。","匏瓜常自系，河鼓难为声。","吁嗟尔知己，相欢如平生。","阮公赋咏怀，携手八荒行。","洋洋会风雅，从子与齐称。","昔焉冯大河，今焉履薄冰。","妖姬自可求，渔父谁能名。"]},{"t":"为区母陈太君寿 其一","f":"五言古诗","c":["煌煌天上星，三五成鸳鸯。","匏瓜独无匹，织女徒相望。","如彼单枝莲，苦心含九泉。","如彼兔丝花，松折还缠绵。","独活为谁施，不学华山畿。","绸缪君牖户，鞠育君孤儿。","平生昧凫藻，梦寐见容姿。","长歌入君木，越礼非所宜。"]},{"t":"为区母陈太君寿 其二","f":"五言古诗","c":["妾心非朝露，不为白日晞。","芙蓉负霜死，不作浮萍移。","寒苦四十年，春阳无见期。","伯姬蹈汤火，高行毁容辉。","百尔君子怀，两髦怜我仪。","有腼未亡人，敢当称寿辞。","所愿为蜉蝣，泉下早同归。"]},{"t":"清明展墓作","f":"五言古诗","c":["妖姿痛不留，华年惜中夭。","墓草根已陈，松枝翳萝茑。","绣床所怜女，魂魄何娇小。","药石弗能追，相随入先兆。","沉阴日杳冥，泉下无时晓。","忧毒能伤人，吾将殉窈窕。"]},{"t":"游罗浮作","f":"五言古诗","c":["隆嵷两灵岳，佐命于祝融。","蓬莱浮海来，与之合鸿濛。","曜真秘阴室，朱明开阳宫。","夜半海日飞，摇荡石楼红。","石楼夹天起，云气流如水。","日出见仙人，玲珑水帘里。","迎我四百峰，蝴蝶大不已。","袅袅铁桥垂，欲度愁风吹。","白云为羽翼，一举将何为。","苏耽尚有母，莱子亦有妻。","潜龙宁勿用，雷雨将乘时。","麻姑有酒田，聊自耕紫烟。","捣药命红翠，流杯持寒泉。","欢娱可因物，变化宁在天。"]},{"t":"游黄龙洞","f":"五言古诗","c":["洞口花萦回，微磴在溪水。","交瀑络峰腰，积翠明潭底。","倒影麻姑台，一望成霞绮。","白石含金沙，紫蒲吐琼蕊。","群峰稍开豁，阴云泱漭起。","坐爱盘石广，卧欣芳草靡。","天华寻遗宫，蒙茏馀葛藟。","歌响散天飞，舞尘逐云委。","兴废祗终朝，割据一何鄙。","英雄宁无成，不夺儿女子。","混沌留吾年，蝉蜕帝王里。","洋洋风佩飘，天路从兹始。"]},{"t":"冲虚观","f":"五言古诗","c":["平生好峤岳，所至栖丹丘。","太华虽言好，未若归罗浮。","冲虚有云构，葛公所绸缪。","喑虎守洞穴，碧鸡松际游。","石乳滴人寒，花气随风留。","仙璈奏池底，月明声可求。","发晞笼葱林，手弄芙蓉鸥。","日月还雰虹，元气郁不流。","研精在玄奥，吾且以销忧。"]},{"t":"宿宝积寺","f":"五言古诗","c":["行缘一瀑布，高上层峰端。","兰若冠青壁，松林郁巑岏。","光霞舒丹气，暄风凄微寒。","锡杖有神溜，嘘吸漱潺湲。","衣裳何飞飞，随风上檀栾。","洗药尚未毕，长啸凌天门。","孤生悼已晏，妙志矢无谖。","沮溺虽隐约，松乔共盘桓。","日暮闻钟声，聊与飞鸟还。"]},{"t":"进帆石门怀古作","f":"五言古诗","c":["洋洋牂牁水，万里番禺通。","百川灌其西，三江潴而东。","分源自夜郎，合流趋郁铜。","势束高要崄，声奔昌乐泷。","春膏溉雄田，夏涨挟旧风。","滔滔安所归，溟渤朝祝融。","崩波吭一门，喷激争其冲。","竦石尽壁立，沓潮声相舂。","我舟朝溯洄，暮犹双阙中。","飞峡有惊瀑，穿林多横峰。","耽兹山水胜，挂帆时来从。","楼船想杨仆，策略怀唐蒙。","奇道乃自泄，偏霸知将终。","裸国亦称王，矧尔臣佗雄。","中华当拓境，扬越先成功。","前军寻陕破，后骑石门攻。","蠢尔一州主，汉为天下宗。"]},{"t":"西台雨后行田","f":"五言古诗","c":["蒙茏黄木洲，汎滥扶胥汇。","池台俯闾井，耕钓存风概。","濒海多涂泥，芳沃罕灌溉。","春雨上膏滋，冬潮咸气退。","烧盐有馀秆，垦土无留块。","曰我沮溺人，耕惭微禄代。","宁须富粳稻，但欲除污莱。","始晴命夫男，露田行不怠。","汩汩引泉脉，苍苍悦山黛。","虹生黄晕中，日出阴霞内。","土坼百卉惊，基崩众流溃。","殷勤语我农，旨否尝不逮。","滂沱趣导渠，湍激宜安碓。","在彼牛力偿，在此锄功贷。","苗壮须附根，草肥或留菜。","平生究水利，斥卤亦所爱。","尽力志沟洫，开荒喜草昧。","王道始力田，子职期秉耒。","踟蹰盻有年，勤动终无悔。"]},{"t":"鸿雁","f":"五言古诗","c":["鸿雁从风飞，气力亦自爱。","所忧霜雪寒，艰难来入塞。","如何纥干山，群雀啾啾在。","高秋八九月，冻死乃无悔。","物性苟知时，哲人生感慨。","不见山梁雉，三嗅入茫昧。"]},{"t":"寄四会李子","f":"五言古诗","c":["念子离根蓬，随风去何之。","少年好驰侠，意气为雄儿。","持忧催白发，我年已崦嵫。","玉沥与金华，成仙不可期。","聊为亡命人，隐忍居下邳。","事败死无名，空令骨肉糜。","吾子弃其觚，立功思边陲。","英雄苟有具，富贵宁无期。","穹庐多秘馆，中有琵琶姬。","射猎得猪鹿，相与聊娱嬉。"]},{"t":"送铁桥道人 其一","f":"五言古诗","c":["十二慕信陵，十三师抱朴。","十五精骑射，功名志沙漠。","袖中发强矢，纷如飞雨雹。","章句耻不为，孙吴时间学。","蹉跎遂暮年，丧乱成萧索。","洗心向林泉，所望惟鸾鹤。","瀑水与萝花，飘飘梦中落。"]},{"t":"送铁桥道人 其二","f":"五言古诗","c":["相逢少林僧，剑法将传子。","绕身若电光，声如风雨至。","良马名铜龙，雄鸡悍无比。","慷慨少年场，报仇兼雪耻。","丈夫苟能军，市人亦可使。","何听命于人，自损英雄志。"]},{"t":"送铁桥道人 其三","f":"五言古诗","c":["立功良有命，英雄思战殁。","可惜沙场中，少君一白骨。","神仙学未成，见道苦超忽。","努力去云雾，天光自开发。","归去养生人，聪明毋自伐。","朝气若流泉，暮心如海月。"]},{"t":"送陈中洲 其一","f":"五言古诗","c":["问子游何之，长啸而不言。","民生悲局促，轻举思浮天。","寄躯于飞蓬，阳风乘飘然。","夜光无自耀，明膏不自煎。","服丹身无影，所至如云烟。","赠子寂寞床，玄虚为广旃。","行行至青原，朝夕聊安禅。"]},{"t":"送陈中洲 其二","f":"五言古诗","c":["白发秽光仪，年华亦已暮。","如彼兰蕙芳，离披向霜露。","子才逸卿云，复有鸾龙度。","慷慨泣明珠，光辉谁不顾。","吴越多知音，而今重词赋。","闻子父兄名，新知尽成故。","行矣路方长，时时望丘墓。","莫即学苏耽，仙成上烟雾。"]},{"t":"为夏子题奉母图","f":"五言古诗","c":["麋鹿得甘草，呦呦鸣其麑。","儿生失慈母，匍匐将安归。","不如彼燕雏，有母教之飞。","羊羔亦有乳，乌子亦有枝。","嗟君始六岁，已抱杯圈悲。","茕茕在襁褓，黄口长含饥。","辛苦得成立，堂前怀断机。","丹青作图画，梦想存容姿。","瞻依向纨素，出入将庭帏。","如闻叹息声，俨见劬劳时。","丁兰刻芳木，日禅泣阏氏。","同怀终天恨，孝思无穷期。","庶几扬令名，以慰圣善贻。"]},{"t":"古诗为叶金吾寿","f":"五言古诗","c":["英雄日已老，颜色难长好。","昔为张子房，今作商山皓。","吾将终罗浮，服食惟朱草。","何以被四肢，蝴蝶大如箕。","小翅为下裳，大翅为上衣。","何以作栖宿，十围笼兖竹。","一节为一房，两节为一屋。","何以为俦侣，麻姑与玉女。","作使五色禽，纷纷炼珠黍。","何以充羽觞，玄碧酒如浆。","饮之一呼吸，水露皆生香。","有友金吾子，家在丰湖埃。","吾令两瀑布，流出桃花蕊。","桃蕊是丹砂，君餐兼露华。","复有蝙蝠好，双栖芭蕉花。","千年白如雪，红者如朝霞。","赠子白复红，佩之衣带中。","能令男女媚，相爱长相同。","白以佩吾子，红以佩昭容。","黄帝昔成仙，其术惟房中。","素女为之师，浮丘为之宫。","真人在玄牝，出入如虚空。","日月一相摩，光彩成青童。","吾慕鲁女生，翩翩骑白龙。","仙成上太华，毛女千人从。","君今有窈窕，左右争芙蓉。","我亦容成子，大道在其躬。","相将且驻年，紫髓而方瞳。","时来建勋伐，乃追太保公。"]},{"t":"卧疾行","f":"五言古诗","c":["贞女长苦寒，介士长苦饥。","吁嗟蕙兰草，雨露不相滋。","人情若流水，流水东以西。","一日不胶漆，十日不相知。","我有负薪忧，药石谁见贻。","一身事尊老，衣食无所资。","为子复为妇，出门尝迟迟。","水精为明月，一气相光辉。","月中有日影，如子在母怀。"]},{"t":"送王子从军","f":"五言古诗","c":["太白天将军，夜来穿月出。","光芒一何长，直使阴精失。","吁嗟兵象见，变乱将无日。","怜君虎豹姿，自此难安佚。","子房青云士，高尚素无匹。","一朝去从军，鞍马如风疾。","经营罗甸兵，左右哀牢帅。","天心早能知，王命多论述。","英雄方缤纷，囊括须高密。","王侯宁有种，厮养亦胶漆。","仲夏珠江湄，送君情洋溢。","离支堆玉盘，花露甘如蜜。","半醉即扬鞭，乳羊啖未毕。","慷慨辞故人，故人多卓逸。","羊裘钓泽中，亦有男子一。"]},{"t":"偶从风洞眺望始安山水赋呈秦使君","f":"五言古诗","c":["自我班师还，永日游山水。","城隅得风洞，爱玩心难已。","攒石多巉岩，方圆乱相峙。","峰高易倾侧，崖落势不止。","绝壁窥天窗，光从潭底起。","盘旋上松门，狼藉踏花蕊。","萝林外冥郁，石乳中奇诡。","玉床既膏滑，丹灶无泥滓。","惊濑不因风，水石自相使。","飞溜吐复吞，空响震心耳。","坐久机虑忘，一息归无始。","终日介马驰，佳憩乃得此。","无人共胜赏，窃忆秦夫子。","解组初投閒，老易重为理。","用亢得无悔，知足自多祉。","褰溯任所适，渊默人难指。","留侯岂仙人，导引诚有以。","蝉蜕帝王中，功名同敝屣。"]},{"t":"曾公子樱挽诗 其一","f":"五言古诗","c":["公子少游侠，甘心信陵君。","玉颜舒苕华，长剑吐浮云。","贤豪与争博，睚眦尝下人。","弦高思救郑，晋鄙难摧秦。","慷慨请兵符，肝肠感三军。","吁嗟乌合众，为阵何纷纭。","横戈当瞿唐，出没如鬼神。","我扼其咽喉，贼气不得伸。","士卒坚如山，对垒动兼旬。"]},{"t":"曾公子樱挽诗 其二","f":"五言古诗","c":["朝廷讵无将，君独奋布衣。","手提五百人，不死其何归。","肌肤为兜鍪，厮养为神师。","一夫先刈旗，贼惊刀相糜。","奇兵无全胜，救援苦不来。","彼为泰山崩，我为独木支。","寒寡终不敌，猛士咸疮痍。","人持一半冰，马负一束萁。","且战且退走，骁骑惮不追。","呜呼蛇矛失，流涕满边陲。"]},{"t":"曾公子樱挽诗 其三","f":"五言古诗","c":["剧孟一敌国，条侯资其雄。","如君勇盖世，可无横草功。","烈士非徇名，王臣原匪躬。","终军乃自媒，少卿竟谁从。","马步势悬绝，战酣频饮血。","杀人惨无声，阴风吹凛烈。","徒手犹奋呼，百人无尺铁。","成败天所私，吾谋将焉哲。","呜呜陇头水，沉沉沙场月。","为君歌国殇，泪流满衣褋。"]},{"t":"哭内子王华姜 其一","f":"五言古诗","c":["呜呼我昊天，降祸一何酷。","我岂儿女仁，所惜亲茕独。","我生苦伶仃，以妇为骨肉。","况是窈窕姿，恩情日以笃。","三载客将军，欢乐亦云足。","朝进紫驼羹，暮听秦筝曲。","卿家歌舞多，富贵非所欲。","携手还丘园，殷勤耕且读。","老姑自汝来，欢喜加饘粥。","笑与邻姥言，新人颜似玉。","定省几晨昏，孝声闻戚属。","凶变在须臾，人理一何促。","哀叫天不闻，有身宁可赎。"]},{"t":"哭内子王华姜 其二","f":"五言古诗","c":["阿母年七旬，哭汝声摧裂。","当食不能餐，喉间日哽咽。","念尔万里身，艰难历胡越。","暑雨及祁寒，驰驱不暂辍。","关中积高府，风气多惨冽。","我性不能寒，疏理畏风雪。","鹧鸪向日飞，桂华以冬发。","自返南州来，中怀少郁结。","汝亦乐土风，所愁独炎热。","海氛多毒淫，腹痛成夭折。","仓皇医未来，瞥已电光灭。"]},{"t":"哭内子王华姜 其三","f":"五言古诗","c":["炎州虽烟瘴，珍果足娱子。","子慕离支浆，能令颜色美。","可怜未及餐，仓卒归蒿里。","自作翡翠钗，自剪蒲桃绮。","簪服几何时，弃捐箧笥里。","汝生既柔脆，汝病复不已。","水土不相宜，卑湿损年纪。","家贫药饵少，夭枉非天理。","痛酷五中崩，我罪伊何矣。"]},{"t":"哭内子王华姜 其四","f":"五言古诗","c":["皇天何不仁，不念鞠子哀。","不念我君姑，白发方摧颓。","魂魄今越散，逢祭时一来。","我魂在姑前，朝见姑泪涟。","我魂在夫侧，暮闻夫叹息。","稚女未成人，殡宫日匍匐。","我欲乳遗孤，鬼伯相摧逼。","儿寒姑与衣，儿饥姑与食。","劳苦今惟姑，姑将无气力。","谁割我孝慈，皇天不与直。"]},{"t":"哭内子王华姜 其五","f":"五言古诗","c":["汝魂毋飞扬，万里随悲风。","汝父为国殇，精爽在榆中。","汝兄亦殉死，黄口为鬼雄。","游魂尚未变，白骨可相从。","汝生不识父，死后见形容。","桓桓大将军，苦战黑山戎。","左手挽人头，右手持秦弓。","须髯怒尽磔，流血被体红。","黄云野莽荡，阴气横苍穹。","前有无定河，后有赫连宫。","父子惊相持，恸哭何时终。"]},{"t":"哭内子王华姜 其六","f":"五言古诗","c":["汝魂复何之，汝母在朝那。","生时命奇薄，夫死矢靡他。","孤女藐始孩，提抱出干戈。","伶俜未亡人，被发奔风沙。","汝小既偏孤，汝大又无家。","自汝失天只，骨肉成土苴。","泉下今相遭，烦冤诉无涯。","长城土惨裂，黑水冰峨峨。","严风纵横起，吹汝魂无多。","朝随转蓬飞，暮逐惊沙过。","边地虽故乡，阴寒谁奈何。","母子魂来归，归我罗浮阿。"]},{"t":"哭内子王华姜 其七","f":"五言古诗","c":["尔死作归人，我生何聊赖。","恍惚成狂痴，魂梦思交会。","与子合婚来，别离常在外。","相见曾几何，一旦成茫昧。","两载共行役，岂无饥渴害。","诗书相与娱，为道忘颠沛。","彤管我能操，雅琴卿亦解。","自古黔娄妻，偕老多年岁。","如何卿乐贫，独不保少艾。"]},{"t":"哭内子王华姜 其八","f":"五言古诗","c":["凄凄灯火光，照我空房寒。","旨酒谁与饮，弹琴谁与欢。","徬徨泪横迸，不寐茹哀叹。","衾帱不忍展，翰墨不能看。","学诗虽未成，才思已波澜。","风雅日弦歌，书写满齐纨。","蕣华不终朝，玉魄难为团。","徒栽同本芝，徒种同心兰。","上天恶贤淑，使我成孤鸾。","梦想何时衰，忉怛摧心肝。"]},{"t":"哭内子王华姜 其九","f":"五言古诗","c":["采采荼蘼花，花露红以滋。","为姜作面色，光艳使情怡。","之南市石黛，之北市燕支。","芳香用未毕，蕙草忽先萎。","幽镜生红埃，罗帏交网丝。","笑貌若流光，一绝不可追。","莓苔馀履迹，彷佛行迟迟。","我有第五妹，与姜日娱嬉。","梳姜堕马髻，服姜月华衣。","四妹嫁远方，尚未觏容姿。","今晨两恸绝，闺阁将谁师。"]},{"t":"哭内子王华姜 其十","f":"五言古诗","c":["西北多佳人，平生性所慕。","驰侠至秦中，荷卿爱词赋。","朝共恒华游，暮指潇湘路。","并马榆关行，同车梅岭度。","妆罢弄图书，酒酣射雉兔。","欢娱及閒暇，燕婉忧迟暮。","我情日以柔，汝姿日以嫭。","竭力媚闺房，不为荒淫故。","宁知忘忧花，一旦摧朝露。","积想成狂疾，寻子向丘墓。"]},{"t":"哭内子王华姜 其十一","f":"五言古诗","c":["相如还成都，衣裘尽贳酒。","自刺美人赋，消渴恐不寿。","脸际芙蓉花，谁知先速朽。","幽歌惜永绝，盛颜难复取。","笔床销翡翠，杂佩捐琼玖。","服玩尽棺中，箱帘无所有。","同穴尚无期，我留为慈母。","殉尔一鸣琴，暂作黄泉友。"]},{"t":"哭内子王华姜 其十二","f":"五言古诗","c":["我不忘大德，尔毋思小怨。","自尔入家门，饮食须相劝。","始度台关时，我情弥婉娈。","我乡日已近，汝乡日已远。","好言相安慰，不久还沙苑。","当奉白头姑，共隐华山巘。","居贫愁懑多，婢仆时骄蹇。","恭敬岂无违，所恃卿良善。","纤手所循环，女图日不卷。","新颂伯鸾妻，德音聊自遣。","箧中馀绣袷，颜色红无损。","自今不敢视，一任浮埃满。"]},{"t":"哭内子王华姜 其十三","f":"五言古诗","c":["清明节已届，雨露使心悲。","外舅与外姑，野祭今同谁。","汝生治酒食，汝死魂无衣。","骸骨傍先公，安此南海湄。","扶胥云惨惨，黄木风凄凄。","万里归成妇，袝葬固其宜。","大恩虽未卒，孝媛名已垂。"]},{"t":"陈恭人挽诗 其一","f":"五言古诗","c":["娥娥文简孙，厥云陈恭人。","肃雍秉令德，弱笄四教敦。","惟膏不厌鲜，惟兰不厌芬。","冰清而玉映，来为君子嫔。","君子结大义，患难来方殷。","皇舅为邦家，战死未归魂。","羽林一孤儿，衰绖往从军。","妾身殊不幸，茕独当青春。"]},{"t":"陈恭人挽诗 其二","f":"五言古诗","c":["凤凰卵不完，一朝巢倾覆。","君舅已国殇，君姑亦无禄。","两雏羽未成，啾啾在沟渎。","大雏乃儿夫，弋人慕其肉。","妾父为朱家，任侠轻金玉。","努力救遗孤，恩义一何笃。","君子怀父冤，水深伤独漉。","妾亦愿损躯，报雠持剑槊。","雄儿命苦屯，郁郁居林谷。"]},{"t":"陈恭人挽诗 其三","f":"五言古诗","c":["君子生多才，夫妇以文娱。","五经而六纬，博雅为大儒。","白鹄负其雌，五步一踟蹰。","终然为王事，琴瑟成离居。","初生黄口儿，君在潇湘湄。","再生一女子，君在河之涘。","荼苦妾自甘，孤茕谁为理。","蕙草一朝摧，临危泪如水。"]},{"t":"陈恭人挽诗 其四","f":"五言古诗","c":["丈夫为干将，妇人为莫邪。","雌雄中道别，何以报王家。","妾身久婴疾，针药难屡加。","彩镜失鸾影，朱颜凋蕣华。","阴啸召君魂，阳呼召君魄。","冉冉去何之，黄泉遂永隔。","恸哭摧心肝，独生亦何益。","皇天忌燕婉，佳人殊不惜。","死为苟奉倩，从子归窀穸。"]},{"t":"陈恭人挽诗 其五","f":"五言古诗","c":["余妻曰华姜，聪明亦如子。","寻尔向黄垆，揽袪啼不止。","妾父亦将军，与卿皇舅似。","腐肉何馨香，忠魂在箕尾。","与卿诉天帝，请剑诛封豕。","生未复家雠，死当雪国耻。","在古有娥亲，在今惟伯姊。"]},{"t":"赠徐处士","f":"五言古诗","c":["虎生而文炳，凤鷇已五色。","天性本自然，岂以文章饰。","美才忌轻出，所志非官职。","诸葛骋龙光，游步以自适。","乱世无全臣，欲仕非其国。","四方正云扰，大汉多蟊贼。","抚弦复搦矢，不射非无力。","荀彧王佐风，从曹至今惜。","霜降草乃成，雪深梅始识。","与君松柏姿，无苦岁寒逼。","何以结久要，艰难事潜德。"]},{"t":"赠孔参军","f":"五言古诗","c":["丈夫志经营，岂曰生不辰。","依人七尺贱，隐忍成埃尘。","亲寿如过隙，欲去还逡巡。","狐裘裼素锦，玉气为女人。","单步以负笈，英雄方苦身。","与君同感激，酣饮娱青春。","紫袖方吹箫，青绡持拂巾。","上客列广座，欢言相情亲。","文藻四辉映，绮思霞氤氲。","如彼洞光珠，精灵烛百神。","司马秉冰镜，林宗乐人伦。","殷勤勖明德，及此白发新。","著作为世师，岂敢辞苦辛。"]},{"t":"寿吴云遇先生","f":"五言古诗","c":["先帝诸词臣，天南有其二。","一惟我吴公，冠冕庶尝士。","三朝无实录，史官久不备。","简讨方须才，兼书行在事。","公时当圣心，回翔清切地。","石室书初抽，崧台草亦视。","岂谓复西巡，君臣忽相弃。","霓旌若转蓬，万里追难至。","匍匐返岩阿，天颜在寤寐。","渊明居玉京，子真隐梅市。","义不慕长生，所怀沟壑志。","忽尔享期颐，神明以无累。","先朝一耆旧，天留有深意。","须发虽皤然，精纯若童稚。","令子富才华，文章为酒食。","丹青与草书，一一供亲嗜。","鹤鸣喜在阴，天籁日相媚。","父歌紫芝篇，子疏白华义。","何以轩冕为，山水娱仁智。","岁寒独后凋，努力为苍翠。","荫我半生枝，得成清庙器。"]},{"t":"送李子蓝","f":"五言古诗","c":["日馀尚幽独，夙昔卧林水。","兰生自无人，岂敢怨泥滓。","在春兰则黄，在秋兰则紫。","颜色虽随时，芬馨无终始。","岁寒寡所期，邂逅得吾子。","峨峨武林彦，奕奕文章美。","光掩南海珠，价重凤凰子。","知音亦复希，萧然返乡里。","时无战国雄，黄金斗游士。","且复怀短长，以待人求己。","相送郁江湄，殷勤问行李。","重来不可谖，故人望玉趾。"]},{"t":"读史赠陈献孟并送其行","f":"五言古诗","c":["秦季焚诗书，先圣道以丧。","诸儒负礼器，仓卒归陈王。","匹夫徒发愤，曾不识兴亡。","隐忍成功名，何如张子房。","子房非儒者，为气何坚刚。","其终如鲁连，其始如荆卿。","平生予所希，君亦慕其狂。","终古两盗雄，兰池与博浪。","少年虽轻发，气实吞始皇。","君于太公书，曾否得其纲。","先公有宜略，揣磨宜不遑。","将飞且伏翼，将呜先引吭。","何必魁岸人，始能应帝王。","从容以步游，游于淮海旁。","英雄无神师，其学不明光。","苟能依老成，以礼为之方。","我亦倜傥人，垂老犹摧藏。","汉初两孺子，不得与偕行。","强忍亦已久，中夜起徬徨。","君今血气盛，甘苦未多尝。","思为日本刀，须炼梅花钢。","屈伸能自如，入石乃无伤。","行矣复迟迟，咫尺即相望。"]},{"t":"莲花峰篇赠黄山闵宾连","f":"五言古诗","c":["我昔入秦关，手攀太华峰。","千峰为莲瓣，三峰为莲蓬。","三峰祗一石，一石三芙蓉。","纷纷莲花须，化作千万松。","白帝与明星，宫在千叶中。","高高五千仞，仙掌擎当空。","自谓天下奇，群岳不能从。","何意一黄山，莲花亦次宗。","一茎上矗天，千瓣开濛濛。","从茎上至蕊，吹堕愁天风。","盘回穿岩窦，忽见轩辕宫。","峰凡三十六，此峰太华同。","夫君几登陟，身染莲衣红。","自作黄山经，神与山精通。","文章亦巨灵，开辟将何穷。"]},{"t":"江氏双烈篇","f":"五言古诗","c":["凤凰不孤生，雎鸠无再匹。","姑妇苦相依，岁寒同一室。","良人在泉下，幽幽视皦日。","皦日久无光，光自妾心出。","江家多女宗，礼义为琴瑟。","五妇垂管彤，复兹叔与侄。","教子各成名，文章持笃实。","湘也更多才，贤豪与胶漆。","剑气如白云，玉光温以栗。","以母柏舟篇，相示泪洋溢。","阿嫂亦陶婴，黄鹄歌未毕。","安得圣人生，列在变风一。"]},{"t":"送汪扶晨归歙葬亲","f":"楚辞体","c":["十月河已冰，朔风苦萧瑟。","之子望松楸，行行雪没膝。","乌乌啼以南，乌乌啼以北。","一啼一白头，阿母不可得。","墓道何巉岩，送者皆匍匐。","飞土逐丰狐，殷勤助封植。","而我独不遑，泪垂但沾臆。","以君孝子思，茫茫此何极。","母兮在苍天，朝朝见颜色。","母兮在黄泉，暮暮闻叹息。","文章为牺牲，仁义为鼎实。","庶几贻令名，以为天下则。"]},{"t":"蜀冈陵占 其一","f":"五言古诗","c":["步出城西门，盘回见丘垤。","隋家旧宫殿，林际尚明灭。","亡国以荒淫，雷塘乃无穴。","吁嗟美人魂，风吹作蝴蝶。","玉颜虽黄埃，遗香托花叶。","英雄在白杨，悲啸亦呜咽。","血为萤火飞，雨中光熠熠。","地道通峨眉，千里陂陀接。","幽幽一井泉，中有古日月。","虚无见玉勾，洞府藏冰雪。","举觞相与倾，慷慨中怀热。","茫茫失路中，痛饮诚贤哲。"]},{"t":"蜀冈陵占 其二","f":"五言古诗","c":["秣陵山水多，龙蟠兼虎踞。","可惜张锦帆，未往江南去。","重华挟二妃，时巡冒霜露。","五岳与三湘，銮舆不遑驻。","胡为爱江都，天险从人据。","中原一崩裂，人人皆项羽。","好色以自强，山河诚敝屦。","李花将代杨，兴亡有天数。","君勿笑荒亡，黄泉人笑汝。"]},{"t":"送程君还歙","f":"五言古诗","c":["容成与浮丘，毋乃非神仙。","御女教轩皇，徒为后世传。","君今返黄山，一手携㛹娟。","莫上丹台峰，长跪天老前。","素女安可师，大道贵自然。","凤凰不下地，鸳鸯不上天。","甘瓜相钩带，生子期连绵。","况君美天爵，将为用世贤。","文章有奇器，金石能相宣。"]},{"t":"赠颜君","f":"五言古诗","c":["复圣之子孙，大宗在曲阜。","峨峨司勋郎，与我知交久。","曩者游西秦，声诗相可否。","黄河石华鱼，华阴槐曲酒。","风俗爱宗周，酣歌亦击缶。","洋洋风雅篇，正变无不有。","夫子昔删诗，先师尝左右。","三百所弦歌，琴声满窗牖。","龟山与猗兰，二操亦在手。","子孙被流风，德性尝敦厚。","世为鲁大夫，文献十而九。","宗器多圭璋，孔氏称甥舅。","光禄善五言，人诵秋胡妇。","遗响在黄门，一赋如琼玖。","司勋正始声，比兴无其偶。","赋诗存讽谏，美刺绝不苟。","君也为哲兄，埙篪如一口。","陋巷有神灵，文章作渊薮。","分支去温陵，礼乐遥遵守。","闽海接泗沂，先学相师授。","公本济世才，辉映桃陵后。","为政历朔南，声教先孝友。","含吐黄钟音，中和以自寿。","复圣乃春生，一阳为物母。","以配复初爻，龙潜未见首。","元气在素王，司徒能多取。","公也益含弘，光大庶无负。"]},{"t":"正月既望太仓王虹友兄弟招同诸子集善学斋中有赋","f":"五言古诗","c":["吁嗟岁庚申，昊天降威疾。","正月方屯蒙，雷乃从地出。","去年霹雳早，旱乾兼水溢。","饥馑及娄东，稻蟹三馀一。","阴阳久不分，元气复无日。","人民愿岁丰，张灯祈太乙。","歌舞且须臾，号呼天岂恤。","东北地震馀，至今魂惴栗。","龙血成坚冰，玄黄战未毕。","馀杀在三阳，太和期勿失。","饮食以相需，主人敬终吉。","煌煌火树开，阳春先一室。","白华将绛趺，光华何盛实。","昆弟连枝多，蝉嫣金玉质。","唱叹得良朋，洋洋清庙瑟。","二南兄弟诗，周召如胶漆。","孝友垂正风，以作人伦率。","风雅之大师，娄江旧无匹。","琅琊与太原，诸王多丽逸。","吴许六朝英，赋心总绵密。","我亦希云间，黄门精论述。","所愧称离骚，怨诽难自律。","神听在和平，性情忌淫佚。","何以慰微诚，愿言贻道术。"]},{"t":"咏高士王逵","f":"五言古诗","c":["嗟尔支离疏，傲倪得其天。","长乘莽渺鸟，翱翔穷九埏。","君子道固穷，小人利是缠。","鲍焦持其蔬，晋楚难比肩。","高行虽伤身，令名百世传。"]},{"t":"赠魏处士冰叔","f":"五言古诗","c":["岩岩宁都山，穹石蔽天起。","中有金精峰，翠微与相似。","汉初有逸民，张芒一女子。","玉貌生奇光，纨扇照如水。","垂涕悲民生，欲嫁无良士。","不义衡山王，乃为重瞳使。","弑帝郴江中，悖逆非人理。","兵威劫丽英，披发卧泥滓。","氤氲石鼓旁，奇女气青紫。","有鸾自舞歌，慷慨不可止。","嫁夫得鄱君，婵娟所深鄙。","可惜汉高皇，大度容仇耻。","方徙长沙封，不共淮南死。","佳人重意气，仙举非得已。","安期策苟行，岂爱菖蒲美。","君居临翠微，丽英乃乡里。","平生不字贞，茕茕无娣姒。","薇芜作面脂，菡萏为文履。","云步何虚徐，谁能持玉趾。","玉帛一朝来，容颜遂自毁。","岂伊是籧篨，臭恶还芣苢。","隆准尚不臣，所希在黄绮。","邻女窈窕姿，将老犹珠珥。","枯杨忽生华，以为士夫喜。","秉节乃不终，媒妁持为市。","蔡琰苟忘夫，王昭将妻子。","橘柚已踰淮，芳馨宁有尔。"]},{"t":"送丁使君之官南赣","f":"五言古诗","c":["峨峨虎头城，咽喉我蛮扬。","五岭此大门，筑关自秦皇。","尉佗绝新道，以之为屏障。","山川连瓯闽，建瓴势莫当。","郁孤有台基，三省之堤防。","使君负雄才，天南所歧望。","礼阴而乐阳，为化流炎荒。","声诗百福宗，人伦于焉昌。","宣布天地精，中和在宫商。","六义始于风，动人宜温良。","微言一相感，万物开其房。","方今用兵馀，民风多忧伤。","所赖诸侯诗，优柔致祯祥。","使君藩维寄，德教先豫章。","身作南长城，恩及祝融乡。","巡行至大庾，阴雨滋桄榔。","玉枕山嵯峨，霹雳泉汤汤。","攀援南北枝，要我毋相忘。"]},{"t":"题吴氏一砚斋","f":"五言古诗","c":["中山王之琢，南京有四园。","其东傍青溪，一曲流潺湲。","秦淮窈窕通，钓鱼来至尊。","至今濯锦塘，御气生朝暾。","左右多居人，蒲荷接市门。","罂粟与文无，一一含旧恩。","我将携妻孥，于此开层轩。","为怜有吴君，掌故相讨论。","呜咽成春秋，纪亡不纪存。","君言有玉砚，吐辞如春温。","将输仁爱思，与我同晨昏。"]},{"t":"蓬山篇为顾子丰及其配双寿","f":"五言古诗","c":["天边罗与浮，合体如夫妇。","本是蓬莱峰，尧时乃东走。","洪波浩荡中，难恃神鳌守。","山君华子期，惆怅泉源口。","引领望夫君，功成封户牖。","携尔鲍家妹，来作朱明友。","帝命治黄龙，花田开百亩。","作使小凤凰，采花作春酒。","东西二石楼，玉女充箕帚。","子房本仙人，才大无其偶。","游戏楚汉间，赤帝在两手。","潜跃但乘时，谁见神龙首。","辟谷亦何为，自与天长久。"]},{"t":"赠别甘处士返豫章","f":"五言古诗","c":["甘君生豫章，才藻含素芬。","文章精且醇，色映匡庐鲜。","挟子游江东，雏凤何翩翩。","以予罗浮人，白鹇同飞鶱。","能知老夫佗，南武霸一偏。","其时雄豪士，何以终九真。","使无佗为君，必当出暑门。","相从子房流，为汉树功勋。","予言二世时，扬粤有梅鋗。","其家在台岭，自言勾践孙。","沛公义兵起，鋗亦奋戈鋋。","户出一壮士，家出一櫜鞬。","领以摇毋馀，踰岭至馀干。","先说鄱阳君，当从沛公西。","芮也豫章人，与鋗桑梓连。","发兵使先行，行至南阳间。","天授得帝子，立谈动龙颜。","遂从破秦关，功为诸侯先。","二周与勾践，雠耻一时湔。","使其相尉佗，不过蛮夷贤。","箕踞反天性，礼义同草菅。","贻笑陆大夫，吕嘉徒周旋。","安得万户封，汤沐梅花田。","我家临番禺，在佗故台端。","孔雀珥门户，离支充玉盘。","翠羽作船䉶，明珠盈衣缘。","奇花与珍木，户牖香翻纷。","苛法苦屠雎，诛求无茕鳏。","桀骏夜出攻，五军血如泉。","生性本陆梁，与嬴有深冤。","龙川乃秦令，讵肯为其臣。","自当踵台侯，大义以雷震。","君归在金精，乃与张女邻。","丽英昔不嫁，芮也徒缠绵。","泠泠石鼓歌，高响流云烟。","君如遇衡山，亦可相婵嫣。","毋怀匹妇谅，褰衣而不前。"]},{"t":"蔡玑先观行堂成有赋","f":"五言古诗","c":["自我来建康，交游得蔡子。","昆弟有四贤，鸾龙人所喜。","叔也新堂成，观行名殊美。","洋洋祖父风，修身自诗始。","敦尔一家言，弦歌日盈耳。","二南与家人，其道相表里。","化物以正风，风从花萼起。","汝曾守塘公，布衣格桑梓。","解橐息斗争，脊令因友悌。","长跪讼者前，依依若同体。","各得金与田，不知其所使。","有子二白贤，益务惇伦纪。","作令先声教，文武为张弛。","潜乎白莲难，不战戢奸宄。","赞画蓟辽军，精明知彼己。","诸将服先几，督师听谗毁。","功可同丘山，言难合乳水。","一麾守云朔，边疆当重委。","至郡即巡行，鸣镝群披靡。","朝猎阏氏营，暮逼胡卢垒。","苍鹰奋郅都，毛血洒千里。","强号亦已诛，正直清西鄙。","噤口有大珰，汗颜复御史。","天私一直臣，未从杨左死。","慷慨南渡初，安危实可倚。","区区职方郎，宁能扫国耻。","画江作鸿沟，君臣忽泥滓。","冠挂司马门，贼臣尝发指。","哀痛抱玉环，艰贞保金矢。","令子济物心，委蛇聊一仕。","才为异代用，俯仰亦知止。","当其宰甘泉，流亡尽耘耔。","正赋辄代输，割肌救疮痏。","秦人麋烂馀，一旦复肥美。","以最得股肱，两郡无鞭箠。","宪府开几时，林中藏玉趾。","白华孝养多，亲串分滫瀡。","利害在乡闾，一身任首尾。","大义虽秋毫，郁若泰山峙。","清浊日沉冥，酒狂亦自拟。","为诗以韬精，悲歌或变徵。","教汝弟与兄，多才无不似。","五经在大春，四海来凿齿。","叔也开谈林，天人探奥旨。","有客齐鲁儒，金声甚条理。","言易先图书，称诗去淫绮。","雅歌何翩翩，和平以受祉。","呜鸟悦同声，菉竹期有斐。","三闾隐士宗，相贻有兰芷。","从兹至岁寒，芳馨长尔尔。"]},{"t":"寿江节母","f":"五言古诗","c":["卫风歌靡他，恒辞贵从一。","春秋诸列女，伯姬固无匹。","自母失所天，艰贞矢永毕。","十五奉罗巾，二十罢瑶瑟。","供养代良人，甘肥机中出。","有时倚柱吟，鲁女同忧恤。","朝上君姑堂，暮入叔姑室。","姑言妇未亡，亦如儿在膝。","皇天悯苦寒，与母以白日。","年今已五旬，鬓发尚如漆。","鞠育一雏鹓，诗书去骄逸。","蟾兔在腹中，月光长盛实。"]},{"t":"河鲀","f":"五言古诗","c":["今岁雨水伤，河鲀人不取。","食之死者多，价贱如泥土。","所因胡蔓子，乘潦落江渚。","河鲀食而肥，其毒益在乳。","乳甘且膏腴，滋味入肺腑。","一脔能醉人，迷乱以无主。","仓皇饮粪清，妻孥泪如雨。","茭塘黄河鲀，产妇云有补。","相戒勿鲜食，去肠用为脯。","醋蒸胜雏鸡，姜桂十之五。","风俗苦嗜之，臭腥遍闾户。","亡命诸渔人，不用张网罟。","河鲀触生钓，一钩辄无数。","腹大似水泡，其性最暴怒。","恶者更板牙，斑斑鳞且羽。","河伯遣杀人，非惟作鱼虎。","口腹人所贱，况乃饱腐鼠。","养小以失大，君子宜审处。","区区此鯸䱌，安足借刀俎。"]},{"t":"镇海楼","f":"古风","c":["渺瀰祝融汪，嘘噏鹑火房。","房中一都会，番禺为纪纲。","二山虽卷石，亦为南岳宗。","层楼何穹然，作冠玉山冈。","五重若棋累，势与云低昂。","屹屹出崇堞，盘基何堂皇。","绝地无根株，茎台四相望。","虚无若蜃气，含吐朝霞中。","日月互穿穴，玲珑贯榑桑。","飞榱袅千尺，悬栋森成行。","随风或远近，岳立仍中央。","神明所凭依，奠我勾蛮疆。","楼南何所见，牂牁浮青苍。","万里作南渎，崩奔从夜郎。","三江汇惊涛，海珠扼其亢。","浮沉一地脯，险若三门当。","潮汐苦相沓，秋咸水益涨。","鱼蟹负阴火，与蚌争胎光。","水怪纷往来，一一交精爽。","番舶逐鳌呿，倏忽非乘风。","帆穿吞舟鱼，自口出中肠。","自谓黑山中，安知非溟洋。","瑰货所委输，辐辏交三城。","小者牛头舶，大者独木樯。","我舰空飞云，莫敢与颉颃。","纷纷白黑艚，视之犹凫跄。","楼北何所见，白云连北邙。","蜿蜒自衡岳，孕精岣嵝峰。","丹台矗鹤舒，石室开龙骧。","菖蒲翳溪路，?簩阴苑墙。","韸韸流花水，郁郁扶荔乡。","地肥宜畜牧，騊駼与羱羊。","鸣箛归紫驼，吹角来黄獐。","水草胜朔漠，甘美无盐霜。","马食多禾苗，湩乳成酒浆。","人头岭已平，沟壑无馀香。","白狐既悲啸，黄狐复跳梁。","人膏作青燐，白昼迷阴阳。","松柏何萧萧，魂魄吹无方。","楼东何所见，扶胥祠谷王。","海口控虎门，诸蛮多梯航。","红毛知荷兰，黑齿惟越裳。","战退鬼楼船，白丹幸无伤。","人鱼既醉饱，洪波为不扬。","断虹一相假，飙然踰零丁。","阴墟庙貌尊，黄木牺牷芳。","百川争东朝，水帝纷来享。","楼西何所见，灵洲砥荡荡。","潮来石门辟，郁水喧鱼梁。","贪泉曰溃决，滔天谁堤防。","仕宦寡廉洁，蹄涔为之殃。","一饮丧吾宝，腥臊德以彰。","不祥兹盗泉，沛然南海放。","生民骨髓尽，为患何时终。","楼上何所见，南戍垂精芒。","五星东井环，越门蒙馀光。","赵佗以偏霸，与汉争雌雄。","客星出牵牛，士燮亦奋兴。","流人纷依归，苟安免夷创。","月食牛女间，刘晟以陨亡。","荧惑入南斗，建德丧其邦。","南斗越司命，自昔多灾祥。","上天苦悬象，占验谁能明。","所希老人星，常见吾闺庭。","寿光盛秋分，俾我尊母康。","再拜向南极，配月如长庚。","长庚何依依，为予当丙丁。","楼下何所见，南武馀离宫。","倔强乃朝汉，朔望兹回翔。","老夫反天性，一州安足强。","椎髻祗自外，窃据诚何功。","苔生呼銮道，草没瘗剑场。","木棉拂绮疏，参差连赭桐。","枝枝女珊瑚，叶叶山凤凰。","粪香越王鸟，衔穗仙人牂。","甡甡茂林下，蹲倚当丹床。","是为罗浮麓，朱明此潜通。","仙灵所窟宅，我来每徜徉。","不揖安期生，即拍浮丘公。","招手登兹楼，揽执云衣裆。","御风复何待，飘飘明将行。"]},{"t":"维帝篇","f":"楚辞体","c":["维帝颛顼裔，周氏相蝉嫣。","食土荆湘邑，屈姓何连绵。","左徒死怀忠，日月在罗渊。","宗臣不去国，恩义同比干。","子孙藏剑佩，世守长沙田。","汉初实关中，昭景同西迁。","族贵称王孙，文采未相宣。","武帝爱离骚，始命淮南笺。","买臣工楚学，能言廿五篇。","三闾之弟子，王逸益精妍。","所恨灵均孙，名姓未有传。","唐时美词藻，只有屈同仙。","千载失宗支，遗书荡如烟。","徒闻宋南渡，我祖从秦川。","抱挟离骚经，肇居番禺偏。","番禺两山连，桂林横大川。","冰霜避炎德，熊罴盘层峦。","神灵所窟宅，形胜亚中原。","少祖拥义兵，力拒元可汗。","言从东莞伯，归命洪武年。","褒勋锡彤矢，作镇临幽燕。","本支在茭塘，世德列朝鹓。","三闾大夫祠，峨峨南澥边。","景差与宋玉，配享蘼芜坛。","女媭之婵媛，岁时祀孔虔。","天问及九章，凄悲被笙弦。","称觞何济济，伐鼓复填填。","女巫献玉琐，姣服若飞鸾。","灵兮黪两螭，云旌来翩翩。","迎之激楚舞，侑以招魂篇。","习射张大侯，中者为神欢。","山谷气巃嵷，樛木缭苍烟。","土膏春既动，禾稼郁芊芊。","聚族二千人，公耕兹墓田。","百果从离支，芬馨充豆边。","龙目酿饮酥，醪者寿多延。","东家笼窗竹，西邻翡翠兰。","中池翔文鱼，孔雀尾斓斑。","皓发四五叟，混茫谈羲轩。","子弟工文辞，风华尚小山。","榕树大十围，流泉应鸣蝉。","百尺木棉花，朱火然高天。","灵境似华胥，淳俗誇桃源。","花落鸡犬静，处处张春筵。","爰从广州陷，我父方言还。","勤王功未成，避世志难宣。","吁嗟蚩尤乱，阊阖纷刀鋋。","湘君沉锦瑟，重华失金銮。","四澥沸鼎镬，九州惊虚弦。","将相妇人衣，崩角穹庐前。","其时歌薤露，吾亲泪涟涟。","龚胜屡绝粒，陶潜时呜弦。","遂筑怀沙亭，背冈带修湍。","岌岌远游冠，卖药东市廛。","增城受丹诀，委蜕从稚川。","正气得所繇，庶几返自然。","嗟予破家产，报国多迍邅。","左持将军头，右揕秦王肩。","虎狼不足刺，生劫酬燕丹。","吁嗟天命衰，脱身出函关。","爰从翟义公，兴师平陵西。","逐日麾金戈，捎星曳红旃。","黄帝驾象车，飞廉挥虹鞭。","一夫先拔木，五丁齐开山。","魑魅纷来战，雷霆相纠缠。","予时当一队，矢尽犹争先。","猛士尽疮痍，一呼皆腾鞍。","手剥太行玃，足蹂阴山豜。","雄虺昂九首，吞人益其肝。","神虬忽失穴，潢污蟠蜿蜒。","不能为国殇，含羞馀空拳。","天方造草昧，养晦为大贤。","鹏运需扶摇，折翼避鹰鹯。","割肉聊自食，毋须膏火煎。","婉彼蛾眉女，瑶瑟中道捐。","大禹方胼胝，遑恤涂山颜。","客获千金殊，乃遭骊龙眠。","英雄不学道，功名安足传。","飘然登太山，长啸摇天门。","鸡呜见澥日，涌出如金盘。","神光腾八极，顿豁鸿濛前。","盘古日九变，玉斧开方圆。","死生如循环，寻之渺无端。","公孙舞双剑，宜僚弄一丸。","鬼出忽电入，兵机获无传。","囊括其雌雄，妙得将将权。","蒲且弯长弓，风胡操龙泉。","卫我归罗浮，省母梧桐间。","凤凰挟其雏，羽仪九苞妍。","一鸣圣人生，再呜泰阶平。","此身非血肉，五岳共乔骞。","庶几鞠育恩，少报罔极焉。","弟妹未婚嫁，夙夜亦怀仙。","寡兄奉为师，冥探太素言。","梁鸿尝牧豕，弄玉思骑鸾。","织缣为亲衣，采薇为亲餐。","甘瓜抱苦蒂，骨肉相夤缘。","自谓依庭闱，没齿同贞坚。","何意鲜飙激，孤雁吹飞翻。","日月有盈亏，吾生遑得閒。","挥涕出门去，斯民方倒悬。","事亲贵养志，治国若烹鲜。","乘彼太清霞，白鹿何娟娟。","尘垢铸尧舜，羽翼凌绮园。","御世有操纵，六辔如琴然。","四夷若牛马，累累受拘牵。","东游寒风阙，西戏昆崙巅。","足性自无待，横流一手援。","回顾乡闾中，萧萧桑梓寒。","仲尼怀疾固，思归修遗编。","百川朝沧溟，清浊必还源。","北斗天中央，周流光不偏。","姑射以神凝，使民庇厉蠲。","苏耽能反本，化为黄鹄旋。"]},{"t":"咏古 其一","f":"五言古诗","c":["日月镜万方，精华在君子。","一虚而一盈，以我为终始。","包牺至纯厚，画卦顺斯理。","神明所旁通，日月乃文字。","平生好学易，精微性所喜。","未得大过无，皤然已老矣。"]},{"t":"咏古 其二","f":"五言古诗","c":["黄帝与重华，在昔皆远游。","翩翩挟妃女，翱翔穷九州。","黄山有丹台，梧野有珠丘。","故都终不归，宫阙随云流。","帝生实神灵，仙道未尝求。","无为合坤乾，禅受如春秋。"]},{"t":"咏古 其三","f":"五言古诗","c":["神尧爱二女，尽以归重华。","长者为女君，容颜如朝霞。","少者为夫人，亦若扶桑花。","袗衣破南风，琴歌何纷葩。","朝同蓬莱宫，暮去潇湘涯。","帝既崩苍梧，妾亦捐长沙。","神光两不离，月以日为家。"]},{"t":"咏古 其四","f":"五言古诗","c":["管蔡殷遗臣，忘亲以徇国。","武庚志中兴，忠孝皆可则。","天命已去殷，报雠终勿恤。","如何微与箕，弗往为羽翼。","凄酸麦秀歌，迷民泪沾臆。","故都遂丘墟，徬徨亦何极。"]},{"t":"咏古 其五","f":"五言古诗","c":["秦缪伐西戎，开地千馀里。","天王贺金鼓，攘夷甚光美。","用谲得繇余，遂以霸西鄙。","不忍舍良臣，收之同穴死。","身没犹爱才，泉下须辅理。","哀哀黄鸟诗，岂足知君子。","杀身殉令名，兼以报知己。"]},{"t":"咏古 其六","f":"五言古诗","c":["之推昔从龙，割肌啖其口。","文君既升云，泥处功不有。","此身得全归，绵上偕慈母。","隐者焉用文，躬耕日胼手。","环山作汤沐，报德恩良厚。","介山高入云，伫望以永久。"]},{"t":"咏古 其七","f":"五言古诗","c":["王蠋能存齐，功与安平似。","义激亡大夫，相聚求王子。","一言作战气，燕军尽披靡。","布衣不北面，在位宁无死。","徇国成功名，为齐复伦理。","襄王得立时，封爵乃忘尔。"]},{"t":"咏古 其八","f":"五言古诗","c":["湘累泽畔吟，亦似秦庭哭。","同怀宗国心，夙夜忧倾覆。","自古楚贤才，二君最贞淑。","忠爱格上天，大仇终报复。","三户即三闾，亡秦在公族。","义帝虽不终，诸侯尽臣仆。","汉兴离骚显，楚声被丝竹。","高帝歌大风，夫人和鸿鹄。","皆是离骚馀，哀乐同敦笃。"]},{"t":"咏古 其九","f":"五言古诗","c":["相如睨柱时，勇气一何激。","一璧虽轻微，如以国与敌。","渑池相高会，盘瓶使秦击。","颈血得溅王，闻言尽悚惕。","威信虎狼秦，御史书功绩。","知死则必勇，智士以为的。"]},{"t":"咏古 其十","f":"五言古诗","c":["骐骥盛壮时，一日驰千里。","臣精今消亡，衰老讵可使。","自杀送荆卿，激之为丹死。","燕中节侠多，无能救太子。","狗屠与渐离，不请非知己。","击筑和歌时，相位徒为尔。","平生游诸侯，所结贤豪士。","曷不待须臾，仓黄挟竖子。","慷慨为羽声，壮士发尽指。","悲风何萧萧，吹泪成寒水。"]},{"t":"咏古 其十一","f":"五言古诗","c":["维昔二周君，皆以诛秦亡。","大义帅诸侯，王朝亦有纲。","惜哉无良将，九鼎归咸阳。","是时秦亦灭，嫡裔止庄襄。","政也实奸生，吕代嬴氏兴。","二世不旋踵，赵高撼其吭。","前秦祖蜚廉，后秦祖文信。","无德易颠覆，虎狼总推刃。","诗书亦何罪，儒生同一烬。","痛绝骊山坑，多言说尧舜。"]},{"t":"咏古 其十二","f":"五言古诗","c":["徐福入海中，将以求神异。","三千童男女，五谷工师备。","西皇资以行，持为海神赐。","行行得平原，膏腴可兴利。","振子尽妃匹，留王何神智。","福也非神仙，救民有奇意。","诈之出汤火，三千诚不易。","传今东海中，亶州是其地。","相连数大洲，波涛人罕至。","自作一蓬莱，以为祖龙戏。","为仁亦滑稽，自是神仙事。"]},{"t":"咏古 其十三","f":"五言古诗","c":["峨峨太华山，上有四毛女。","苟非逃学仙，从死成黄土。","光光人鱼膏，泉下照歌舞。","泪作水银海，肠为黄金缕。","秦时女高士，丽英与为伍。","翩翩金精峰，相逐有毛羽。"]},{"t":"咏古 其十四","f":"五言古诗","c":["陈涉奋布衣，遂成士崩势。","偏袒一大呼，秦已无二世。","匹夫举大名，汤武若符契。","扶苏虽当立，诈称亦非计。","将诛无道秦，师行宜大誓。","成败在上天，西向乘锋锐。","毋示天下私，自王以微细。","为秦多益敌，六国蒙嘉惠。","入关令诸侯，功德可为帝。"]},{"t":"咏古 其十五","f":"五言古诗","c":["鲁儒抱积怨，发愤于陈王。","艰难负礼器，卒与涉俱亡。","匹夫苟建义，瓦合亦非尝。","礼乐所凭依，缙绅为之倡。","涉亦圣人徒，能知孔鲋良。","先置博士官，以甲为纪纲。","用人先诸儒，文学已有光。","惜哉昧行兵，破灭成苍黄。"]},{"t":"咏古 其十六","f":"五言古诗","c":["仓海君何人，家能畜力士。","金椎误中时，秦王魄已褫。","报雠虽未成，天下兵以起。","功为陈项先，豪俊闻皆喜。","贼在下邳中，无人言孺子。","从容得步游，任侠惊闾里。","老人教强忍，命之下取履。","岂有王者师，而为血气使。"]},{"t":"咏古 其十七","f":"五言古诗","c":["不忍杀沛公，使之得天下。","英雄有至情，难忘妾与马。","亡我实繇天，知命乃无假。","慷慨泣数行，实为红颜者。","王霸如浮云，功名羞苟且。","仓皇垓下歌，直可继骚雅。","斯是国殇篇，三军和者寡。","悲风起帐中，杀气横原野。","河汉惨无光，痛饮过三斝。","自刎报父兄，江东泪同洒。","善败能从容，功亦在区夏。"]},{"t":"咏古 其十八","f":"五言古诗","c":["荥阳诸女子，功与纪信似。","夜出冒楚围，披甲为战士。","楚军似刈刍，血流作渠水。","君王既无兵，妇女相驱使。","幸有三千人，可以代披靡。","楚军虽受欺，流涕亦不止。","妾命甘如尘，得无大王耻。","自古战争中，国殇宁有此。"]},{"t":"咏古 其十九","f":"五言古诗","c":["淮阴不悖汉，忠信天下知。","可惜智绝人，乃为儿女欺。","当帝至楚时，淮阴能识几。","相携钟离昧，逃于东海湄。","弃王如敝屣，神龙不受羁。","远追范大夫，近为留侯师。","岂非明哲者，超然有道姿。"]},{"t":"咏古 其二十","f":"五言古诗","c":["汉帝亦多情，酒酣思猛士。","悽悲大风歌，辞与招魂似。","韩彭皆已亡，慷慨不可止。","泣下为淮阴，非是悲游子。","刻薄钟室诛，终古帝王耻。","忍以英雄人，以与儿女子。"]},{"t":"咏古 其二十一","f":"五言古诗","c":["汉高诸功臣，项伯谁能似。","次则昌国君，能全王父子。","大封诸侯王，亦及一雍齿。","如何忘荥阳，纪信代之死。","君王恩谊高，岂以诈降耻。","荥阳与平城，得脱以女子。","仓皇秉黄屋，诳楚一何鄙。"]},{"t":"咏古 其二十二","f":"五言古诗","c":["陵母何慷慨，一死如田光。","激子成功名，始终事汉王。","丈夫有侯嬴，妇人有陵母。","烈烈汉功臣，乃在一箕帚。","教子以忠贞，令名在人口。","天下既定时，陵封宜勿受。","请以母为侯，汤沐及诸舅。","伏剑墓门前，黄泉期速朽。"]},{"t":"咏古 其二十三","f":"五言古诗","c":["季布多战功，数能窘汉王。","摧刚以为柔，得脱因濮阳。","朱家不相负，名声闻四方。","滕公非任侠，为汉求忠良。","从容为上言，私怨以之忘。","廷叱樊将军，十万罢横行。","辞气何刚直，殿上皆惊惶。","天下虑摇动，生民尚痍创。","嫚书禽兽言，安足争短长。","孝惠至高后，兵革久不兴。","实以季布力，海内得宁康。"]},{"t":"咏古 其二十四","f":"五言古诗","c":["季心为任侠，气盖关中儿。","弟畜灌将军，兄事惟袁丝。","杀人乃恭谨，赴义如渴饥。","壮士争为死，肝胆诚吾师。","十载持大黄，乃为豺虎欺。","智勇不足恃，遑遑将何之。","龙蛇日起陆，天方发杀机。","闭门造奇器，阴阳相推移。","北斗有天枢，握之谁能知。"]},{"t":"咏古 其二十五","f":"五言古诗","c":["叔孙诚圣人，能知世要务。","先言诸大猾，以为爪牙布。","汉王方虎斗，矢石宜争赴。","诸生岂能兵，群盗知有素。","短衣变楚制，毋使大王怒。","道亦尚委蛇，希世非无故。","当时谀二世，虎口脱危惧。","狗盗安足忧，守尉自能捕。","斯言诚滑稽，阴已亡秦祚。","直谏亦有时，国奉以坚固。"]},{"t":"咏古 其二十六","f":"五言古诗","c":["马援处田牧，有羊数千头。","一朝散昆弟，简君聊遨游。","光武非人敌，委身倾阴谋。","为君取隗嚣，聚米成山丘。","移师灭先零，转战平交州。","男儿有汗血，自当死戈矛。","马革包馨香，云台垂勋猷。","悲哉武溪深，三军泣箜篌。","水崩船不上，凄凉卧壶头。","用兵贵万全，涂有所不繇。","据鞍徒顾盼，一挫失通侯。"]},{"t":"咏古 其二十七","f":"五言古诗","c":["乾坤造草昧，狗盗方争雄。","干将不善割，势与铅刀同。","少小习兵书，慷慨气如虹。","沈算贵先机，羞为汗马功。","龙腾阶尺木，鹏运须长风。","冉冉岁云徂，衰鬓如飞蓬。","王业尚无始，天心鲜有终。","凄凄梁父吟，感叹将何穷。"]},{"t":"咏史赠杨君","f":"五言古诗","c":["张耳从汉高，实用甘公说。","任嚣志偏霸，亦以天文决。","五星射越门，光气分隆准。","甘公言一倡，诸侯尽心折。","圣汉以龙兴，功可齐人杰。","君今治天官，言星复明哲。","手执大人符，机祥虑先泄。","观文以察变，吾尝求五列。","元气斟酌之，欲将斗柄揭。","三易有洞玑，微言幸未绝。","与君为天数，阴阳受开闭。","灾异谨大书，忧患惟崩竭。","天监岂无知，云汉光尚彻。","牵牛终服箱，南箕将失舌。","织女多文章，经纬资吾拙。","君且引兕觥，俯仰毋悲咽。"]},{"t":"赠邳州季生","f":"五言古诗","c":["中原何汹汹，英雄日棋跱。","香饵引泉鱼，重币购壮士。","嗟君勇绝伦，昆吾犹未试。","入猷而出铃，中道伤捐弃。","侥倖成功名，王侯久丧耻。","盗蹠脍人肝，仲尼不敢视。","悲哉圣人才，甲兵成虚器。","游鱼脱深渊，飞鸿戾天际。","贫贱聊娱怀，敦我箕山志。"]},{"t":"猛虎行","f":"五言古诗","c":["边地不生人，所生尽奇畜。","野马与骆驼，騊駼及驼鹿。","羱羊千万头，人立相抵触。","上天仁众兽，与以膏粱腹。","变化成猛虎，食尽中土肉。","哮吼一作威，士女皆觳觫。","广南人最甘，肥者如黄犊。","猛虎纵横行，餍饫亦逐逐。","朝饮惟贪泉，暮依惟恶木。","人皮作秽裘，入骨为箭镞。","人血充乳茶，脂膏杂红曲。","子狗有爪牙，攫搏苦不速。","恶性得自天，牝牡日孳育。","在天为贪狼，在地为荤粥。","人类日已尽，野无寡妇哭。","隆冬不患饥，髑髅亦旨蓄。","多谢上帝仁，猛虎享天禄。","为兽莫为人，牛哀得所欲。"]},{"t":"橐驼行","f":"五言古诗","c":["橐驼生一女，不肯与之乳。","羌儿谓橐驼，恩薄乃如许。","女亦肉为鞍，女亦力如虎。","重能驮帐房，可眠我妻女。","屈足受重载，万斛如鸿羽。","中国奇畜稀，肿背人争取。","牝牡不用分，独峰亦爱汝。","泉脉每能知，跑地水如缕。","青海热风来，先鸣报行旅。","粪烟直上时，望似狼烟举。","有时亦人立，两脚相支拒。","夏至虽退毛，封牛谁敢侮。","橐驼且自欢，听我兜离语。","我鼓大琵琶，一曲为而舞。","橐驼知音声，湩流复如雨。","饱饫橐驼儿，蹄峰免刀俎。"]},{"t":"古鼎篇为邓丈作","f":"五言古诗","c":["君子有宝鼎，神光出重渊。","先王与先公，手泽所盘旋。","得自少昊墟，鲁侯世相传。","地不爱重器，以君能奉先。","亨可享上帝，岂惟祖祢贤。","木火命已凝，腹中有纯乾。","神灵所凭依，洋洋在豆笾。","摩挲阴阳文，隐若蛟龙缠。","皇天鉴仁孝，馨香贻万年。","耳目咸聪明，金玉贯无偏。"]},{"t":"赠阳春令","f":"五言古诗","c":["达人志济物，而不卑一邑。","春州古瘴乡，膏泽乃先及。","王孙学道姿，手尝圭璋执。","赋诗多土风，声教有篇什。","美刺何温柔，如春无不入。","讼庭无人时，群山相拱揖。","为养若寒泉，人人得自汲。","空桐有岩穴，风云互嘘噏。","阴为石乳凝，阳作天柱立。","我昔攀诸峰，猿狖颇相习。","图经撰未成，幽怪多捃拾。","君于簿书馀，新志已在笈。","声色虽可娱，神明期厚集。","交广有春秋，乘时更补缉。"]},{"t":"夜上漓江作","f":"五言古诗","c":["水落滩更高，我船苦难上。","舟子声凄酸，榜歌不能唱。","天寒白雾深，川路迷苍莽。","山月忽西东，愁人苦相向。","霜气一冬乾，水声半夜长。","衣食分熊罴，无金士难养。","久戍尽黧黑，绝地无盐酱。","所历州县多，牛酒有谁饷。","微闻沙中语，军穷生怨望。"]},{"t":"送梁药亭北上","f":"五言古诗","c":["南为天之阳，其人多文明。","精神得日月，变怪成文章。","朱火所沐浴，一一含珠光。","蔽亏牂牁海，照曜祝融宫。","朱明一洞穴，阴与衡岳通。","祝融亦水帝，来治临扶桑。","文章作司命，吾党所大宗。","炎德在辞华，明明烛四方。","云汉同昭回，朱鸟分光芒。","始自洪武初，五星会文昌。","海隅作邹鲁，白沙应其祥。","弟子王佐才，冠以梁文康。","不草威武诏，以臣名君王。","秦藩却请地，正直持天纲。","忠谟动武庙，相业高始兴。","兰汀乃族孙，扬葩继后行。","艺林尊正朔，风雅何铿锵。","其笔女珊瑚，其墨黄金珰。","写用鲛人绡，薰以鹤顶香。","奇丽掩中原，郁为日南英。","与师泰泉公，大小皆凤凰。","君今同一本，峨峨南海梁。","明月出琼蚌，朝霞吐神龙。","丹山无凡羽，桂林多奇芳。","六经乃神器，羽翼不敢忘。","逝将嗣先美，令名流玉堂。","努力就计偕，上书惊公卿。","同里霍与伦，亦可相翱翔。","伊予为隐夫，未能垂素功。","研精在神化，徒欲参羲皇。","著述虽满籯，不如君秕糠。","及早得志归，求我乎混茫。"]},{"t":"玉虚宫夜作","f":"五言古诗","c":["北辰垂大象，造化实枢机。","吐纳天中黄，群星蒙光辉。","真气贯我身，洪荒如盘羲。","清宵事禹步，斗路无端倪。","灵风吹羽裾，飘飖将安归。","天回九地转，彷佛乘龙螭。","嗟彼世间人，神珠弃污泥。","变诈成功名，英雄诚小儿。","何如长桑君，长咏还虚辞。"]},{"t":"送家舍人","f":"五言古诗","c":["白云何蓬蓬，朝别岱山中。","岂不念本根，仙人在崆峒。","似君久流离，万里思从龙。","天心未厌祸，颠沛将焉穷。","厉夜得宝剑，安知雌与雄。","雄能制诸将，雌亦至三公。","赠君及壮年，往取留侯功。"]},{"t":"古意 其二","f":"五言律诗","c":["夷光有宝镜，沉在若邪溪。","朝霞沐其彩，明月扬其辉。","春秋迭代谢，菱花终不萎。","安得佳丽人，持将照蛾眉。"]},{"t":"古意 其三","f":"五言律诗","c":["落花辞故枝，飘零逐溪水。","道逢浣纱人，拾花置怀里。","与君同春荣，相怜贵终始。","但愿东风吹，长堕机中绮。"]},{"t":"古意 其四","f":"五言古诗","c":["凄凄岁云暮，蟋蟀呜堂隅。","场苗不可食，谁当维白驹。","伊昔采桑女，窈窕秦罗敷。","银钩挂柔条，绿蕤映罗襦。","托心自有所，但笑使君愚。"]},{"t":"咏怀 其一","f":"五言古诗","c":["瑶琴欲高张，角弓贵持满。","至人漱正阳，神明日三浣。","驾言陟天孙，揽啸迎风馆。","明月升娥光，鲜霞流玉盌。","逢君安期子，相求何嬿婉。","至道如膏粱，厌饫世所罕。","秦皇不可说，怀策自萧散。","抚节一悲歌，时逝将奈何。","玄霜杀百卉，积石扬洪波。","宁无鲁阳德，回日扶桑柯。"]},{"t":"咏怀 其二","f":"五言古诗","c":["峨眉有仙人，颜如皦日光。","蜿蜒御双龙，云气四飞扬。","朝游蓬莱山，暮归太微堂。","天命自流行，混沌居中央。","我为德充符，万物皆无伤。","窅然丧天下，乃能应帝王。"]},{"t":"咏怀 其三","f":"五言古诗","c":["条风拂樱梅，翠羽鸣参差。","昊天爱万物，飞植各乘时。","如何苦贫士，鬒发成素丝。","幽兰生谷底，朝阳无见期。","渴饮坚冰浆，饥掇丹林荑。","苟非含道腴，安得好容姿。"]},{"t":"咏怀 其四","f":"五言古诗","c":["惊风鼓松柏，栖鸟群翻飞。","开门望行人，浮云暮不归。","种桃爱其葩，种柳爱其枝。","虽无岁寒用，夙昔同裳衣。","鱼目乱火齐，蟾蜍蚀清晖。","遂令金石交，千里相乖违。","拔剑击盘石，石碎剑亦亏。","感激将何言，泪下空涟而。"]},{"t":"咏怀 其五","f":"五言古诗","c":["仙人骖文螭，西游阆风阙。","神珠藏九渊，变化如日月。","顾见世间人，声色自沉没。","仲尼居九夷，至道当谁悦。","哀哉人命危，蜉蝣伤掘阅。","兹时方板荡，匡济需贤哲。","列宿在草莽，紫薇光彷佛。","天钟运筹人，何时见功伐。"]},{"t":"咏怀 其六","f":"五言古诗","c":["鼷鼠潜神丘，鹓雏集高枝。","区区保性命，二虫曾何知。","哲人无死地，所至福履绥。","以兹七尺身，为君作蓍龟。","赴义不返顾，成仁无推移。","天狼纷下食，中土为肉糜。","予为民请命，大呼起疮痍。","事成天地悦，事败鬼神悲。","乘道而浮游，无须驾鸾螭。","妻孥乃敝屣，已矣从此辞。"]},{"t":"咏怀 其七","f":"五言古诗","c":["兰丛盛枳棘，凤穴邻鸱鸮。","利害日相摩，金石为之焦。","仲尼探虎口，蹠也方矜骄。","仁义为盗积，天下谁宗尧。","驱车以放志，言观东海潮。","波涛飞雪山，河汉垂天桥。","蛟龙隐文章，尾闾水潜消。","宁无百尺丝，吞饵惟游鲦。","白云来何迟，俯仰托长谣。"]},{"t":"咏怀 其八","f":"五言古诗","c":["蓬头诸剑士，飒飒曼胡缨。","十步杀一人，虽勇无功名。","我有轩皇书，阴阳为甲兵。","道大难为容，浮沉伤中情。","大盗为诸侯，卞随久捐生。","神龟婴余且，驺虞五鼎烹。","利器乃假人，天下何繇平。","悠悠羲农初，无为孰与京。"]},{"t":"咏怀 其九","f":"五言古诗","c":["庖人烹赤鱼，鱼尾何离筛。","风雷起神鼎，俄然摩天飞。","冠霞登紫宫，骖鹿上兰池。","遨游经四澥，回顾伤黍离。","潜龙贵勿用，秕糠为帝师。","至道久蝉蜕，七圣莫能知。","悠悠具茨云，吹笙何参差。"]},{"t":"咏怀 其十","f":"五言古诗","c":["王母有小女，其名为婉罗。","教我玉胎篇，俯仰餐太和。","玉颜争皦日，吐词如鲜葩。","神明所膏沐，物物成丹砂。","还开偃月炉，纯阳生紫芽。","合散皆文章，一气如朝霞。","神仙多诙谐，与龙为变化。","出入太无中，真道苦不华。","哀彼世路人，白发空婆娑。"]},{"t":"咏怀 其十一","f":"五言古诗","c":["山人酌流霞，浮杯菖蒲溪。","笑我不肯饮，容颜无光辉。","桃花恃春阳，松柏有霜威。","白云多变化，讵随鸿鹄飞。","请谢阴长生，何恋紫房为。","吾心似秋月，皎洁谁能知。"]},{"t":"咏怀 其十二","f":"五言古诗","c":["芳风起池塘，花逐鸳鸯飞。","明月何娟娟，为君扬蛾眉。","请弹石上琴，更酌黄金卮。","蓬莱水已竭，麻姑鬓成丝。","芙蕖自有英，何慕松楸为。","松楸凌霜雪，虚名将安归。"]},{"t":"咏怀 其十三","f":"五言古诗","c":["危冠切青霞，长裾扫八裔。","我岂学游仙，逍遥自无外。","日月在掌中，收来有六辔。","顾谓王子乔，至道须神契。","四海如镜明，何劳去昏翳。"]},{"t":"咏怀 其十四","f":"五言古诗","c":["溪谷何多风，猿猴鸣相追。","兔丝无断绝，百尺绿松枝。","调琴苦弦急，望远苦心悲。","断发逃荆蛮，三载不得归。","岂无骨肉亲，金尽天性亏。","世路皆太行，履道吾何之。","神鸾冲高天，毋使鸒鸠欺。"]},{"t":"咏怀 其十五","f":"五言古诗","c":["方朔乃岁星，游戏柏梁台。","王侯若草芥，啸傲凌松崖。","招摇履为綦，沧海持为杯。","既笑首阳拙，复卑柳下才。","专气而致柔，与世为婴孩。","予亦韩终流，骖鹿相徘徊。","千年鍊金骨，双髻象蓬莱。","安用天下为，逍遥以无怀。","飞龙擘河汉，驽马沦尘埃。"]},{"t":"咏怀 其十六","f":"五言古诗","c":["阴阳迭迁谢，人世悲蜉蝣。","命我云螭驾，逝将登不周。","饥餐苕华玉，寒披九凤裘。","井水无大鱼，新林无长楸。","纷纷彼妇口，乃为君子羞。","鲍焦已槁死，强嬴吞诸侯。","伤哉仁义衰，奸雄皆窃钩。","仲尼无斧柯，龟山空夷犹。"]},{"t":"咏怀 其十七","f":"五言古诗","c":["九州何茫茫，吾独哀无女。","绥绥涂山狐，九尾难与处。","服我琼琚衣，鸣琴临北渚。","湘妃虽目成，自媒非所许。","盈盈匏瓜河，兰荪媚平楚。","怀修追有鳏，褰裳聊容与。"]},{"t":"咏怀 其十八","f":"五言古诗","c":["朝露畏太阳，高梧忌秋霜。","嗟尔绮纨子，欢乐焉能长。","势利一浮云，人命如流光。","人鬼互相代，谁能出阴阳。","放志以遨游，行行至太行。","车马屡倾覆，我心终不伤。","高鸟凌霄飞，日月在其旁。","荣名非所慕，保此岁寒芳。"]},{"t":"咏怀 其十九","f":"五言古诗","c":["初日丽垂杨，朱楼临大路。","纤纤彼女手，当户裁纨素。","雍雍雁南游，遗音落沧州。","美人耻歌舞，箧笥叠衣裘。","衣裘有时著，孟冬清霜落。","皎皎蕣华姿，岁寒逾绰约。","道胜忘纷华，心游贵恬汉。"]},{"t":"咏怀 其二十","f":"五言古诗","c":["玄黄何烟煴，尘埃间白云。","含此苕华姿，独行无与群。","天鉴讵孔明，玉石郁未分。","兔丝织为衣，燕麦持为飧。","冻馁不能语，为节何艰辛。","驽马食龙刍，一日成骐驎。","曜灵不弃予，屋漏垂阳荐。"]},{"t":"咏怀 其二十一","f":"五言古诗","c":["鸿鹄何苍茫，背负青天飞。","白波捲沧海，声如鬼神驰。","予时弹雅琴，成连嗟不归。","回风翻木叶，斜日悬江矶。","凄凄水仙吟，中曲断朱丝。","四望悄无人，天吴方躨跜。","神物有变化，至人能推移。","拔山岂无力，枭雄吾不为。","慷慨发冲冠，伤哉失路悲。"]},{"t":"送妹 其一","f":"五言古诗","c":["翩翩东海燕，衔彼棠棣华。","我生鲜兄弟，乡闾尝咨嗟。","令妹圭璋姿，教诲荷亲慈。","采桑提玉筐，织素呜春机。","纤纤彼女手，朝夕供甘肥。","青春日载阳，雎鸠差池飞。","家贫不终养，临别泪涟而。","虞舜耕历山，伯瑜披綵衣。","嗟予弃人爵，与亲聊餔糜。"]},{"t":"送妹 其二","f":"五言古诗","c":["青阳属令辰，来雁鸣雍雍。","朝云媚桃李，乳燕栖房栊。","窈窕彼君子，佩玉乘青骢。","朝为孤鸳鸯，暮作双飞龙。","子怀在高逸，偕隐宜梁鸿。","絺绤胜鲛绡，荆簪玳瑁同。","箱帘无宝玩，图史盈其中。","芳颜匪膏沐，令德惟温恭。","先人箕颍流，黾勉追素风。"]},{"t":"黍谷","f":"五言古诗","c":["步出铜马门，遥望大房山。","幽燕有奥室，鬼神潜其间。","群峰郁㟏岈，溪流何潺湲。","猛虎飞食人，长啸随风还。","凝冰折林木，玄云蔽河关。","维昔邹衍生，悬河此谈天。","一为吹黄钟，幽谷春阳旋。","至人御六气，呼吸走百川。","是非总天籁，悠悠诚何言。","天下久忘我，无劳烹小鲜。","泽雉有饮啄，优游聊终年。"]},{"t":"出永平作","f":"五言古诗","c":["洪河无停流，惊枝无栖翰。","志士生乱离，七尺敢怀安。","青萍不刈黍，明月宁沉渊。","断袂别亲友，成败俱不还。","诛秦报天下，一死如泰山。","宝马与美人，乌足酬燕丹。","驱车出卢龙，迢递度渝关。","二水交滦漆，千峰连贺兰。","征蓬自回转，去雁群飞翻。","悲歌吊飞将，声振长城间。","猛虎为我啸，玄猿为我叹。","奚儿动成群，箜篌对月弹。","弥令远游子，侧听心哀酸。"]},{"t":"登轩辕台作","f":"五言古诗","c":["边风起蓟门，黄云高嵯峨。","予登轩辕台，四望发悲歌。","哀哉帝王都，城阙如丹霞。","朝阳开露掌，阊阖摇金波。","碣石悬天柱，桑乾接银河。","真人兹建极，亿载讵云多。","谁令羽林儿，一旦倒长戈。","逼遥关塞路，朝暮驱橐驼。","橐驼安所负，美人如桃花。","凄凄当落日，莽莽扬风沙。","龙髯攀莫及，玉女舞婆娑。","天庭方晏乐，宁知予咨嗟。"]},{"t":"出塞作","f":"五言古诗","c":["边秋多风沙，狐兔长悲鸣。","慷慨思奢牧，因游雁门营。","饥食太行薇，渴饮桑乾冰。","问我亦何为，壮士不顾生。","生骑一骏马，权奇如龙媒。","追风数千里，直上单于台。","东望朝鲜江，北望白龙堆。","凌飙发长啸，游兵射我来。","左手接飞镝，右手挥金鞭。","驰归锦州城，汗下如流泉。","念此血气勇，毋乃非圣贤。","忍耻古所尚，留侯亦迍邅。","长松寒逾劲，南金锻弥坚。","启箧读秘书，聊谢诸少年。"]},{"t":"凝渡三岔河有寄","f":"五言古诗","c":["辽东苦寒地，十月河已冰。","我从辽西来，驱马冰上行。","回望巫闾山，千里阴气凝。","明月出黑澥，苍茫照孤征。","疑兵四面来，但闻觱篥声。","行行迷失道，误入骨都营。","饥渴向妖姬，乞得驼馀羹。","马乳饮苦酸，鱼皮衣苦腥。","神龙困蝼蚁，勺水不能兴。","凤鸟失其群，见辱海东青。","因怜雪窖中，持节有子卿。","题书托飞雁，双泪如雨倾。","安得同携手，以解流离情。"]},{"t":"赠远","f":"五言古诗","c":["美人如花飞，玉佩冰绡衣。","长风吹欲堕，揽带前相持。","问子游何处，笑含碧云姿。","言我华阳来，将从勾曲栖。","麻姑久相待，去去与我辞。","语卿且莫辞，我有芙蓉池。","鸳鸯戏碧叶，翡翠巢金枝。","愿将天上月，长照双蛾眉。"]},{"t":"采菖蒲作","f":"五言古诗","c":["菖蒲何葑茸，郁生南涧曲。","三花凌紫烟，九节削青玉。","采采临寒泉，因以濯吾足。","死生虽已齐，长年亦所欲。","仙人安期子，与尔聊餐服。"]},{"t":"赠友人 其一","f":"五言古诗","c":["英雄耻割据，拂衣游江湖。","我为沉水香，君为博山垆。","紫烟扬光彩，丹成凌仙都。","仙都虽宴乐，苍生嗟未苏。","红旗如云霓，锦带曳芙蕖。","利剑在掌中，出入风雷驱。","萧曹刀笔吏，项羽乃匹夫。","苟能拯水火，何辞七尺躯。","王侯如敝屣，山林堪长娱。"]},{"t":"赠友人 其二","f":"五言古诗","c":["悲风振宿莽，贫士方寒饥。","悠悠天上云，长借明月辉。","嫫母已衣锦，南威长刈葵。","乔松生路傍，不如彼薋葹。","弹我丘中琴，彷佛孤鸾飞。","落花如美人，翩翩来何迟。","仰视云间星，牵牛光独微。","淑慝不同涂，盈虚良有时。","慎矣怀道符，颍阳以为期。"]},{"t":"赠友人 其三","f":"五言古诗","c":["灼灼怀春鸟，衔花吴江浔。","玄豹久不食，蔚然文采深。","风云荡天路，邂逅抒忧心。","凭君青玉案，中夜张瑶琴。","明月照南浦，晨风巢北林。","河精为天汉，小星易浮沉。","妙道贵忘言，达人无哀音。","持此箕颍怀，聊以答所钦。"]},{"t":"赠友人 其四","f":"五言古诗","c":["樛木不下垂，甘匏安所依。","嗟君富无骄，乃与黔娄期。","黄流在玉瓒，大德在蒲衣。","佻佻彼公子，安知天爵为。","今时方丧乱，群盗争雄雌。","授子以丹书，揣摩为帝师。","神龙尚可醯，骏马亦可羁。","至人与天游，虚无谁能知。"]},{"t":"赠友人 其五","f":"五言古诗","c":["煌煌我上天，照此豺虎骄。","我无戈与矛，何能入山樵。","石溪流溅溅，蘋萍随风飘。","游鱼畏鹈鸪，神龙乐波潮。","仙童颜姣好，迎我双琼箫。","东游扶桑阙，西渡绛河桥。","至道非无形，如月悬中宵。","揽之盈玉手，欲赠彼娇娆。","人生如电影，千载不崇朝。","念彼牛山涕，乘化且逍遥。"]},{"t":"赠山阴祁七","f":"五言古诗","c":["凉风吹竹筱，携手澄湖滨。","言持芙蓉花，插尔华阳巾。","我亦浣纱人，明妆照日新。","何当上苏台，一笑倾吴君。","明月岂长满，朱华不再春。","徒怀阳阿曲，寂寞度芳辰。"]},{"t":"送朱十","f":"五言古诗","c":["昨冬冱寒时，方舟同入越。","君望赤城霞，我弄耶溪月。","月出香垆峰，光摇东海雪。","美人吹紫箫，一曲梅花发。","梅花犹满林，君唱怀归吟。","未游云门寺，遽别天姥岑。","可怜双白鹤，相送吴江浔。","冉冉芳春晚，桃李皆成阴。","贫女无刀尺，谁裁鸳鸯衾。","素丝亦易染，孤凤难为音。","愿言秉贞洁，黾勉同我心。"]},{"t":"送王屋","f":"五言古诗","c":["神螭方鱼服，美玖藏沙尘。","英雄未遇时，状貌如妇人。","赠尔双吴钩，中有爱子魂。","君王雠未报，岂敢顾所亲。","挫蘖调君酒，送送灞陵津。","皦日照河水，悲风激车轮。","去矣毋多虑，男儿自有神。"]},{"t":"答谭非庸 其一","f":"五言古诗","c":["嗟予遘阳九，不得全天形。","接舆已髡首，桑扈亦裸行。","兰草非人锄，鸾皇乃自烹。","念君意气存，禦侮如干城。","小人箕其舌，君子渊无声。","经德不可回，相将保千龄。"]},{"t":"答谭非庸 其二","f":"五言古诗","c":["黍苗何离离，雉雊求其妃。","咨予久独立，幽兰为薋葹。","今天降蟊贼，王事艰且危。","膂力君方刚，经营愿相资。","欲猎为呼鹰，欲战为骖骊。","骖骊何彭彭，西北开龙荒。"]},{"t":"寓山园吊祁忠敏公","f":"五言古诗","c":["园林午澄霁，左右芙蓉披。","浮舟弄清暾，遂至镜湖湄。","阳涯云方散，阴峰露未晞。","再拜清泠渊，泪下沾裳衣。","吁嗟怀沙人，守道无委蛇。","筑宫水中涘，兰橑莺粟楣。","金峦开彩翠，玉溜滴葳蕤。","方怀安石赏，遽与彭咸期。","皇舆已败绩，发肤何以为。","浩歌赴长湍，溯洄从九嶷。","容与凌明霞，触石体不隳。","怒潮为安流，靡濡鱼鳞衣。","我祖维灵均，冠剑郁陆离。","夫君交手去，重华以同归。","玄烟横极浦，冲风激寒澌。","投篇涕汍澜，日暮感舟师。"]},{"t":"衡山篇为徐武子丈寿","f":"五言古诗","c":["衡山有奇筱，为音何洋洋。","雌枝吐流徵，雄枝含清商。","美人摛朱唇，为君乐无方。","凤将九子吟，龙挟五驹翔。","紫芝成宫阙，醴泉满壶觞。","莱妻共高逸，为寿未渠央。","金庭连玉柱，四皓所徜徉。","昊天毋嗟嗟，痛饮以自强。"]},{"t":"和陈元孝登吹台作","f":"五言古诗","c":["夙闻太阿剑，霜锷莲花发。","楚王一麾之，三军尽流血。","夫君事远游，家贫一蒯缑。","千里登吹台，慷慨思报仇。","夷门无监者，谁为公子谋。","我昔吊梁园，所见惟林丘。","洪河崩底柱，蔓草连神州。","惊鸟纵横飞，离兽鸣相求。","平台宾客尽，四顾泪交流。","怜尔多难人，徘徊当暮秋。","长歌蓬池上，击筑睢水头。"]},{"t":"登石门怀慧远尊者","f":"五言古诗","c":["双峰耸天阙，一水悬神池。","积石若朝霞，连林多夕霏。","丹溜含清泠，鲜葩吐葳蕤。","予偕二三子，来自虎溪湄。","矫掌承飞泉，抠衣陟金梯。","萧条远公迹，亭阶有留基。","怅然增逸兴，方嗟哲人萎。","白云开阖际，忽见金仙姿。","玉瓶灌甘露，龙策振灵飔。","回目流神光，示我青莲枝。","挥玄入无朕，俾为万象师。"]},{"t":"别王二丈予安","f":"五言古诗","c":["美人在霄汉，灼灼如丹云。","手持凤凰子，毋乃魏元君。","我昔登太山，天门啸不还。","瀑布为长带，浮云为高冠。","游仙岂不乐，悲此市朝间。","圣贤耻独善，所贵匡时艰。","太阿苟不割，蛟龙将波澜。","箧中有阴符，吾生焉得閒。","平沙利马足，惊飙宜鹰翰。","遥遥万里心，慷慨入长安。"]},{"t":"梅市别祁四丈季超","f":"五言古诗","c":["沉沉海月生，嘒嘒寒蜩鸣。","游子在天涯，触物生忧情。","赖有二三友，金玉同坚贞。","鼋鼍互变化，神龙丧其形。","岂不思奋翼，上天无雷霆。","昔我别慈亲，王事劳孤征。","风雪历四载，谋深竟难成。","黄蘖与春荠，甘苦不分明。","至道尚可信，寂寞元生平。"]},{"t":"桐君山作","f":"五言古诗","c":["清溪流㶁㶁，白石如摴蒱。","桐君去我久，谁与同欢娱。","利器乱天下，濠梁日如愚。","白发渐纷纷，于世复何须。","远游可长生，逝将登蓬壶。","青霞为绣袷，明月为耳珠。","金火相盘旋，神丹生太无。","天孙嫣然笑，结我合欢襦。","誓言何旦旦，岁晏终不渝。"]},{"t":"答吴巨手","f":"五言古诗","c":["白云何晶晶，倏忽归无形。","尸居龙不见，与君共沉冥。","黄虞久已没，吾道难独清。","深谷何逶迤，朱华含春荣。","采采以疗饥，将游太上庭。","汤火煎太和，膏粱损奇龄。","浮沉日月中，人命如流萤。","哀哉嵇叔夜，多才乃捐生。"]},{"t":"还故山作","f":"五言古诗","c":["谁谓客行乐，岁寒无衣裳。","羁栖在枳棘，悠悠思故乡。","步出稽山门，乘春聊徜徉。","丹霞抱秀粤，珍木交回塘。","水鸟相和鸣，窈窕皆鸳鸯。","人生道不存，何以持文章。","苟与太虚冥，仁义皆秕糠。","南金一出矿，遂为贫者殃。","长叹辞世人，飘飖归罗阳。"]},{"t":"将归省母留别诸友人 其一","f":"楚辞体","c":["海上三珠树，孤鸾鸣啾啾。","养子羽翼成，翻飞向九州。","九州一何旷，回顾生烦忧。","寻仙蓬壶中，谒帝昆崙丘。","繁霜陨百草，琅玕无晨羞。","慈乌能反哺，凤兮命不犹。","归与守故巢，戢翼为良谋。"]},{"t":"将归省母留别诸友人 其二","f":"五言古诗","c":["良谋亦何有，持道足娱亲。","母为天上月，子如江中云。","云月相终始，流光谁与伦。","翩翩两海燕，挟雏游青春。","衔我蕙兰花，悲音何感人。"]},{"t":"将归省母留别诸友人 其三","f":"五言古诗","c":["感人惟杨柳，飞花皎如雪。","如雪岂不芳，所忧本根绝。","昔我与亲辞，五岳将寻师。","乃觏姑射人，赠我青莲枝。","青莲合为丹，能生明月姿。","岂敢自恰悦，万里其持归。"]},{"t":"将归省母留别诸友人 其四","f":"五言古诗","c":["持归明月姿，皎洁无纤瑕。","朝含东海日，暮膏赤城霞。","重袭盘龙锦，毋使蒙风沙。","以奉白发人，一照生桃花。","如彼西王母，长居太清家。"]},{"t":"将归省母留别诸友人 其五","f":"楚辞体","c":["太清何寥廓，浮云去不息。","呦呦野鹿鸣，甘草不自食。","如何舍友朋，奋然思矫翼。","四海皆兄弟，亲兮难再得。","循彼南陔间，相思何终极。"]},{"t":"将归省母留别诸友人 其六","f":"五言古诗","c":["极望惟吴越，吴越多山川。","玄豹藏深雾，应龙蟠巨渊。","神物必有偶，磁石金相连。","离别虽须臾，恩爱终不愆。","遥遥骨肉情，去如箭离弦。"]},{"t":"将归省母留别诸友人 其七","f":"五言古诗","c":["离弦去南里，烟波何渺茫。","朝与凫雁群，暮随明月光。","仰视虚宇中，众星灿成行。","而我独何辜，乃为参与商。","人命在呼吸，后会其毋忘。"]},{"t":"将归省母留别诸友人 其八","f":"五言古诗","c":["后会庶不移，参商有见时。","红日生沧溟，万物蒙其辉。","矧我体道人，金石宁或亏。","飒飒霜下草，荧荧园中葵。","敦彼后彫质，岁寒以为期。"]},{"t":"寿母","f":"五言古诗","c":["文武道未坠，圣谟何洋洋。","我生获胎教，少小修天常。","早岁负剑游，所希应帝王。","天命在庭闱，贤母知废兴。","年今至八旬，灵寿自翱翔。","岳莲标独干，嫠星流孤光。","母为飞鹊镜，子为蛾眉妆。","形影不相离，从今至千霜。"]},{"t":"题王丈华阴书阁","f":"五言古诗","c":["太素有元精，凝为三芙蓉。","美人日揽撷，彩翠餐无穷。","白发临玉颜，岂敢从飞蓬。","道德为膏沐，光彩开童蒙。","人伦垂胜业，含垢悲予躬。","老聃效夷言，大禹裸而东。","昊天徒嗟嗟，委蛇吾安终。"]},{"t":"酌贪泉作和人","f":"五言古诗","c":["朝饮贪泉水，暮濯贪泉流。","廉夫不可为，仁者皆窃钩。","天方授盗蹠，吾介徒罹忧。","合浦多明珠，朔漠多貂裘。","仲尼思执鞭，况我斗筲俦。"]},{"t":"咏张子房示诸生","f":"五言古诗","c":["淮阳昔学礼，故能敬老父。","长跪纳履时，强忍甚可取。","少年虽任侠，喜与老人伍。","四皓奉手行，不敢越规矩。","所师尽黄发，深藏若处女。","甚悔博浪沙，徂击徒豪举。"]},{"t":"为故黄靖南侯参军陆生作","f":"五言古诗","c":["仗剑出门去，高堂悲不胜。","婴母既知废，陵母亦知兴。","送子涉淇河，倚闾泪沾膺。","黄云驱匹马，惊风击饥鹰。","努力参卿军，智谋夙见称。","报亲在何所，沙场奋猿肱。","屠毒天未厌，髦头国方兴。","天矢不敢射，贪狼日凭陵。","豪雄致帝怒，祸患来相乘。","哀哀皋鱼痛，使尔肝肠崩。"]},{"t":"赵陈二烈女","f":"五言古诗","c":["鲁女倚柱吟，忧国无人知。","妾身逢丧乱，志节聊自持。","罗敷虽靡匹，秋胡宁为期。","吁嗟尔元憝，安知礼义归。","猛虎尚可驯，神鸾终不移。","抽吾玳瑁簪，可以刺熊罴。","天道故祸淫，气矜吾不为。","珠沉靡点辱，玉碎馀光辉。","对君刎绣颈，去去从湘妃。"]},{"t":"求二桥山人画三闾大夫像","f":"五言古诗","c":["先生怀姱节，寤寐见古人。","凌朝漱九阳，为予貌灵均。","曲眉象珠斗，姣衣飘春云。","云中嫣含笑，望如扶桑君。","正气得所繇，变化皆吾真。","下为兰杜滋，上为日月陈。","子其虚以待，鬼神将来奔。","其小入无内，其大廓无垠。"]},{"t":"赠陈十一 其一","f":"五言古诗","c":["金瓶连素绠，百尺汲寒浆。","清泠涤尘垢，何减流霞觞。","城南新赐第，贵盛如金张。","昔作骑都尉，今封右校王。","胭脂骄塞马，芍药艳吴娼。","汉恩岂独薄，天道终有常。","吾子抱忠信，诚为百鍊刚。","沙头且射虎，飒飒凌风霜。"]},{"t":"赠陈十一 其二","f":"五言古诗","c":["茹荼甘若荠，慷慨荆蛮地。","猛虎不忍射，爱彼爪牙利。","筑台南岳阳，丹火流扶桑。","仙人多剑侠，起舞佐霞觞。","填填丰隆鼓，咽咽右英簧。","双龙绕指柔，俄为掣电光。","惊风逐千里，澥水群飞扬。","划然君一啸，为乐何洋洋。","我亦白猿俦，相逢聊翱翔。"]},{"t":"赠别武昌陈子山昆弟之作","f":"五言古诗","c":["江汉何滔滔，其神足纲纪。","大别如长城，中分南国水。","君家高冠山，黄鹄当门峙。","形势雄湖湘，人才争郁起。","昔我客汉阳，求友得一士。","岂知君弟昆，乃在吾桑梓。","伯仲圭璋姿，青云翘玉趾。","所得凤凰毛，多分诸季子。","三百日弦歌，情礼为终始。","贤父师于家，金玉相涤理。","扬粤观人文，化成察所以。","颜曾昔童蒙，造道莫能止。","年少圣所畏，惭予将暮齿。","清夏珠江湄，饮饯交壶矢。","执手情依依，所赠惟璚蕊。","我本荆楚人，秭归有故里。","先臣居屈沱，女媭砧在彼。","安得从君归，三闾陈簠簋。","汉家重楚声，离骚多所拟。","君为宋景徒，努力事兰芷。"]},{"t":"垂老 其一","f":"五言古诗","c":["垂老心多忧，饮酒未尝旨。","上忧忧老亲，下忧忧稚子。","稚子始匍匐，其一六龄耳。","长者及九龄，已赴黄泉矣。","次者葬秦淮，下殇以疮痏。","两女亦婴孩，饥寒殊未已。","呱呱满膝前，无钱致饼饵。","我生拙经营，甘贫已三纪。","采薇成不仁，洁身累妻子。","谁使廉夫刚，鲍焦终槁死。"]},{"t":"垂老 其二","f":"五言古诗","c":["死者日以安，生者日以危。","旻天何不怙，人命轻如泥。","玄云一蓊郁，白日去安归。","长夜终不晨，胶胶劳鸣鸡。","我生慕夷皓，垂老益调饥。","苦节同妻孥，捃拾难自资。","絮巾布襦裙，单复亦随时。","薄馔荐先公，泪下如绠縻。","不义而富荣，毋乃辱亲为。"]},{"t":"垂老 其三","f":"五言古诗","c":["衣敝何尝补，履决何尝组。","勉力糜粥间，艰难事慈姥。","叱咤及犬鸡，亲前敢有怒。","深爱在婉容，白头若孩乳。","有妇布襦裾，割烹未为苦。","膝前黄口儿，不使分馀脯。"]},{"t":"咏古 其一","f":"五言古诗","c":["汉皇有神器，光明长盛实。","白气郁成云，状若龙蛇出。","太白精所凝，一挥天下一。","自斩白帝子，血光尝如漆。","本以诈力雄，汤武非其匹。","猛士无韩彭，四方岂宁谧。","威加海内归，霸图有得失。","慷慨泣数行，悲歌风瑟瑟。","时无周旦才，谁与陈无逸。"]},{"t":"咏古 其二","f":"五言古诗","c":["诸葛王佐才，乃慕乐将军。","燕昭本姬姓，豫州亦懿亲。","齐破将尊周，霸业为桓文。","为燕振积弱，周命亦维新。","天王威一奋，六国仍为臣。","燕号为宗国，西向制强秦。","孔明为刘氏，与乐同一身。","帝蜀岂本怀，汉业徒三分。","悲哉孝献没，一日能无君。","元年纪章武，掩泪当秋旻。"]},{"t":"留别羊城诸子 其一","f":"五言古诗","c":["大鱼啖虾䱉，小鱼啖沮洳。","风波一失所，微沫犹相濡。","吁嗟尔君子，念我如黔娄。","养亲无甘毳，从君无骊驹。","怀宝而迷邦，前路多忧虞。","王孙诛淖齿，伍子干阖庐。","所愧病无能，日暮空踟蹰。"]},{"t":"留别羊城诸子 其二","f":"五言古诗","c":["枯鱼日衔索，高树多惊风。","我亲已白发，我行犹转蓬。","仲繇嗟负粟，冉子念尸饔。","携手出东门，泪落尘埃中。","蛇脂已耆乾，龙饥尚未充。","耘瓜忌伤根，结兰贵心同。","孝子当不匮，锡类及微躬。"]},{"t":"孤燕篇 其一","f":"五言古诗","c":["燕燕昔双飞，衔花何差池。","皇天命早寡，雨泪毁容姿。","与君如日月，光景不相离。","与君若泾渭，清浊必同归。","鬒发剪无馀，玉棺叩且开。","傍人相慰留，黾勉陶婴为。","上念养公姥，下顾黄口儿。"]},{"t":"孤燕篇 其二","f":"五言古诗","c":["葳蕤女贞树，含此少阴精。","岁寒不凋谢，高行通神灵。","孤燕何啾啾，挟子饲其英。","凤凰心不乐，乌鹊甘伶俜。","托孤昔所重，从死今所轻。","子既羽翼成，母仪万方盈。","母为月经天，子如太白明。"]},{"t":"赠友 其一","f":"五言古诗","c":["鱼目似明珠，阳货似仲尼。","苟非明哲人，安能辨几希。","嗟予久飞遁，墨名行殊非。","朝行脍人肝，暮行搴紫芝。","吾子不遐弃，狂简其同归。","隆冬不肃杀，阳春奚光辉。","披裘入裸国，优哉聊娱戏。"]},{"t":"赠友 其二","f":"五言古诗","c":["甘匏抱苦叶，萏菡含污泥。","子推身已隐，焉用文章为。","露华零蔓草，觏尔清扬姿。","旷世无奇服，琼琚非所宜。","携手登绵山，念我蛇无脂。","神龙尚饥渴，君岂有兰饴。","兰饴无使露，渊塞秉其私。"]},{"t":"赠友 其三","f":"五言古诗","c":["我本接舆流，被发歌凤衰。","时无鲁仲尼，狂简将何归。","六经久榛莽，诸子多淫辞。","嗟予非先觉，斯道将陵迟。","狂澜思砥柱，疾风宜劲枝。","嘉子方少龄，颜闵能为期。","直如麻中蓬，皎若霜上曦。","烹鱼为溉鬵，射虎为张机。","堂堂并为仁，弃我莫如遗。"]},{"t":"赠友 其四","f":"五言古诗","c":["桃虫化为雕，群飞啄九州。","凤凰集于蓼，饥渴常怀忧。","与君志天爵，仁义交绸缪。","惕厉处明夷，保身随波流。","瓶罍贵相资，箕毕贵相求。","美人乘白云，昆崙去悠悠。","吾将为造父，往御彼骅骝。"]},{"t":"赠友 其五","f":"五言古诗","c":["日月私照临，我食恒无馀。","绝尘天下马，今乃伏盐车。","美人如惊鸿，飘飖过丹虚。","神光倏阴阳，欲揽无琼琚。","崇山蕴宝玉，沧海含龙鱼。","云霞苟蒸液，变化在斯须。","食德为膏粱，服道为绣襦。","勖哉尔君子，毋效彼蘧蒢。"]},{"t":"赠友 其六","f":"五言古诗","c":["黄鹄何缡褷，单游心伤悲。","美人发无旟，君子佩无琚。","萧艾盈中林，予兰将安依。","驰车适西吴，庑下敛光辉。","昔为清水珠，今为浊泾泥。","吞声行踯躅，愿子相提携。"]},{"t":"赠友 其七","f":"五言古诗","c":["黄山有温泉，日月所流精。","饮之生羽翼，飘飖如容成。","文章若云浮，五色为天经。","三闾变风雅，好色成仙灵。","轻举含道真，颜如蕣华荣。","我持远游章，被之雅琴声。","为君千金寿，相与娱生平。"]},{"t":"读顾子忠纪赋赠 其一","f":"五言古诗","c":["苏合何氤氲，非烟亦非云。","我为铜垆器，与子日三薰。","美人临九天，光彩如东君。","傅说托房星，精华垂大文。","愿得俱翱翔，冠盖绝尘氛。","大招匪荒淫，风谏同三仁。","重华可折衷，何求时俗闻。"]},{"t":"读顾子忠纪赋赠 其二","f":"五言古诗","c":["伊予遘乱离，为诗多变风。","秦庭昔鹤立，痛哭人谁容。","从俗以偷生，神仙托其踪。","须臾愿无死，以观宗国终。","君子厉明德，邂逅欣心同。","蜿蜒为文章，皇颉非雕虫。","大道所周流，敬哉尔天工。"]},{"t":"题申苕青画","f":"五言古诗","c":["黄鹄在天地，一举知圆方。","游仙未解忧，时时思故乡。","志士贵成仁，松乔非我良。","众人树苦桃，君兰实不成。","众人重鱼目，君珠黯无光。","游艺为丹青，山川日徬徨。","晻霭如鬼神，云霞出中肠。","离忧翳萝木，阳谷不垂光。","麇麚方慕类，与子聊低昂。"]},{"t":"寄祁四丈西遁 其一","f":"五言古诗","c":["桂树含炎德，敷荣霜霰间。","款冬花严寒，相与同贞艰。","峨峨冠浮云，锵锵呜玉环。","惠而君好我，携手会稽山。","仲尼如日月，光华为我颜。","老聃其犹龙，变化在子闲。"]},{"t":"寄祁四丈西遁 其二","f":"五言古诗","c":["子闲多龙驹，食我玉山刍。","文章天所授，五色为子娱。","白鹿云中翔，鲤鱼九渊居。","高深不可恃，久已充庖厨。","嗟余薄长生，成仁心所须。","潜神在玄默，与道为隆污。","吾子独全归，寿考保无虞。"]},{"t":"咏怀","f":"五言古诗","c":["溪谷何清凉，回风以飘忽。","荷襦易凋零，不如服狐白。","旷土贵和同，蝉蜕仲尼迹。","凛凛冬冰凝，何如春冰释。","我已秽玄珠，离娄不能识。","我已摧号钟，师旷不能绎。","美人如游龙，纤腰日玄折。","一低而一昂，人以为臣妾。"]},{"t":"再送从弟无极 其一","f":"五言古诗","c":["秋天今肃杀，山林凄且凉。","游子临归风，忧心以多方。","皇天若浮云，报施何靡常。","黄钟委尘垢，瓴甋登明堂。","吾生既不辰，子亦命无良。","雄翡而雌翠，今朝难同翔。","哀哉骨肉情，临别徒徬徨。"]},{"t":"再送从弟无极 其二","f":"五言古诗","c":["阴阳有纲纪，夫妇人伦始。","葛覃恐失时，摽梅求庶士。","子归娶齐姜，及此春冰弛。","慈姑嗜鱼鲙，施罛在河水。","恩义相缠绵，琴瑟为亲喜。","我有不肖躯，因依无葛藟。","何以事高堂，孝德惭君子。"]},{"t":"赠诸氏兄弟","f":"五言古诗","c":["朝登雁门望，杀气从西来。","在天为黄云，在地为黄埃。","吁嗟我游子，悲秋行徘徊。","披发而吹箫，闻声令子哀。","子情如醇酒，日酌我金罍。","子诗温且润，日馈我琼瑰。","弟兄相宴尔，携手临高台。","猗猗合欢竹，枝叶交山隈。","愿言靡离别，千秋慰我怀。"]},{"t":"和友人度昭关之作","f":"五言古诗","c":["端居苦离索，思君芜湖间。","忽闻昭关咏，感激泪潺湲。","丈夫不得志，饥寒行中原。","断发投炉中，为君铸龙泉。","器成不见御，雌雄各沉渊。","登高望四野，亭障何连连。","惊风折旗帜，落日迷山川。","谁知远游子，呜咽不能言。","维昔吴子胥，吹篪诚足怜。","一怒覆强楚，父雠不戴天。","解牛宜薄刃，驱马贵长鞭。","苟能勤耘耔，何必求膏田。","亮怀鹰隼羽，时至自飞骞。","勉尔慷慨人，遥遥托赠篇。"]},{"t":"赠张文谷孝廉","f":"五言古诗","c":["橘柚贵素华，匪尚叶葳蕤。","凤凰苟成德，何用文章为。","秋霜日凛冽，白发秽光仪。","学道久未成，吾生将安归。","吁嗟尔君子，六经纵横施。","离骚多夸诞，变声蚤能知。","发愤事声色，神仙遑与期。","浩浩仲尼徒，德行臻庶几。","愿言诱狂简，弃我毋如违。"]},{"t":"答谭非庸","f":"五言古诗","c":["采菽需筐筥，为仁贵朋旅。","盈手琼瑶华，夫何饥季女。","季女多徽音，其谐如瑟琴。","乾糇非失德，弃我如飘风。","白首始成欢，君能同锦衾。","断发为龙渊，雌雄相升沉。","虽无金玉相，追琢亦能任。"]},{"t":"猛虎篇 其一","f":"五言古诗","c":["猛虎不食人，食人必豪贤。","为天生羽翼，飞渡大河间。","我弓既已良，我马亦已闲。","踟蹰不忍射，恐非天所安。","天安惟猛虎，作威予敢侮。","腐肉如山丘，所甘惟肺腑。","猛虎不见人，见人则不取。","所见尽禽鹿，人立而虞麋。","肥者噬无馀，瘠者以为脯。","麒麟与凤凰，不足为粪土。"]},{"t":"猛虎篇 其二","f":"五言古诗","c":["凤凰肉不甘，麒麟肉不肥。","猛虎亦好生，何不食饘糜。","凤鸟乘于风，为皇作威仪。","麒麟乃仁兽，生草不践之。","上天命猛虎，威向豺狼施。","如何饵灵物，口腹亦细微。","生怀腥臊德，炳耀徒留皮。","吁嗟尔猛虎，哮吼诚何知。"]},{"t":"答王生","f":"五言古诗","c":["二女佩明珠，顺风翔蓬阙。","朝霞一膏沐，娭光流如月。","园桃何夭夭，秋霜徒磬折。","嗟尔荜门子，献玉悲三刖。","崇兰忌当门，甘泉必先竭。","布衣可终老，濮阳有芳节。","请诵伐檀篇，十亩聊怡悦。"]},{"t":"为梁生寿母作","f":"五言古诗","c":["金盘脍嘉鱼，玉瓒酌黄流。","为君寿圣善，欢乐盈林丘。","孝子贵修身，天爵为公侯。","非义而富荣，毋乃贻亲忧。","不逢尧舜禅，宁戚终饭牛。","嗟予亦有母，欲养无珍羞。","采兰不盈掬，中道化为莸。","鸡鹜日争食，凤饥呜啾啾。","勖君孝不匮，永锡尔同俦。"]},{"t":"题王子省斋","f":"五言古诗","c":["鹊鸰何友悌，飞鸣不相离。","王雎声相求，贞洁慎所妃。","君家多弟昆，金玉交光辉。","精神见山川，令我乐忘归。","君爱我离骚，洋洋风雅遗。","圣贤贵发愤，哀乐为人师。","尔躬日三省，经术是凭依。","彷佛见先王，忘言在隐微。"]},{"t":"赠大毛子","f":"五言古诗","c":["煌煌太华荷，玉颜照万方。","昔余乘白云，攀折日翱翔。","国风乐不淫，小雅哀无伤。","恭承皇降衷，好色成文章。","审声知清浊，听曲辨兴亡。","吾子乃延陵，聪明不可当。","子为清庙瑟，神人久和康。","朱弦而疏越，吾其继后行。"]},{"t":"咏梁子六瑩琴","f":"五言古诗","c":["太冥有寒桐，琼干含黄钟。","凤凰何秋秋，为君结流风。","我为园客丝，缠绵玉轸中。","玉轸有时折，朱丝无断绝。","大弦含幽兰，小弦吐白雪。","鼓舞尽神明，庶以酬先哲。"]},{"t":"天泣","f":"五言古诗","c":["天泣一何哀，鸣声如转磨。","无云乃作雨，凄凄泪交堕。","悲此下土民，斩刈遭殃祸。","仁圣不降生，天地日多过。","我生抱忠诚，与天素相左。","俯仰愧怍多，死生无一可。","茫茫饥溺怀，泪下悲坎坷。"]},{"t":"谁谓","f":"五言古诗","c":["谁谓苍天高，我行曲其躬。","履霜惟葛屦，薾电无青骢。","遑遑尘壒间，慷慨谁相容。","吁嗟尔君子，揽我如芙蓉。","持华赠子充，持叶赠狂童。"]},{"t":"邓氏丈寿辞","f":"五言古诗","c":["方今斗牛墟，老人星实见。","其下多寿耇，皤皤复耆彦。","我公生番禺，实乃天所眷。","弧南一老人，光芒射赤县。","乾坤归火主，汝当师保荐。","口授壁间书，宫中赐银绢。","太和作口实，自养幸毋变。","膏粱岂朵颐，饮食人皆贱。"]},{"t":"拟古","f":"五言古诗","c":["人生无百年，命在呼吸间。","长风飘落叶，一去不复还。","人鬼互相送，阴阳不少閒。","天地岂不仁，人物自相残。","吁嗟世道丧，吾生日已艰。","寥寥含道腴，所润惟容颜。","甘肥久已绝，蔬食馀一箪。","回也日闭户，禹稷同心肝。"]},{"t":"留别槎山诸子","f":"五言古诗","c":["絺绤含凄风，葛屦濡寒霜。","我行一何窭，歧路复亡羊。","白驹在幽谷，行行悲迷阳。","吾子陈瑾瑜，为我禦不祥。","日月居东南，沐浴成文章。","予技非雕虫，为天补衮裳。","彤管何光辉，贻君殊未央。"]},{"t":"有鸟篇送妹 其一","f":"五言古诗","c":["有鸟名苏耽，千载蓬莱还。","为亲植朱橘，离离成神丹。","孝子贵锡类，天性谁能残。","子慕秦王女，吹箫心孔閒。","幽贞少不字，学道怀骖鸾。","牵牛俟银汉，匏瓜期绛天。","日月一夫妇，交会相回旋。","子今勉于归，及此冰犹坚。","阳雁喜朝日，夭桃矜春妍。","鸡鸣警君子，夙夜礼无愆。","尊章益虔事，当得王母怜。"]},{"t":"有鸟篇送妹 其二","f":"五言古诗","c":["混元生两仪，四象运璇玑。","民生有俦匹，阴阳圣所师。","嗟尔幽閒女，于归今及期。","琴用先人桐，张以所缲丝。","一弹再三鼓，凤凰鸣参差。","明月喜几望，受日逾光辉。","服德为黄裳，乐我惟缟衣。","灵仇天所眷，敬尔百威仪。"]},{"t":"送铁井子","f":"五言古诗","c":["葵生知向阳，梅吐必南枝。","嗟尔远游子，择主将安之。","玄冰结大漠，白日倾崦嵫。","怀宝不自衒，所恃璠玙姿。","维昔越溪女，红颜扬光辉。","采采五色丝，织成歌舞衣。","朝咏梧宫秋，暮为香泾嬉。","佳人重意气，一举沼吴归。"]},{"t":"咏怀","f":"五言古诗","c":["我昔萝华胥，扶摇凌自然。","神气何混茫，挥斥昆崙巅。","峥嵘下无地，寥廓上无天。","大鹏张两翼，东西覆群仙。","朝霞开北阙，旭日悬高旃。","狂吟太和曲，王母笑容妍。","五岳相鼓舞，来迎云翩翻。","至人奉遗物，垂区将穷年。"]},{"t":"赠别查德尹","f":"五言古诗","c":["君之父与兄，与予相友善。","父也岁寒姿，柯条蒙雪霰。","松柏天所私，青青长不变。","大冬愁凝阴，微阳难与战。","潜神在九渊，龙蠖谁能见。","我亦款冬花，苦寒相婉娈。","春日未载阳，甘同萎草贱。","相别未几时，溘焉朝露先。","岂谓觏夫君，先人俨颜面。","彷佛黄钟声，有光目流电。","肥瘠亦不殊，天形妙相践。","长短争秋毫，䰄少亦连卷。","识者尽惊喜，性亦同狂狷。","文章若孔鸾，珠毛相贯串。","黄者如金钱，白者如绡练。","自铸伟丽辞，六艺作钗钏。","吟言自回环，不嫁惜婵媛。","盛饬将有行，未能舍环瑱。","太素在中央，絺绣四为缘。","易爻尚白贲，诗风后绘绚。","先公所教勒，夙夜惟经传。","明将于国雍，写书自供缮。","贻我外家语，摩研当无倦。"]},{"t":"送五弟还里 其一","f":"五言古诗","c":["子行归故乡，劬劳将父母。","虽无金满籯，有友贻琼玖。","吴越多秀民，襄阳足耆旧。","称诗相欢娱，为情若醇酒。","谓我兄弟贤，无忝三闾后。","揽执芙蓉袪，缠绵大道口。"]},{"t":"送五弟还里 其二","f":"五言古诗","c":["大道直如弦，汝行勿回曲。","骐骥少壮时，飞扬苦不足。","所难中规矩，千里自拘束。","北风安可依，尘沙为我辱。","岂无水草甘，未免为臣仆。","宁为越翡翠，衔泥日三浴。"]},{"t":"咏阮嗣宗","f":"五言古诗","c":["阮籍英雄人，高逸非其志。","驱车临广武，大笑楚汉事。","饮酒以轻生，杜康知此意。","邻家有好女，蕣华伤萎地。","恸哭涕滂沱，情深岂妖媚。","长啸若凤鸾，亦乃途穷泪。","嵇公薄汤武，遗曲广陵坠。","越礼逾矜慎，言怀务闳肆。","当日竹林贤，沉冥惟尔醉。"]},{"t":"送江太守还柳州","f":"五言古诗","c":["柳江在城南，清接黔中水。","瓯骆一都会，诸蛮所纲纪。","太守汝多才，文武为张弛。","吁嗟喋血馀，未忍事鞭箠。","东下牂牁来，疮痍别千里。","须臾失襁褓，盻盻劳赤子。","良马早还归，殷勤迎玉趾。","片言肉白骨，彼姝何以畀。","饮饯崧丘旁，称诗惟孔迩。"]},{"t":"王夫人殉节诗","f":"五言古诗","c":["呜呼岁甲申，皇朝婴大变。","天王死宗社，苦为诸侯先。","谁从烈后妃，厥有邦之媛。","君舅永宁侯，外戚称祥善。","夫人为介妇，早寡剺颜面。","攀髯大小臣，哀哀同白练。","夫人乃九渊，湘君相婉娈。","媳女牵衣裾，诸孙抱环瑱。","相从露井中，玉浆寒辗转。","血射惊鲋鱼，魂浮助龙战。","瓮敝触肌肤，泥深苦吞咽。","沉瓶激哀响，飞绠争幽牵。","波涛忽腾涌，吐色如红茜。","贼奴不敢饮，倾泻手长颤。","匍伏窥潜源，洞门如或见。","冉冉媵文鱼，翩翩翳羽扇。","玉甃发神光，笑口流如电。","蟾蜍衔耳珰，苔藻生金钿。","精灵处太阴，水府开宫殿。","再拜辘轳旁，开渫虞天谴。","玄泉引杳冥，素华四相溅。","瑶瓮以龙腾，洒激如霜霰。","终古此圆渟，上帝可盥荐。","玲珑玉槛施，更作银床遍。","娥月在中央，女星相贯穿。","照胆恐生寒，美人目流盻。","桐华落缤纷，水草何葱茜。","乳脉多潜通，出云动成片。","宜谁此影蛾，罗敷是其选。"]},{"t":"虎门观海作","f":"五言古诗","c":["朝自扶胥南，万里穷泱漭。","溟波接百川，倾泻多奇状。","潮从虎门出，势到沃焦放。","祝融在阴墟，天池正相向。","天命南海帝，来从南岳上。","宫阙临扶桑，百王所禋享。","元气一吐吞，日月光相养。","混沌在中央，精华资酝酿。","咫石天河通，浮槎日来往。","丈夫朝饮牛，牛口吐溟涨。","渚边多织妇，微闻弄机响。","八月水益大，吾欲浮演漾。","槎从海若取，食须天吴饷。","倏忽至云汉，客星恣摩荡。","抚手笑黄姑，独处徒惆怅。"]},{"t":"答陈宛平 其二","f":"五言古诗","c":["五十尚无闻，岂敢为人师。","区区章句末，腐儒吾不为。","天命在渺茫，垂白犹未知。","老莱事嬉戏，自视如婴儿。","君顾我蓬蒿，存问及孀慈。","茅家苦贫窭，供养无肉糜。","有鸡若鸾鸟，有黍如兰饴。","君为举匕箸，不忍弃寒微。","感兹情意厚，久要以为期。","微尘撼华岳，蚁穴溃金堤。","人言贵深察，强恕有良规。"]},{"t":"答李缓山","f":"五言古诗","c":["昔在建陵时，与君尝不寐。","干将徒出匣，宰割难自试。","纷纷驽骀者，千里先骐骥。","君击唾壶缺，酒酣益涕泗。","神勇笑荆轲，乃为燕丹使。","不与渐离行，匕首无成事。","沉沉夜漏长，棋局消神智。","英雄亦反覆，一子勿倒置。","亚夫苦持重，诸军患儿戏。","乌合取胜稀，皇皇徒逐利。","壮心一日暴，十日寒频至。","拂衣沔阳湖，君归如脱屣。","赋诗向白蘋，垂钓持芳饵。","云梦吞吐时，洞庭为酒器。","遨游至五羊，寻找屠沽肆。","相见即言易，剥极见天意。","乾坤一硕果，万物所从始。","贵以土德厚，栽培无老稚。","相望及春阳，云雨同行施。"]},{"t":"寻墓诗为徐护卫作","f":"五言古诗","c":["嗟君何不怙，十一丧而母。","四十不知墓，匍匐来陇首。","珠江当其前，龟峰在其后。","蔓草既已平，牛羊满林薮。","号泣依旻天，水浆恒不口。","神明欲告人，不向蓍龟取。","蓍龟亦不知，精诚自相偶。","白骨忽踊跃，潜寐黄泉久。","浅土二尺中，待儿陈絮酒。","孝思所凝结，玉红自不朽。","心作漆灯光，耿耿悬培塿。","一穴乍明灭，莓苔积已厚。","蝼蚁所盘旋，咫尺劳相守。","昏绝忽僵仆，山鬼牵左肘。","肘下即瓷棺，阙地大逾斗。","刳血何淋漓，涓滴归无有。","白骨忽复肉，生气怀中走。","幽明一呼吸，生死相为寿。","薰用都梁香，惊精返窗牖。","西王好戴胜，麻姑未蓬首。","喜见出腹子，丈夫顷而黝。","才气世无双，豪杰效奔走。","显亲始羽林，养志胜肥牡。","石奋性恭谨，厕腧昔在手。","老犹孺子慕，仁爱及诸舅。","灵爽所凭依，重封庶不苟。","锦绮裣纵横，芳香相杂糅。","重招先考魂，嫡妣同樽缶。","黄沉雕琢之，血花涂左右。","高作马鬣形，合葬仍兹阜。","泪作一泓泉，身为白杨柳。","阴风长萧萧，石马助悲吼。","行人纷掩泣，看尔土亲负。","赐祭会有时，汤沐百馀亩。"]},{"t":"为陈母姜夫人寿","f":"古风","c":["夫人年七十，有子才且贤。","迢递八千里，顾我东皋田。","爱亲及我亲，仁孝情相宣。","左持一白鹅，右持一豚肩。","僮仆奉樽酒，酒乃惠山泉。","为母千金寿，申以南山篇。","感激仲子赐，光生深井间。","忠养方有愧，敢当不匮言。","惟君能锡类，施及恩缠绵。","我欲寿而母，无物致拳拳。","惟有一片石，可以明贞坚。","令子圭璋质，攻之期不偏。","友道在追琢，所以娱高年。","夫人百龄时，我当来幽燕。","跪将吾母命，并上肉芝鲜。","今且养鹓雏，待之?綵笺。"]},{"t":"采药西宁承张大令使君命其侄孙豫表陪探燕子岩大峒龙井诸胜","f":"五言古诗","c":["泷东与泷西，岩嶂蔽天起。","泷西林木深，窈冥数百里。","城与白云争，所得尺有咫。","猿鸟欺吏人，峰峦压厅事。","开辟未百载，夷椎尚多鄙。","使君造草昧，雷雨自兹始。","仁声务洋溢，文教期光被。","我来听鸣琴，泠泠匪山水。","先王风未绝，咏歌日盈耳。","相赏在无言，唱叹亦有以。","郊坰富丘壑，先导命犹子。","枫叶作香饭，笋篮代玉趾。","衣裳湿岚翠，杖屦沾泥滓。","石窟俯身入，洞天穿地底。","绝壁攀莓苔，幽丛掇花蕊。","奇葩爱无名，大药疑不死。","猴姜既蔓引，凤竻复披靡。","兰青翡翠同，竹大笼䈡似。","松栝互支拄，麇麚或腾倚。","郁鸡惊出林，白鹇冒其尾。","山鹕解媚人，孔雀可驱使。","飞崖畏足践，盘石若棋累。","方圆竞相叠，大小皆竦峙。","鬼神所荡踏，风雨或迁徙。","陟高眺锦石，特立牂牁沚。","玉表何峨峨，翠屏复几几。","汉臣昔封植，功可铜标拟。","蒲桃裹宫锦，五彩绚峛崺。","泷西夙望秩，山宗实在此。","罗旁九九曲，势至咽喉止。","汹涌千万嶂，所赖一柱砥。","使君天下才，今乃在蛮俚。","亦如陆大夫，区区至交阯。","峻极持崧高，英灵作南纪。","注以洪河流，波涛沃疮痏。","恩膏随沓潮，以及我桑梓。","汤沐不在多，锦石亦可喜。","肯钖一陂陀，当尽树兰芷。","来为泷西氓，殷勤负耒耜。"]},{"t":"知州赵公殉难诗","f":"五言古诗","c":["呜呼国再亡，其亡岂天作。","亡以一贼臣，仓皇弃君父。","半夜开国门，三宫不遑顾。","诈言奉太后，行间犯霜露。","屠毒我民人，豺狼宁有数。","疾攻广德城，相公肆虓怒。","太守抗凶威，矢石下如雨。","为国诛元憝，众心恐不固。","勖哉为国殇，有身白如瓠。","腐肉何芬馨，乌鸢俾含哺。","七尺即金汤，作气无朝暮。","畿南股肱郡，死守非无故。","颈血直射天，贼臣亦崩惧。","亦以死吾民，代之齿力锯。","至今旄与倪，涕泣犹缟素。","与彼梅花岭，衣冠两封树。"]},{"t":"赠别朱二陶","f":"五言古诗","c":["与君结相知，一见即胶漆。","是我直谅友，为心何笃实。","谗言日以起，所忤人非一。","君乃爱楚狂，狂歌有得失。","秃鹜啄凤凰，口血乾无日。","毛羽何摧颓，交亲笑且咥。","都蔗不可杖，徒然甘如蜜。","蛇床不可怀，能乱薇芜质。","白璧难久完，夜光天所嫉。","努力为不才，片言杀身毕。","吾友罕夹辅，君行复仓卒。","士败气不挫，玉碎光逾出。","妖蛊仅一时，吾道戒淫泆。","君去我益孤，相思成疢疾。","无人为禦侮，所恃两贤匹。","季心一手援，鲍宣复相恤。","握手立斯须，慷慨情洋溢。","弱龄学古道，垂老犹骄逸。","补过兹不暇，君其加诸膝。","君子爱同类，岂敢为私昵。","恺悌毋信谗，所望诸侨肸。","临岐路涟涟，风叶为萧瑟。"]},{"t":"从军行","f":"五言古诗","c":["我亲疾痛馀，颐养少甘毳。","手足苦不仁，扶持赖两弟。","为国弃庭闱，此行伤进锐。","七尺遂许人，天年不遑计。","远惭狗屠者，好勇诚吾蔽。","亲日既苦短，喜惧心徒系。","豪杰贵先人，奋扬在乘势。","利剑苟在掌，即可操宰制。","获报君父雠，于孝乃不细。","努力赴戎行，介胄不挥涕。","上天悯苦心，所希锡智慧。"]},{"t":"赠王给事 其一","f":"五言古诗","c":["君家临大河，龙门仅数武。","生长飞浮山，耕牧安瘠土。","西河溯遗风，咏歌三百五。","小序乃国史，得失于焉取。","周南本根地，厥惟夏阳古。","太姒窈窕姿，宫人所歌舞。","洋洋雎鸠篇，房中以为祖。","君诗兼风雅，哀乐有规矩。","后妃与琴瑟，文王与钟鼓。","文母墟墓存，再拜以依怙。"]},{"t":"赠王给事 其二","f":"五言古诗","c":["合阳诗大宗，苏武开其始。","西京十九篇，丽则同芳轨。","文质何相宣，汉风此尽美。","君如清庙瑟，唱叹得遗旨。","太音在朱弦，神明所张弛。","五言变风雅，乐府亦驱使。","河华气所生，子卿共乡里。","元精得太素，刚厉岳灵似。","神胡一赑屃，洪流为披靡。","手荡龙门开，二山忽分峙。","太华以四方，削成苦如砥。","君从白帝求，混茫得斯理。"]},{"t":"赠王给事 其三","f":"五言古诗","c":["读书芝阳山，子长祠在侧。","土高风淳朴，大文以为则。","灏气接周秦，含弘复金德。","治水临沱潜，七年蠲寝食。","忧旱索鬼神，五行哀失职。","奉圭祀孔虔，孳孳以稼穑。","汉江与争命，蛟龙戢其翼。","身为淇园楗，决口于焉塞。","上帝悯精诚，胼胝为沟洫。","微官免为鱼，成功告禹稷。","平生河渠书，至此得尽力。"]},{"t":"赠王给事 其四","f":"五言古诗","c":["治行以循良，厥为天下最。","徵拜居黄门，直言无内外。","奉使日南来，咨询惟利害。","执辔当市门，殷勤驻旌旆。","求贤得彼姝，片言若龟贝。","下问何温恭，小心事耆艾。","好学以无倦，所书溢鞶带。","富有非文章，日新乃光大。","持节还承明，喉舌帝所赖。","北斗一斟酌，元气以滂沛。"]},{"t":"梅花村作","f":"五言古诗","c":["路从卖酒田，乃至梅花村。","罗浮梅大宗，太古多遗根。","纷纷诸岩谷，红白皆子孙。","蔽亏玉女峰，含吐扶桑暾。","依依绿毛鸟，朝夕相寒暄。","白名曰么凤，啾嘈似有言。","团团以相抱，首尾无一存。","倒挂以自娱，雌雄情何敦。","氤氲两翅间，一一梅花魂。"]},{"t":"松上兰","f":"五言古诗","c":["兰生乃无土，托根高松端。","为君作萝茑，青青同岁寒。","馨香在天半，无因充玉盘。","嗟尔搴芳人，盻望空长叹。","紫茎何袅袅，绿叶何反反。","但见白云覆，安知清露漙。","嗟彼生沅湘，枝枝临江干。","行人得采撷，持以成幽欢。","一朝蕙草晚，弃捐同齐纨。","虽蒙置箱箧，讵异涂泥间。"]},{"t":"箁提坛","f":"五言古诗","c":["菩提有灵树，植自萧梁前。","智药所移根，航海来炎天。","岁久干中空，苍皮相纠缠。","根须自上生，千百垂连卷。","大者成虬螭，小者藤萝穿。","结束成一身，四体何拘挛。","下枝多洞穴，崩陷至三泉。","上枝虽臃肿，亦自方且圆。","雷霆日大索，鳞爪无留奸。","神火所焦灼，千寻亦童颠。","二月叶始陨，槎枒馀一拳。","叶状如柔桑，五川争新妍。","僧伽沤成纱，弱薄如翅蝉。","持以遗远方，恍惚鲛绡烟。","南中多怪木，巨者惟木棉。","柯作女珊瑚，丹葩烧天边。","开时无一叶，一一烽火然。","光如十日出，吞吐海东偏。","么凤巢蕊中，血染绿毛鲜。","复有细叶榕，交阴连陌阡。","根须亦倒生，合抱为一椽。","纵横作广厦，户牖相盘旋。","腹大容十牛，亦可藏舟船。","皮肤左右纽，瘿瘤以万千。","士女所婆娑，伏腊拜必虔。","菩提更神怪，与之难比肩。","大士昔灌溉，甘露流涓涓。","左与诃子接，右与频婆连。","蒲葵居门外，其寿亦彭篯。","下滋达磨井，上蒙虞翻园。","肥沃多火膏，咸气不能宣。","菩提所覆被，细草皆芊绵。","累石作香台，虫蚁愁攀援。","谈经者谁子，袈裟罗东西。","空中雨四花，大半为青莲。","琉璃作喉舌，宗派开南禅。","遗坛久寂寞，钟鼓徒喧阗。","大夫京国来，车骑何连翩。","求古得招提，实为越王宫。","牛羊所踯躅，霸气成埃尘。","楚冢既芜没，佗城亦已平。","番禺作双阙，药洲犁为田。","英雄乃椎结，窃据亦其贤。","身为裸国王，兴亡诚足怜。","不才叹乔木，汝乃全天年。","不蒙匠石顾，鬼物司其权。","人生有太和，日月苦相煎。","本根不自固，轮囷安得存。","文梓化青牛，老枫成羽人。","精气非我有，与物相推迁。","愿言保萌蘖，三复牛山篇。"]},{"t":"五仙观","f":"五言古诗","c":["神灵所窟宅，厥惟祝融乡。","浮丘与安期，来往亦不常。","何者五仙人，各骑一色羊。","手持五谷穗，芃芃三尺强。","黍稷居两旁，粳稻居中央。","羊亦衔果蓏，以种遗炎方。","丰年再三祝，倏灭馀景光。","越人念粒我，春秋修蒸尝。","报赛若先农，水旱仍遑遑。","作观楚庭西，五仙列成行。","少者反当中，老者左右方。","膝前各一石，或蹲或翱翔。","或立或僵卧，大小相低昂。","抵触势有馀，角形弯以长。","言是羊所变，毛质皆青苍。","一卷自周时，摩挲历帝王。","斑驳见手泽，表里含光芒。","番夷多膜拜，薰用苏合芳。","馀窍出烟气，一缕何飞飏。","恍若白云核，氤氲所含藏。","尺寸天所留，所关乃雨旸。","吁嗟尔君子，言观来芝房。","南交多瑰货，不以充资装。","依依此怪石，三叹空徬徨。"]},{"t":"送张超然还虞山","f":"五言古诗","c":["去年春上巳，送子珠江南。","愿子岢峨舟，上无樯与帆。","今年小寒食，送子珠江北。","愿子万里身，上有双飞翼。","三岁别妻孥，梦中见颜色。","吴下一舂人，鸳鸯苦无力。","娇女未扶床，呱呱在锦臆。","游札有遗风，伯鸾所朝夕。","昔家梧宫傍，今移拂水侧。","言公昔浣衣，有石方且直。","夫在石东耕，妇在石西织。","节节皆为双，白纻充衣食。","裁成一明月，皎洁终何极。"]},{"t":"行药城东作","f":"五言古诗","c":["仲春已清和，逍遥可行药。","炎洲多灵草，勾萌先咀嚼。","采兰者谁子，邂逅当林薄。","无营似白华，无欲同朱萼。","绿叶与紫茎，平生所磨错。","微雨上膏滋，本根远相索。","其旁石菖蒲，尺寸琼瑶削。","紫茸何葳蕤，九节含风弱。","安期所服饵，玉颜以灼灼。","秦帝于我求，蓬莱奋云蹻。","千岁与君期，神仙多戏谑。","桥下流韸韸，少君与斟酌。"]},{"t":"古诗为王将军寿","f":"五言古诗","c":["将军学渊府，日与诸儒游。","纵横飞文雅，藻思纷云浮。","大帐开朝台，道德为戈矛。","清辞若飞兔，超山越海陬。","伊予乃驽骀，龙骥不可求。","首夏气清和，衣袷临河洲。","酒称千金寿，主宾交献酬。","十丈攀枝花，朵大如觥觓。","注酒须瓣中，百壶争川流。","玉女笑如电，红口不能收。","壶矢一再行，雅歌相绸缪。","愿君似山丹，颜渥无春秋。","岁岁珊瑚林，持以为觞筹。"]},{"t":"不草诏","f":"五言古诗","c":["如何圣天子，乃称大将军。","当制不敢草，嫌以臣名君。","皇帝拔剑起，不草即诛尔。","免冠伏殿前，泪流请就死。","刚哉古大臣，不辱朝廷体。"]},{"t":"咏高士王宾","f":"五言古诗","c":["至人能婴儿，嬉戏存天真。","长为浑沌宗，弃智如埃尘。","直木必先伐，甘泉必先湮。","于世吾何求，聊为葛天民。","朝饥采松柏，暮寒栖草茵。","抗节终不回，汤武非吾君。","毁我白玉颜，裂我华阳巾。","遥遥狂接舆，相携共沉沦。"]},{"t":"诃林咏古","f":"五言古诗","c":["萧森诃子林，蒲葵郁相向。","榕树与菩提，枝枝似交让。","岁久根为干，倒生多怪状。","植自萧梁年，半槁神尔王。","下有谈经坛，精灵此惝恍。","昙摩昔盥钵，泉涌何瀁瀁。","海眼虽潜通，洋溢非潮涨。","三酌有馀甘，欲持作春酿。","南汉迹未湮，有无在沧漭。","塔影摇清漪，鱼戏王亳上。","光流若玄珠，盈手可相贶。","佛氏多寓言，翻译劳文匠。","妙道贵神会，无心即罔象。"]},{"t":"老谷树为大风所摧诗以伤之","f":"古风","c":["谷树大数围，植时不知岁。","精多作胶液，注流至根柢。","斲以团丹砂，玄黄何泥泥。","或为金石漆，脂膏苦自毙。","虫蚁所疮痏，百千以肤噬。","臃肿既空心，拳曲亦流涕。","霜皮剥辱馀，虽存若蜩蜕。","窍穴一穿漏，枅圈无巨细。","腹中若蜂房，蛇鼠相启闭。","一二鼻口者，火入烟蒙翳。","疾雷屡震惊，花叶多焦脆。","䬏䬔昨楝风，四方忽排挤。","怒呺一昼夜，柯条尚牛掣。","雨师复掊击，参天俄失势。","朽蠹已有年，婆娑终一蹶。","摧折当腰吕，寻尺若刀?。","崩压西邻墙，斧斤劳仆隶。","大枝劈不开，小枝竞先曳。","凭依惧有神，酒食陈微祭。","丧我高楼阴，炎曦无可蔽。","嘲啾绝燕雀，缠糺失萝荔。","生身本恶木，美名蒙诟厉。","散材一何幸，与檀作兄弟。","托身在丘园，有萚思为砺。","斑谷持作冠，楮桑持作币。","所用虽皮肤，于人已有济。","亦未苦其生，楂梨共狼戾。","本无劲挺姿，枝节多疣赘。","菑害始香甘，蠢动乘其敝。","狙猿杙亦安，岂必高名丽。","受命有穷时，薪蒸不遑计。","培覆皆天年，萌蘖庶自卫。"]},{"t":"闭瓮菜","f":"五言古诗","c":["北人重御冬，菜茹多旨蓄。","芥美在霜根，下体甲诸蔌。","秋脍用多馀，瀹汤杀其酷。","芗料糁屡加，茴香与椒目。","实之大小罂，卵盐相渗漉。","封口水泥坚，芬馨瓮中复。","一闭天地房，氤氲历凉燠。","出之佐齐豉，辛脆宜糜粥。","膏腴餍饫时，爽口凭一匊。","薄切蜩翼微，三朝无白醭。","下酒废烝雏，烧雉及腒䐹。","浙东糟笋苞，吴阊䤉莱菔。","莴苣称秣陵，黄芽说安肃。","岂如斯味嘉，嗜之非口腹。","性温夺七菜，宁惟胜榆肉。","荼苦既不同，荠甘亦非族。","使君撤俎时，以兹雪公餗。","马驮自宝坻，羸瓶苦不速。","故乡风味存，和调自家督。","北人喜芳辣，姜桂日餐服。","牲用煎茱萸，濡鱼多实蓼。","贵以辟天寒，口体非相逐。","化食通五中，为菹及金伏。","岁暮百草萎，市无生菜鬻。","腌者先温菘，藏者及蘡薁。","地炕蕴火多，郁养催瓜菽。","冬生物性违，非时嗟彊孰。","在芥虽易生，秋收忌霜触。","富家千甔瓵，于芥靡赢缩。","贫亦拾滞遗，寒争一日暴。","宁如我岭南，腊月嘉蔬足。","三蒿与二蓝，纷葩滋五沃。","莙荙蔽田塍，菠菱弥水澳。","一稞三两钱，畦畦杂穜稑。","叶青连露葵，花黄若时菊。","冰雪昧平生，微雨时膏沐。","人家菜脯稀，鲜食乘芳郁。","蓣芋如丘山，为饭代粳粟。","豕饲馀芜菁，马衔兼苜蓿。","芥薹四尺强，芼羹亦碌碌。","茎股九蒸晒，间用吴风俗。","野人方灌园，荷锄先僮仆。","三餐厌葱韭，匕箸惭华屋。","从君乞此方，今冬作数斛。","南中水土殊，滋味恐未淑。","须君岁见贻，银鱼及醽渌。"]},{"t":"后割肉诗为汪孝妇作","f":"五言古诗","c":["新妇前割肉，割肉为翁痡。","翁苦膈食人，腹中粒米无。","门前十万寇，杀人肝脑涂。","无从乞针药，鬼伯方呜呜。","救死何所有，所有惟肌肤。","翁命系新妇，气绝只须臾。","抽刀向左臂，虽羸犹膏腴。","一脔大逾寸，重可二十铢。","非方亦非圆，圭璧良不殊。","血裹若绛雪，猩猩红不如。","聂切作和羹，翁食能无馀。","胸膈忽荡开，病瘳不待晡。","贼众闻却走，毋犯孝妇闾。","邻里竞来视，各请翁所需。","馈食悉精美，餍饫翁不臞。","夫时在邗沟，亲友皆来趋。","夫名以妇知，称妇因称夫。","不知夫视妇，芬芳长与俱。","无何先朝露，夫溘归黄垆。","讣闻不欲生，欲殉忧诸孤。","呱呱尚可弃，堂上有舅姑。","舅姑岂盘石，身衰同秋蒲。","匍匐灵柩前，奠馔无蒸雏。","抽刀再割肉，右臂白如瓠。","左臂创末平，刀口成痈疽。","疗翁未死前，割肉犹不辜。","夫既已奄逝，割肉何所图。","肉岂惊精丸，刀圭魂昭苏。","三日苟不生，神即幽酆都。","割之等泥土，祗自戕罗敷。","念己活君舅，天理庶不诬。","为夫惜一脔，恩义何次且。","报生复报死，所捐非全躯。","腥臊不足食，差胜充庖厨。","皇天令不死，五十犹勤劬。","二男已成立，干禄知读书。","母肉尚馀几，一身半菀枯。","在母如鸿毛，宁如惨自屠。","在舅如泰山，返魂因彼姝。","在夫即牲牷，肥腯逾羊酥。","吁嗟夫在外，不得亲口珠。","尊章与藁砧，骨肉何亲疏。","九泉歆此羹，味淡同瓜菹。","十年不同食，所嗜忘其初。","忍死更几时，同穴宁踟蹰。","为寿讵忍言，儿女徒欢娱。","未忘至百岁，蜉蝣归其居。"]},{"t":"王母金孺人寿篇","f":"五言古诗","c":["阿母年稚时，疗亲能割股。","肌肤不敢爱，欲以报依怙。","北宫撒环瑱，不嫁亦何补。","既归事威姑，殷勤持湩乳。","为姑食小郎，鞠育无宁处。","妇也母其姑，身犹膝下女。","朝夕慈旨甘，力作为脩脯。","为舅偿积逋，十指累铢黍。","夫亦用计然，争时务废著。","粪土贵出之，珠玉以贱取。","既富行其德，乐为仁义主。","公子法雍容，游閒孔氏伍。","得利愈纤啬，归富乃廉贾。","暮齿返乡闾，骨肉欢相聚。","有子二三人，多才学渊府。","岁朝陈椒觞，上寿歌且舞。","偕老始六旬，孺子色犹妩。","白头喜戴胜，垂发至腰吕。","堂前大小妇，髻高学天姥。","百福开春奁，千华献瑶筥。","为母称无疆，与公享天祜。"]},{"t":"送王立安还宝坻","f":"古风","c":["朝辞罗浮东，暮指田盘北。","代父观察公，还家敦子职。","太公七十馀，未杖多筋力。","好学日神智，康强以不息。","天生难老姿，况复善饮食。","脍兔春宜葱，羹鱼香用稷。","自酿渠阳春，益滋玉颜赩。","元气日斟酌，用精解纤啬。","耇造多子孙，一一皆歧嶷。","大小诸童蒙，纳妇家能克。","观察政大成，悦亲道已得。","迎养苦路长，炎荒在蛮域。","兹焉复川南，蜀道劳攀陟。","尊老不遑将，靡盐情郁抑。","所喜太公年，春秋尚千亿。","眉寿天所私，于以报平直。","君今去奉养，慈孙人尽识。","文章焉旨甘，仁爱乃容色。","神明出不穷，古人渐相逼。","吐纳风与骚，以为大雅则。","子道在白华，弦歌贵朝夕。","无欲尔处子，堂堂作矜式。","脂车明启行，逾岭方崱屴。","间关岂不苦，庶以荡胸臆。","山川洞经纬，利害知兴塞。","情伪若观火，庶几免回惑。","风尚还淳庞，人心去邪慝。","持此经术功，自可一道德。","行矣趋祖君，于彼无终国。","候雁春方归，翩翩同矫翼。","上堂奉几杖，嬉然随钓弋。","馀閒向南丘，或亦观稼穑。","引领当夔门，仆夫正匍匐。","嵚崎栈阁倾，诘屈车轮仄。","蚕丛九折中，而翁驭方叱。","江行复滩崄，丛石争雄特。","千盘出崩厓，百丈牵生竻。","巫云撒白盐，三峡俄昏黑。","舟与淫预斗，象马势不测。","入城尚无人，猿狖疑苍赤。","豺虎方咆嗥，甘人作口实。","况渡泸水西，壤已邻滇僰。","乌蒙与镇雄，翘首神君亟。","抚绥亮有方，威爱知无忒。","艰难移孝时，庭闱不敢即。","万里致忠勤，何殊在亲侧。","往觐君毋然，垂堂且自敕。","居行各有经，至性本天植。","纯孝质有馀，不受丹青饰。","矧君迩京华，会当驰玉勒。","竭考得秘书，凤池簪笔入。","日惟大父庆，此事亦孔棘。","帆开珠海湄，沙喧起鸂?。","送送无尊酒，何以慰相忆。","泽陂有芙荷，中心含苦薏。","美人硕且鬈，寤寐终何极。"]},{"t":"题桃画","f":"五言古诗","c":["父年九十二，松翠多霜姿。","女年七十一，萱荣含丹晖。","父乃为女寿，濡笔何淋漓。","画出绥山桃，红灼如花时。","葳蕤带绿叶，硕大垂青枝。","五桃象五孙，大小光离离。","王母此奇果，玉盘盛参差。","昔与汉武帝，食之享期颐。","父今亦方朔，持以与女儿。","女为人尊母，福履无穷期。","康健富筋力，玉杖尚未持。","行李已大耋，厥翁方秀眉。","作使萼绿女，奉觞亦不迟。","闺庭日为乐，和气何雍熙。","嘉庆留此图，令人生孝慈。"]},{"t":"赠佟声速","f":"楚辞体","c":["长君四十年，汝乃谓予兄。","岂非以才故，虽少可雁行。","我愧老无闻，蹉跎徒杖乡。","于道苦不足，岂敢矜文章。","殷勤辱招致，何以酬谦光。","暇日开园林，相与浮羽觞。","袒跣攀芙荷，礼法亦已忘。","亭似华绛跌，注立池中央。","义如千叶间，特出为莲房。","君多令兄弟，靴如唐棣芳。","华萼相承覆，亲爱多嘉祥。","伯兮宰大邑，治行称循良。","叔季皆大器，磨砻成圭璋。","与父观察公，撞踵登庙廊。","君今未欲仕，散带聊清狂。","黄金得贵显，是道奚足臧。","才如汉司马，嗟彼乃赀郎。","时时幸称病，不逐诸公卿。","得与文君欢，饮酒清琴旁。","君今美辞赋，知己多鸳鸯。","毋令绿衣人，侵彼丹凤凰。","君子哀窈窕，不淫师文王。","如彼王雎鸟，和呜当春阳。"]},{"t":"临危诗","f":"五言古诗","c":["丙子岁之朝，占寿于古哲。","乃得邵尧夫，其年六十七。","我今适同之，命也数以毕。","所恨成仁书，未曾终撰述。","呜呼忠义公，精神同泯沕。","后来作传者，列我遗民一。","生死累友人，川南自周恤。","独漉题铭旌，志节表而出。","华趺存后人，始终定无失。","林屋营发冢，俾近冲虚侧。"]},{"t":"御书歌","f":"七言古诗","c":["先皇昔爱松风吼，时作松风字如斗。","铁画银钩草带真，宣庙神宗同一手。","国变馀君大布衣，兼金购得御书归。","日日焚香瞻圣藻，天门龙跳见天威。","手种苍松何礧砢，松髯看似龙髯堕。","皮经岁月长斑鳞，子为乾坤留硕果。","血泪风吹无尽时，枯枝复似海棠枝。","岁寒不为君王改，节苦惟应天地知。","华阳昔种苍松盛，白衣宰相言符命。","一身前后事齐梁，有愧松风清且劲。","君今对越松风字，先帝威灵应鉴只。","千秋御气托茅茨，一片神光生玉玺。","殷勤拂拭绝纤埃，芳辣三薰恐蠹来。","异日黄纱笼入献，文华殿里待重开。","二字煌煌如大训，九宾肃肃设平台。"]},{"t":"烈皇帝御琴歌","f":"七言古诗","c":["呜呼苍天不可识，炎精久被虹霓食。","共工怒触天寿崩，百神惊走惨无色。","先皇龙战血玄黄，云中徒跣归文昌。","臣寻弓剑煤山旁，泪枯参天双海棠。","宫门邂逅故尝侍，曾见先皇诸宝器。","乌嘷久已殉银泉，龟书无复藏金匮。","惟馀一琴贼不伤，真人手泽犹光腻。","花纹细作飞龙形，玉管亲题翔凤字。","济南李卿怀孤忠，千金购兹太冥桐。","拂拭神蛾丝五色，沐浴珠徽光的皪。","月明如见朝鬼神，天阴时闻轰霹雳。","我从李卿请琴观，楚囚相对泣南冠。","湘妃锦瑟秋风咽，山鬼罗衣夜雨寒。","欲排阊阖叩天鼓，忠信翻为虎豹侮。","乾崩坤拆帝无闻，日拥投壶诸玉女。","蒲陂南薰操不成，昆丘黄竹歌空苦。","宵衣旰食十馀秋，有宫无商泪自流。","大弦既急小弦绝，谁为君王蠲百忧。","其时坐有杨太尝，曾承天语称师襄。","玉熙宫中久供奉，琴声高奏侑羽觞。","岐伯铙歌扬武德，延年乐府擅鸿章。","呜咽牵予诉遗事，咬春燕九陪游戏。","琵琶水殿弹娇娥，龙舟争采夜舒荷。","唐山新制房中乐，黄鹄交飞太液波。","叠叠水嬉金傀儡，纷纷过锦玉婆娑。","月照龙颜含喜色，千秋万岁乐宁多。","千秋万岁乐无多，忽尔辽阳烽火动，焦劳无复听云和。","天昏莫埽蚩尤雾，河决谁怜瓠子歌。","吹角难令玄女降，舞干其奈有苗何。","甲申三月燕京乱，此琴七弦忽尽断。","玉殿横飞铁骑声，天威先示空桑变。","从此中华礼乐崩，八音遏密因思陵。","小臣亦似峄阳干，半生半死难骞腾。","伏波马革裹未遂，轩辕龙髯攀不能。","感君珍重此琴归，九庙神灵实凭依。","鼓之舞之元气驰，帝出乎震是今时。","殷荐上天以崇德，此琴将为圣人师。","太尝于焉再稽首，为取赐琴挥玉手。","童子金炉添御香，主人朝服当西牖。","落日阴连海岱云，平沙远映青徐柳。","初拨宫弦钟吕鸣，缥渺箫韶吟紫清。","春风吹满蓬莱阙，和銮正绕千花行。","移商未成忽变徵，剑戟相摩两不止。","中原群盗俄蜂起，至尊叹息呼赤子。","更调角羽风嘈嘈，中见黄巾争舞刀。","杀人无声如刈蒿，茫茫百草儿女号。","又闻投鞭渡临洮，九龙池水流人膏。","百官披发冲波涛，君王泪沾火藻袍。","笳声夜奏单于小，猎火秋悬太白高。","堂堂天朝事遂去，可怜万国无臣庶。","往日霓裳宴太平，开元子弟俱何处。","抔土谁封金粟堆，杜鹃自挂苍梧树。","惊风如刀频割弦，欲续断弦双手酸。","馀音绕梁何缠绵，满堂宾从皆涕涟。","请君罢弹莫终曲，恐令南北诸侯哭。","偶然失势龙为鱼，终见时来马生角。","他朝日月定重输，今夕鸾皇聊独宿。","否极泰来天有尝，万里高飞翼先伏。","偕君阿阁贺升平，雌雄和鸣三十六。"]},{"t":"绿绮琴歌","f":"七言古诗","c":["罗浮四月春泉决，流出千溪万溪雪。","丰湖浩渺连空天，鸳鸯鸂鶒纷明灭。","主人汉代执金吾，归筑楼台半在湖。","桂棹湖南邀宋玉，银筝湖北奏罗敷。","顾谓双鬟陈绿绮，一时宾客皆倾耳。","言是中书邝子琴，珠徽如月寒光起。","梅花千片断龙鳞，沉香一节烧鸾尾。","制自唐朝武德年，隐隐金书御玺连。","毅皇亲向宫中选，赐与刘卿世世传。","中书乃自刘家得，似捧乌号泪沾臆。","珍重君王手泽馀，大弦小弦日拂拭。","时飞纤指理南风，彷佛重华见颜色。","自从朔骑围三城，中书奉使归筹兵。","日与元戎亲矢石，时将彩笔作戈旌。","双阙恨屯回纥马，六龙愁在亚夫营。","城陷中书义不辱，抱琴西向苍梧哭。","稽康既绝太平引，伯喈亦断清溪曲。","一缕肠萦寡女丝，三年血变钟山玉。","可怜此琴遂流落，龙唇凤嗉归沙漠。","蔡女胡笳相惨凄，王昭琵琶共萧索。","叹君高义赎兹琴，黄金如山难比心。","我友忠魂今有托，先朝法物不同沉。","我昔山东见翔凤，念是威皇手所弄。","复从太尝见赐琴，一朝开元旧供奉。","背有崇祯玉玺留，五声亡角悲民流。","太尝为我一挥手，呼天抢地愁复愁。","君是当年侍从者，出入尝陪八骏马。","十三官拜羽林郎，二十战酣涿鹿野。","一自龙髯不及攀，丰湖一曲遂栖閒。","乐器不同微子抱，淋铃难见上皇还。","此琴宝惜宜加厚，列朝恩在宫商间。","安得翔凤入君手，更召太尝至窗牖。","一奏当令白鹄翔，再弹会见神龙吼。"]},{"t":"布政张公挽歌","f":"七言古诗","c":["贵阳城崩谁巷战，参政张公奋刀箭。","手提银印血模糊，冒阵一呼天地变。","贼怜神勇欲降公，泰山自掷鼎镬中。","奋骂一军皆辟易，舌如电光不敢食。","丈夫羞与贼同生，妾媵欢然争死敌。","愿为良臣安可得，杀身成仁亦何益。","腐肉如山魂袒裼，白昼城中犹荡击。"]},{"t":"与陈明敬采方竹作","f":"七言古诗","c":["不采禹阳阮隃枝，不求罗娇笼䈡干。","闻君方竹拂云霄，枝枝中矩堪把玩。","我生好入名山游，手中竹杖是朋俦。","阮隃只堪作长笛，笼䈡但可架高楼。","爱兹方竹坚如铁，出入扶持宜暮节。","进长居后退居前，令我不随人磬折。","贤人方之圣人圆，嗟余违世不知权。","但使乔松得本性，何须散木终天年。","与君向此筼筜掘，磊砢怜伊有正骨。","摩娑不减金琅玕，铿然爪甲声清越。","人间五岳好游嬉，莫教尚平婚嫁迟。","骑二茅龙君不羡，驾三青鸟吾不希。","但将方竹作双杖，与尔高高上翠微。"]},{"t":"送韩石耕","f":"七言古诗","c":["我闻黄山有汤泉，轩辕浴之飞紫烟。","琼楼珠阙万峰连，瀑布为梁度群仙。","白云瀰漫如沧海，丹台石笋忽不在。","天风吹开金芙蓉，中有日月纷光彩。","送君归去餐日华，桃花片片是丹砂。","三日容颜如玉女，却来同我登青霞。"]},{"t":"愤歌","f":"七言古诗","c":["时人皆谓我狂生，蓬头垢面纵横行。","神龙变化愧无力，失水乃与蝼蚁争。","哀哉天下日沉浊，孟轲好辩遭凌辱。","从来君父若浮云，暮楚朝秦非反覆。","我今守道诚不详，孔雀何如牛有角。"]},{"t":"上千尺峡百尺峡至温神洞宿","f":"七言古诗","c":["十八盘尽见西峰，游人匍匐上芙蓉。","攀援铁绠数千尺，身似飞猿时一掷。","阴阴天井上穿天，袅袅石梯悬度石。","神爽先飞玉女峰，啸歌暂憩羽人宅。","月中明灭白云流，风外砰磅瀑泉激。","咫尺翻愁帝座逼，吐纳聪明慎今夕。"]},{"t":"西峰访范复庵不值留赠","f":"七言古诗","c":["横天一壁惊无路，频骑夹岭空中度。","栈边万壑沉青冥，桥下千峰出烟雾。","我从玉井得真源，明星玉女招不顾。","直向西峰攀所思，楼压莲花花倒垂。","三闾披发同山鬼，四皓疗饥有紫芝。","咫尺白云寻不见，先朝耆旧君堪恋。","无悲帝座隔层城，自有天门通一箭。"]},{"t":"西峰下窥水帘洞作","f":"七言古诗","c":["玉井潜流为瀑布，诸峰喷薄如烟雨。","天风吹断水晶帘，似见投壶诸玉嫭。","河汉纵横难为梁，欲度不度愁参商。","石髓金精不我与，银台玉室徒相望。","山鬼幽篁悲昼晦，美人其雨怨朝阳，行歌散发且徜徉。"]},{"t":"华顶放歌同王伯佐","f":"七言古诗","c":["太华峻极惟南峰，脚踏万朵青芙蓉。","东西二峰尚匍匐，白帝上宫不敢即。","天柱摇摇风欲倾，元气茫茫日无色。","我行飞栈若惊鸿，君骑搦岭如游龙。","君过玉女饮三浆，我向将军攀五松。","狂啸翩翩凌绝顶，目营四海神光骋。","水帘高捲入珠楼，莲叶深披探玉井。","黄河浩浩泻愁心，明月苍苍逐孤景。","尘垢犹堪铸帝王，清虚何足留箕颍。","形势依然天府雄，龙争虎斗谁途穷。","千里金城收一掌，万年甘露待重瞳。"]},{"t":"王允塞招饮竹林精舍醉赋","f":"七言古诗","c":["黄神谷口开精舍，萧萧树石流泉泻。","主人觞我竹林前，与客七人成七贤。","旷达谁能拘礼数，豪雄不屑居神仙。","娇歌急管且流连，蛾眉相妒不相怜。","蹩者欲斩平原妓，蔡经难受麻姑鞭。","醉来飞马直上天，蹴踏华峰十丈连。","人间万事如尘烟，我乃酒狂合自然，请君无为醒者传。"]},{"t":"长春石室","f":"七言古诗","c":["长春先生好吹笛，吹之裂尽华山石。","一笛持来只一吹，岁用琅玕数千尺。","一吹即复投岩中，笛与人间制不同。","人间不见长春笛，惟闻笛声满碧空。","仙人自古重音响，吹使乾坤气清爽。","一曲中和致太平，遗音千载穿云上。","我向先生石室栖，每寻长笛临回溪。","愿作仙人笛弟子，朝朝吹彻云台西。"]},{"t":"洗象行","f":"楚辞体","c":["玉河六月河水长，朝廷旧典赐洗象。","昆明不见旧楼船，太液何来新甲仗。","倾都观者皆欢娱，宣武门外铺氍毹。","公子踏花红叱拨，佳人障日锦屠苏。","须臾前导执金吾，二十四象天街趋。","龙旂送出千门柳，羽骑迎过万岁湖。","花牙润洁体雄诡，横行郁若丘山徙。","自是瑶光星降精，惟有神龙力可比。","夜郎蛮奴驯习者，手握银钩左右下。","骑入洪波走巨鱼，突出平沙惊万马。","水花澒洞溅浮云，两边金鼓鸣虎贲。","似逢光武昆阳战，如破吴王水犀军。","万人喧呼动城阙，一片红尘污冰雪。","争道骅骝拥御桥，两行灯火侵宫月。","白头中使偶相逢，三朝腰玉赐穿宫。","谓余此象养天厩，当年俸与将军同。","晓披璎珞朝皇极，秋驾銮舆出喜峰。","去岁云南师败绩，象兮曾与沮渠敌。","周王八骏去何之，夏后两龙归未得。","可怜巀嵲虎豹姿，虽饱膏粱泪沾臆。"]},{"t":"赠清霞子","f":"古风","c":["我昔游太华，亦上终南山。","为寻仙人清霞子，那知乃在东湖间。","本是紫髯一将军，家在贺兰临塞云。","赫连台畔时游猎，花马池前成典坟。","曾逐孙公大司马，血战黄巾郏城下。","七日霖雨真可怜，三军粮绝泪频洒。","潼关再战功垂成，天妒孙公使结缨。","为忠只有乔参赞，作叛何多白总兵。","清霞此时河南走，黄石兵书尝系肘。","英雄且战且学仙，旷达一吟一饮酒。","九圣微言久寂寥，神明幽赞暮还朝。","王弼天人谈不倦，庄周蝴蝶梦相邀。","东湖水自罗浮落，石室烧丹汝新作。","要将鸡犬共冲云，莫使嫦娥先窃药。","潘茂名、郁先生，千年象数相传授，后天之学汝尤精。","至人变化无生死，一龙一蛇谁得似。","曼倩何妨谑浪多，老聃不在虚无里。","夏日荷花满湖绮，玉琴三弄鸳鸯起。","我言素女即丹砂，君欲云英化为水。"]},{"t":"辛亥中秋夕作","f":"七言古诗","c":["去年月比今年好，娇女如花在襁褓。","手持一物笑当门，柚子灯红如玛瑙。","前年月比去年明，内子新归自镐京。","画舸朝维杨柳岸，香车暮入凤凰城。","盘中果爱甘蕉美，槛外花怜抹丽清。","稚子争围秦弄玉，慈姑似见计飞琼。","今年月色如冰冻，独坐帘前抱哀痛。","吴宫紫玉遂成烟，巫岫朝云元是梦。","幽魂不返月支香，仙蜕已藏毛女洞。","泪落黄泉知不知，黄泉少见月明时。","难将一片天边月，长照黄泉冰雪姿。","黄泉母子应相见，见此月明泪如霰。","人间月似白玉盘，地下月如白团扇。","团扇光辉乍有无，愁君失路一身孤。","夜深环佩归宜数，莫向黄泉空望夫。"]},{"t":"雷阳郡斋醉中走笔呈吴使君","f":"七言古诗","c":["使君风流世所宗，饮酒不醉真酒龙。","一麾出守濒海郡，三年坐啸擎雷峰。","有一酒狂人不容，闻君新醅荔支浓。","沉香觥船大如斗，中有扇沙嫩鹿茸。","香狸之脯鲨鱼翅，玉盘行出和春菘。","使我朵颐不能已，番禺千里来相从。","中秋月照郡斋夕，轰饮吏人俱辟易。","鲸鱼自合乾百川，鼹鼠犹能尽一石。","玉山忽倒红氍毹，谈禅交吐夜光珠。","娇歌婉转东西和，花旦温柔左右扶。","英雄达生无不可，一代糟丘今属我。","古来贤圣尽浮云，岂必二豪同蜾裸。","昔人酒中谁陆沉，阮公一醉直至今。","酣放动经六十日，千载惟公知此心。"]},{"t":"寿汪虞部","f":"七言古诗","c":["南阳老人汉郎官，七十面如红玉盘。","家近浮丘丈人馆，御女早得轩皇丹。","二月罗浮大蝴蝶，纷纷出茧食花叶。","山人言是小凤凰，五色之鸟为臣妾。","有似君家诸小郎，三岁四岁初扶床。","琳琅尽是天庙器，神仙之雏不可当。","君今垂老多欢乐，左鬓会应生肉角。","著书已当内外篇，采药还期南北岳。","从来大道贵传人，长生有术予将学。"]},{"t":"陈丈种花歌","f":"古风","c":["丈人无事惟种花，花开红白如明霞。","朝从花市得金错，暮向花田吸月华。","花中一树绿萼梅，下有水仙数丛开。","水仙乃自秣陵得，绿萼元从罗浮来。","愿作罗浮大蝴蝶，与君朝朝食花叶。","愿作罗浮五色禽，与君暮暮宿花林。","清凉海棠大十围，吉祥古梅自六代。","不及君家此园春，千葩万粟飞成茵。","閒来只抱丈人瓮，隐去谁知渔父津。","自结二亭小，稏兰花四绕。","冬有芙蓉亦有桃，绝喜岭南霜雪少。","花落争来酿酒人，花开早至收香鸟。","往时朱叔贤，种花禺阳边。","殷勤葬落花，处处成花阡。","与花共生死，好花成神仙。","君今落花弃不可，日日埽来尽与我。"]},{"t":"东湖篇赠高明府","f":"七言古诗","c":["柳丝柳丝长复长，虽长难系紫鸳鸯。","鸳鸯飞逐落花去，使我攀丝空断肠。","使君欲执鸳鸯鸟，来向东湖临浩渺。","更怜鱼尾红筛筛，不惜竹竿长袅袅。","佳人忽自罗浮来，中有梁陈多丽才。","云霞被服三铢剪，蝴蝶文章五色裁。","风流携得诸伎乐，娥郎一曲传边朔。","十番大小更誇人，诸童新就吴侬学。","使君渊雅最知音，邀下楼船更鼓琴。","章句离骚殊未已，弦歌三百一何深。","公馀祗欲寻高士，荷叶荷花映人吏。","著书却笑葛稚川，虚无但道神仙事。"]},{"t":"高州大水作","f":"七言古诗","c":["天决鉴江灌高凉，一夕水高三丈强。","西南二门白昼闭，城中城外愁汪洋。","大雨滂沱不得止，飓风吹倒牛与羊。","千家号哭万家走，妇子尽同鱼在罾。","白波捲去南巴城，烟火不知何处有。","蛟龙拔木山欲摧，潭中惊出雌雄雷。","狂夫欲渡不能渡，中流浪打被发回。","二村已遭白牛陷，挺剑我欲为澹台，斩尽水怪无凶灾。"]},{"t":"龙门健儿行","f":"楚辞体","c":["龙门健儿身手强，绵木为鎗三丈长。","三人持一绵木鎗，风旋电转谁能当。","进四尺兮退四尺，挑起人马半空掷。","朔骑干群丧精魄，前锋夹以竹篙锥。","三丈不足二丈馀，藤牌絮被滚如珠。","三眼鸟鎗洞铁甲，绕指郁刀随捲舒。","憔铜锋镝涂毒药，猛虎中之仅三跃。","用短尤能精用长，纵横击刺千军却。","往日勤王义气作，文烈张公恣挥霍。","大小百战似雷霆，长驱几欲空沙漠。"]},{"t":"奈何帝歌","f":"古风","c":["奈何帝，奈何帝，风流亡国亦足豪，美人相抱井中坠。","可惜井中水不深，美人不死伤我心。","泪痕化作胭脂痕，千秋漠漠苔花侵。","苔花侵，美人墓在青溪阴。","不死胭脂死青溪，可怜不作井中泥。","国亡不恨恨惟此，山河不易一女子。"]},{"t":"南海神祠古木棉花歌","f":"七言古诗","c":["十丈珊瑚是木棉，花开红比朝霞鲜。","天南树树皆烽火，不及攀枝花可怜。","南海祠前十馀树，祝融旌节花中驻。","烛龙衔出似金盘，火凤巢来成绛羽。","收香一一立花须，吐绶纷纷饮花乳。","参天古干争盘拿，花时无叶何纷葩。","白缀枝枝蝴蝶茧，红烧朵朵芙蓉砂。","受命炎州丽无匹，太阳烈气成嘉实。","扶桑久已摧为薪，独有此花擎日出。","高高交映波罗东，雨露曾分扶荔宫。","扶持赤帝南溟上，吐纳丹心大火中。","二月花开三月叶，半天飞落人争接。","东风乱剪猩红绒，儿女拾来柔可摺。","正及春祠百谷王，神灵不使马蹄蹀。","还怜飞絮白如霜，织为緤布作衣裳。","银钗叩罢双铜鼓，岁岁看花水殿旁。"]},{"t":"寿霍丈","f":"古风","c":["天上有寿星，饮酒辄一石。","人间有酒龙，为寿亦过百。","君今六十兴翩翩，梦想庐山醉石边。","讲学十年称祭酒，隐居双岳得飞仙。","山禽吐锦当晴日，海气成楼在晓天。","杖策逍遥无不可，酣来更拂落花眠。"]},{"t":"汪虞部以咂嘛酒惠奠华姜赋谢","f":"古风","c":["华姜本秦人，平生爱芦酒。","华山玉泉与醴泉，槐曲酿之尝在手。","截竹为筒一尺长，华夫相对吸天浆。","注以玉女洗盆水，糟中时有莲花香。","自到岭南芦酒少，荔枝龙眼甜难尝。","樽石先生知嗜好，惠我数罍手所造。","秦娥一笑忘他乡，粤客三杯通大道。","夫妇欢娱曾几时，一朝蕙草先秋萎。","中圣中贤我不忍，含哀久与杜康辞。","先生悯念黄泉下，芦酒今朝奠一斝。","馨香更用返魂烧，清冷如将甘露洒。","恍惚既醉朱颜酡，姗姗来迟可奈何。","意气未能忘赋客，精灵应解报恩波。"]},{"t":"伶俐江口遇风作","f":"七言古诗","c":["北风吹舟冲石壁，我篙竞下如拒敌。","夹岸溟濛沙乱飞，中流汹涌石相击。","舟破定知触鬼神，樯折有声如霹雳。","风狂岂可满帆张，长年不戒使我伤。","忠信宁忧白头浪，笑谈曾渡莲花洋。","不须弯弓射潮水，且复横槊赋诗章。"]},{"t":"寄赠高博罗","f":"七言古诗","c":["使君昔宰罗浮西，讼堂水接罗阳溪。","使君今宰罗浮东，浮碇高冈在县中。","罗山为主浮为客，罗与浮分峰四百。","使君岂亦一仙人，长与罗浮合精魄。","为政风流近若何，著书应比葛洪多。","仙方不屑言黄白，王道惟知保太和。","我别罗浮亦已久，从军欲出飞狐口。","不似浮山有所依，长与朱明为户牖。","当年著得罗浮经，欲待功成勒翠屏。","使君词赋应多载，留照山中御简亭。"]},{"t":"送曾止山还光福歌","f":"七言古诗","c":["炎洲之南天气和，梅花更比江南多。","梅花大宗在庾岭，小宗乃在罗浮阿。","春来开遍枝南北，万壑千岩花四塞。","梅花将军越王孙，汤沐正在梅花国。","飞扬往日破强秦，沛公项羽资其军。","台岭因之号梅岭，梅花万户酬功勋。","风吹上天雪纷纷，行人远望如白云。","檀香玉蝶大可爱，萼绿香气尤氤氲。","西溪邓尉天下闻，当年种自梅岭分。","梅花子孙亦太古，光福一半今在君。","淮南作客胡为者，十月梅花已堪把。","花片堪为三月粮，岁寒何用离花下。","太湖万顷当门前，君归更浮洞庭船。","莫釐缥缈二峰接，人家多种梅花田。","我将移居向慈里，与君咫尺梅花里。","千年冰雪作肌肤，欲学仙人姑射子。","梅花岂是一尘垢，铸舜陶尧将以此。"]},{"t":"广陵篇赠别吴鹿园","f":"七言古诗","c":["江北烟花是广陵，江南山水惟京口。","蕃釐观左一逢君，欲典衣裘取清酒。","飞桥十五首红桥，夹岸蘼芜渐及腰。","才子偏来明月夜，美人不见落花朝。","芜城一赋君能续，更有冶春三十曲。","千载知音是紫薇，竹西歌吹伤繁促。","哀怨犹多楚性情，荒淫未变吴风俗。","山中虽有玉勾天，日月长含第五泉。","儿女但能催白发，英雄那得再青年。"]},{"t":"题陆天浥泰山图","f":"七言古诗","c":["海中日涌声如雷，天门夜半鸿濛开。","天鸡鼓翼波震荡，金银宫阙东飞来。","此时丈人峰上客，日华嘘噏荡精魄，东君玉颜在咫尺。","扶桑万朵红复红，玉女三千笑口同。","丹青虽神画不得，朝霞倏忽吹成风。","千岩万壑太古色，秦代苍松人不识。","图成慎勿置金箱，留与人间见胸臆。"]},{"t":"题吴太守江山清啸楼","f":"七言古诗","c":["江南山色渡江飞，飞向君楼含夕霏。","空翠不随流水去，鸿濛忽化白云归。","吴兴太守真州客，日夕捲帘荡精魄。","舞影时翻天女花，歌声欲裂雷公石。","浮玉双峰架笔高，芙蓉一朵一离骚。","六朝春色为膏沐，万里天风且羽毛。"]},{"t":"题周梨庄戴笠图","f":"七言古诗","c":["梨庄本是青云器，四十于今犹未仕。","前朝文献在君家，著作欲继先公志。","秣陵藏书谁最多，读画楼中高嵯峨。","捃拾能笺五代史，时谈遗事如悬河。","董狐有志我未逮，三百年中谁记载。","汉史应须属紫阳，元人岂解尊昭代。","青溪水阁閒相期，笔削相将乘此时。","王猛犹能存正朔，许衡那得配先师。","栖霞之山好林樾，更为同人开理窟。","片言亦可成春秋，一画自能知日月。","閒来戴笠将何之，遣谷逍遥若有思。","接舆髡首且相对，佯狂于道亦良宜。"]},{"t":"读李耕客龚天石新词作 其一","f":"七言古诗","c":["东风吹愁满天地，越客羁栖不得意。","携家远自南海来，十口飘飖无所寄。","秦淮一曲且侨居，升斗之水愁枯鱼。","故人咫尺在幕府，慰我饥渴三致书。","公子多才年复少，乐府能兼南宋调。","风流初见藕庄词，与君宫体皆娟妙。","我方笺易临河楼，梦寐日与羲皇游。","新词见赠不遑答，精微空向画前求。","南楚好辞宗屈子，学诗昔自离骚始。","含风吐雅数千篇，美刺颇得春秋旨。"]},{"t":"读李耕客龚天石新词作 其二","f":"七言古诗","c":["艰难持向清凉台，一秋不视白鱼来。","圣贤自古皆寂寞，文章于我诚尘埃。","闻君新校春秋疏，欲为唐人傅啖助。","多金镂得授经图，功在尼山流美誉。","交广春秋我亦成，南方异物多经营。","陆贾山川未作纪，嵇含草木徒知名。","长跪几时能请教，知君博物有深乐。","花中锦绣足文鹓，果下金钱饶小豹。","收香书带与相思，赋咏惟君綵笔宜。","我愧江淹才欲尽，那得倡和及芳时。"]},{"t":"过黄俞邰藏书楼作","f":"七言古诗","c":["我生南海愁偏僻，经史之外寡书册。","扁舟遥至金陵城，欲向名家求载籍。","黄君父子世藏书，一室尝开万卷馀。","欲使文章归性命，岂将词赋送君诸。","六经我道非糟粕，天地精神于此托。","一画能令日月开，古圣神明必有作。","君家易疏几青箱，借我无嫌岁月长。","卦外始能知太极，图中亦可得羲皇。","君今继述从何始，应徵未与先朝史。","文献无稽是此时，春秋有志惟君子。","秦淮水长连青溪，三月河房柳向西。","欲邀雪客同挥管，吾学诸编更整齐。","我且浓磨方氏墨，殷勤花下为君携。"]},{"t":"女儿葛歌","f":"古风","c":["女儿十三发覆额，精工善作女儿葛。","花针挑出葛丝丝，织成蝉翅弱霏霏。","一端祗得三四铢，出入笔管轻且微。","十年一匹不满机，制为夫婿乘凉衣。","日炙葛丝皱，风吹葛丝旧。","儿郎惜葛丝，莫当风日走。","宁无绮与罗，是侬手所就。"]},{"t":"紫霞杯歌","f":"七言古诗","c":["山之赤精石流丹，巢繇服之生羽翰。","太玄赨黄作杯好，持酌酥醪颜不老。","此杯不是芙蓉砂，君应得自神仙家。","杯名甚美名紫霞，雄黄一朵雕桃华。","连枝带叶大如掌，色似夭桃花两两。","白石床中无此丹，此杯乃是丹干长。","君今为寿见君情，自此觥船不用擎。","百花仙酝频催酿，与尔林中日日倾。"]},{"t":"观云公所绘听松图为叶平仲作","f":"七言古诗","c":["黄山之松天下无，云公写入洞庭图。","松声捲起瀑泉水，散作天风落五湖。","洞庭东西二峰好，玉柱金庭栖绮皓。","当年缥缈莫釐间，我亦行携石公姥。","叶子幽居偃盖阴，身如菟丝缠松林。","兴公斋前已楚楚，华阳楼外还森森。","拂地参差多麈尾，无生日说如流水。","声飞天外不因风，千里萧骚犹在耳。","云公最善绘寒声，声自空生亦有情。","嘲嘈忽似苏门啸，谐会琴音满太清。"]},{"t":"送洪氏兄弟读书黄山白龙潭","f":"七言古诗","c":["松松倒悬数干尺，身似藤萝缠怪石。","有时怒随雷雨飞，三十六峰腹尽坼。","洪生兄弟性爱松，读书各据一芙蓉。","黄山本是白云海，松树大小皆神龙。","罗浮七星作道士，邀予每道神仙事。","繇来变化本无情，性尽自然天命至。","汝师汪子在天都，曾见轩辕得道无。","莫浴汤泉生羽翼，且将石笋作摴蒲。","言兵实自轩辕始，八卦神机连甲子。","峰峰布列是阵图，白云出没为旗帜。","阴符不用更钩深，象数之中总可寻。","读易自应知战法，裁诗且复遣愁心。"]},{"t":"石公种松歌","f":"七言古诗","c":["石公好写黄山松，松与石合如胶漆。","松为石笋拂天来，石作松柯横水出。","泾西新得一山寺，移松远自黄山至。","髯猿一个似人长，荷锄种植如师意。","师本全州清净禅，湘山湘水别多年。","全州古松三百里，直接桂林不见天。","湘水北流与潇合，重华此地曾流连。","零陵之松更奇绝，师今可忆蛟龙颠。","我如女萝无断绝，处处与松相缠绵。","九疑松子日盈手，欲种未有白云田。","乞师为写潇湘川，我松置在二妃前。","我居漓南忆湘北，重瞳孤坟竹㛹娟。","湘中之人喜师在，何不归扫苍梧烟。"]},{"t":"寄汪扶晨","f":"古风","c":["黄山之麓有潜溪，君家溪口花竹迷。","飞书招我谒轩后，三十六峰素手携。","行至芜阴车忽止，六月盛暑汗如水。","安得风捲朱砂泉，飞来为我易毛髓。","膏淳黛蓄白龙潭，雨中喷薄当花龛。","诸泉尽自汤泉出，未若潜溪味最甘。","寄我紫霞茶，不寄潜溪水。","活火自烹时，相忆情难已。","我在秦淮日举杯，糟丘何处不蓬莱。","酒星最忆青莲客，独溯风流采石来。","谁作长歌赠太白，任华才气真诗伯。","去年汝惠一长篇，捲起西江泻精魄。","丈夫叱咤本非常，战法往往寓文章。","五兵相救乃神变，用短从来兼用长。","天生汝笔能雄放，青莲未是丈人行。","处处金焦砥海门，篇终始得波涛壮。"]},{"t":"短歌赠别陈子","f":"七言古诗","c":["丘园著书久寂寞，茫茫周蝶谁先觉。","虹霓为带佩华星，欲舍愁心游五岳。","五岳迢遥路不通，何如高卧谢鸿濛。","仙人祗在玉壶里，无为之化如重瞳。","伯乐无烦治天马，藐姑不待御飞龙。"]},{"t":"送客上庐山","f":"七言律诗","c":["庐山之奇在瀑布，飞流千道穿云树。","峰峰皆有吕梁洪，渔父濯缨予濯足。","送君直上芙蓉屏，俯视天河若建瓴。","狂来莫点神龙睛，恐挟风雷下四溟。"]},{"t":"题钦子五芝图","f":"七言律诗","c":["二十四种黄金芝，我昔罗浮皆采之。","此芝一茎五枝秀，君今图此将何为。","君能服食自不老，丹砂不若紫芝好。","园绮当年餐紫芝，容颜得为君王保。"]},{"t":"白鹇篇柬萧山周子","f":"七言古诗","c":["炎方珍禽有閒客，雌者纯丹雄者白。","咫尺烟霄未可飞，羽毛幸有高人惜。","君有文章亦孔鸾，南来此地求琅玕。","离支绝胜丹砂好，甘蔗还如玉液寒。","不必金装如陆贾，珠兰瑶草应长把。","南方草木疏成书，芭蕉叶大堪挥洒。","生日何妨举一杯，如君真未愧瓶罍。","冉子情多频请粟，皋鱼泪尽只衔哀。","圣明湖与湘湖接，紫莼甚美多茎叶。","高卧萧然一故人，岂有疗饥芝烨烨。","与君怀望每临风，何时归去同渔猎。"]},{"t":"为王璞庵题骑白鹿图","f":"七言律诗","c":["白马小儿窃天禄，青牛老人去函谷。","君今白鹿行翩翩，岂为茅山高卧足。","乾坤此日尚鸿濛，王霸雌雄一笑中。","他时忆我罗浮顶，可有风云起伏龙。"]},{"t":"赠陈药长","f":"七言古诗","c":["神仙中人谁不羡，羡子朱衣方拭面。","点漆凝脂是右军，瑶林玉树如王衍。","日日弹棋用拂巾，时时作草多团扇。","新诗更播宝安城，前辈风流不敢轻。","太白最能歌进酒，张衡还解赋同声。","我过每谈风雅旨，三闾婉顺真君子。","谁道离骚乃变风，可怜忠原心无己。","遗音千载有君知，日日弦歌是楚辞。","为言乃祖多忠愤，苍梧昔逐翠华迟。","事去捐躯沉桂水，愁来作赋续湘累。","大节表扬犹未得，求予作传传京国。","每闻人诵怀沙篇，感念先臣泪沾臆。","今朝娶妇思承宗，敬尔威仪玉帛从。","婿如葛勃应无恨，女得陈丰复有容。","纱扇披时惊似月，香车乘处喜如龙。","为君敬进新婚箴，性情之际难处心。","令祖争光同日月，慈孙继志在高深。","燕婉定知长不惑，忠贞自此世相寻。"]},{"t":"九日过李十一二耆山房赋赠","f":"七言古诗","c":["白昼婆娑古树下，华堂无事招儒雅。","苏门高士过弹琴，天宝将军来画马。","此日重阳黄菊开，寂寥馀我登高台。","被发狂游人削迹，持觞高论尔怜才。","江山战后秋无色，天地穷阴消不得。","周王兵士化沙虫，汉代衣冠委荆棘。","君家殉国有难兄，散尽黄金事不成。","脊令空抱苌弘血，鸿雁犹吞伍尚声。","我在山中无素业，一遇屠沽欢笑接。","道成不屑居神仙，气使翻然作游侠。","为君题诗花萼楼，羽声慷慨谁不愁。"]},{"t":"轩辕二帝子别业作","f":"楚辞体","c":["七十二峰不相离，兄与弟兮共冶之。","兄在禺南弟禺北，峰峰相对不参差。","二禺君臣自太古，三峡长为汤沐土。","轩辕龙驭迥难攀，徒为君王留洞府。","榴花五色红氤氲，阮隃枝枝拂涧云。","楚客悲思惟帝子，南人俎豆独夫君。"]},{"t":"仙人","f":"古风","c":["仙人饵飞鱼，暂死百馀年。","蹶然起鼓掌，玉容如霞鲜。","飘飖入东海，长揖谢轩辕。","我寻其踪上太岳，元气鸿濛无晦朔。","天鸡鼓舞向我鸣，忽然日月生两角。","回首人间尘垢多，金囊玉匕将如何。"]},{"t":"东湖走笔寄詹明府","f":"七言古诗","c":["东湖水似镜湖水，一片荷花不见天。","更有荔支千万树，离离朱实含霞鲜。","孔雀衔过水帘去，有时落在美人边。","彭洞缤纷洒冰雪，罗浮缥缈飞云烟。","主人乃是名吏部，风流日日荡湖船。","朝从兰若求支遁，暮向檀槽觅小怜。","毕卓已多瓮头酒，山公还有竹林贤。","竹林之下谁名饮，兴来我亦清狂甚。","醉卧当垆红粉旁，落花无数沾衾枕。","长啸一声远寄君，君在浮丘闻不闻。","漆园傲吏为蝴蝶，勾漏仙人拥白云。"]},{"t":"读杖人师武夷遗草因怀武夷虎啸洞诸胜","f":"古风","c":["我昔游五岳，身骑二茅龙。","惊风忽然起东海，日月吹落金银宫。","愁将白发三千丈，归去朱明四百峰。","朱明洞里多仙客，饵我云母颜光泽。","时偕玉女侍轩辕，不共安期干项籍。","闻钟又复證无生，足踏空王顶上行。","冲霄一剑如秋水，彻夜双箫响太清。","饮光尊者频招手，飘然遂至凤凰城。","尊者玉毫何宛转，手把芙蓉微笑展。","可怜楼上相见时，玲珑秋月珠帘捲。","江南乱后草离离，回首青山隗我师。","未将电足酬支遁，空对冰弦忆子期。","当时语我武夷好，九曲清溪流浩浩。","接笋峰前多紫云，飞猿岭上饶芝草。","几度安禅在翠微，天花绕座鸟衔飞。","茅户只今委苔藓，嗟予振策何时归。","空读遗书开玉箧，太山颓笑伤何及。","姑射仙人不降生，茫茫天下皆臣妾。","苏门一啸如鸾音，散入天风不可寻。","凭谁寄与武夷客，会取高山流水心。"]},{"t":"送李十还晋康山中","f":"七言古诗","c":["尚平五岳游初返，四十为农殊未晚。","安得田园湖海傍，朝朝暮暮雕胡饭。","晋康山水天下稀，君家洞口泉争飞。","文章自可娱慈母，富贵何繇在布衣。","君行为结松间屋，相待明秋住翠微。"]},{"t":"答姜十三送游天台之作","f":"古风","c":["昔我随远公，幽居庐山南。","香炉峰下水，濯遍十三潭。","松萝花开覆盘石，卧视秋云天外白。","秋云舒捲本无心，忽向天台弄素琴。","逢君散带耶溪上，赠我幽兰积雪吟。","我有双白鹤，欲放沃洲山。","朝啄苍梧之珠尘，暮随明月东海还。","期君来听九皋唳，天籁清寥非世间。"]},{"t":"西樵歌","f":"古风","c":["西樵山，何耸峙。","峨眉之孙，罗浮之子。","霞城乳窦碧玲珑，千尺珠帘挂秋水。","仙阙遥开白日边，人家尽在桃花里。","我寻羽客到锦岩，盘旋磴道上松杉。","月明一啸惊鸾鹤，飞入青冥瀑布南。"]},{"t":"渌水曲","f":"古风","c":["二月镜湖春，桃花开玉津。","无数紫鸳鸯，飞绕浣纱人。","浣纱殊未返，摇曳春云晚。","月出白蘋洲，烟生垂柳岸。","垂柳依依在月中，可怜嘶断玉花骢。","轻风忽引罗衣去，一曲菱歌听未终。"]},{"t":"将归东粤省母留别王二丈亹祁四丈骏佳","f":"楚辞体","c":["磨剑未屠龙，弯弓未射虎。","郁抑英雄姿，念我有慈母。","白云东去复西飞，万里罗浮今又归。","白云散尽露秋月，炤见高堂鬓如雪。","鬓如雪兮我心忧，孤鸾朝饥鸣啾啾。","惟尔仙人居射的，可有玄梨应我求。","钱塘之水入海流，蒲帆明朝去悠悠。","回首山阴最相忆，骨青髓绿园绮俦。","只将一片盘龙镜，长挂君家十二楼。"]},{"t":"题山阴祁五祁六藏书楼","f":"古风","c":["夙闻治水经，银泥封绿字。","龙威丈人招我游，林屋洞中探玉笥。","白云瀰瀰洞庭波，七十名峰奈乐何。","长风吹我至禹穴，猿啼虎啸依藤萝。","秦皇碑爱虫文古，夏后书愁鸟迹多。","平生窃慕柱下史，列国宝书求未已。","开君家书万卷馀，欲向琅函作蠹鱼。","志在春秋希鲁叟，才堪辞赋薄相如。","迩来颇究太公符，每恨荆轲剑术疏。","筑坛天目步珠斗，一龙一蛇左右趋。","闻君藏得鍊剑图，时时风雷起座隅。","慷慨肯授英雄无，鉴湖之水多芙蕖，日捲珠帘楼上居。","天下战争犹未已，请君亦读孙吴书。"]},{"t":"四百三十二峰草堂歌有赠","f":"楚辞体","c":["君不见罗浮秀出朱明天，璇台万仞阊阖连。","石桥如丝横绝顶，往来者谁皆飞仙。","我年十五芙蓉妍，麻姑携手相缠绵。","服食青霞犹未毕，忽见海日如金盘，悟道直出轩皇先。","喜君清爽有仙骨，凌峰相寻白云间。","白云兮翩翩，蝴蝶大如车轮然。","衣裳五彩眉连卷，双栖池中千叶莲。","我尝乘之访稚川，大笑世人鍊金丹。","淮南八公来周旋，角髻青丝如童颜。","教我含精御六气，白兔长跪献一丸。","形见神藏龙蜿蜒，内圣外王体自然。","仲尼不及姑射仙，黥人仁义徒多言。","吾心皎皎秋月圆，一死一生如浮烟。","鹑衣鷇食可忘年，何为烦忧著太玄，聊与君游游不还。"]},{"t":"有所思","f":"楚辞体","c":["我有花宫在罗浮，水帘千尺悬沧洲。","仙人教我吹玉笛，一曲未终凤来游。","凤兮皎若峨眉雪，口衔芙蓉向丹穴。","因之万里蓬莱飞，回首故都心断绝。","心断绝兮不能持，故都禾黍已离离。","折尽扶桑拂日枝，重华何处就陈辞。","曾将玉佩投湘浦，欲采珠尘向九疑。","九疑联绵在何处，斑竹阴森山鬼语。","明月中宵出洞庭，炤见皇英之二女。","瑶瑟声声怨别离，霓旌飒飒吹风雨。","白熊鱼服几多时，玉殿凄凉仗数移。","将相几人留岛屿，君王何日出蛮夷。","可怜五色飞龙马，无繇扈从到瑶池。","落花寂寂愁独处，浮云渺渺长相思。"]},{"t":"罗浮放歌","f":"七言古诗","c":["罗浮山上梅花村，花开大者如玉盘。","我昔化为一蝴蝶，五彩绡衣花作餐。","忽遇仙人萼绿华，相携共访葛洪家。","凤凰楼倚扶桑树，琥珀杯流东海霞。","我心皎皎如秋月，光映寒潭无可说。","临风时弄一弦琴，猿鸟啾啾悲枫林。","巢繇不为苍生起，坐使神州俱陆沉。"]},{"t":"会稽春暮酬南海陈五给谏怀予塞上之作兼寄西樵道士薛二","f":"古风","c":["我家扶桑下，日日见东君。","遗我紫琼花，风吹落白云。","白云泱漭起南海，蓬莱宫阙须臾改。","往日三千玉女群，祗今惟有麻姑在。","与君携手入罗浮，瑶琴一曲难消忧。","绮季终当扶汉室，张良未得报韩仇。","君家相国奋长剑，曾捧轩辕出金殿。","呜呜吹角为龙声，大呼玄女来助战。","蚩尤未灭妖氛多，可怜碧血归天河。","君栖芦中凡几日，悲风吹断鹊鸰歌。","神虬久蛰无人识，黄鹄高飞奈我何。","高飞忽向天山月，月炤天山皎如雪。","丁零争献葡萄杯，苏武共持青海节。","鸿雁南从大庾回，口衔尺素落龙堆。","开缄未读泪沾臆，城上吹笳凄且哀。","处处牛羊衔白草，纷纷雨雪下轮台。","问君塞上胡不来，当时敕赐有龙媒。","投笔曾无班子志，吹篪宁让伍胥才。","新诗字字琅玕重，何时草就西樵洞。","西樵道士剑侠流，应共悲歌击银瓮。","春风三月梨花飞，我游禹穴方思归。","黄莺开关啼碧柳，万里乡心连翠微。","谁怜寂寞耶溪上，泪洒西施金缕衣。"]},{"t":"木棉花歌","f":"七言古诗","c":["广州城边木棉花，花开十丈如丹霞。","烛龙衔日来沧海，天女持灯出绛纱。","树树双栖孔雀暖，枝枝交映扶桑斜。","仙种珍奇世希见，受命天南绝霜霰。","汉帝曾栽扶荔宫，越王为造珊瑚殿。","月下红侵舞女衣，风前香绕留仙宴。","回首春深怨杜鹃，荣华寂寞泪潸然。","残英化作天山雪，飘落胡人玉笛边。"]},{"t":"赠张丈天生","f":"楚辞体","c":["八月鶗鴂呜，愁云何浩浩。","长松生路旁，不如高冈草。","夫子搴芳逢此时，饥来可有金光芝。","自堪绝粒同龚胜，谁向披裘识启期。","中原战争方惨淡，鹿门山上多冰鉴。","谁为伏龙与凤雏，我欲从之问阴符，兼之风角天文书。","徉狂予非高阳徒，九龄好道守丹炉。","丹成欲济苍生厄，未遂轩皇升鼎湖。","鼎湖龙去亦已久，我寻衣冠往天寿。","铁壁斜攀湖岭西，银山直抵居庸口。","荆棘纵横虎作群，守陵不见羽林军。","花落锦城哀望帝，月明瑶瑟怨湘君。","一丝正统悬天地，六尺真孤托水云。","离忧我亦同山鬼，思灵修兮纷流涕。","蘼芜采得贻何人，念尔丘园白发新。","葛巾定漉陶潜酒，渭水应垂尚父纶。","垂纶兮千尺，漉酒兮百石。","庄周蝴蝶和天倪，醉后安知朝日白。"]},{"t":"精卫行","f":"七言律诗","c":["重瞳孤坟在何处，青鸟衔珠泪如雨。","海思云愁为别离，道逢精卫邀相语。","日日填河力已穷，凌霄未得羽毛丰。","荆山之玉君休抵，待雪深冤天地中。"]},{"t":"春日怀白华园","f":"七言古诗","c":["樱桃花发吴溪香，客里看春黯自伤。","可怀海燕差池羽，挟子翻飞归画梁。","我家远在番禺县，此日春人事游宴。","翡翠城边柳正垂，琵琶洲畔莺初啭。","旧栽梅树玉堂边，我母折梅大士前。","松风隔水吹朝梵，山月含霜炤夜禅。","一别乡园经四载，浮云舒捲瀰沧海。","五色明珠不肯投，千金匕首依然在。","纷纷天下逐雌雄，安期枉去说重瞳。","仙人本为苍生出，大道难令浊世容。","楚客空知笑衰凤，叶公不解好真龙。","徘徊歧路将何适，采采芳兰三叹息。","弱弟虽承菽水欢，鲜民未尽耕渔职。","鸿雁飞飞向塞天，谁怜落羽屡惊弦。","弋人应念衔书苦，万里飘零非偶然。"]},{"t":"张二丈画马送予出塞诗以酬之","f":"七言古诗","c":["我栖罗浮四百峰，十年学道师老龙。","忽睹扶桑上红日，真人飞出药珠宫。","迩来剑得白猿术，登台尝舞双芙蓉。","清泉白石心已厌，慷慨欲游关塞中。","怜君少小事游侠，智勇深沉慕荆聂。","悲来每叩玉壶歌，酒酣频向南山猎。","平生画出真骅骝，将寻天子昆崙丘。","万里风沙开缟素，千群汗血骋王侯。","今朝闻我天山去，停杯不觉泪如雨。","可怜陌上握别时，桃花乱落黄鹂语。","黄鹂睍睆不堪听，离家去国怨孤征。","白草连天过鹿碛，黄云蔽日向龙庭。","不是摩腾取贝叶，将同介子持长樱。","叹君五十无知己，黄金散尽惭妻子。","不能杖剑远相从，猿肱燕颔徒为尔。","空将秃笔扫龙媒，送我直上单于台。","神骏已居曹霸上，鹰腾肯让卫青才。","纷纷世上皆凡马，如此骐驎空冀野。","为君携出玉门关，戎王应奉千金价。","秋夜悬军瀚海西，哀笳吹月马频嘶。","此时思尔茅堂里，赋就铙歌待客归。"]},{"t":"歌赠金溪邹子","f":"古风","c":["丈夫生世何坎坷，佯狂为奴谁识我。","当年赁作向朱家，此日栖迟寻紫逻。","云蒸龙变在何时，怜君白发亦成丝。","君臣之义不可解，欲报何须国士知。","国士雄才天所产，楚汉纷纷那在眼。","子房本是烟霞人，万里青天任舒卷。","舒卷何渺茫，登台飞羽觞。","时哉双黄鹄，与尔相翱翔。"]},{"t":"那旦道中作","f":"七言古诗","c":["孟秋九日寒无比，东西南北飓风起。","阳春道上不可行，吹我仆夫僵欲死。","有车既陷泥淖中，有马亦倒沟渠里。","雨挟惊沙扑面飞，征人湿透苦无衣。","黑云一片横天尽，红叶千种见日希。","登高四望无烟火，白石苍苔滑杀我。","但得天晴到夕阳，自有人家当道左。"]},{"t":"放歌别戴十一","f":"楚辞体","c":["今朝春暖桃花多，为君张宴烹明驼。","酒酣慷慨高唱发，死生有命奈谁何。","王孙当日出裤下，含羞忍耻非无故。","北溟鱼起须扶摇，南山豹变繇烟雾。","君今贫贱何须愁，才气无双天所留。","庄蹻人肝可分食，伯夷薇蕨且莫忆。","隐忍终酬国士知，深沉不必时人识。","纷纷天下无贤良，豺虎皆化为侯王。","我今挽弓三石强，欲射不射心徬徨。","徬徨兮何极，临歧泪沾臆。","王陵有母发垂白，遇难不能供子职。","知君肝胆如青天，甘肥可托供朝夕。","鹜鸟将搏先戢翼，圣人将动必愚色。","丈夫所患独无身，我今且就朱家匿。"]},{"t":"赠张损之","f":"七言古诗","c":["秦淮之水连青溪，君家芙蕖出水齐。","性好丹青作花卉，含毫多在莲叶西。","张颠白日老閒事，中散青霞郁奇意。","画出芙蕖天下无，叶叶花花香扑鼻。","旧院风流往日多，沙嫩清箫传寿歌。","齐梁艳曲为君唱，求画芙蕖日夕过。","长板桥边明月满，脱家十娘开别馆。","枣花帘子捲晴云，邀画芙蕖香更薰。","千钱一幅传都市，一时好手谁如君。","只今王谢俱零落，青楼歌舞不复作。","桃叶渡头空夕阳，东华园里无红药。","君家寂寞在溪湄，南朝逸老无人知。","顿杨二姓红颜尽，那有犀簪供画师。","君且据梧复隐几，繁华销歇毋多悲。"]},{"t":"药地禅师于青原得一瀑布名曰小三叠泉请予题长句","f":"七言古诗","c":["闻道青原新瀑布，奔飞绝似匡庐山。","匡庐瀑布推三叠，一半移来烟雾间。","大士无心偶开辟，挂出晴川数千尺。","说法无烦玉麈挥，日夜雷声喧石壁。","康王谷里水帘长，玉镜潭前白练光。","昔予散发卧其下，洒面冰花凉复凉。","黄岩更比石门好，香山亦有银河倒。","天风吹断落彭湖，散作金波千万道。","平生最爱是飞泉，处处飞泉弄紫烟。","天台雁宕都奇绝，未若青原更可怜。"]},{"t":"八月十八夕风雨歌","f":"七言古诗","c":["去年八月十八夕，前年八月十八朝。","宝带桥边观串月，钱塘江上弄惊潮。","今年此夕何萧索，秋雨泙澎沉月魄。","万里银河水倒飞，千条瀑布天争落。","吹笛空为壮士声，何时一战似雷霆。","沙场后夜逢明月，会有葡萄醉卫青。"]},{"t":"题铁桥丈画鹰","f":"七言古诗","c":["铁桥老人七十五，画马画鹰力如虎。","此幅角鹰何飞扬，汉代郅都非其伍。","飒然恃出当秋天，林间不敢有毛羽。","雕如车轮空作群，金眸玉瓜不如君。","杉鸡竹兔方纷纷，何时一击开边云。"]},{"t":"赠卫山人","f":"七言古诗","c":["卫子兴来书自圣，鸾鶱凤举繇天性。","弯弓昔作李将军，搦管今为王大令。","虎豹雄姿可奈何，无因血战出朝那。","林泉处处成高隐，丝竹时时间浩歌。","我今学书费毫素，下马何时草露布。","君家夫人笔阵图，与尔经营及迟暮。","报恩况复有文章，经世何妨向烟雾。"]},{"t":"浮丘修禊作","f":"七言古诗","c":["朱明门户是浮丘，浮丘丈人昔此游。","采药相携浮丘叔，时从洞里入罗浮。","挹袖堂前花几处，春光一望消愁绪。","云霞十里蜃楼台，锦绣三城龙子女。","今晨上巳是佳晨，与客倾壶坐草茵。","偏霸不须为武帝，清狂且复作仙人。"]},{"t":"过长寿院","f":"古风","c":["尉佗城边长寿里，古寺前临白鹅水。","家家蕹菜有浮田，处处?鱼归大市。","钟磬声随山雨来，菩提坛接越王台。","石门南对红楼出，珠浦西连绀殿开。","师向人天无可说，诸方尽让琉璃舌。","丹青一一是无生，词彩纷纷洞冰雪。","自种花多灌美泉，头陀苦行在花田。","不须天女频来散，终岁花开冬亦妍。","林塘曲曲通潮汐，鸥鸟时来争坐席。","童子欢娱足白鹇，老人变化多黄石。","相对空天月上时，海光如见杖人师。","曾分宝镜虽无用，欲举青莲亦有期。"]},{"t":"送蜡石行","f":"楚辞体","c":["峨峨七尺嵩华身，峰峦不起已嶙峋。","黄云之根白云蒂，色如蒸栗温且纯。","展转豪家不得出，移来丈室辞埃尘。","老禅摩娑日三四，苍松所化何轮囷。","殉葬将同琐子骨，沙弥薰用戒香新。","西府海棠梅绿萼，交阴左右当芳春。","墨痕湿润少苔藓，虫书鸟迹长逡巡。","英州玲珑似斧凿，天然输尔玉浑沦。","东安旧令见忽夺，十夫难挽如有神。","泣别空王向垢浊，齐奴金谷多青燐。","东安县中富奇石，参天一一斧劈皴。","崆峒穹窿诸石笋，君归何不随车轮。","大峰小峰充囊橐，犹胜钜万未提银。","我闻巴县陈石丈，临行石犀泣江滨。","县中财物尽捆载，石犀独留何不仁。","石丈当时亦爱石，巴县石皆充下陈。","死时尸虫流户牖，石虽在旁如路人。","噫吁嘻，石虽在旁如路人，会见汝卧当荆榛。","匹夫只今尽怀璧，为官自合多奇珍。","石兮好去休酸辛，不久复与高禅亲。","九曜之石尚颠仆，马蹄践踏峨与岷。","裨王苑囿委蔓草，菹醢未足谢吾民。","蛟蜃子孙绝遗种，报施往往勤高旻。","嗟尔一卷何足道，顽冥岂得长锦茵。"]},{"t":"题李韶州种竹图","f":"七言古诗","c":["韶阳几载行无事，九郡如公真卓异。","手种筼筜翠映空，鸾凰欲为神君至。","琅玕截取作清箫，吹出元音满紫霄。","冉冉重华仙驭降，纷纷韶石彩云朝。","九成台畔行春早，甘雨随车禾麦好。","孝慈更使竹多孙，六县讴歌慰尊老。","朱轓露冕下佗城，贵倨应深捉吐情。","有道岂须姝子告，多文犹恐使君轻。"]},{"t":"扬州女儿行 其一","f":"七言古诗","c":["扬州女儿雪花命，飘至炎天花不病。","禺阳云气画为衣，珠海波光悬作镜。","嫁得风流号璧人，关关绣颈日交亲。","白发爷娘凭养老，生儿那得有金银。","为妻不若为姬妾，抛掷红颜轻似叶。","叶如桃叶有人争，王郎自解亲持楫。","世上如无渔色人，阿翁岂免空箱箧。"]},{"t":"扬州女儿行 其二","f":"七言古诗","c":["贫家有女即银树，一朵琼花人竞娶。","女儿嫌老不登车，泣向双亲泪如雨。","阿娘好语慰妖娆，秘戏欢娱得几朝。","此翁早遣黄泉去，更向豪家渡鹊桥。","青春不误都繇汝，即使生儿何用举。","桃花不惜傍枯杨，为展春图师素女。","繇来鬼伯在扬州，催命家家红粉楼。","少年尚可迎桃叶，老大休教买莫愁。"]},{"t":"送尹生北上","f":"七言古诗","c":["虎门潮长催舟发，君行万里辞扬越。","尊老京华启事时，殷勤省觐当双阙。","荔枝蕉子酿酥醪，霜蟹雪螺多水膏。","持献堂前复鲨翅，故乡风味及同曹。","莞香朝夕薰衣服，生结清甜兼水熟。","知燠知寒及自公，闻诗闻礼乘休沐。","春诵秋弦太学中，能将三德教童蒙。","仇香定得诸儒敬，郭宪元将六艺通。","少年立身须及早，出事公卿先有道。","赀郎未足累相如，辞赋何如铜臭好。","一尊相送郁江湄，莫向莺花惜别离。","越鸟怀南无远志，蛮骢归北有雄姿。","为语故人王祭酒，翰苑朱吴诸好友。","高怀倘不嚇鹓雏，应寄新诗来陇亩。"]},{"t":"答李五稔","f":"七言古诗","c":["李五聪明近无比，示我奕诀有精理。","自来奕数准图书，图生书克相表里。","神尧作奕教丹朱，与羲画卦形神似。","李五之奕今国手，京师让人恒九子。","以吾学易知象数，画前所得惟心耳。","君今久不事楸枰，天地杀机从此止。","易尚生生造化心，以视围棋殊不尔。","吾儒用阳老用阴，变诈岂足为纲纪。","君今所学在至诚，大经大本期无倚。","闭户静观天与渊，化育定知所终始。","时时讲习有罗胡，阿兄亦契中庸旨。","袒跣莫复争摴蒱，半日读书半隐几。","况汝歧黄术亦精，为医岂惜居廛市。","谁道仙人有玉壶，玉壶于我亦泥滓。"]},{"t":"堂上行","f":"七言古诗","c":["堂上老人七十九，绝似麻姑能饮酒。","白发垂垂亦至腰，梳头辄命梁鸾妇。","小妇脔鸡鸡颇肥，大奴斸笋未曾稀。","果甘最爱芭蕉实，花好时簪茉莉围。","当轩一树沙梨熟，男女孙雏分亦足。","画眉两两斗歌声，萱草纷纷争一束。","骥子先教三字经，熊儿早诵九春曲。","春来日比人间长，举杯劝日休飞光。","听泉之妣百有四，沧洲处士八旬强。","我今母子如能似，亦为吾族一祯祥。"]},{"t":"画兰行","f":"七言古诗","c":["张公画鹰胜画马，兰竹尤精知者寡。","兰师乃是程六无，竹亦仲昭始能写。","写成辄乞我题诗，墨花如雨争淋漓。","我欲学兰兰不就，馨香难寄所相思。","多日湘累音响绝，紫茎绿叶无人说。","枝枝画出亦离骚，彷佛潇湘见风雪。","兰膏细共露华滴，兰芽乱向春泥茁。","稏兰一箭五十花，罗浮生长美人家。","花多人疑是蕙草，花少乃是真兰葩。","为兰为蕙总芳芬，兰蕙繇来本一身。","画手写多休写少，一花即是一幽人。"]},{"t":"乞砚行","f":"七言古诗","c":["羚羊峡东惟端溪，水岩之口临江低。","石师匍匐下绝磴，中穿四洞先东西。","使君最嗜紫云片，脚踏青天割为砚。","青花细细似微尘，蕉叶白中时隐见。","空濛雨气成黄龙，欲散不散浮水面。","猪肝淡紫方新鲜，带血千年色未变。","中间火捺晕如钱，半壁阴沉望似烟。","翡翠朱砂非一种，斑斑麻鹊点多圆。","斯是水岩石中髓，水之精华结渊底。","就中纯粹含乾德，纷纷脂玉惭肌理。","入手温然煖若春，浮动心花兼意蕊。","姑射冰凝总在神，昭仪膏滑那濡水。","玉骨虽刚按似柔，生气周身无不靡。","鸲鹆何须活眼多，云霞亦是空天滓。","使君命匠细磨砻，中有三方最高美。","其馀浸润水盘中，水碧金膏尽糠秕。","分我东洞一大脔，似方非方非石子。","纵横六寸甚端厚，蕉叶青花相间起。","前者两片琢未成，赠我已与琼瑶似。","使君割爱本非常，不贪为宝吾难已。","连城之璧妄希求，腼颜未免秦人耻。","何物能为十五城，赋诗适自呈媸鄙。","使君作者本多才，笑我布鼓持当雷。","不须狡狯凭诗笔，自有神明契合来。"]},{"t":"寄薛二 其一","f":"古风","c":["君戴芙蓉冠，几日罗浮返。","芝房白玉童，应笑学仙晚。","我在天台读道书，春风三月怅离居。","盈盈一片流花水，欲共琴高驾鲤鱼。"]},{"t":"寄薛二 其二","f":"古风","c":["东西二樵山，有如日与月。","相望不相知，梦魂常恍惚。","四百馀峰高复低，难将七十二峰齐。","飞桥恨不长千丈，朝向东樵暮向西。","东樵四百三十二峰，西樵七十二峰。"]},{"t":"夷门行 其一","f":"七言古诗","c":["信陵当日救邯郸，毛薛诸公尽结欢。","怅望夷门哀饮剑，逡巡函谷恨回鞍。","魏王不信佳公子，醇酒美人终已矣。","兵法空名宾客书，合纵未雪诸侯耻。","大梁为君频驻马，燕赵萧条同泪下。","荆卿一去无酒人，朱亥已没谁屠者。","狐兔纷纷古市游，灌城早已知鸿沟。","侯嬴不吊吊公子，遗墓苍茫何处求。"]},{"t":"夷门行 其二","f":"七言古诗","c":["自迎监门劳玉趾，引车回入大梁市。","从骑皆惊骂小人，岂知嬴乃为公子。","刎颈送君君勿悲，为酬晋鄙血淋漓。","效命只须进朱亥，报恩况复得如姬。","卖浆博徒贤似汝，殷勤问步频相许。","天下无双是妄人，平原多客空豪举。","威名尽出抱关人，率领诸侯遂抑秦。","末路可怜长夜饮，东门草蔓失城闉。"]},{"t":"易水行","f":"七言古诗","c":["荆卿匕首渐离筑，诸侯宾客一时哭。","筑声总为故人悲，下报知交擿不迟。","白首相要在一死，缟冠相送未多时。","生劫宁因燕太子，深雠多为樊于期。","风雨萧萧生易水，一歌直与招魂似。","吾家渐离应与俱，彼竖舞阳安用此。","亦知此去事无成，争奈田光一死轻。","剑术虽工亦何益，丈夫原不为功名。"]},{"t":"博浪行","f":"七言古诗","c":["一声震动惊秦始，猛过当年椎晋鄙。","山东豪俊尽生心，圯上老人应不喜。","英雄坚忍事方成，徼幸何须学庆卿。","副车误中知天意，要使沙丘载臭行。","扶苏不得作天子，总在沙丘龙一死。","可怜百万死秦孤，祗有赵高能雪耻。","赵高生长赵王家，泪洒长平作血花。","报赵尽倾秦郡县，报韩只得博浪沙。"]},{"t":"垄上行","f":"七言古诗","c":["耕夫有志如鸿鹄，一夕丹书发鱼腹。","天教狐啸起英雄，遂使雌雄争逐鹿。","壮士生当举大名，身作陈王事乃成。","分兵徇地多秦敌，一一诸侯尽膝行。","所置将军尽豪杰，纷纭竟使强秦灭。","驱除已是霸王威，发难何殊汤武烈。","戍卒能为天下倡，何辞一战殉沙场。","第一功归汉高帝，无双不数楚真王。","汉业皆因张楚业，千秋砀上陈馨香。"]},{"t":"临邛行","f":"七言古诗","c":["临邛令前请奏琴，王孙有女能知音。","一曲艳歌传绣户，无端挑起凤凰心。","侍者殷勤通彼美，风流放诞那能已。","罗敷不肯见金夫，文君苦欲依才子。","临邛还作酒家胡，脸际芙蓉绝代无。","钱多会数黄金错，丝短能提白玉壶。","雍容时浣锦江水，慷慨或裂红罗襦。","嫁时衣物俄分与，家童钱帛兼无数。","归向成都作富人，宫商一任勤綦组。","子虚有赋无知者，一日声名动金马。","心存风谏本离骚，靡丽曲终方奏雅。","大人颂成欢至尊，飘飘气欲凌寒门。","生幸长卿共时代，得闻仙道齐轩辕。","长门复幸陈王后，一赋能令恩似旧。","金与文君取洒来，不为长卿作婚媾。","茂陵求女成荒淫，非关妾妒绿衣深。","祗为君多消渴疾，凄悲故作白头吟。","自君为郎每称病，草木书成图养性。","两意俄分乌鹊栖，一心未毕鸳鸯命。","为君羞看女贞花，为君羞对离鸾镜。","同衾共枕方须臾，忍教燕婉成蘧蒢。","鲤鱼离蓰亦有尾，鸳鸯缠绵将有雏。","妾身自同山上雪，君心好似云间月。","月肯回光阙复图，雪益含辉彻肌骨。","意气如何让妇人，凤凰始终须一身。","永托孳尾言尚在，愿为比翼长相亲。"]},{"t":"酥醪村作","f":"七言古诗","c":["梅花村北酥醪村，家家争酿梅花魂。","梅花与酒一时熟，香吹罗浮当朝暾。","山人嗜酒日沉湎，醉来跌破苍苔痕。","大嚼梅花贪醒酒，消渴之藤穷株根。","麻姑酒田亦不远，往来垆侧常鲸吞。","麻姑要诗作酒价，一篇动挥千万言。","抚掌大笑李太白，眼花落井空昏昏。","酒星堕地不归去，化为酒泉长崩奔。","文章亦与酒泉似，波涛汹涌倾龙门。","白头潦倒每一石，螟蛉果裸淳于髡。","呼吸水露作玄碧，骖驾飙车凌昆崙。"]},{"t":"赠尹学博","f":"七言古诗","c":["广文先生居崖州，乃在琼南天尽头。","洞天大小日觞咏，且喜海外有丹丘。","学田颇有槟榔树，椰子之林租可收。","白椰浆清黄椰浊，消渴日饮如黄流。","槟榔花甜胜于子，回甘不用南扶榴。","崖人沐浴汝膏泽，诗教亦稍知温柔。","渐将礼义变蛮俗，更使文章为脯脩。","十年不迁崖人喜，贤师教化天所留。","道行岂惜浮涨海，官贫亦胜为黔娄。","橐中沉速定多少，与黎相易惟肥牛。","黎娘爱针及红布，持之易香长满篝。","好香亦未损清德，君于五指还冥搜。"]},{"t":"梅花叹","f":"七言古诗","c":["今岁南天太暄暖，梅花瘦损无肌肤。","梅花命苦要寒冻，多食风雪方肥腴。","一朵开残始一朵，未开已落无根株。","檀香玉蝶半成蜕，葳蕤不得长黄须。","多因绝粒少膏润，长饥遂成山泽癯。","姑射枉称似处子，留侯久已非美姝。","经旬僵卧委篱落，珠玉咳唾谁沾濡。","安得惊精一含嚼，紫圭成烟俄复苏。"]},{"t":"擂茶歌","f":"七言古诗","c":["东官土风多擂茶，松萝茱萸兼胡麻。","细成香末入铛煮，色如乳酪含井华。","女儿一一月中兔，日持玉杵同虾蟆。","又如罗浮捣药鸟，玎珰声出三石洼。","拂曙东邻及西舍，纤手所作喧家家。","以淘粳饭益膏滑，不用酒子羹鱼虾。","味辛似杂贲隅桂，浆清绝胜朱崖椰。","多饮往往愈腹疾，不妨生冷长浮瓜。","我来莞中亦嗜此，岕菘欲废春头芽。","故人饷我日三至，丝绳玉壶提童娃。","为君餍饫当湩酪，力法归教双鬟丫。"]},{"t":"为广州太守刘公寿","f":"七言古诗","c":["使君露冕来仙城，吏人亲爱同翁卿。","九郡诸侯奉师表，百蛮髦士钦仁明。","中郎三十已开府，我公春秋日未午。","生朝恰值小春阳，梅花万枝献神父。","珠江开学希文翁，养正殷勤作圣功。","子弟弦歌沐膏泽，大夫兰芷香童蒙。","讲堂右肱有楼阁，假我卑栖欢燕雀。","何殊解榻为周璆，直教隐几同南郭。","南中文献君所留，斯楼依稀文选楼。","言谈林薮端在此，文章渊府更何求。","君侯政教两称善，去岁嘉禾应复见。","化如时雨沾天乔，润似黄河被畿甸。","兹晨负喧冬春交，使君帡幪先草茅。","贱子自惭鸠性拙，身依召公有鹊巢。","鲙鲤盘行及张仲，燕喜为侯陈雅颂。","岂弟自膺眉寿多，不用罗浮芝草送。"]},{"t":"卢亭","f":"七言古诗","c":["老万山中多卢亭，雌雄一一皆人形。","绿毛遍身祗留面，半遮下体松皮青。","攀船三两不肯去，投似酒食声咿嘤。","纷纷将鱼来献客，穿腮紫藤花无名。","生食诸鱼不烟火，一大鲈鱼持向我。","殷勤更欲求香醪，雌者腰身时袅娜。","在山知不是人鱼，乃是鱼人山上居。","编茅作屋数千百，海上渔村多不如。","卢循苗裔毋乃是，化为异类关天理。","或有衣裳即古人，避秦留得多孙子。","我亦秦时古丈夫，手携绿毛三两姝。","祗因误餐谷与肉，遂令肥重非仙癯。","卢亭羡尔无拘束，裸国之人如可畜。","猩猩能言虽不如，彼却未离禽兽族。","鱼人自是洪荒人，茹腥饮血何狉獉。","我欲衣裳易鳞介，尽教蛙黾皆吾民。","自古越人象龙子，入江绣面兼文身。","腼然人面能雪耻，差胜中州冠带伦。","觞乃豆肉且分与，期尔血气知尊亲。"]},{"t":"鱼子行","f":"古风","c":["谷雨?，清明鲤，相逐雌雄贪咬子。","鱼子争乘春水生，鱼花却让西江美。","鱼花一一似桃花，红漾春潮乱绮霞。","九江人尽鱼花户，解漉鱼花向海沙。"]},{"t":"蚺蛇行","f":"楚辞体","c":["蚺蛇吞人方半吞，两手死攀松树根。","一夫往救不量力，蚺蛇钩取如束薪。","牛将两角与抵触，鳞甲溃裂膏血喷。","人虽吐出已半死，一月僵卧亡精魂。","牛兮汝乃能救人，两人沾汝父母恩。","天生义勇少人有，牛兮绝胜血气伦。"]},{"t":"刘仙岩","f":"七言古诗","c":["高高城外风门岭，仙女岩扉时倒影。","水盂朝吐白云香，石镜暮含明月冷。","黑米成珠旧日粮，玉浆如乳谁家井。","闻道瑶姬绝世姿，芙蕖早把铅华屏。","绿眉卢女画当心，鬒发丽英披至颈。","云母丹成即上仙，紫鸾衔得书来请。","罗浮自古女仙多，知与鲍姑为首领。"]},{"t":"徭歌","f":"七言古诗","c":["盘瓠荒祠盘瓠峒，诸徭男女歌相送。","裙衫染黑大家同，绒绣花连大头凤。","峰田火粒早收成，为赛社王多酒瓮。","山狸肌作木瓜香，竹鼬肉如绵絮松。","官催刀税到兰和，绝嫩鹿茸先纳贡。"]},{"t":"水车","f":"七言古诗","c":["江中栅松纷无数，奔流横截相支柱。","要令江水尽湍急，势似惊滩石龃龉。","松身入水苦不朽，老龙一一皆锥处。","即枯尚裹霜鳞甲，断节膏流未成土。","何年五鬣失轮囷，潜无首尾谁知汝。","槎枒但有齿角用，纵横水中若钩距。","水车因尔得旋转，昼夜轮翻起风雨。","一车灌田四十亩，槽槽相接输甘乳。","舟人最苦水车多，上车下车色无主。","车车渐高高入云，车尾车头争鼓舞。","身强撑折湾湾篙，篙势有如大黄弩。","水浅不苦苦水深，雨多久已迷洲渚。","从阳向少乾旱忧，岁岁有收盛禾黍。","估人来往水车旁，各奋长篙助公姥。","我行虽觉此路艰，终爱水车利农圃。","丈人抱瓮一何愚，岂知桔槔施已普。","圣人制器因自然，机事前民从上古。","绝圣弃智非神明，大巧斯为道所取。"]},{"t":"从化县斋有古松一株见而叹之","f":"七言古诗","c":["古松一树愁拘束，生长县斋非空谷。","贪与仙人吏隐同，女萝亦免樵苏辱。","臃肿偏多鳞甲开，知是龙身不敢触。","枝柯多节或空心，膏流未免因肥沃。","官閒一日三摩娑，自汲寒泉与洗浴。","松花春熟入怀香，黄多绝胜金如粟。"]},{"t":"送沙子雨往安南","f":"七言古诗","c":["闽粤奇人沙起云，茫茫浮海凌秋雯。","扬帆直入大鳅腹，晞发欲就扶桑暾。","琉球日本一再至，萨摩长揖诸郎君。","倭奴宝刀日在手，暹罗火春时濡唇。","片脑炎油结欢好，红毛白丹通殷勤。","长沙石塘逐潮势，诸番往来犹苦贫。","身与人鱼互出没，昆崙舶小波长吞。","掣鳌欲学古公子，射蛟不数飞将军。","东西二洋若平地，蓬瀛诸岛诚微尘。","舍舟忽然辞海若，日南首路摩金邻。","前年已抵交阯界，鬼门关阻愁逡巡。","有兄久为安南客，白头未归含酸辛。","脊令急难冒凶险，禦侮欲批修蛇鳞。","古森先谒四峒主，山深箐密防狉獉。","摩挲铜柱古斑驳，伏波血汗馀苔文。","马流丁口尽汉种，黄褟一一神华民。","麋泠双女化燐火，西屠诸王无馀魂。","蛮逻至今畏新息，岁时腠腊陈椒芬。","匍匐不敢庙门入，国王徒跣先其臣。","白马衔中亦有庙，象来蹴踏身俄焚。","文渊威灵亘绝徼，中华长城凭一身。","交人亦尚汉冠带，虽然被发知人伦。","裒衣广袖耻左衽，旃裘不肯同吐浑。","君行喜得暂束发，网罗马尾重包巾。","光光髻子叠纱帽，纵横玉簪含花薰。","大樾国中奋才藻，侏离酬和宁无人。","美娘香蜡日膏沐，素趺乱踏桃花梱。","媚人更多鬼子女，鬒发苦拭杯盘银。","君行见兄即返马，此邦淫蛊多妖氛。","男女同川兼鼻饮，伤无礼义教持循。","谁当恢复此疆土，三百年来哀沉沦。","三杨王通罪莫逭，王者无外宁不闻。","金标岂是南极界，象林忍使茅长分。","夷椎踉跄畏铁骑，巨象丘山偏崩奔。","交鎗宁如我长技，丛雷大炮摧千群。","君行更为熟形势，为图山川穷嶙峋。","唐蒙奇道在掌股，邓艾裹毡当有神。","竻竹之城难负固，铜柱易折如枯薪。","先臣文简与文敏，两公硕画行须遵。","招降兼用邳离策，还同永乐重平陈。","倔强自娱亦已久，逋诛宁识天朝恩。","与黎皆在我心腹，虽有血气殊尊亲。","虎豹累朝驱未得，魑魅随在皆甘人。","君今盛夏触炎暑，钦州取道沿江濆。","帆扫牙山行十日，笑冲烟瘴香氤氲。","丈夫万里若几席，倏忽即可穷九垠。","鸿蒙爵跃恣所往，列子御风随天轮。","浮游直出天地外，猖狂岂暇忧迷津。","况乃居之亦何陋，夷中尽可图功勋。","猿狙既好周公服，未应犷悍长难驯。","祖宗郡县旧赤子，弃若弁髦伤吾仁。","彼中已尝被声教，夫子犹能尊大绅。","居行且与说词赋，挥洒翰墨争清新。","镇蛮铜鼓尽作铭，大书一一传九真。"]},{"t":"石公石姥歌","f":"古风","c":["两石湖边号公姥，状似老人何伛偻。","何事双双化石来，多情不肯归黄土。","从来化石因望夫，武昌贞妇无处无。","男子何因亦化石，鸳鸯相对为欢娱。","东向石公拜，汝岂谷城旧精怪。","不然汉代修羊公，故向君王作狡狯。","西与石姥语，汝岂秦时采螺女。","巫山十二芙蓉中，亦有望夫峰似汝。","我今学仙仙未成，愁将体魄归泉扃。","他年亦欲化为石，恨无比肩一娉婷。"]},{"t":"追答王学士庐山篇见赠之作","f":"七言古诗","c":["我昔庐山寻瀑布，香炉峰上披烟雾。","白云无事早知还，欲共渊明奋高步。","渊明醉石横溪边，九叠屏风三叠泉。","饮酒正怜重九日，闻钟忽悟远公禅。","吾心皎皎如秋月，照映寒潭无可说。","何妨变化若浮云，自有光辉含积雪。","沙门束教非高士，吾今况尚为人子。","养母宜耕十亩田，求人欲著三朝史。","简君旧赠庐山篇，庐山回首泪潺湲。","遗民此日成通隐，啸傲王侯亦偶然。"]},{"t":"听琴歌","f":"七言律诗","c":["匡庐瀑布三千尺，飞入琴中如霹雳。","苏门仙者听无声，一任崩云兼裂石。","峄阳桐树尔何求，不遇箫韶返故丘。","明月从来不妄照，孤云何事亦群游。"]},{"t":"锦石歌为梁芝五作","f":"七言律诗","c":["匹夫守志如磐石，采山饮河聊自适。","五色文章世不怜，散作金膏和水碧。","梁芝拾得满数斗，云自铜陵大江口。","他年持献女娲来，西北天倾复何有。"]},{"t":"题伍子胥传赠友","f":"七言古诗","c":["丈夫忠孝难两立，此身一死真可惜。","雪耻当为伍子胥，归仇莫作徐元直。","鹿生于野命系庖，时危那得适乐郊。","干将大阿不自握，为人所戮非英豪。","君今何为恋儿曹，及时建钺拥旌旄。","骑虎之势不可下，负恩人是报恩者。"]},{"t":"题卫叔卿博台","f":"七言古诗","c":["昭王旧作钩梯处，武帝尝求博戏人。","羽盖云车何婀娜，花台石笋复嶙峋。","强梁自贵欲相臣，何足误之大道真。","紫芝老父曾逃汉，飞兔先生亦却秦。","紫雾濛濛绝壑里，閒持六箸对天神。"]},{"t":"玉女峰观洗头盆作","f":"七言古诗","c":["东峰傍削一高台，玉女常乘白马来。","玉盆潜通黄河水，鬒发沐罢光徘徊。","我来日月荡精魄，飞蓬自愧无膏泽。","黄陵昔恋湘君祠，太华今怜玉女宅。","圣贤发愤诗三百，风雅洋洋多好色。","公子应知憔悴人，三闾非是荒淫客。"]},{"t":"题王山史独鹤亭","f":"楚辞体","c":["仙人骐骥是胎禽，千岁丹砂入顶深。","闻尔浮丘能相鹤，孤飞忽至华山阴。","华山三峰削青天，白帝金精育大贤。","黄河万里入胸臆，文章一泻如云烟。","我本罗浮五色鸟，化为仙人出炎峤。","狂歌不逐衰凤游，高举时蒙斥鴳诮。","闻君好鹤鹤亭居，九皋清泪为君娱。","携持杯杓来相就，骖驾烟霞遂共驱。","共驱直向华山巅，鹤兮起舞何翩翩。","衣裳皎若玉井莲，何殊玉女临樽前。"]},{"t":"饮王氏漱园醉赋","f":"七言古诗","c":["华山山口云茫茫，寻君台馆玉泉傍。","閒挥玉麈论秋水，庄襟老带何清狂。","朝邑美人善歌舞，荆州处士能壶觞。","飞扬且任神龙性，温柔何羡白云乡。","白云变化何时息，人生寿命有时极。","努力读书与好色，明星玉女日侍侧。"]},{"t":"丙午夏日将同李天生之雁门道过蒲城饮米侍御园亭即事有赋","f":"七言古诗","c":["蒲城六月火云高，行人飞鞚寻东皋。","大夫射雉有遗处，台榭阴阴风雨聚。","金粟堆南问二陵，尧山谷口迷千树。","主人骢马早归来，敕赐芙蕖对客开。","前席少年筹汉罢，上林高士望京回。","惊鸿流雪慰摧颓，醉挥漫水入金杯。","同心藕使冰盘满，并蒂花教玉管催。","织女多情银汉度，匏瓜无匹心相妒。","失志聊为声色荒，求仁不被神仙误。","歌长烛短夜无多，明朝秦晋阻黄河。","雁门深入胡天雪，回首西方忆绮罗。"]},{"t":"古丈人洞草堂歌","f":"古风","c":["丈夫非仙人，毛女亦高士。","相携向白云，欲学采薇子。","天生两洞如鸳鸯，西临太华东首阳。","女萝飞花蔽洞口，双栖人在洞中央。","草堂之中何所望，有美一人持玉浆。","巨灵掌上石楼长，水帘捲起见明妆。","草堂之中何所服，石髓金精满岩谷。","古松千岁吐奇光，夜如荷花昼牛目。"]},{"t":"田三丈席上歌","f":"七言古诗","c":["今夕何夕醉频阳，王剪祠前堪断肠。","美人一双紫鸳鸯，愿随长风共翱翔。","秦筝慷慨西气溢，燕歌变转南魂失。","佳丽须归楚些人，神仙肯作湘累匹。","往日人传好色名，南求交趾东辽城。","交州美人珠鬘送，辽阳美人貂裘迎。","只今祋祤情难已，温其如玉惭君子。","羽钗既挂远游冠，牙床敢展合欢被。"]},{"t":"雁门送客","f":"古风","c":["君在雁门北，我在雁门南。","雁门八月纷霜雪，何事征夫系玉骖。","桑乾水绕长城远，句注山含秋色晚。","塞女吹残觱篥声，举杯劝尔江南返。","江南春色在君家，早将妻子别龙沙。","楼台更向秦淮曲，日对夭桃几树花。"]},{"t":"送孙丈归黄山 其一","f":"楚辞体","c":["君何不向黄山归，君家有松大十围。","松外一天云气湿，松间百道瀑泉飞。","我思三十六翠屏，复爱松兮长青青。","安得随君入杳冥，君为免丝我茯苓，相与松兮至千龄。"]},{"t":"送孙丈归黄山 其二","f":"七言古诗","c":["去年东岳兼西岳，来往真如天际云。","今日黄山游不得，三十六峰空待君。","君归好向汤泉浴，曾见骨青而髓绿。","容成教以驻年方，服食虚无坐紫床，道成相与随轩皇。"]},{"t":"乌蛮大滩谒伏波将军祠代景大夫作","f":"七言古诗","c":["乱石截流数千里，大石生人小石死。","水小不险水大险，穿舟最患石齿齿。","水石喧阗斗不开，水崩石裂声如雷。","两岸青峰随帆转，一滩白鸟逐篙回。","滩名乌蛮最险恶，伏波往日曾疏凿。","功同神禹合俎豆，有庙巍巍镇瓯骆。","瓯骆至今遵约束，岁时庙下祭旗纛。","祠中铜鼓铸马馀，银钗叩击蛮风俗。","麋泠双女僭为王，将军破贼威扬扬。","双植金标临涨海，七腰银艾到炎荒。","神灵终古槎江在，巨石依然排壁垒。","湍流赑怒状军声，势逐牂牁东入海。","两江黔郁此朝宗，我溯惊涛欲上邕。","千篙日与雷霆战，万马横当水石冲。","调兵东征苦不速，番禺九郡未恢复。","遇主徒希马伏波，委身未遇刘文叔。","将军际会本非常，我忆重兴二十霜。","扫荡南交待□命，邀君灵宠早还乡。"]},{"t":"秋夜恭怀先业师赠兵部尚书岩野陈先生并寄恭尹","f":"楚辞体","c":["惊风吹折扶桑柯，白日惨惨沉沧波。","无数哀猿啼不止，美人回首泪滂沱。","曾将九辩吊沅澧，长夜悠悠雪千里。","招魂何处告巫阳，被发空然呼上帝。","忆昔从师粤秀峰，授书不与经师同。","捭阖阴谋传鬼谷，支离绝技学屠龙。","天下山川能聚米，壮夫词赋薄雕虫。","小子生年方十五，意气飞腾思食虎。","喷玉才蒙伯乐看，追风便向天墀舞。","天墀春暖彩云开，帝乘玉辇陪京来。","万里江清鳷鹊观，六朝花发凤凰台。","夫子忧时双鬓白，频献重兴三十策。","不从魏绛拟和戎，遂与贾生为逐客。","唾壶击破愁心多，君父仇雠将奈何。","长缨不许终军请，黄鹄谁令翁主歌。","九鼎茫茫沉泗水，六龙冉冉出蓬婆。","奔走中原殊未已，孤臣泪作黄河水。","东渡徒劳舣棹心，南巡未雪胶舟耻。","巫咸终合作波臣，智伯何曾知国士。","国士纵横不可当，平生裤下多侯王。","但教死去图麟阁，不愿生还挂鹊章。","一呼市井千人战，广州城下兵如电。","半月连营虎豹屯，六花奇阵鸳鸯变。","先锋已拔骨都旗，后劲全消当户箭。","岂意军无三日粮，马衔枯骨士金疮。","频杀美人来飨士，美人花映蛾眉长。","天心何故邻□子，国步迍邅今若此。","长留正气为山河，空有神光照箕尾。","惭予亡命奔天涯，误掷千金博浪沙。","穷途不得尺寸柄，髡钳为奴卖朱家。","朱家豪侠倾四澥，堂前宾客如云会。","卜夜聊为歌舞欢，探囊尚有孙吴在。","向秀难听长笛哀，伯牙欲把鸣琴碎。","鸣琴碎兮我心苦，西山采薇将何补。","翠华缥缈苍梧烟，玉佩飘零洞庭雨。","枫叶萧萧二女祠，芦中穷士寒无衣。","白头渔户沧浪去，麦饭壶浆欲待谁。"]},{"t":"长歌为玉龙子寿","f":"楚辞体","c":["蒲桃美酒金叵罗，银盘堆炙高嵯峨。","请君酣饮当秋月，世上功名奈尔何。","月出凉州雪海涌，琵琶羌笛閒相弄。","卫霍鹰扬自有时，荆专狗盗终何用。","我有纯钩一雌雄，三金吐焰芙蓉同。","纷纷虎豹不足刺，出天入地如飙风。","自从搀枪犯帝阙，四渎波翻天柱折。","包胥恸哭无人闻，勾践深冤难自雪。","因之游心八阵盘，奇正相生环无端。","龙蛇变化在掌握，全师一掷非所安。","狐裘蒙茸垂锦带，遨游东走邯郸外。","倾家交结高阳徒，燕姬酒楼争摴蒱。","千山杀气渔阳惨，五夜笳声大帐孤。","逢君沙漠至，意气相欢呼。","长兄张子房，小弟周亚夫。","肝肠剖出如白日，太山一诺堪捐躯。","岁月滔滔若流水，忽别江南数千里。","天心不肯厌□孥，世态那能留国士。","我如梅福弃妻子，蓬头垢面栖吴市。","桃花春满会稽山，鼓棹南湖苍翠间。","凭谁寄语鸱夷子，载取西施月下还。","西施还兮一携手，逢君忽在胥山口。","衣服犹沾马汗红，风流不减虬髯秀。","莫嫌三十犹沉沦，夷门曾有抱关人。","才似文渊不惜老，美如曲逆宁长贫。","看花且乘青雀舫，朝斗且戴华阳巾。","悬黎追琢始成器，豫章郁结方有神。","天生我技能穿杨，时来三箭谁能当。","汉贼繇来不两立，男儿岂必封侯王。","瓶中况有丹砂在，只须功成便翱翔。"]},{"t":"四孝烈","f":"古风","c":["黑云沉沉压城隅，城中食尽雀鼠无。","谁其死守右骨都，饥来脍人为朝餔。","可怜窈窕三罗敷，肌如冰雪颜如荼。","再拜乞充君庖厨，解妆请代姑与夫。","妾年尚少甘且脆，姑与夫老肉不如。","请君先割妾膏腴，味香不负君刀殳。","食之若厌饫，愿还妾头颅。","姑老夫无子，妾命敢踟蹰。","有女年十馀，缇萦亦不殊。","哀求赴汤镬，保父千金躯。","保父千金躯，泉下报章渠。","无嫌女身小，一饱只须臾。","须臾饱亦可，章渠单杀我。","天生娇女身，为君供鼎俎。"]},{"t":"梦马歌","f":"七言古诗","c":["张侯十六勇无敌，锦衣玉貌乌孙识。","千金买得大宛骝，骑出沙场人辟易。","挥鞭曾跃三重河，势如天边紫电过。","羌儿万箭射不得，死生可托征蓬婆。","一朝汗血用忽竭，君恩难报徒呜咽。","玉勒金羁委草莱，龙鬐凤臆埋冰雪。","英雄无命自古伤，驽骀寿比骐驎长。","嗟子功名终不偶，归耕海上泪浪浪。","髀里肉生悲老大，虚拟封侯如拾芥。","霸陵醉尉时相侵，榆次博徒尝见卖。","秋宵木叶飘寒庭，苞衣肉酪心不平。","弯弓欲射天山月，拔剑难斩被头星。","长夜悠悠何时旦，君父仇雠不可缓。","梦中忽在白龙堆，追风千里飞龙媒。","细看乃是旧乘骏，玉花朱鬣气雄哉。","初交冲破沮渠阵，横行踏倒赫连台。","双瞳黄金蹄碧玉，閒向长城窟中浴。","圉人乃是诸降王，日喂焉支花百束。","阴风吹帐雪纷纷，魂去魄来瀚海濆。","死葬黄沙犹恋主，生为红粉更依君。","繇来良骥感一顾，赤兔当年殉吕布。","愿君努力更临戎，厉鬼还能相夹辅。"]},{"t":"义象行","f":"楚辞体","c":["将军来从夜郎天，万里旌旗横海边。","左右名王膏玉斧，西南君长执金鞭。","因之问罪尉佗国，兵胜繇来骄气作。","美女聊为歌舞欢，谋臣白有孙吴略。","营中何物高嵯峨，十四雄象相荡摩。","久向滇池习斗战，凭之触敌计良善。","蛮奴一下紫金钩，蹴踏沙场山岳转。","岂意中宵敌溃围，不诛庄贾损军威。","至尊方有平城厄，丞相频从泸水归。","谁言不败繇天幸，自是无功因数奇。","神龙失水困蝼蚁，往日风雷嗟已矣。","梅鋗关上阵云崩，伏波祠前鼓声死。","象兮尽入橐驼群，口衔苜蓿泪纷纷。","蕃雏骑向天山道，汉使愁看黑水滨。","中间一象独不驯，天子曾封为将军。","势每奔腾蹂万马，声如暗哑废千人。","曾击长沙城阙碎，如虎如熊谁不爱。","皇天不欲兴神州，致使六军齐受害。","繇来犬马思报主，况乃瑶光星降汝。","曾被雷惊花入牙，御前妙舞如鸾翥。","唐朝不拜赤心儿，今日宁降老上师。","几夜偷营多伤杀，田单火牛宁足奇。","堪嗟巨炮争丛击，战场孤立终难支。","皮可寝兮肉可食，死为鬼雄游八极。","从来骥也称奇德，人不如兽徒千亿。"]},{"t":"登秦望山寄酬庐山无可大师","f":"楚辞体","c":["秋风忽起飘井桐，白凤西飞紫凤东。","何处思君最凄断，流泉潺湲秦望峰。","秦望高兮烟霭重，我持明月照鸿濛。","云间夏后金书在，松下秦皇玉辇空。","遥望庐山倚南斗，三石梁边君隐久。","阴符宝剑与何人，玉麈青莲应在手。","几宵乘月弹瑶琴，寄我潇湘帝子吟。","梅花乱落云门寺，经岁相思未嗣音。","此日登高眺东海，日出天台佳气在。","黄屋将浮碣石来，紫芝尚向商山采。","采紫芝兮使心愁，功名让与屠沽流。","仙人肌体如冰雪，姑射山中自可留。"]},{"t":"客山阴赠二祁子","f":"七言古诗","c":["君家楼阁鉴湖边，杨柳千条春色妍。","疏牖朝开射的雪，空帘暮捲香垆烟。","閒拥牙签披万卷，小谢风流诗更善。","可怜初日吐芙蓉，更有澄江飞白练。","我从罗浮万里来，逢君文采一徘徊。","天上雪花那有蒂，云中玉镜不安台。","相留暂向祗园住，正是中丞殉节处。","碧水含秋似汨罗，黄金布地同玄度。","樱桃开遍画栏杆，挥麈鸣琴兴未残。","半山每答猿公啸，千仞将联凤鸟翰。","凤鸟高飞何所止，金陵宫阙五云起。","一鸣素水降真人，再鸣留侯遇松子。"]},{"t":"送方瞳子","f":"楚辞体","c":["家本浮罗上，仙人日往还。","就中勾漏令，似尔芙蓉颜。","芙蓉颜兮谁不悦，朝如丹霞暮如雪。","弄玉来教紫凤箫，灵峨照以瑶台月。","月出瑶台奈乐何，忽乘天马超天河。","遨游每共东方朔，功业聊为马伏波。","干金买得鱼肠剑，七宝装成狮子花。","天下侯王犹草泽，江东子弟已干戈。","问君望气意如何，五色龙文嵩雒多。","我作班彪王命论，群雄不敢思并吞。","赤眉必有长安败，王莽终遭宣室焚。","自古帝王尽天授，云台诸将罗星宿。","子房奉是赤松流，汉家乃继唐尧后。","春日张筵戏马台，千枝芍药送春来。","燕姬竞作莲花旋，羌笛齐吹阿亸回。","惨淡风云归沛上，苍茫淮海入金杯。","看君醉后挥鞭去，飒飒龙沙万里开。"]},{"t":"游会稽山怀古并酬陶生见赠","f":"楚辞体","c":["葳蕤紫鸾鸟，口衔扶桑花。","翱翔朝禹穴，双翼蔽天涯。","禹穴龙葱云五彩，千峰竹箭连沧澥。","玉简金书不可寻，香炉天柱依然在。","为刑白马登天坛，冉冉龙舆望不还。","四岳衣冠归郁水，诸侯玉帛待涂山。","涂山南去阳明洞，酌酒秦皇三石瓮。","白鹤吟笙射的来，仙人荡楫樵风送。","樵风飒飒铸溪滨，当年此地成纯钧。","雷公为鼓阴阳炭，天帝来看龙虎文。","烂如列星罗太乙，皎若芙蓉含夜月。","登高山兮临深渊，一麾敌国皆流血。","嗟予亦是风胡流，心与天通事远游。","君王未雪夫椒耻，臣子难宽范蠡谋。","玩弄仇雠股掌上，六千君子为吾养。","繇来举事随天时，阴谋逆德蹈危机。","天地相参功乃就，援枹提鼓莫迟迟。","避迟兮奈何，冲风忽起澥扬波。","逢君玄夷苍水使，授受天书鸟迹多。","承以文璜覆盘石，昔年宛委山中得。","深藏不使鬼神知，默诵尝将符谶测。","符谶今归大帻人，云台二十八星陈。","我着羊裘渔大泽，君攀凤翼上天津。","天津迢遥接具茨，牧童七岁为轩师。","天授英雄非偶尔，何减黄公遇下邳。"]},{"t":"舟上西江值大水有作 其一","f":"七言古诗","c":["六月滇黔水大来，端州城门不敢开。","左右双江争一口，白波倒捲失崧台。","咽喉最苦羚羊小，水花四飞如白鸟。","洪涛鼓舞不因风，一出峡门成浩淼。","此水发源自夜郎，万里来入祝融江。","南天一渎亦无愧，势与岷江争短长。","春来一雨成黄浊，八斗淤泥那可濯。","炎方水土此难尝，生长蛮中殊不觉。","我行正溯牂牁西，津路微茫咫尺迷。","牵舟欲上木棉树，走马不见桃花堤。","榕叶阴阴馀片地，芭蕉土布来金利。","渔父鲥鱼尺许长，买来且作风前醉。"]},{"t":"舟上西江值大水有作 其二","f":"七言古诗","c":["峡口片云时启闭，风雷更助建瓴势。","水头十丈似黄云，两岸崩崖苦相制。","牵舟直上望夫台，万壑千岩往复回。","石栈如丝萦绝顶，飞梯上下愁莓苔。","滇黔至此水始放，河伯未见奔腾状。","万里苴兰赴海来，炎风吹尽无烟瘴。","风俗家家种橘田，淘金采石峡门边。","多鱼正喜西江涨，妇女相将日数钱。"]},{"t":"上峡","f":"七言古诗","c":["水如奔箭穿霞壁，舟与浪花相拒敌。","千岩万壑势将崩，一石中流犹荡击。","风挟惊涛似飓来，斜吹一半断虹开。","潮向北江犹可上，西江从未有潮回。","北江势比西江缓，水性西江尤劲悍。","时时一口似龙门，万里飞流束欲断。","牂牁至此尾闾同，到海犹须两日功。","倾泻不教元气尽，故为三峡吕梁中。"]},{"t":"蕉布行","f":"七言古诗","c":["芭蕉有丝犹可绩，绩成似葛分絺绤。","女手纤纤良苦殊，馀红更作龙须席。","蛮方妇女多勤劬，手爪可怜天下无。","花练白越细无比，终岁一匹衣其夫。","竹与芙蓉亦为布，蝉翼霏霏若烟雾。","入筒一端重数铢，拔钗先买芭蕉树。","花针挑出似游丝，八熟珍蚕织每迟。","增城女葛人皆重，广利娘蕉独不知。"]},{"t":"查君来自黔中赠之","f":"古风","c":["怜君万里事孤征，艰难来自黔阳城。","黔阳乃是烟雾海，天无三日能乾晴。","雨师最好黔阳地，霢霢濛濛岂天意。","三年未洗战场红，红满黔阳皆血泪。","啾啾新鬼多王侯，可怜白骨成山丘。","英雄岂合建大义，杀身自古因春秋。","水深火热天所喜，汤武之世皆逆理。","君臣一炬谢生灵，赤县神州终已矣。","君向黔阳吊战场，仲家黑白邀壶觞。","腐肉之中相饮食，乌鸢往往争肝肠。","争肝肠，中有馨香是国殇。","生降差比部尉强，君行莫与别阿梁。"]},{"t":"赠周文学","f":"七言古诗","c":["君如琼树方敷荣，又似玉壶冰至清。","三岁珊瑚色尽赤，五年孔雀尾全成。","年少周郎古所羡，况复聪明是才彦。","不工顾曲但读书，文章已见云霞变。","幽轩列植多名葩，美盎滋兰尽发芽。","香煎水熟风微起，琴写泉声月正华。","书多不用徒渔猎，至道从来少枝叶。","古圣精微在六经，神明一片宜相接。"]},{"t":"七星岩磨厓题名歌","f":"七言古诗","c":["七星化作七芙蓉，斗柄乃是玉屏峰。","中有夹天千尺峡，天开一罅烟重重。","振策飞厓同我友，摩挲怪石云濡手。","心怜绝壁势争雄，欲得蛟螭字如斗。","君也今之顾八分，石经瘦劲汝其伦。","墨气淋漓山鬼泣，无端破我苍苔痕。","白石肌肤如玉雪，磨砻欲出巨灵血，数声斧外何清越。","石工一字一螺金，丁丁日夕愁穿穴。","石火射人光不寒，为君留得冰雪肝。","姓名他日谁不朽，置身且学此峰峦。"]},{"t":"伏波射潮歌","f":"七言古诗","c":["后羿射日落其九，伏波射潮灭六口。","海水至今不敢骄，随月盈虚少沓潮。","流向东西各半月，新潮既长旧潮消。","将军天命治南海，万古波涛精爽在。","前驱海若后波臣，民免为鱼仗真宰。"]},{"t":"端州访砚歌和诸公","f":"古风","c":["古之著书人，岂必端州砚。","黄帝阴符有作时，墨池只用琼瑶片。","君今采砚思氤氲，不踏青天割紫云。","身入东西双洞口，九渊始得青花文。","水岩之石水精子，带血羊肝纯作紫。","火捺金钱朵朵圆，白凝蕉叶为肌理。","年来岩底采无馀，鬼斧神工多得髓。","纷纷散入富豪家，什袭文绫与绛纱。","未雨那知泉有本，长乾曾见墨生花。","绿尘半与图书积，安得松烟饱朝夕。","真气徒含天一深，空光未有云霞迹。","琉璃作匣枉称珍，终日随身讵有人。","风雅纷葩思赋客，春秋羽翼忆经神。","君今欲采圭璋质，尺寸微瑕皆勿失。","天留淳朴与遗人，鬼瞰高明悲巨室。","石工欺汝只纤毫，翡翠朱砂总未高。","鸲鹆眼多堪抵鹊，梅花坑好可磨刀。","神物繇来知者寡，相错刚柔方大雅。","不得精华日月中，文明安足成天下。","为君钩索尚茫然，应有精诚格上天。","成璧成圭凭帝赍，天然不必问方圆。"]},{"t":"老树歌为蒋少参寿","f":"七言古诗","c":["少参堂侧有老树，似榕非榕榕所寓。","叶叶含苞如木笔，叶开忽似花争吐。","花亦非花花不如，红浅绿深带膏露。","千万根须作一身，虎倒龙颠应有故。","我公构宇轮囷下，日见柯条出烟雾。","公馀一日三摩挲，时遣词人竞题赋。","拥肿不知大几抱，朔雪炎霜自朝暮。","青牛变化已多年，白鹤巢栖宁有数。","尉佗城中古木少，除却菩提应独步。","越人以此为甘棠，一叶一枝孺子慕。","公之先公所根本，南海一株磐石固。","百年父老已汤沐，万古神灵定呵护。","霜威尚带西台柏，匠石森然不敢顾。","五岭凭兹作梁栋，望似丘山阴四布。","吐纳精华日影中，元气茫茫各奔赴。","膏流金玉总堪饵，腹有文章长不蠹。","天南奇树罕人知，木棉千尺虚当路。","桢干因君益大春，剪拜恐为雷雨怒。"]},{"t":"古铜蟾蜍歌","f":"七言古诗","c":["古铜金质久已化，血花绣蚀三泉下。","何人铸此月中物，持作薰炉喷兰麝。","月中与兔为阴阳，三足婆娑桂树旁。","日中之乌亦三足，一东一西遥相当。","太阴呼噏生潮水，仙人师尔服气方。","生长瑶台明镜里，精华不待取扶桑。","汉宫以此为神器，煎取沉馢消梦寐。","红颜不少嫦娥寡，相伴蟾蜍度年岁。","摩挲铜色何斑斑，看丹如绿有无间。","双烟自可通瑶圃，一气何须假博山。","轩鼎馀铜龙不爱，神工拾得虚无外。","无香亦复雨氤氲，有火莫教云叆叇。","时时一缕生空中，太古长留一点红。","纵是灰寒终不灭，神灵看与蜃楼同。"]},{"t":"赋得石琴送陈健夫往零陵","f":"古风","c":["端州白石天下稀，声含宫商人不知。","斲瑶琴长四尺，轻如一片番流离。","石音最是难调者，碧玉老人能大雅。","繇来太古本无弦，不是希声知者寡。","无弦吾欲并无琴，琴向高山流水寻。","天籁元从人籁出，非君谁识此元音。","君今欲向潇湘去，此是重华挥手处。","五弦一一在天风，二女双双出烟雨。","诗篇投向洞庭波，山鬼篁中答啸歌。","幽兰积雪频相寄，慰我相思愁梦多。"]},{"t":"梅花泉","f":"古风","c":["梅花泉泉作，梅花朵朵圆。","五出有时还六出，雪花一半相洄漩。","泉出梅花万树里，天一所生无彼此。","在天为雪地为泉，欲作梅花无不似。","武陵溪口桃花时，泉作桃花人不知。","红红白白因花性，散作烟波不自持。","君今结宇西溪好，万树梅花日相抱。","泉里梅花更不穷，流出人间岂浮藻。","一杯一朵月精华，知尔松乔自难老。"]},{"t":"留石行奉呈黄参军","f":"七言古诗","c":["英州之石甲天下，一一峰峦削成者。","尺寸皆作一岩洞，一卷已自成西华。","使君作宦来炎方，十四芙蓉牍案旁。","嵌空斗竦分韶石，大小相叠读书床。","扁舟不肯载归去，留我草堂使箕踞。","奇云所变势巉岩，就中大者如淫预。","昔人高致有陆绩，虽清亦爱郁林石。","君今石乃似沉香，十四芙蓉同一掷。","沉香长在沉香浦，英石长与翁山伍。","行者为岱坐为嵩，乳窦玲珑出烟雨。","君之风流在此间，苍翠依依是玉颜。","殷勤洗濯去苔藓，朝夕再拜那能閒。"]},{"t":"韩宪使见贻二白鹇赋以答之","f":"七言律诗","c":["使君持宪白鹇国，白鹇一一生颜色。","相贻雄白与雌朱，教我烟霄恣胸臆。","山鸡孔雀满金钱，閒客衣裳似雪鲜。","明朝放向罗浮去，应解衔花旧主前。"]},{"t":"送吴少参返历阳","f":"七言古诗","c":["天作天门夹大江，君边苍翠湿秋窗。","西梁烟接东梁雨，看杀芙蓉第一双。","兰桡曾系君杨柳，莺向春人催饮酒。","沿月频过采石矶，乘潮直出鲇鱼口。","江北烟花是历阳，君归为乐正多方。","谢公陶写凭金管，太白风流在玉觞。","养寿岂须紫芝草，忘情自令朱颜好。","文章已可得长生，况有醉乡纵怀抱。"]},{"t":"送杨别驾返云间","f":"七言古诗","c":["云间曾至季鹰家，白白鲈鱼出浅沙。","四月紫莼复肥美，盘中不数龙孙芽。","君自九峰至南越，梅花何似泖湖月。","三年佐郡傍台关，大庾之山尝拄笏。","还家且向吴淞居，为政心閒在读书。","故人石父长思尔，会有相思托鲤鱼。"]},{"t":"季伟公赠我朱子纲目诗以答之","f":"七言古诗","c":["春秋之后有纲目，有如日月光相逐。","月光元自日光来，紫阳一日三膏沐。","地义天经总在兹，温公书法不曾知。","背秦岂合诬周赧，篡汉那堪奖魏丕。","昭烈一隅元正统，武侯六出本王师。","乱臣贼子不诛灭，黄初却在建安时。","笔削无过助凶逆，褒贬乃自行阿私。","牝鸡亦可当尊位，吕武纪年此何义。","英宗忽使考仁宗，父子可怜名实戾。","真是尼山一罪人，紫阳不出无天伦。","冠履一朝辨上下，血气自此知尊亲。","史中有经何精粹，素王宗子真无坠。","此书君乃肯相贻，诵读自今忘夜寐。","年来辞赋已无心，早岁春秋元有志。","书法只今在草野，一部成仁吾史记。","上师尼父下紫阳，空名不敢遗天王。","天留一岛作华夏，茫茫海外长相望。"]},{"t":"赋得蝴蝶茧赠王黄门幼华","f":"七言古诗","c":["罗浮蝴蝶有洞穴，天蛾吐丝白如雪。","千丝万丝作一茧，仙胎只为凤车结。","终日缠绵如有情，变化一一通神明。","茧中久蛰经霜雪，雌雄之雷不能惊。","枝间厚裹乌桕叶，山人采得盈筐箧。","四百峰边大小村，家家皆有大蝴蝶。","黄门近自京华来，邀我共上麻姑台。","不爱纷纷五色鸟，不求朵朵同心梅。","只怜凤子多香茧，神物人间知者鲜。","携归置在梧桐间，明岁车轮双翅展。","仙人骥骥最相宜，庄得其雄老得雌。","云霞衣服谁能似，日月精华总在兹。","君亦当年勾漏令，自入罗浮多啸咏。","鲍靓丹炉造未能，袁宏山疏题初竟。","干金何物作装还，蝴蝶之茧徒斑斑。","已掷沉香教作浦，更包锦石使成山。"]},{"t":"箪友篇","f":"七言古诗","c":["山人遗我荔枝瘿，得自罗浮第三岭。","刳作一瓢字箪友，挹泉日向越王井。","拳曲千年成一节，半生半死沉香结。","精力坚凝剥烂时，饱经甘苦成寒铁。","霜皮未尽尚磨砻，蛴螬半食心已空。","螺纹如丝旋细细，左纽右缠文不同。","故株笼颠复虎跛，留此一拳见礧砢。","臃肿何须中规矩，非方非圆但随我。","腹大如壶曲柄长，匏尊让尔居中央。","巢父手间日摩弄，松枝挂处何清凉。"]},{"t":"罗浮探梅歌为臧喟亭作","f":"七言古诗","c":["罗浮梅花天下闻，千树万树如白云。","开时花似玉杯大，枝枝受命罗浮君。","么凤一食三百朵，绿萼檀香留与我。","君来先到梅花村，重梦美人君不可。","四百峰间开更开，花从旧蒂作新胎。","今岁雪多添一瓣，去年霜少尽重台。","玄墓西溪花百里，可惜天寒香似水。","炎天气暖长氤氲，生熟水沉作须蕊。","不到罗浮争得知，梅花自此长相思。","化为蝴蝶车轮大，岁岁来攀太古枝。"]},{"t":"五十四岁自寿歌","f":"七言律诗","c":["西樵七十有二峰，东樵四百三十二。","峰峰吾皆居一年，不觉年今五十四。","明年又复居西樵，一年一峰吹玉箫。","但教七十二峰遍，便与仙人上紫霄。"]},{"t":"江山风月福人歌自寿","f":"七言古诗","c":["铁崖老人发毵毵，行年八十犹宜男。","琼华翠羽蛱蝶扇，柳枝桃叶芙蓉簪。","江山风月吾亦耽，日饮美酒能成酣。","散花天女绕左右，一朵一杯优钵昙。","天年得至九十九，赋诗应馀十万首。","年今六十紫髯长，先驻玉颜娱老母。","老母康侯王母同，受兹介福天长久。"]},{"t":"奉答张观察枉顾沙亭村舍之作用韵","f":"七言古诗","c":["东海北海海之滨，文王不作归谁亲。","太公渔钓奸西伯，美女奇物称三人。","吁嗟文武师若此，何如墨胎二子仁。","不才佯狂居南渎，食薇颜色能如春。","东方每笑首阳拙，曾参亦讥黔娄贫。","持蔬槁死宁不可，有母白发方九旬。","使君轩车忽相访，鸡鸣犬吠惊乡邻。","亥唐菜羹亦未设，荷蓧黍饭乃自珍。","踰垣闭户岂中道，礼尚往来吾当循。","威凤有德贵能下，神龙之性期终驯。","使君吐哺向白屋，刍荛之智图咨询。","庭前秋水漱白石，屋后乔松矗苍旻。","物物可以代忠告，岂必有言书诸绅。","驺忌鼓琴托讽谏，斲轮喻道偏如神。","知公相契在默识，忘怀自此日以真。"]},{"t":"自蒲涧至廉泉洞寻郑仙鹤舒台作","f":"七言古诗","c":["七月廿四廿三日，广人倾都东门出。","菖蒲涧中漱寒泉，共寻郑公炼丹室。","传闻此日鹤舒翼，安期上仙就仙职。","秦皇苍苍向烟雾，东使少君求不得。","玉舄何年留阜亭，蒲花紫茸含秋馨。","越人祈子每双乳，高禖此地惟仙灵。","水帘半遮大岩口，松柏数株老猿守。","锦幡争答白花男，珍果竞怀红粉妇。","仙人拇迹履纷纷，触破苔痕生白云。","生儿我欲生高士，似我迷花不事君。"]},{"t":"黄山五松歌","f":"楚辞体","c":["松兮松兮龙之宗，龙不为龙乃为松。","松作女萝缠一石，石为松困难成峰。","倒生下垂几千仞，松头生在青芙蓉。","龙渴下饮髯拂水，一者横卧当石淙。","一者破石石腹裂，石为之母胞胎重。","石无窍穴松久孕，横枝千载乃穿胸。","松胶石漆日坚固，松身长大石无缝。","石兮乃有松为子，石生石养无土壅。","龙性从来不见石，石即泥土恣所冲。","人间但见松变怪，岂知是龙不可踪。"]},{"t":"题西子祠","f":"七言古诗","c":["苧萝村中祠西子，苍梧城外祠绿珠。","湔裙一派美施水，得似双角井泉无。","子胥鸱夷浮江水，夷光乃亦浮五湖。","亡吴之罪亦足蔽，与诛妲己皆良图。","可惜吴亡不自死，下同紫玉在黄垆。","夫差得尔一相殉，魂魄至今娱姑苏。"]},{"t":"细月歌","f":"楚辞体","c":["有天将军名太白，尝配明月逐月魄。","小儿不识是长庚，唤作细月笑宾客。","青莲小时月不识，白玉之盘向空掷。","谓瑶台镜亦不然，镜岂有轮大十尺。","太白之星诚易知，穿入月中苦蛮夷。","太白高兮中国利，金星但愿出毋卑。","汝今夜夜拜太白，朝朝启明起莫迟。","启明多拜得聪慧，长庚更与命长宜。"]},{"t":"乌江吊项王","f":"楚辞体","c":["力拔山兮天下雄，气盖世兮乃无终。","王以天下兮三让，不然汉高无大风。","一让兮不杀沛公，鸿门不追至军中。","始驱除兮终拱手，禅授之德真重瞳。","再让兮不都关中，天府捐弃咸阳宫。","故乡彭城不忍舍，鸿沟为界来相攻。","三让兮不渡江东，江东吴越地未空。","八千子弟倘复起，夫差句践霸可同。","江涛怒兮水倒立，大野吹兮多落枫。","时不利兮骓一蹶，天之亡我命当穷。","死生与虞同一命，蛾眉血兮溅衣红。","王多情兮不负季，视季亦与虞兮同。","还定三秦忽失约，季负王兮季非忠。","不杀义帝季亦杀，三军缟素欺愚蒙。","英雄岂必皆好信，势便逐利如转蓬。","三杰不言复雠事，董公遮道计殊工。","吴芮不杀王不服，弑君之贼乃有躬。","义帝无后汉不立，汉之寡恩诚不聪。","英雄成败两不义，谁言天授非人功。","吁嗟，谁言天授非人功。"]},{"t":"嘉禾歌为王础尘寿","f":"古风","c":["嘉禾生，在何地。","一茎嘉禾有八穗，一穗有谷六十四。","望如芦荻一丛丛，朱家巷口廿里中。","三百年来草未垦，此土发祥有真龙。","真龙昔向句容产，黄气紫云长鸿濛。","瓜瓞绵绵此根本，民之初生沮漆同。","嘉禾知是后稷穑，不烦播种因天功。","子孙会有圣人出，嘉禾为兆非年丰。","我从王君闻此兆，如此嘉禾古所少。","八穗乃是八纯卦，六十有四合大小。","易为日月两大象，相代为明昏复晓。","一穗具卦六十四，造化有心殊易了。","持将八穗为君寿，数符五百不先后。","名世即同王者兴，周公嘉禾作应又。"]},{"t":"黄山僧述古画黄山诸松见寄诗以酬之","f":"七言古诗","c":["大师将毋永嘉僧，画松往往松飞腾。","梦中吞龙知几百，吐为松树有神冯。","狂来倒吸歙溪酒，醉中鳞甲出两肘。","黄山诸松最奇怪，秃笔扫来无不有。","此图十株皆逼真，尺蠖盘回苦不伸。","千态万状在枝干，多横少直争轮囷。","日挥双管走奇鬼，一为生枝一枯蘖。","拂水藤缠夜叉臂，凌霄花结灵鼠尾。","针芒一一如铁攒，中有风雨驱惊湍。","阴森已过毕庶子，劲挺绝胜蒋长源。","大师画手老无敌，因我爱松费笔力。","他时我向黄山行，偃盖株株应遍识。","会当再拜卧龙松，十旬坐卧当卧龙。","剪取生绢长一丈，乞师图取归南禺。"]},{"t":"莲","f":"七言古诗","c":["红莲宜子白宜藕，白者香多红者否。","莲秧频种春分前，红莲持作白莲偶。","枝头向南叶易舒，花比叶高一丈馀。","春分后种花苦短，田田影里含芙蕖。","年年种莲不及早，街头买得数缸好。","吹香一夏喜风多，朝朝一朵开怀抱。"]},{"t":"合欢木歌","f":"七言律诗","c":["合欢合叶不合花，花合何如叶合好。","夜夜相交不畏风，令君蠲忿长相保。","劝君多种合欢枝，叶至黄昏合不迟。","夜合合花那得似，花有离时叶不离。"]},{"t":"山大舟歌","f":"七言古诗","c":["自是赭桐人不知，山大舟名空陆离。","越王烽火开千树，石氏珊瑚碎万枝。","终年吐艳光相射，不待烛龙成不夜。","端阳日酷色逾鲜，虽黄未肯先红谢。","无数小花攒大花，玲珑雕出芙蓉砂。","一花动至百馀日，不老须君媚岁华。"]},{"t":"后箪友篇","f":"七言古诗","c":["古之瓢饮巢与繇，颜渊亦以酌溪流。","彼皆苦叶匏所作，短颈大腹轻且浮。","系而不食经霜落，腰之深浅用亦优。","我之瓢与香瘿瘤，根之生结非香肉。","渣滓已化馀皮坚，黄熟未成苦面皱。","一柄屈折珠斗同，又如人胆刳空中。","就泉掐取日挹注，不用羸瓶多有功。","一勺于我亦已足，五石笑彼无所容。","平生与箪作一处，贫贱之交相尔汝。","匏瓜无匹箪其匹，中流千金吾不与。","未能长吸作鲸鱼，且复量腹为偃鼠。","所乐谁言不在兹，洋洋泌水吾香糈。","此瓢真是吾俦侣，五岳相携历寒暑。","中路与君恐非情，使箪无友长伶仃。","不及昔时太白老，鸬鹚之杓同死生。","箪友在君宁在我，久要于义乃云可。","木质轻微不足贵，遗君当致一金叵。"]},{"t":"嘉禾歌为广州刘太守寿","f":"古风","c":["昔有贤太守，渔阳与颍川。","嘉禾麦两歧，颂声天下传。","一茎九穗今重见，我公德政谁不羡。","吐秀亦五七，衔滋露泫泫。","异母同颖与周同，成王将复馈我公。","充箱之实为公饭，上天所贶以报功。","父老纷纷上堂寿，持此嘉禾拜左右。","殷勤欲请归禾篇，家家管弦为公奏。"]},{"t":"惠州王太守入罗浮寻梅花村不得用子瞻松风亭下梅花诗原韵有作予为和之","f":"七言古诗","c":["水帘洞口梅花村，梅花不见馀冰魂。","美人已随明月没，依稀缟衣来黄昏。","翠羽啾嘈怨幽谷，白云黯淡愁荒园。","使君苦寻千万树，一冬冲雪忘寒温。","急须更植遍岩壑，依之吐纳扶桑暾。","尽教玉女插云髻，复为老人遮松门。","千秋梅花作汤沐，四百君当闻此言。","一罗一浮再开辟，花时招我倾清尊。"]},{"t":"水仙叹","f":"七言古诗","c":["往年水仙从吴来，四万馀本花尽开。","今年祗得四千本，十本一花无重台。","家家水仙苦不售，一钱一本谁买回。","人穷罕有好事者，生理萧条良可哀。","水仙天暖但生叶，天寒始见花含胎。","今岁广南颇风雪，冻伤无数桃与梅。","水仙苦寒亦不发，安得一夜春气回。","我心望春与花似，春来我心花亦开。"]},{"t":"广陵老僧闻一以画扇见贻诗以答之","f":"七言律诗","c":["老僧能琴复能画，八十四龄何潇洒。","扇头贻我潇湘景，彷佛闻有飞泉泻。","乞师即来一鼓琴，移将万壑寒松林。","霜钟一醒青莲耳，流水长清太白心。"]},{"t":"修复浮丘诗社有作","f":"古风","c":["仙城三石三塿，似三神山随波流。","地道潜通第七洞，朱明门户惟浮丘。","浮丘丈人昔栖此，子乔吹笙翩来游。","浮丘伯与浮丘叔，兄弟一罗而一浮。","稚川来挹浮丘袖，丹井至今如龙湫。","海神珊瑚一再献，珊瑚知自珊瑚洲。","瀫阳浮丘结大社，吾越风雅凌中州。","前掩曲江后海目，埙篪一一相绸缪。","变乱以来遗响绝，后生不知分歌讴。","抗风轩中失领袖，诃子林里谁赓酬。","别裁伪体遍里巷，汉唐规矩同寇雠。","泰泉弟子多古调，兰汀青霞居其优。","我今欲作钟吕倡，欲得二三黎与欧。","南园东皋总荒草，坛坫复有浮丘不。","招携诸君理芜秽，胜事更与仙灵谋。","曜真之天再开辟，泉源福地持咽喉。"]},{"t":"次和惠州王子千太守初入罗浮宿冲虚观用东坡同子过游罗浮韵并以为寿","f":"七言古诗","c":["朱明曜真仙人京，太守入山天乐鸣。","洞天日月一沐浴，碧鸡红翠生光明。","天教太守主双岳，神君元是长庚生。","药市酒田暮治事，琪花瑶草朝省耕。","仁爱使民尽眉寿，岂徒一身聃与彭。","东浮西罗恣攀陟，车轮蛱蝶同身轻。","鲍女飞猿尚蹩躠，葛公哑虎徒狰狞。","铁桥自可到银汉，玉柱何用探金庭。","踏穷四百三十二，一峰一峰图且经。","泉源福地置飞阁，真一法酒留丹铭。","金马且复隐星宿，玉蟾岂必辞公卿。","冲虚玉简多秘祝，先为苍生求太平。"]},{"t":"王太守作见日亭成诗以美之","f":"七言古诗","c":["泰山鸡鸣始见日，罗浮夜半踆乌出。","南溟自是阳明谷，十日所浴光洋溢。","三足欲栖上下枝，天鸡惊起黑如漆。","珊瑚之树即扶桑，曜灵家在鲛人室。","牂牁大洋咫尺间，蓬莱一股何曾失。","未暾峰峰见东君，六螭先指浮山云。","金光直射散飞电，火轮千里烧氤氲。","玄黄鸡子连珠似，五色鸿蒙分不分。","罗山势与浮山并，见日有台当绝顶。","泰山日观高不如，俯视朱天最空迥。","台风每苦扶摇多，吹倒铁桥堕青冥。","重造飞亭今有谁，惠阳太守才天挺。","郁仪日日朝朱明，君为东道有馀情。","导引重轮勤夙夜，寅宾两珥竭神明。","昧爽沧凉好晞发，日华吐纳变金骨。","羲和为尔再中天，不使白驹过倏忽。","云衣霓裳日往来，文章更与炎精发。"]},{"t":"罗浮对雪歌","f":"七言古诗","c":["峤南自古无大雪，况复罗浮火洞穴。","山人不识冰与霜，白露少凝阴道绝。","今年季冬太苦寒，雪花三尺如玉盘。","麻姑玉女尽头白，四百缟素失峰峦。","天气忽将南作北，层冰峨峨路四塞。","浮碇冈头似白山，罗阳溪口成敕勒。","千株万株松欲摧，梅花冻死无一开。","北风惨吹笼葱裂，猿狖僵卧吟且哀。","辟寒有方得仙客，斫取龙鳞薪琥珀。","地炉烧出日轮红，天井迸来云箭白。","咫尺空濛接海津，光摇宫阙失金银。","玉作越王烽火树，瑶华飞满珊瑚身。","天鸡夜半冻不叫，曜灵忍失朱明照。","久伤乌羽坠重光，安得烛龙衔一爝。","欲挽羲车力士无，穷阴苦逼岁华徂。","麑裘不暖难消夜，坐拥瑶琴影太弧。"]},{"t":"鱼缸","f":"楚辞体","c":["天南仲秋始清凉，使君高宴飞羽觞。","鱼缸最小受涓沥，以予公荣非酒狂。","宣成之间御窑器，年来仿古多精良。","文渊酒魂化为土，陶家取作杯玄黄。","鸡缸岂如鱼缸雅，兼金争购从鄱阳。","泑如羊脂绝瑩白，丹青不敢污中央。","烧出小鱼类榆荚，黑睛朱鬣浮生光。","得酒噞喁若新水，四尾相逐何洋洋。","生忧嘘噏鱼入口，合唇微饮贪闻香。","涵泳飞华唼浮蚁，冬甘夏苦鱼先尝。","缸中自是酒泉郡，鱼兮汤沐须醉乡。","宁图溟渤恣潜跃，一滴两滴真濠梁。","失水不忧忧失酒，相濡相喣樽罍旁。","云沸渊流贵不息，兰生萼绿无参商。","每君饮釂似乾泽，鲜薧倏忽成沧桑。","青州露甜易州辣，一斟再酌苏吾僵。","醇酿即是桃花水，糟粕亦乃鲲鹏乡。","浊贤岂必清圣好，北酒诚比南醪强。","我欲为鱼在缸里，金钩桂饵长无殃。","一勺琼苏亦鲸吸，纤毫不惜居鱼秧。","五石瓠瓢拙用大，何如用小蟭螟藏。","蝉翼自能负嵩华，蜗角岂必争侯王。","吞舟每忧值芥叶，漏网所贵同针芒。","白小天然尚二寸，入缸已是寻龙鳇。","我今非鲂亦非鲤，酒龙变化铢黍长。","相随蠛蠓游曲糵，此乐谁知吾蒙庄。"]},{"t":"初春六瑩堂雅集主人梁庶常出六瑩琴相示歌以纪之","f":"七言古诗","c":["主人花多开成行，入门白碧红绯香。","华堂扫花燕嘉客，吴歌楚舞纷鸳鸯。","酒伴张琴如绿绮，蛇腹古光玄雪起。","太冥桐干含黄钟，彷佛落霞与流水。","杯行未暇调清商，点徽转弄妨绕梁。","大小鼙婆恐终曲，新声靡曼娱中肠。","长清短侧俟他日，为君一弹欢未央。"]},{"t":"韶石歌韶州太守席上作","f":"七言古诗","c":["使君五马从韶阳，春融开宴来仙羊。","誇予韶石三十六，芙蓉一一摩青苍。","韶阳千里尽奇石，各为根株森相望。","箨龙拔地动千丈，大小削成纷圆方。","瑶篸玉柱千万计，排立有时如堵墙。","巨灵荡踏苦无力，岩岩铁壁当中央。","使君拄笏韶石下，氤氲紫翠流衣裳。","双峰左右接天阙，二楼高下临皇冈。","重华对越俨精爽，二灵彷佛非鸿荒。","神明沕穆合古乐，箫韶日夕深微茫。","南薰再鼓解民愠，玉琴之外无陶唐。","香炉宝盖试击拊，安知不可仪凤凰。","无声之乐道所贵，期君肉味长相忘。"]},{"t":"望夫石歌","f":"七言古诗","c":["二禺之峰七十二，中有石人立苍翠。","望夫化作石嵯峨，留取贞心在天地。","石公石姥洞庭西，合体休垂双玉啼。","安得郎归亦化石，白云深处常相携。","无情化石石难好，有情化石石难老。","郎归会见石能言，招手天边待相抱。"]},{"t":"精卫词","f":"古风","c":["西山木，一日一枝衔未足。","口血沾濡枝忽荣，化作扶桑向旸谷。","扶桑枝枝有一日，一日未终一日出。","人间十日不妨多，后羿弯弓休更弹。","日光倘肯照心肝，但教烧得海水乾。","海水乾时精卫死，魂作一金乌，与日相终始。"]},{"t":"七夕后二日送王君还渠阳","f":"七言古诗","c":["双江合流何汤汤，左江右湖城中央。","浮桥冲断望风雨，迟君一日开帆樯。","炎云欲散苦未散，秋过七夕方微凉。","平头交扇尚挥汗，解襟且复依林塘。","君今拜亲留不可，八千馀里归称觞。","阿兄晨羞弟夕膳，笑加匕箸因芬芳。","紫芝老父两眉秀，白鹿仙人双耳长。","明岁能来觐叔父，宝坻美酒多携将。","惠阳郡楼一再酌，更看灵鹊填河梁。"]},{"t":"口占赠谢七丈长松","f":"古风","c":["罗浮七星松，曾化七道士。","君是第几株，苍龙夭矫似。","年方八十已大耋，问汝奇龄安所底。","手种诸香成水沈，生结熟结多肌理。","赠我太古根，枝枝含石髓。","焚向南山垆，氤氲浸四体。"]},{"t":"质古玩行","f":"七言古诗","c":["我之所玩无珍奇，玉杯玉盘佳人贻。","珊瑚樱桃红多肌，以为笔格光离离。","贫中往往乏名酒，杯无颜色焦羊脂。","象箸纷纭作一束，山殽厌饫无香狸。","雷惊花入纹参差，血牙鲜润徒空持。","饥来儿女容惨淡，堂上旨甘安所资。","赵生为我鞠躬执，子母钱家求毫釐。","寄实于人不越宿，于托妻子怀忧疑。","暴弃天物贵易贱，锥刀之末终何裨。","韫椟不能沽不忍，须臾割爱含酸悲。","况兼玉镇雕眠狮，初看绝似丹玻瓈。","何年出自晋灵冢，蟾蜍书滴交光辉。","昔人殉葬苦用此，宝华吐白虹霏霏。","精彩溢流可照面，美人气见春含滋。","血痕暗洒古花碧，水岩火捺同膏肥。","藐姑冰雪久渗渍，苌弘朱碧争淋漓。","珊瑚旧是烽火柏，赵佗铁纲千寻施。","一本三柯献高帝，夜光欲然惊波斯。","一年始黄三年赤，扶疏石上连根移。","积草池中泣辞汉，流落石家人不知。","多谢绿珠铁如意，为予击碎馀一枝。","槎枒颇似鹿角菜，礧砢多节仍纷披。","虫食琅玕小穿穴，洞见心赤如通犀。","不知珊瑚雄定雌，或女珊瑚之孑遗。","珊瑚之棁一萌蘖，尺寸亦作盘蛟螭。","绿沈漆镂大小管，参两架取随高卑。","犀植象跗恣偃仰，铜龙不插难倾欹。","门庭免著太冲笔，笔床不用相撑支。","一朝为质去书案，兔翰狐柱伤无依。","栖笔寝牍自今始，泣别左伯兼张芝。","馁在砚田耕不得，鬻文为活求者谁。","君苗焚笔欲更学，陈汤掷笔思乘时。","错刀粪土尔何物，令我推颓迷所为。","锱铢仰面贾人子，彼贱丈夫何蚩蚩。","一钱羞涩笑杜老，岂知百万囊珠玑。","珠玑无用化鱼目，泥沙抛弃空骇鸡。","妻孥朝夕作书蠹，食尽万卷仍长饥。","鲋鱼只求升斗活，鹓雏遑与梧桐期。","呜咽无言向珍宝，临分审视无瑕疵。","鲛文鹅眼多盗铸，绀文赤仄忧吾欺。","但求白镪救当厄，多寡敢望兼金赍。","区区长物不自保，匹夫怀璧防灾罹。","交情所贵在终始，遗簪故剑诚吾师。","殷勤赎汝未容缓，恐遭点辱琼瑶姿。","与儿辈处患玷缺，白圭再磨终不宜。","紫榆文具谨扃钥，愿言什袭长孳孳。","稍待竭力营阿堵，朱提或得微刀圭。","凭君完璧复归我，被褐坏之毋迟迟。"]},{"t":"赠惠阳俞别驾","f":"七言古诗","c":["罗浮多年无主人，惠阳太守今如神。","公与卧治同清静，风流文采俱仙真。","左江右湖日挂笏，讼堂无事官长贫。","王祥声名起别驾，良二千石犹逡巡。","股肱之郡贵公等，朱轓不日閒行春。","芙蓉四百且登陟，葛洪鲍靓招为邻。"]},{"t":"插木棉","f":"古风","c":["乱插木棉乘大雨，无根易长珊瑚树。","一枝一干似人长，明岁花如木笔吐。","花比辛夷更大朵，开时半天红似火。","纷纷赤玉杯，争向怀中堕。","拾来堆成霞，狼藉芙蓉砂。","苔阶扫不尽，萎谢仍芬葩。","生长南州盛炎德，纯丹表里含光华。","朱颜无命易憔悴，弃捐岂敢辞泥沙。"]},{"t":"送朱上舍","f":"七言古诗","c":["汝兄峤南来可怜，故人不得相周旋。","台门咫尺邈千里，相知何苦相天渊。","汝今又归桐乡去，临分那得无缠绵。","嘉禾我友十馀辈，汝兄第一胶漆坚。","筜谷已往墓木拱，武功广汉皆黄泉。","平生知己在梅里，白头存者多迍邅。","汝行为讯缪天自，二李伯仲应归田。","徐家复有磨镜者，季也亦诚生刍贤。","鸳湖一别动廿载，人生倏忽真浮烟。","富贵非时自知隐，文章无命谁求传。","恋君一步一握手，赋诗金石聊相宣。","汝才峥嵘亦奇辟，开元大历羞比肩。","参差似兄腾笑集，埙篪同开风气先。","逃唐归宋计亦得，韩苏肯让挥先鞭。","大雅只今久沦替，吾衰难起黄初前。","老岂争名向轻薄，自来可杀惟青莲。","苦心经术作书蠹，五经纵横情所便。","春秋已知非笔削，大易亦谓无方圆。","十翼思返仲尼旧，三传欲将公谷捐。","诗歌末艺任工拙，汉儒章句方拘挛。","壮心慷慨尚复尔，时时自苦明膏煎。","葛公中华倦游步，龙光欲骋聊高眠。","故人倘询英霸器，为语奇雅犹芳年。"]},{"t":"哭王处士","f":"七言古诗","c":["大江以南谁狂奴，故人未兴何所图。","长身美髯气虓勇，叱咤可恨风云无。","国亡甘作沐犊子，二十有六称鳏夫。","亚匹管萧吾亦尔，英雄命苦成拘儒。","每兄事君拜床下，疏巾单衣长与俱。","托凤攀龙既已矣，拂衣且先归黄垆。","姿才冠绝亦何益，天生我辈填沟渠。","总揽国殇向地下，厉鬼亦可相驰驱。","我今亦是鼓刀屠，老母天年哀已徂。","无亲可事合从死，白头下殉同啼乌。","哭君不脱衰绖往，抚棺非吊空号呼。","平生慷慨共心胆，悲歌往往崩玉壶。","君死狂言向谁发，只应天口长喑呜。"]},{"t":"送季子扶两尊人灵柩归葬钱唐","f":"古风","c":["为君歌弹歌，亲死不葬哀如何。","桐棺暴露亦已久，越王台下乌鸢多。","飞土可怜汝孝子，二人封树无蒿里。","主丧未敢脱衰裳，日向黄肠泪如水。","十数年来栖炎方，先人宅兆怀钱唐。","归祔松楸遂丘首，精灵相逐佳城旁。","崔瑗张霸阙遗令，止葬岂可依他乡。","陈寿不归遭贬斥，知君及早事窀穸。","裂书昔感故人心，推辇今蒙谁氏力。","惠阳太守真申屠，归善令公亦范式。","教营高燥赠多金，高义云天安有极。","秋凉首路出台关，舒卷悲旌向北还。","如堂定筑南屏上，物土依稀天竺间。","我昨营坟已襄事，会当庐墓长憔悴。","死作乌雏更断肠，生为猿子空悲泪。","白马素车难送君，微茫望断西湖云。","皋鱼哭处风萧瑟，声乱白杨谁忍闻。"]},{"t":"题钱子濯足图","f":"楚辞体","c":["不濯缨，但濯足。","不见沧浪清，但见沧浪浊。","浊可濯兮何必清，清斯受辱浊斯荣。","君今但濯无清浊，清浊都忘志即平。"]},{"t":"蓑亭为飓风所摧","f":"楚辞体","c":["葵叶为蓑蓑在身，风吹不去长随人。","蓑为亭子风不许，捲入空冥要吹汝。","天生葵叶作君蓑，汝不被蓑蓑自去。","蓑归来兮休乱飞，吾将以尔为毛羽。","白茸茸兮似鹭鸶，伏芦花兮无人知。","以笠为亭无不可，吾生无分居茆茨。"]},{"t":"少谷 其一","f":"七言律诗","c":["早黏将及秋分熟，飓风吹去三分谷。","今岁沙田又少收，一冬祗可充饘粥。","耕不逢年奈命何，家贫幸未买田多。","空惭妇子长饥汝，更使无衣带薜萝。"]},{"t":"少谷 其二","f":"七言古诗","c":["去年阳月无壬子，留寒到春寒不已。","一春况复阴雨多，冻与大冬冰雪似。","诸花未见发根荄，兰叶才开三四耳。","荷锄种豆且莫早，土膏虽动亦冻死。","立春不得一朝晴，今岁农夫又已矣。","白头饥馁复何极，苦与蛴螬争一李。","于陵矫廉人尽笑，只有辟纑是知己。"]},{"t":"沟壑行","f":"七言古诗","c":["岭南三月桐未华，柳才生发青鬖髿。","緤布欲裁无棉絮，冷淘欲作无槐芽。","雨多天乔皆烂死，一春花蘤失红紫。","水潦不忧却忧旱，春雨未应逢甲子。","农夫奔走争祈晴，吉贝豆苗伤已矣。","已过清明十馀日，苦寒尚与龙荒似。","餐眠谁问浣花翁，一日素书三四纸。","抵死饥寒不忍言，甘心沟壑今如此。"]},{"t":"食蕨 其一","f":"七言古诗","c":["雨多蕨芽肥不已，拳曲重重毛色紫。","一夕雷惊总怒生，茎茎看与龙头似。","畲人采得兼香蕈，殷勤持向从阳市。","无人肯买充盘餐，多为性寒损肌理。","清斋我久绝膏腴，不为逃禅学妙喜。","高堂往日好伊蒲，野蔌山肴思所嗜。","肉味乾濡未忍甘，姜桂相滋今疾止。","鸡豚无复佐晨羞，蔬食从今至没齿。","寸寸春葱总断肠，枝枝冬笋休生矣。"]},{"t":"食蕨 其二","f":"楚辞体","c":["昔人食薇不食蕨，食蕨能令心断绝。","蕨生一一应猿啼，猿啼一声蕨已齐。","千茎万茎况雷雨，一夜穿尽春山泥。","猿啼多处蕨无数，泪痕一一应沾汝。","汝生何苦傍猿边，猿易断肠生太苦。","枝枝亦是断肠枝，下箸令人悲复悲。","我今无薇更可采，薇兮要汝长疗饥。","蕨寒薇暖薇应食，薇食令人好颜色。","夷齐食薇得三年，不死多因薇气力。","首阳一去薇香传，人言夷齐古薇仙。","薇生黄农虞夏代，不生今世因无贤。","我今食蕨当食薇，薇与蕨忘无是非。","恍惚闻猿啼左右，思与猿同三峡归。","我生与猿同性命，化为蕨兮即清圣。","断肠久矣不须啼，情返无情期得正。","猿之所在即多蕨，故食蕨能令人悲。"]},{"t":"杜鹃峰作","f":"楚辞体","c":["浮山顶上花万千，一峰花独多杜鹃。","色兼蓝紫与黄者，绝少殷红猩血鲜。","开时无叶但枝干，槎枒屈曲相钩连。","浮山旧多海底树，岂铁珊瑚风吹坚。","定知不是子规血，不然望帝成神仙。","春心已得丹砂化，蚕丛旧恨都弃捐。","谢豹亦作捣药鸟，口中长吐瑶池莲。","开多黄色得中气，与金芙蓉争光妍。","西蜀安得有此种，啼痕沾湿迷荒烟。","斑斑胭脂自太古，那能化碧沉重泉。","龙为鱼兮谁不苦，潇湘之竹同烦冤。","噫吁嘻，潇湘之竹真烦冤。"]},{"t":"赋为王紫诠使君寿兼送迁任川南","f":"七言古诗","c":["使君一作罗浮君，亭开子日当飞云。","要与岱宗日观敌，三更已见金乌踆。","南溟咫尺即旸谷，吐纳不外扶桑暾。","礼接曜灵本天职，朱明况与台门邻。","青冥绝顶作云搆，呼吸上通天帝欣。","位置岂如赵汝驭，横翠拂松徒纷纭。","白玉真人有宿契，梦中相命何谆谆。","仙驾长在洞天里，朝元每夜同紫宸。","前身或是鹤林辈，紫元紫华为高群。","不然玉局一散吏，重来彷佛惊山䰠。","翠羽屡逢铁冠队，青牛时开云篆文。","梅花村口劝农罢，都虚坐啸长经旬。","畲田无讼鞭挞废，白衣山子皆良驯。","半遮水帘视公事，欲归官阁还逡巡。","治行第一股肱郡，邻邦疾苦兼咨询。","荐章谓良二千石，荣迁忽向泸江滨。","鹅城父老日奔走，乞留绯鱼丰湖漘。","白石争求鲍太守，荔支宁数陈将军。","黄龙诸仙亦惆怅，碧鸡鵔鸃皆酸辛。","哑虎将出负书簏，啼猩亦欲攀车轮。","玉女奉饯酥醪酒，麻姑泪沾蝴蝶巾。","铁桥石柱黯无色，餍饫珠玉犹嫌贫。","一峰一匹锦绣段，四百三十愁未均。","争留大夫作生日，石楼星精来老人。","八十九条瀑喷薄，二十四种芝轮囷。","玉源为君作膏泽，瑶石为君铭功勋。","丹成已坚黄金骨，婴姿孺貌长韬真。","此行剑门历艰崄，如乘龙蹻凌苍旻。","舟上瞿塘利风水，旌麾高拂瑶姬裙。","巫山十二为我数，一峰不肯相嶙峋。","定贪暮行香雨去，芙蓉飞坠知横陈。","天上王郎谁识得，烟霄一下婴埃尘。","子晋且停白鸑鷟，方平休跨黄麒麟。","阴功即是稚川药，至道惟凝姑射神。","孟夏陶陶盛发育，初度令节丛嘉宾。","安石榴吹丹灶焰，麝香萱吐华堂禋。","阿翁红肌兼绿发，在家常醉田盘春。","那能方朔至青鸟，安得琴高来赤鳞。","王乔飞舄正杳杳，王阳叱驭方駪駪。","昔为刺史今岳牧，神仙自来多外臣。","日月薄蚀要补救，云电屯难需经纶。","四海饥溺未由己，百蛮痌瘝先在身。","夜郎君长亦游戏，未忍鄙夷斯苗氓。","会将礼乐变殊俗，尽令猡缅知同伦。","有教岂分人兽类，但含血气皆尊亲。","永宁居之亦何陋，咽喉三省劳才斌。","诸葛治蜀虽多猛，庄蹻开滇元用仁。","清廉得垂橐橐去，绝胜养砂成金银。","代偿逋赋更破产，肯持南物过峨岷。","脂膏毛米不濡润，斯道绝响今复振。","与予金石交已定，六年相对忘衣鹑。","但怜华采似鳷鹊，未嫌疏野同䴥麇。","此行巴渝不偕去，参差儿女牵婚姻。","簸弄明珠我亦得，婆娑海水公无嗔。","终然相寻踰白帝，川南取道过金潾。","勉赓白盐赤甲赋，祗愁笑破花翁唇。","杜陵放翁汝勍敌，将来鼎跱成三分。","才华绝世不入蜀，争得奇险篇篇新。","雄浑奡兀尽神变，要令鬼哭吾吟呻。","五丁在手苦开凿，天然不露秋毫皴。","知君拔山笔力大，此番冥搜天地根。","乱挥三峡恣澎湃，细写千嶂穷氤氲。","锦江桃色染笺纸，遗我作草龙蝹蝹。","书君怪丽句千万，散为天花飞九垠。","祗恐管城不能给，紫毫抽尽东郭㕙。"]},{"t":"合江楼宴集次苏长公韵","f":"七言古诗","c":["洋洋乎水何美哉，合似罗浮不复开。","天下朋友之胶漆，安得尽似双江来。","登临风日正清美，长啸休惊鸥鹭起。","使君醇醪自宝坻，倾作金波逐江水。","一杯明月一杯新，明月笑我非仙人。","仙人未有不饮者，更须沉湎罗浮春。"]},{"t":"糠覈行赋赠陈子","f":"古风","c":["美丈夫，一身之外衣食无。","糠覈之肥白如玉，英雄亦多冰雪肤。","貌如好女发鬒美，魁梧奇伟乃如此。","逃秦一任四衰翁，兴汉只须两孺子。","君今长大宁长贫，且先辟谷同仙人。","自古王孙要饥绝，壶浆岂必求交亲。","读书只是学黄老，阴谋实伤天地仁。","其间名世端不尔，与君儒者元多珍。"]},{"t":"分笔行","f":"七言律诗","c":["故人遗我湘江管，花纹斑驳琅玕满。","五儿分取作真书，女仿曹娥花露盥。","我日临池学擘窠，伯英弟子草书多。","安得吴兴真紫颖，千枝挥洒换群鹅。"]},{"t":"银河曲","f":"七言古诗","c":["万里银河接凤城，迢迢怅望不胜情。","生作仙灵偏独宿，天公何苦累双星。","为天耕织辛勤绝，一年一夕还呜咽。","谁言天上暂生离，胜似人间长死别。","人间死别又吞声，泪逐银河地下倾。","荷鼓有妃仍命薄，匏瓜无匹肯心平。","相隔盈盈才一水，何如泉路数千里。","紫圭烟化绿珠沉，再见容华终已矣。","清浅河精本易乾，何须乌鹊日盘桓。","填河肯用支机石，会见桥飞胜羽翰。","将牛更饮银河尽，天罪多情应不忍。","本是牵牛贵莫当，化为沐犊穷堪悯。","玉手回旋作七襄，长空日夕锦霞张。","难将绮绣偿天债，皇穹何不重文章。","浣纱水冷谁知汝，胍胍灵仇不得语。","龙镳不解逐浮槎，逃向人边依海渚。","双精曾降黄姑地，金篦划河阻天使。","河名百沸至今传，牛女有祠人尽祀。","窃药嫦娥路不迷，蟾兔宫中容叛妻。","不闻天帝罪奔月，天仙偏遣守空闺。","香华既有芳祠在，七夕不须针缕待。","丈夫况作馆甥来，帝子应教须女代。","女儿乞巧且逡巡，巧得蟢丝祗误人。","宝家枉自回文妙，卢女虚传飞盖神。","指间织锦称机绝，岂是星光长照身。","缣素不劳分丈尺，旧人争得白头新。","自古才贤罕嘉耦，生逢寡宿难消受。","安仁悼俪为姿研，诸葛求婚须貌丑。","而今倘欲娶姬姜，先乞双星与年寿。"]},{"t":"草书歌赠蓝公漪","f":"七言古诗","c":["公漪爱我草书好，画成即遣作今草。","角扇屏风总不辞，龙蛇飞动为君扫。","古来草圣称张芝，神变无方吾所师。","点画精微尽天纵，岂惟劲骨兼丰肌。","二王笔精复墨妙，思极天人无不肖。","率意超旷我亦工，研精体势未知要。","汉人遗法久无传，用笔从来贵极圆。","怀素颇得草三昧，夏云随风任盘旋。","米芾神锋每太峻，大黄远射力愁尽。","张旭颠草虽自然，亦伤雄壮终非晋。","我今学草常苦迟，未能变化犹矜持。","裙滑无多羊氏练，水清安得伯英池。","伯喈作书必纨素，欲购千端与毫兔。","仲将如漆墨盈箱，左伯光妍纸无数。","为君乱作一笔书，心手窈冥随所如。","蛟龙拿攫恣夭矫，骤雨飘风教有馀。","秾纤折衷更精熟，每日淋漓须百幅。","君之散隶亦入神，以之相易须神速。","君有尊人草篆精，凡夫赵氏同飞名。","故君法书具清识，感激知己深余情。","笔力会当友造化，安得闭门日多暇。","右军筋骨亦精心，与君八分早相亚。"]},{"t":"读先祖沧洲处士诗集","f":"五言律诗","c":["八十婴儿慕，如翁世所希。","苏耽今化鹤，莱子尚留衣。","仁孝传桑梓，文章映少微。","无能歌祖德，手泽泪空挥。"]},{"t":"清明展先府君墓 其一","f":"五言律诗","c":["蕨薇留寸草，桑梓别经年。","积雨崩丘垄，名山失简编。","大招空有赋，薄祭竟无田。","洒尽皋鱼泪，苍茫对昊天。"]},{"t":"清明展先府君墓 其二","f":"五言律诗","c":["昨梦犹尝药，凄凉夜月中。","江山精爽在，伏腊几筵空。","攀柏徒悲泣，吹箫尚困穷。","未能庐墓左，王事正西东。"]},{"t":"清明展先府君墓 其三","f":"五言律诗","c":["报国无三略，违亲有五年。","空将禾黍泪，滴向蓼莪篇。","海阔迷龙驭，山长断马鞭。","茫茫移孝日，难别此黄泉。"]},{"t":"清明展先府君墓 其四","f":"五言律诗","c":["雨露悲寒食，丘中宿草萋。","蘋蘩无妇采，乌鸟向人啼。","勉继春秋志，高求海岳栖。","右军能誓墓，此地蕺山齐。"]},{"t":"北游初归奉家慈还居沙亭作 其一","f":"五言律诗","c":["苏耽成道返，阿母大欢娱。","何意天边月，还为掌上珠。","白华长抱蒂，朱凤更将雏。","日夕流霞献，慈颜似鲍姑。"]},{"t":"北游初归奉家慈还居沙亭作 其二","f":"五言律诗","c":["久客边州里，初归涨海滨。","三迁忧老母，九死愧先臣。","深爱存颜色，微忠托隐沦。","帘前双燕好，挟子献青春。"]},{"t":"北游初归奉家慈还居沙亭作 其三","f":"五言律诗","c":["涕泣辞京国，间关出战尘。","发肤归父母，薪胆献君臣。","逃墨因多难，成仙未是仁。","蛮江葭菼外，此日复垂纶。"]},{"t":"北游初归奉家慈还居沙亭作 其四","f":"五言律诗","c":["五岳游难遍，归来复闭关。","祗因恋慈母，不忍住深山。","草长多麋鹿，江清有白鹇。","物情皆慕侣，吾亦倦知还。"]},{"t":"北游初归奉家慈还居沙亭作 其五","f":"五言律诗","c":["白尽高堂发，秋霜满海天。","早营乌鸟养，莫恋沃洲禅。","井邑烽烟里，山河战伐边。","绝裾谁忍再，空有壮心悬。"]},{"t":"家园示弟妹 其一","f":"五言律诗","c":["先人好种药，遗我神农书。","与子理尝业，参苓带雨锄。","道从多病入，力是耦耕馀。","莫叹生涯拙，韩康此隐居。"]},{"t":"家园示弟妹 其二","f":"五言律诗","c":["两妹年俱长，家贫织素丝。","月分朱火冷，风引玉琴迟。","烟雾怀秦女，兰荪佩楚辞。","隐居应有服，黾勉霸陵期。"]},{"t":"奉母人泷州避难寓从弟之姻林氏馆有赋 其一","f":"五言律诗","c":["白鹄从其母，东飞琼树柯。","苏仙频避弹，炎女未填河。","反哺求粱稻，孤生念茑萝。","昏姻维尔故，留托泰山阿。"]},{"t":"奉母人泷州避难寓从弟之姻林氏馆有赋 其二","f":"五言律诗","c":["衔草鹿鸣麑，呦呦春涧西。","介推惟负母，弘景未归妻。","遁世心无悔，游仙路不迷。","泷州山水好，兄弟且相携。"]},{"t":"登浴日亭","f":"五言律诗","c":["月明南澥阔，中夜气鸿濛。","万马奔旸谷，双螭御祝融。","日轮飞上下，澥市动虚空。","谁与同晞发，沧凉若木东。"]},{"t":"海上","f":"五言律诗","c":["海上青山好，东西耸二樵。","三秋观海日，半夜逐江潮。","宫阙金银在，仙人素手招。","何当共徐市，一去十洲遥。"]},{"t":"鹤舒台","f":"五言律诗","c":["英雄多羽化，高尚更安期。","岂乏留侯舌，差为霸者师。","登台驾玄鹤，涉海握神芝。","父老菖蒲会，千秋空尔思。"]},{"t":"从轩辕宅入迷居洞","f":"五言律诗","c":["晓起蕊珠峰，行行花影重。","林乌飞落月，山鬼啸寒钟。","野饭芝泉冽，秋衣竹翠浓。","昨宵逢道士，疑是七星松。"]},{"t":"宿金沙洞","f":"五言律诗","c":["谷口雨霏霏，樵苏向晚稀。","寒花秋尽发，孤鹤夜深归。","松定闻泉细，峰高见月微。","幽怀如有待，竟夕倚岩扉。"]},{"t":"黍珠庵晚眺","f":"五言律诗","c":["松子落纷纷，樵歌隔水闻。","秋花迷磴道，石窦出风云。","葛令笼䈡笛，麻姑蛱蝶裙。","相逢欢未尽，日暮铁桥分。"]},{"t":"自英德至浛洸道中作","f":"五言律诗","c":["一县尽奇峰，参差削玉蓉。","人烟含乱石，瀑影出寒松。","空翠飞犹湿，馀花落尚秾。","乱同樵女渡，洸口暮闻钟。"]},{"t":"舟上连州 其一","f":"五言律诗","c":["路入涟江远，愁闻是鹧鸪。","草深迷两岸，云涨似重湖。","古木撑崖坠，惊流挟石趋。","拂舟萝带乱，攀折自嬉娱。"]},{"t":"舟上连州 其二","f":"五言律诗","c":["时时川路尽，峡转复天开。","舟掠飞崖过，帆穿落木来。","鸟声多在水，人迹半生苔。","不寐因明月，宵深自溯洄。"]},{"t":"舟上连州 其三","f":"五言律诗","c":["舟小愁炎热，迟回乱石间。","眠篙双女苦，坐钓一人閒。","水响知滩至，林昏羡鸟还。","时来思用武，前路耐间关。"]},{"t":"舟上连州 其四","f":"五言律诗","c":["峰峰相角立，奇石满空中。","山雨夏多白，江霞秋更红。","鱼虾三峡异，妇女一罾同。","数舸沿明月，歌传水帝宫。"]},{"t":"舟上连州 其五","f":"五言律诗","c":["乱流争一壑，风傍水门多。","石势随云落，滩声杂雨过。","只须秋月好，终奈暮猿何。","不寐同渔父，洲边弄芰荷。"]},{"t":"舟上连州 其六","f":"五言律诗","c":["半壁划青冥，双流倒翠屏。","天从江口出，雨以峡门扃。","独夜歌山鬼，无人见野萤。","微风林外过，彷佛芷兰馨。"]},{"t":"舟上连州 其七","f":"五言律诗","c":["不妨滩石乱，溪女解篙舟。","舟似腰肢折，篙随瀑布流。","水声惊万壑，林气似三秋。","风小帆频落，沿洄未免愁。"]},{"t":"过清远诸滩","f":"五言律诗","c":["沿溯频无路，滩门雨不开。","谁从千仞壁，飞下一舟来。","天逐青峰转，人随白鸟回。","数声渔父笛，忽起望夫台。"]},{"t":"望五老峰","f":"五言律诗","c":["飞翠如烟雨，秋来山色浓。","夕阳一返照，明灭金芙蓉。","独啸此亭月，将寻何处钟。","石门精舍近，蚤晚巢云松。"]},{"t":"紫霄峰","f":"五言律诗","c":["言携青玉杖，千折上云霄。","石镜通秋月，兰泉应海潮。","窗开三楚小，帆落九江遥。","一片洪荒色，天风吹不消。"]},{"t":"开先寺楼作","f":"五言律诗","c":["向夕楼中卧，天风忽起西。","不知吹瀑水，飘落几重溪。","窗小云争入，林深雪已迷。","无人爱幽独，来共听猿啼。"]},{"t":"望钟山","f":"五言律诗","c":["一脉茅山至，苍苍烟雾浓。","神宫开六代，王气出中峰。","万古君臣始，九天楼殿重。","卧碑当辇路，春草未曾封。"]},{"t":"送客","f":"五言律诗","c":["莫上高台望，无穷是楚云。","旧游稀白发，独往易斜曛。","木落诸峰见，山空一叶闻。","祗应盘石上，閒坐对秋分。"]},{"t":"木末亭拜方正学先生像","f":"五言律诗","c":["宗臣遗像在，对越孝陵云。","周礼难为国，姬公竟负君。","龙蛇迷旷野，日月在孤坟。","莫问三杨事，忠良道各分。"]},{"t":"寄龚柴丈","f":"五言律诗","c":["我有罗浮月，长悬四百峰。","期君来玉涧，拂石听霜钟。","五色麻姑鸟，千年啸父松。","相依当岁宴，不复寄芙蓉。"]},{"t":"灵谷探梅 其一","f":"五言律诗","c":["往日园陵畔，千株间白云。","芳馨灵谷寺，灌溉羽林军。","乱点钟山翠，争衔麋鹿群。","高皇多手泽，如雪日氤氲。"]},{"t":"灵谷探梅 其二","f":"五言律诗","c":["见说钟山麓，当年万树斜。","谁将辽海雪，来折汉陵花。","冷月含边笛，阴风散暮鸦。","数枝当辇路，不忍吐瑶华。"]},{"t":"灵谷探梅 其三","f":"五言律诗","c":["几树傍朝阳，犹承日月光。","白头宫监在，攀折荐高皇。","上苑樱桃尽，华林苜蓿长。","春风空有意，先到独龙冈。"]},{"t":"吉祥寺古梅 其一","f":"五言律诗","c":["受命生南国，孤根不可移。","寒光含雨雪，元气在茅茨。","空寂无人见，芳馨祗自贻。","上林松柏尽，珍重岁寒期。"]},{"t":"吉祥寺古梅 其二","f":"五言律诗","c":["一夜东风拂，春回半死根。","瑶华答霜雪，硕果孕乾坤。","岂有山川秀，居然鸾鹤尊。","惟应招隐士，来此日攀援。"]},{"t":"吉祥寺古梅 其三","f":"五言律诗","c":["枝枝经百折，终不畏冰霜。","到地花仍发，横空影自长。","月中那可得，人外始闻香。","夜夜难为寐，因君拂石床。"]},{"t":"吉祥寺古梅 其四","f":"五言律诗","c":["山中长自傲，不愧此寒饥。","冰雪归玄鬓，乾坤寄缟衣。","朝随晴日放，暮作白云飞。","一自冥心坐，闻香每发机。"]},{"t":"吉祥寺古梅 其五","f":"五言律诗","c":["白云开半树，香已遍晴春。","明月曾无夜，空山岂有人。","风惊飞瀑断，雪洒落花匀。","坐久石床暖，氤氲一气新。"]},{"t":"福兴山中古梅 其一","f":"五言律诗","c":["念是先朝物，风雷不忍侵。","桐焦空有尾，竹老已空心。","以道酬泉石，无言阅古今。","几宵明月上，为子动瑶琴。"]},{"t":"福兴山中古梅 其二","f":"五言律诗","c":["一花开混沌，静者最先知。","雪满空山夜，云生绝壁时。","幽光溪四照，素影鹤相持。","辛苦传春信，阴风莫太吹。"]},{"t":"紫峰阁梅 其一","f":"五言律诗","c":["绝壑春难早，鸿濛养有馀。","光生无月处，香在未花初。","入石僧同定，横溪客自疏。","年年紫峰阁，为尔一踟蹰。"]},{"t":"紫峰阁梅 其二","f":"五言律诗","c":["夜夜空林里，相看冻不归。","坐残千嶂雪，添尽五更衣。","结侣如园绮，为餐当蕨薇。","无人爱幽独，于此共忘机。"]},{"t":"燕京述哀 其一","f":"五言律诗","c":["先帝宵衣久，忧勤为万方。","捐躯酬赤子，披发见高皇。","风雨迷神驭，山河尽国殇。","御袍留血诏，哀痛几时忘。"]},{"t":"燕京述哀 其二","f":"五言律诗","c":["谁使黄巾乱，乾坤满战尘。","寇雠原赤子，将帅半清人。","抚字无良策，诛求损至仁。","君王频罪己，钟鼓不遑陈。"]},{"t":"燕京述哀 其三","f":"五言律诗","c":["无端招抚策，群盗藐王师。","一自潼关失，频令紫极移。","至尊催战急，司马督兵迟。","可惜舆尸拙，三军食尽时。"]},{"t":"燕京述哀 其四","f":"五言律诗","c":["求言空下诏，谁解圣明忧。","隔岁降章去，当关内使留。","恩威俱致乱，臣庶不同仇。","草野惭无补，终身涕泗流。"]},{"t":"燕京述哀 其五","f":"五言律诗","c":["万岁山前树，无春到澥棠。","宫云空漠漠，沟水自泱泱。","天地馀蒿里，龙蛇有白杨。","陇西鹦鹉在，何处问君王。"]},{"t":"燕京述哀 其六","f":"五言律诗","c":["阴雨煤山树，君臣各一枝。","内城吹角急，前殿击钟迟。","玉辇迁无路，珠丘筑几时。","可怜燕父老，弓剑至今悲。"]},{"t":"燕京述哀 其七","f":"五言律诗","c":["岁岁逢寒食，西山哭圣明。","股肱无稷契，涕泪有皇英。","涿鹿何曾战，髯龙不下迎。","凄凉阊阖外，落日动边声。"]},{"t":"恶少","f":"五言律诗","c":["长箭短刀鋋，幽并恶少年。","马头悬落日，鹰眼射高天。","并饮桃花店，齐弹白纻弦。","胡姬量酒罢，调笑索金钱。"]},{"t":"朵颜","f":"五言律诗","c":["朵颜西部落，屯牧黑河滨。","吹角呼山鹿，弯弓向路人。","马肥燕地草，裘拂蓟关尘。","欲共裨王去，江南踏好春。"]},{"t":"宝勒","f":"五言律诗","c":["宝勒五花骢，骄嘶天育东。","久辞关塞雪，共舞绮罗风。","金埒沙尘细，春槽苜蓿红。","只愁安乐后，无力逐英雄。"]},{"t":"沙河 其一","f":"五言律诗","c":["湿馀诸水落，南北作沙河。","夹岸离宫起，飞桥御辇过。","巩华天险在，威漠羽林多。","此日馀烟树，徘徊奈夕何。"]},{"t":"沙河 其二","f":"五言律诗","c":["汉帝朝陵日，沙河驻翠銮。","宸楼春水上，玉几白云端。","重镇军都拥，长城下口盘。","自天来叠嶂，龙虎万年安。"]},{"t":"沙河 其三","f":"五言律诗","c":["展思宫殿在，创自肃皇年。","列圣焄蒿色，诸陵松柏烟。","黄花通御气，紫塞振长鞭。","一路金汤固，真人自守边。"]},{"t":"沙河 其四","f":"五言律诗","c":["三宫悬大漠，九塞扼居庸。","羽卫何曾战，丸泥本可封。","诸珰争揖盗，万国失从龙。","辇路沙河曲，萋萋烟草浓。"]},{"t":"昌平道中 其一","f":"五言律诗","c":["落日昌平道，愁从关塞归。","九门吹画角，万户捣寒衣。","伏草黄狐啸，衔芦白雁飞。","朝宗桥下水，呜咽出金微。"]},{"t":"昌平道中 其二","f":"五言律诗","c":["可怜陵寝地，千里草离离。","二水沙河在，双桥御道移。","水泉边马识，风候野驼知。","亦有城头月，苍苍似汉时。"]},{"t":"天寿山 其一","f":"五言律诗","c":["燕山连紫塞，千里抱长安。","北锁天关险，东襟渤澥寒。","龙文犹五色，凤势必千盘。","寂寞裬恩殿，孤臣掩泪看。"]},{"t":"天寿山 其二","f":"五言律诗","c":["文皇当正脉，列圣绕中峰。","地作诸华福，山为五岳宗。","东西金殿起，左右宝城重。","云气如宫阙，高高护六龙。"]},{"t":"天寿山 其三","f":"五言律诗","c":["岂意千秋后，空馀龙凤门。","白狐登御榻，青犊入文园。","玉砌磨刀坏，银泉浴铁浑。","雍门无限泪，沾洒列朝恩。"]},{"t":"天寿山 其四","f":"五言律诗","c":["万壑松楸尽，园陵锁寂寥。","空馀龙虎抱，似有鬼神朝。","银海阴风落，珠尘细雨飘。","天南霜露思，极望草萧萧。"]},{"t":"天寿山 其五","f":"五言律诗","c":["辇道哀湍激，神楼晚日悬。","九龙无彷佛，群鹤尚联翩。","玉盌沦秋草，珠帘落暮烟。","白头宫监在，相对泪潸然。"]},{"t":"天寿山 其六","f":"五言律诗","c":["北极钩陈出，西山寝殿移。","香炉销兽火，宝帐挂蛛丝。","山枕黄花戍，泉通太液池。","守陵馀几户，犹是羽林儿。"]},{"t":"天寿山 其七","f":"五言律诗","c":["夹道云龙柱，横空日月楼。","金波鳷鹊动，玉气白虹浮。","命可中华永，功为万古谋。","丰碑无一字，瞻仰泪频流。"]},{"t":"天寿山 其八","f":"五言律诗","c":["十道穿桥水，千林拂殿枝。","飞腾神马在，兴废石人知。","盗火烧香峪，妖云压玉墀。","边墙虚内外，无计护罘罳。"]},{"t":"天寿山 其九","f":"五言律诗","c":["二井东西在，诸妃墓未崩。","国朝稀殉葬，宫女少陪陵。","雨为斑泪滴，云似綵衣凝。","终古闻瑶瑟，凄凄怨不胜。"]},{"t":"天寿山 其十","f":"五言律诗","c":["陵冢纷相望，先皇骨肉留。","小王陪玉匣，贵主接珠丘。","衔石瑶姬恨，吹笙子晋愁。","白杨风飒飒，谁与奠清秋。"]},{"t":"银钱山 其一","f":"五言律诗","c":["银钱苍翠里，先帝有攒宫。","衰草萦金缕，高天堕宝弓。","辽阳来猎火，秦地起悲风。","心共桑乾水，千秋绕汉宫。"]},{"t":"银钱山 其二","f":"五言律诗","c":["不及东西井，峨峨享殿开。","单于封树去，故老岁时来。","万古啼乌怨，三秋落木哀。","中涓陪玉匣，谁奠白蘋杯。"]},{"t":"银钱山 其三","f":"五言律诗","c":["渴葬春秋恨，干戈礼未成。","一抔秋草满，万里朔云平。","白日沉蒿里，青山断宝城。","微臣有兰杜，何处荐皇英。"]},{"t":"金山","f":"五言律诗","c":["路入金山口，丰碑野火焚。","苔侵香水院，潭起黑龙云。","岳势当燕去，河流入塞分。","行人多再拜，天下大师坟。"]},{"t":"居庸 其一","f":"五言律诗","c":["险绝太行北，居庸第八陉。","长城横塞白，叠嶂逼天青。","未可凭飞将，何当弃大宁。","宣辽中路断，此地岂藩屏。"]},{"t":"居庸 其二","f":"五言律诗","c":["崖石争盘束，羊肠不可攀。","塔留番字古，城设汉军閒。","小作弹琴峡，微开纳款关。","中华无锁钥，辜负万重山。"]},{"t":"居庸 其三","f":"五言律诗","c":["岭出居庸上，窥关若井中。","水声千尺落，林响万山同。","地许孤城扼，天教一骑通。","悲风吹不尽，战血染沙红。"]},{"t":"居庸 其四","f":"五言律诗","c":["北口连南口，双峰壁立多。","峡山迷一线，陉水阻重河。","间道松林在，潜军半夜过。","繇来天险地，容易倒前戈。"]},{"t":"岔道","f":"五言律诗","c":["八达资屏障，秋来鼓角雄。","上都西路出，延庆北门通。","马渴衔冰乱，狼惊入草空。","宣宗游猎地，不与四楼同。"]},{"t":"龙虎台","f":"五言律诗","c":["汉帝亲征日，扬威龙虎台。","翠华回朔漠，天寿起蓬莱。","太液桑乾接，佳城玉带开。","万年宫树在，鸾鹤尚飞来。"]},{"t":"八达岭","f":"五言律诗","c":["俯视神京尽，居庸若建瓴。","出关愁草白，入塞喜山青。","千帐牛羊绕，诸陵雨雪扃。","元人南北口，此岭作藩屏。"]},{"t":"宣府作 其一","f":"五言律诗","c":["往日多游幸，云州作帝家。","离宫临雁塞，御气绕龙沙。","青接明妃草，香传萧后花。","羽林军散后，凄切任吹笳。"]},{"t":"宣府作 其二","f":"五言律诗","c":["辽后多遗迹，人怜避暑宫。","塞花明宝靥，边月满雕弓。","二水桑乾合，三云大漠通。","花园经上下，歌管慰飘蓬。"]},{"t":"乌金","f":"五言律诗","c":["乌金营里市，马乳点茶香。","汉女烧银鼠，蕃儿跨大羊。","红颜如粪土，白骨作垣墙。","向晚吹芦管，乌乌断客肠。"]},{"t":"云州秋望 其二","f":"五言律诗","c":["八月大同秋，霜花满客裘。","身随宛马壮，手以角弓柔。","水胍驼能识，边声雁亦愁。","纷纷风柳落，吹入望乡楼。"]},{"t":"茶窝口","f":"五言律诗","c":["紫荆离十里，此处券门开。","高垒资人去，重河拒马来。","冰霜秋栗烈，砧杵暮凄哀。","渐近悲歌地，风吹易水回。"]},{"t":"寒食","f":"五言律诗","c":["萧条寒食节，蒿里草茫茫。","岁月添黄土，英雄聚白杨。","报仇寻豫让，驱马渡清漳。","辛苦邯郸子，从今老战场。"]},{"t":"邯郸道中","f":"五言律诗","c":["叹息丛台下，英雄日寂寥。","战场无白日，旷野一秋雕。","草没廉颇宅，云迷豫让桥。","悲歌谁与和，归思晚萧萧。"]},{"t":"信部","f":"五言律诗","c":["歇马风门望，襄州秋色开。","太行盘钜鹿，漳水绕邢台。","闾里聊为侠，皇天不爱才。","当时赵几霸，谁继武安来。"]},{"t":"边词 其一","f":"五言律诗","c":["边郡今无事，风吹杀气过。","鼓鼙沉上谷，烽火断交河。","子女穹庐入，金珠大马驮。","蒙恬城下骨，夜夜听笙歌。"]},{"t":"边词 其二","f":"五言律诗","c":["草长迷青冢，冰消见白台。","汉儿吹角去，羌女打毬来。","牙帐山山卓，雕旗处处开。","诸王分六角，会猎向龙堆。"]},{"t":"边词 其三","f":"五言律诗","c":["暮冬寒凛洌，出口唾成冰。","肌肉愁风割，胡髯苦雪凝。","边声吞鼓角，战火接园陵。","向夕庵庐宿，凄然泪满膺。"]},{"t":"边词 其四","f":"五言律诗","c":["积冰千万里，北极是寒门。","八月黄榆尽，三春白草繁。","无衣凭戍火，不守惜边垣。","处处开横帐，笳声梦里喧。"]},{"t":"边词 其五","f":"五言律诗","c":["黑峪无人迹，天寒鸟兽饥。","冰残狐不渡，雨暗雁犹飞。","破屋馀烟火，孤城隔翠微。","迢遥西澥子，时见猎人归。"]},{"t":"边词 其六","f":"五言律诗","c":["鹰隼秋轻疾，风霜激羽毛。","逐禽千里远，卓马万山高。","雁膳餐偏饱，驼封卧不牢。","胪朐河畔月，夜影恋征袍。"]},{"t":"边词 其七","f":"五言律诗","c":["弓马疾如飞，将军秋打围。","狼头悬大纛，蟒锦制戎衣。","犯雪过疏勒，冲风下武威。","归来献王子，獐兔尽鲜肥。"]},{"t":"边词 其八","f":"五言律诗","c":["日幕归千骑，骄嘶靺鞨风。","卢沟衰草外，督亢乱云中。","鞍上齐倾酒，营前各祭弓。","誇称小郎主，射得一黄熊。"]},{"t":"边词 其九","f":"五言律诗","c":["伊昔临洮战，几擒吐谷浑。","将军频失道，天子不垂恩。","豺虎无声过，城池几处存。","空馀青海月，长照黑山魂。"]},{"t":"边词 其十","f":"五言律诗","c":["落日在龙城，羌儿向柳营。","弯弓窥汉月，吹笛作秦声。","天似穹庐覆，风从班马生。","当年霍骠骑，一剑此横行。"]},{"t":"边词 其十一","f":"五言律诗","c":["渴饮家驼乳，寒披野马裘。","书生贪射虎，战士喜椎牛。","风动河冰裂，烟含塞日愁。","但令扫雠耻，不必取通侯。"]},{"t":"边词 其十二","f":"五言律诗","c":["夜夜眠庐帐，朝朝控橐驼。","边沙尝似雪，塞水忽成河。","战士黄羊饭，筝人白马驮。","威名想蓝玉，铁券勒功多。"]},{"t":"吴门逢京兆杜子赋赠 其一","f":"五言律诗","c":["我爱秦风劲，无衣不自谋。","美人居板屋，女子解戎辀。","岳走三峰势，河吞八水流。","君从关内至，意气正横秋。"]},{"t":"吴门逢京兆杜子赋赠 其二","f":"五言律诗","c":["姑苏秋月夜，歌舞乱如云。","我亦吹箫至，吴王不可闻。","徘徊金虎迹，想像水犀军。","泉下三千剑，光芒尽在君。"]},{"t":"同杜子入秦初发滁阳作","f":"五言律诗","c":["天晓滁阳望，苍茫大野开。","风威肃人马，烟色惨墩台。","慷慨无衣赋，艰虞不世才。","平生一匕首，为子入秦来。"]},{"t":"中都 其一","f":"五言律诗","c":["王迹兴闾巷，天威奋布衣。","三章开草昧，一战扫金微。","城阙中都在，人民奕世非。","谁令原庙树，零落向斜晖。"]},{"t":"中都 其二","f":"五言律诗","c":["高皇汤沐色，浩荡楚天开。","南北风云会，春秋玉帛来。","灵旗龙陟降，王气凤盘回。","根本岐丰旧，还期辟草莱。"]},{"t":"凤阳 其一","f":"五言律诗","c":["神阜是凤阳，瓜瓞接天长。","仁祖勤耕稼，文孙肃禘尝。","涂山盘寝殿，淮水入宫墙。","白首哀遗老，依依陵树旁。"]},{"t":"凤阳 其二","f":"五言律诗","c":["地插群峰翠，天垂四野青。","皇基犹气象，帝宅自精灵。","禾黍侵周道，貂蝉壤汉庭。","卧碑谁与守，臣仆日凋零。"]},{"t":"具茨","f":"五言律诗","c":["帝受神芝箓，天开大隗宫。","白云迷七圣，黄盖导双童。","有象成金鼎，无为合上穹。","龙颜如皦日，瞻望具茨东。"]},{"t":"硖石道中","f":"五言律诗","c":["天险雒阳西，临关万岭低。","冰坚人马滑，云暗驿楼迷。","竦石频当谷，飞梁忽接溪。","几家陶穴住，烟火暮凄凄。"]},{"t":"阌乡道中呈杜子","f":"五言律诗","c":["中条高积雪，太华远横云。","初日光相乱，芙蓉望不分。","冰开河艇过，风起岳钟闻。","明日苍龙岭，攀跻定与君。"]},{"t":"登潼关怀远楼","f":"五言律诗","c":["山挟洪河走，关临隘地开。","八州高仰屋，三辅迥当台。","戍晚栖乌乱，城秋班马哀。","茫茫王霸业，抚剑独徘徊。"]},{"t":"西岳祠","f":"五言律诗","c":["地引黄河带，天垂太华旒。","威灵扬白帝，肃杀散高秋。","钟鼓存仙殿，云霞拜岳楼。","凭将巨灵掌，万古荡皇州。"]},{"t":"桃林坪","f":"五言律诗","c":["窈窕桃林峡，天如匹练垂。","石门人独入，谷口马难窥。","拂席飞泉湿，衔杯白日移。","神仙亦尘垢，半壁玉棺遗。"]},{"t":"车箱潭","f":"五言律诗","c":["潭水车箱满，潺湲春雨馀。","上临毛女洞，中有渭川鱼。","龙戛铜盘响，人临水府居。","先朝遗玉简，灵气发芙蕖。"]},{"t":"云台峰","f":"五言律诗","c":["闻道黄河底，云台一穴通。","水帘横洞口，天井出空中。","一接苍龙脉，双开白帝宫。","三峰南咫尺，青翠更濛濛。"]},{"t":"历千尺峡百尺峡诸崄至岳顶 其一","f":"五言律诗","c":["临崖垂半足，飞上岳莲端。","玉井窥天小，蒲池弄月寒。","白云吞万象，瀑水泻千盘。","左右石楼敞，吾将寄羽翰。"]},{"t":"历千尺峡百尺峡诸崄至岳顶 其二","f":"五言律诗","c":["飞梯何袅袅，千仞翠微边。","路滑愁春雪，身轻堕紫烟。","峡中稀见日，花里屡逢泉。","早晚携妻子，同餐玉井莲。"]},{"t":"青牛台访彭荆山","f":"五言律诗","c":["谁凿芙蓉翠，飞楼架此峰。","千山围落雁，一脉度苍龙。","日射黄河雪，天摇白帝钟。","王孙游不返，此地种长松。"]},{"t":"大雪西峰作","f":"五言律诗","c":["三峰莲皎皎，万壑雪濛濛。","玉女花频散，仙人雾欲空。","光摇高掌月，声乱紫霄风。","天地茫茫失，骖鸾路未通。"]},{"t":"渭川","f":"五言律诗","c":["渭源从鸟鼠，东走向黄河。","势到潼关大，膏流沃野多。","双桥像牛女，七水汇风波。","往日皇威震，呼韩缓辔过。"]},{"t":"三原人日作","f":"五言律诗","c":["春水流澌满，双渠接瓠中。","桥横清峪阔，城倚仲山雄。","游女骄人日，新妆俨汉宫。","藏梅犹冻雪，著柳已光风。"]},{"t":"初至雁门赠陈祺公使君 其一","f":"五言律诗","c":["雁门雄九塞，句注壮三云。","开拓灵王业，驱除李牧勋。","汉兵天上戍，羌笛月中闻。","锁钥今公赖，威名回冠军。"]},{"t":"初至雁门赠陈祺公使君 其二","f":"五言律诗","c":["武安方略在，烽鼓坐来消。","犄角三关壮，凭陵万里骄。","铙歌开乐府，羽猎会嫖姚。","惨淡黄云外，天盘八月鹞。"]},{"t":"陪陈使君游雁门山水 其一","f":"五言律诗","c":["斗绝开双阙，浮云莫与齐。","一夫当贾屋，干骑阻磨笄。","白草龙沙阔，黄天雁塔低。","使君多古意，秋爽共攀跻。"]},{"t":"陪陈使君游雁门山水 其二","f":"五言律诗","c":["派水重陉出，愁人独漉过。","流离辞广武，呜咽入滹沱。","欲把浮萍寄，其如饮马多。","王公爱行潦，明信愿无他。"]},{"t":"送田丈自代返秦将登华岳 其一","f":"五言律诗","c":["艰难随雨雪，边马急归心。","赵塞辞句注，秦关向华阴。","晴开天井阁，夜听羽人琴。","两戒河山首，无令壮志侵。"]},{"t":"送田丈自代返秦将登华岳 其二","f":"五言律诗","c":["春阴连朔漠，白日惨无多。","喜别楼烦道，愁听敕勒歌。","东峰襟玉女，西瀑泻黄河。","最忆神灵岳，期君扫薜萝。"]},{"t":"繁峙道中赠赵侯苍篆","f":"五言律诗","c":["三泉从太戏，西下作滹沱。","白日秋来少，黄云战后多。","弯弓随大猎，扣剑和清歌。","回首人烟里，城楼接二峨。"]},{"t":"闻雁","f":"五言律诗","c":["雁门无数雁，一夜尽南飞。","我忆罗浮暖，难将雨雪违。","愁来弄羌笛，梦里著莱衣。","明岁梅花发，乡园归未归。"]},{"t":"岁暮送李天生出雁门","f":"五言律诗","c":["雄关高柳北，鸿雁出其中。","天井开句注，长城接大同。","青苔馀战骨，白草失离宫。","岁暮多风雪，愁君一转蓬。"]},{"t":"答天生","f":"五言律诗","c":["蒲柳先秋落，河山异代倾。","报恩无剑术，乞食有箫声。","海鹤双栖少，边雕自猎轻。","君怜慈母在，高义赠生平。"]},{"t":"述婚 其一","f":"五言律诗","c":["岂意飘萍客，天涯得好仇。","佳期牛女夕，独立凤凰楼。","玉帛迎秦塞，笙歌入代州。","威仪应敬尔，拜手荷天休。"]},{"t":"述婚 其二","f":"五言律诗","c":["三星光邂逅，揽执合欢襦。","天使朱弦续，人怜蕙草苏。","鹿车归故里，鱼鲙奉慈姑。","万里成婚媾，恩情良独殊。"]},{"t":"述婚 其三","f":"五言律诗","c":["慈闱黄鹄苦，子舍白华贫。","菽水凭诸弟，关山隔一春。","乱离鸡在国，高尚亦依人。","庑下须裘褐，相将作隐沦。"]},{"t":"述婚 其四","f":"五言律诗","c":["霸陵能共隐，不复慕姬姜。","乐我惟綦缟，娱亲在酒浆。","心悬珠海月，泪洒雁门霜。","愿作双鸿鹄，南飞返故乡。"]},{"t":"初春代州作","f":"五言律诗","c":["二峪冰犹壮，三关草欲薰。","积阴开白日，春色散黄云。","帐小争人合，沙平猎马分。","武皇诸乐府，遗响在罗裙。"]},{"t":"广昌","f":"五言律诗","c":["此地蜚狐塞，神京一线通。","长城带天末，古戍接云中。","马踏三秋雪，鹰吟万里风。","河流声太苦，应为客途穷。"]},{"t":"浮图峪","f":"五言律诗","c":["石路飞狐入，天梯束马过。","峰头千仞堞，峪口两重河。","榆柳新秋少，牛羊落日多。","往时高杀气，诸将此横戈。"]},{"t":"紫荆关","f":"五言律诗","c":["天半旗台起，霞连落日黄。","山开关路小，河绕塞垣长。","蹴鞠将军戏，酡酥上客觞。","夜来笳鼓动，凄切助思乡。"]},{"t":"大同旅次","f":"五言律诗","c":["独宿天难曙，孤征日易曛。","梦魂青冢月，涕泪白登云。","书断随阳雁，笳连守冻军。","代王宫咫尺，砧杵更愁闻。"]},{"t":"边夜","f":"五言律诗","c":["万古明妃月，光含汉苑愁。","吹来龙塞影，散作雁门秋。","白露沾衣湿，天河接泪流。","南飞鸿雁尽，何处寄离忧。"]},{"t":"已恨","f":"五言律诗","c":["已恨关山阔，还愁鼓角悲。","家贫难在外，年长易伤离。","弟妹农桑苦，园林雨雪迟。","梦中见慈母，白发总如丝。"]},{"t":"代州夏日冯方伯招饮故大司马白谷孙公园亭即席赋 其一","f":"五言律诗","c":["何以炎洲翠，而辞大庾梅。","因君有琼树，故拂羽仪来。","峨口朝霞起，圭峰暮雨开。","殷勤赋公宴，持以答金罍。"]},{"t":"代州夏日冯方伯招饮故大司马白谷孙公园亭即席赋 其二","f":"五言律诗","c":["当年大司马，手植此蒲莲。","池引滹沱水，堂开紫府烟。","沙场功不遂，薤露恨空传。","苔径馀行迹，劳君拂绮钱。"]},{"t":"代州夏日冯方伯招饮故大司马白谷孙公园亭即席赋 其三","f":"五言律诗","c":["昔同浣纱女，弄楫太湖亭。","南北穿莲叶，东西入洞庭。","何期句注塞，亦有采香泾。","无数芙蓉发，山光映水青。"]},{"t":"雁门","f":"五言律诗","c":["雁门十八隘，天欲界华夷。","主父长城在，蒙恬古戍移。","雄图归竖子，王气走燕支。","万古扶苏谷，泉声尚恨斯。"]},{"t":"再送天生携家自代返秦 其一","f":"五言律诗","c":["他夕高堂乐，倾觞河汉边。","天教儿女月，长在掌中圆。","花萼连韦曲，田园傍渭川。","从今衣带缓，宴会复何年。"]},{"t":"再送天生携家自代返秦 其二","f":"五言律诗","c":["祝牧思偕隐，行行负戴难。","青霞悲自郁，白首畏人看。","朔雪先花发，炎风到海寒。","鸡鸣频送尔，带梦上征鞍。"]},{"t":"再送天生携家自代返秦 其三","f":"五言律诗","c":["招摇直双华，河伯汇三秦。","泰时神明地，宗周礼乐人。","霞流明月满，露浣白华新。","不共千秋业，离居惜此晨。"]},{"t":"平城","f":"五言律诗","c":["往日平城困，阏氏畏汉威。","三军方彀弩，一角忽开围。","娘子城犹在，陈平计不非。","只今频月晕，谁复救龙旂。"]},{"t":"将从雁代返岭南留别程周量 其一","f":"五言律诗","c":["汉垒悬高柳，胡门控太行。","三年愁出塞，万里梦还乡。","马陷浑河雪，裘沾白草霜。","无才营菽水，萧杀一行装。"]},{"t":"将从雁代返岭南留别程周量 其二","f":"五言律诗","c":["太华当秦阙，终南作汉标。","图书藏玉井，儿女下青霄。","信美非桑梓，言归逐海潮。","三闾元隐士，费尔小山招。"]},{"t":"将从雁代返岭南留别程周量 其三","f":"五言律诗","c":["高高峨口月，万里照边愁。","白雁衔霜信，明河挂戍楼。","庭闱南海隔，井臼朔天留。","去住难为计，悲歌历九秋。"]},{"t":"将从雁代返岭南留别程周量 其四","f":"五言律诗","c":["流落真无计，依人古所难。","自怜因老母，不敢谢长安。","骨肉归相保，关山去正寒。","劳君治行李，歧路泣相看。"]},{"t":"将从雁代返岭南留别程周量 其五","f":"五言律诗","c":["岂少簪缨客，无如桑梓情。","相依期白首，此别见平生。","孝友惭诸弟，诗歌慕两京。","才华竟何益，早去事躬耕。"]},{"t":"将从雁代返岭南留别程周量 其六","f":"五言律诗","c":["炎洲山水好，秀色满烟霄。","与子为兄弟，东西若二樵。","相怜皆翡翠，自媚一兰苕。","此日京华隔，予行秋泬寥。"]},{"t":"将从雁代返岭南留别程周量 其七","f":"五言律诗","c":["声诗满京国，大雅似君稀。","不有黄钟奏，谁知白纻非。","先公多乐府，西汉一音徽。","更作离骚传，佳人志不违。"]},{"t":"将从雁代返岭南留别程周量 其八","f":"五言律诗","c":["罗浮双岳峙，一半是蓬莱。","风雨时离合，波潮若往回。","宁无蝴蝶洞，不及凤凰台。","文献曲江后，须君接武来。"]},{"t":"答王阮亭","f":"五言律诗","c":["朝攀枫树吟，暮拂洞庭琴。","楚客元多怨，淮王最赏音。","先臣有芳草，移植罗浮阴。","采撷沾行露，凭将答所钦。"]},{"t":"答锡鬯","f":"五言律诗","c":["白日今谁照，途穷总苦辛。","乱离难自食，高尚易违亲。","水咽扶苏谷，花悬紫塞尘。","凄凄知己泪，千载一沾巾。"]},{"t":"马上","f":"五言律诗","c":["马上听横吹，征夫心最悲。","边云多惨淡，陇水易流离。","翠嶂盘陵邑，浑河绕岳祠。","时艰思用武，未忍采华芝。"]},{"t":"望田子","f":"五言律诗","c":["天寒宜射猎，君向大同川。","紫兔悬鞍后，银筝在马前。","沙城迷积雪，岳树出晴烟。","日暮行人尽，关门待玉鞭。"]},{"t":"赠楚客","f":"五言律诗","c":["声诗江汉始，莫谓楚无风。","我祖离骚赋，人称小雅同。","明珠贻下女，香草惠童蒙。","之子荆南起，还将乐府工。"]},{"t":"赠别颜修来 其一","f":"五言律诗","c":["斗柄垂双华，龙门控大河。","精灵从此得，哀乐向来过。","白帝开珠阙，苍龙引玉珂。","登临吾与汝，万古一高歌。"]},{"t":"赠别颜修来 其二","f":"五言律诗","c":["我忆炎洲好，乘秋返故乡。","鹧鸪长向日，桂树不惊霜。","别酒愁燕市，征车苦太行。","青云君已达，应自惜圭璋。"]},{"t":"同陈子游五台作 其一","f":"五言律诗","c":["公子追康乐，名山挟少文。","觞浮二峨水，马蹴五台云。","北岳连阴翠，黄沙似夕曛。","酒酣能射虎，不必李将军。"]},{"t":"同陈子游五台作 其二","f":"五言律诗","c":["并骑登岩岫，行行红叶深。","五峰秋积雪，双瀑日穿林。","孤鹤先知曙，神龙善处阴。","先朝钟鼓在，草莽最惊心。"]},{"t":"同陈子游五台作 其三","f":"五言律诗","c":["雪杂山花落，随风入翠微。","冰崖愁马滑，霞壁羡猿飞。","高尚何曾得，佯狂亦觉非。","林泉殊可住，无奈隔庭闱。"]},{"t":"答杜子","f":"五言律诗","c":["万里高堂月，光从涨海来。","衣裘军幕冷，笳管戍楼哀。","高举思黄鹄，娇歌厌落梅。","音书频报尔，秋别白登台。"]},{"t":"武安君庙","f":"五言律诗","c":["往日多奇阵，飞扬教射夫。","守真如处女，出即扫林胡。","伏腊三关泪，兼并百战图。","代州祠畔月，英爽飒虚无。"]},{"t":"唐晋王祠墓 其一","f":"五言律诗","c":["代北威名著，飞扬射马鞭。","长安回帝驾，天祐纪臣年。","三矢山河启，千秋俎豆悬。","从来赐姓者，独有晋王贤。"]},{"t":"唐晋王祠墓 其二","f":"五言律诗","c":["发愤收京阙，当时节度无。","奸雄纷割据，父子一征诛。","辇路迷秋草，陵门怨夜乌。","三垂冈上泪，老去惜雄图。"]},{"t":"唐晋王祠墓 其三","f":"五言律诗","c":["何代丹青妙，雄姿动武皇。","精灵犹白日，弓剑已秋霜。","石马嘶风急，沙河绕塞长。","应州金凤井，霸气共苍苍。"]},{"t":"九日","f":"五言律诗","c":["西风吹白雁，天半落秋声。","感此无衣客，登高赋不成。","并门横大漠，涞水绕长城。","惜别那能醉，樽中酒自清。"]},{"t":"赠故将军","f":"五言律诗","c":["无事客辽西，名王共角抵。","飞腾空射虎，汗血枉成泥。","苏武犹生子，要离已衅妻。","无繇持报汉，愁向朔云啼。"]},{"t":"晋祠 其一","f":"五言律诗","c":["风雷缠一水，松柏贯双溪。","注向横汾北，来从悬瓮西。","霸图烟漠漠，王迹草萋萋。","蟋蟀催迟暮，王孙思欲迷。"]},{"t":"晋祠 其二","f":"五言律诗","c":["一水称难老，交流出晋阳。","东西穿古柏，左右结飞梁。","报祀追桐叶，雍容见衮裳。","金沙不可拾，月照一苍苍。"]},{"t":"平刑 其一","f":"五言律诗","c":["全晋咽喉地，城横万叠山。","西屏句注塞，东控紫荆关。","砧杵三秋急，旌旗一代閒。","天心元朔漠，临眺且开颜。"]},{"t":"平刑 其二","f":"五言律诗","c":["塞垣寒太早，裘马凛秋分。","山雪争初日，河冰乱白云。","一关天上度，双角月中闻。","故国南归好，无因逐雁群。"]},{"t":"武灵王墓","f":"五言律诗","c":["威灵传主父，四战霸山东。","六国朱旗却，三胡紫塞空。","沙丘留大冢，夏屋失离宫。","长技开中国，谁思骑射功。"]},{"t":"送田子之应州","f":"五言律诗","c":["桑浑二水合，缭绕塔儿城。","知远基王迹，沙陀起义兵。","黄风吹日落，白草与天平。","太守君知己，诗应奋夏声。"]},{"t":"代州冯氏园亭赋呈主人杨冯甥舅 其一","f":"五言律诗","c":["叠嶂纷苍翠，随云渡水来。","芙蕖方伯沼，杨柳尚书台。","试马分金埒，流莺送玉杯。","主人挟丝管，更欲画船开。"]},{"t":"代州冯氏园亭赋呈主人杨冯甥舅 其二","f":"五言律诗","c":["花飞棋局乱，月出射堂高。","易饮兰英酒，难酬金错刀。","荒淫三楚秀，游侠五陵豪。","万里成欢宴，笙歌莫告劳。"]},{"t":"代州冯氏园亭赋呈主人杨冯甥舅 其三","f":"五言律诗","c":["雁门旌节罢，宾客少逢迎。","之子连甥舅，诸侯托友生。","依人意气尽，失路羽毛轻。","慷慨抚长剑，知君亦不平。"]},{"t":"代州冯氏园亭赋呈主人杨冯甥舅 其四","f":"五言律诗","c":["江南少鸿雁，塞北足鸳鸯。","送老凭歌管，违亲为稻粱。","云含阴馆尽，城与朔天长。","与子将分手，谁堪此战场。"]},{"t":"夏日清宴堂小集","f":"五言律诗","c":["高馆清和候，披襟化气薰。","菲菲怜细草，黠黠望重云。","捉麈谈秋水，衔觞待夕曛。","边庭人事少，游戏莫离群。"]},{"t":"送汪生","f":"五言律诗","c":["北纪山河曲，中都雨雪边。","客来秋屡晏，人去月空圆。","梦绕三关道，愁连万里天。","离亭频折柳，送尔更凄然。"]},{"t":"代昭生朔州客邸作","f":"五言律诗","c":["坐见星河落，思乡寐不成。","边风吹鬓尽，朔酒带愁倾。","五岳非予志，双鬟送此生。","皇天憎管乐，已矣罢经营。"]},{"t":"保定重别陈少参 其一","f":"五言律诗","c":["去尽雁门客，无依馀片云。","往时托琼树，鸾鹤共纷纷。","幕府虚秋宪，滹沱但夕曛。","何当逐旌节，重向朔方军。"]},{"t":"保定重别陈少参 其二","f":"五言律诗","c":["三年求菽水，流落向人看。","膂力风尘尽，衣裘雨雪寒。","非君重骚赋，之子枉游盘。","挥手此为别，依然行路难。"]},{"t":"保定重别陈少参 其三","f":"五言律诗","c":["返顾同黄鹄，将分恋玉杯。","泪从今日堕，愁自故乡来。","夫子且丝竹，中原尚草莱。","梦中如识路，应向谢公台。"]},{"t":"将游五台宿繁峙客舍作","f":"五言律诗","c":["文殊声色里，何处问仙灵。","风涌滹沱壮，云含太戏青。","浮生悲过雁，薄俗贱飘萍。","不寐怀明发，疏钟起塞亭。"]},{"t":"答李孔德","f":"五言律诗","c":["浮云久失所，空忆洞庭阴。","一叶惊秋早，微霜点鬓深。","感甄劳玉枕，要列费清琴。","君惠招辞好，魂归枫树林。"]},{"t":"留别陈正子","f":"五言律诗","c":["塞北罢游猎，江南思采莲。","高堂有书札，久废东皋田。","别尔渔阳路，愁悬鸿雁边。","临觞可无赠，只此白华篇。"]},{"t":"送麦生","f":"五言律诗","c":["人生故乡好，亲戚使情多。","常叹远游者，无如山水何。","君归毕婚嫁，莫即浮沧波。","往日陶彭泽，田园事匪他。"]},{"t":"九日集陈大夫署中","f":"五言律诗","c":["落叶将蝉去，浮云逐雁来。","可怜出塞客，不上望乡台。","贾屋悬歌席，滹沱泻酒杯。","佳晨同戏马，聊倚宋公才。"]},{"t":"赠李武曾灌园","f":"五言律诗","c":["平生慕农圃，之子在丘园。","为母艺花竹，岁寒无与言。","人烟不出谷，古木自成村。","兄弟桔槔举，一溪流到门。"]},{"t":"真定道中 其一","f":"五言律诗","c":["秋色晚苍苍，驱车过太行。","千山盘上党，万木落渔阳。","结客黄金少，投人白璧伤。","男儿羞血战，谈笑报君王。"]},{"t":"真定道中 其二","f":"五言律诗","c":["饮马浊漳流，茫茫去国愁。","沙阴迷雉堞，草色暗狼沟。","博浪千金尽，淮阴一饭留。","谁怜飘泊苦，忍死为神州。"]},{"t":"豫让桥","f":"五言律诗","c":["国士感知己，能将七尺轻。","击衣譬已报，吞炭气难平。","漳水西风急，邢台落日晴。","千秋石桥上，过客马犹惊。"]},{"t":"永平","f":"五言律诗","c":["碣石悬天柱，卢龙接北庭。","海吞滦漆白，山拥蓟辽青。","古塞燕王筑，雄关汉将扃。","威名思李广，猿臂障朝廷。"]},{"t":"赠汪子苕文 其一","f":"五言律诗","c":["梁鸿慕游札，昔向姑苏台。","岂意延陵子，今逢蓟北来。","为君奏风雅，是日陈樽罍。","曲半新声变，宫商待尔裁。"]},{"t":"赠汪子苕文 其二","f":"五言律诗","c":["君问罗浮里，仙灵事若何。","须知蝴蝶大，更是梅花多。","时有麻姑客，纷从翠羽过。","峰峦胜庐岳，四百玉嵯峨。"]},{"t":"别蒲城王子","f":"五言律诗","c":["思家珠海月，望母白登台。","此去随南雁，明春见早梅。","折贻金粟客，一汎索郎杯。","莫令欢娱少，行歌太华来。"]},{"t":"首山","f":"五言律诗","c":["叠巘华山北，连峰蒲坂东。","巨灵挥斧凿，黄帝采金铜。","翠障三边尽，洪流九曲通。","茫茫天下脊，形势为谁雄。"]},{"t":"三原题杜子草堂","f":"五言律诗","c":["从君来谷口，日夕赋閒居。","田傍池阳薮，门临郑国渠。","峰高先积雪，花落细沾书。","太华劳相导，游仙驾鹿车。"]},{"t":"答王六惠葛巾","f":"五言律诗","c":["叔夜能含垢，科头已有年。","飞蓬悲发乱，堕马愧妆妍。","劳子裁云葛，为巾象岳莲。","醉来休倒著，珍重竹林前。"]},{"t":"送曾庭闻返宁夏","f":"五言律诗","c":["宁夏推雄镇，咽喉花马池。","膏腴鱼米地，灌溉汉唐陂。","尔爱贺兰翠，家临河水湄。","功名边上好，莫即叹流离。"]},{"t":"留别钱舍人","f":"五言律诗","c":["万里庭闱在，言归涨海隅。","谁能弃乡井，自此作屠沽。","京雒辞知己，关山命仆夫。","从客君退食，书札问慈乌。"]},{"t":"日食","f":"五言律诗","c":["端阳逢日食，惨澹蓟门边。","黑水无全地，黄云有半天。","鲁阳戈尚在，羲仲御应旋。","万里蒲甘国，龙旗正倒悬。"]},{"t":"送鲁人刘六茹入华山兼寄彭范二道者","f":"五言律诗","c":["鲁国何男子，夷齐尚不希。","昔当猛虎步，今叩老龙扉。","日观辞沧海，莲花揽翠微。","华阴双隐者，萝薜好同衣。"]},{"t":"张二丈为予画支公养马图","f":"五言律诗","c":["支遁怜神骏，今朝得紫骝。","风沙生素练，剪拂向高秋。","牢落千金骨，苍茫万里侯。","含毫何惨淡，怜尔在林丘。"]},{"t":"赠毗陵毛子 其一","f":"五言律诗","c":["总角逢君日，羊城正卜居。","心摧哀痛诏，泪洒治安书。","仓卒贻兰草，飘零断鲤鱼。","时闻骚些曲，沅上吊三闾。"]},{"t":"赠毗陵毛子 其二","f":"五言律诗","c":["我爱吴音好，悠扬国士风。","美人怀别鹤，清夜拂焦桐。","月迥秋河失，花深镜水通。","天风吹不散，一曲彩云中。"]},{"t":"赠毗陵毛子 其三","f":"五言律诗","c":["客心如顾兔，长在月中生。","只影赊春带，繁声恨宝筝。","骅骝虚朔漠，蟋蟀满秋城。","芜绝寻君梦，连宵到柳营。"]},{"t":"赠二张太史","f":"五言律诗","c":["之子生京口，金焦秀色多。","文章若江水，万里下岷峨。","日月趋丹禁，双双鸣玉珂。","弟兄皆早达，花萼共婆娑。"]},{"t":"赠别楚客","f":"五言律诗","c":["相逢蓟门月，如入洞庭秋。","楚客多奇服，湘娥善暮愁。","平生慕宗国，亦既适荆州。","岂意狂歌客，偏从燕地求。"]},{"t":"慰刘六茹病","f":"五言律诗","c":["吾道宜多病，栖迟及暮年。","同心沟壑尽，受命雪霜偏。","山色寒当户，河声远上天。","祗应娥月好，长抱客星眠。"]},{"t":"赠某大司马 其一","f":"五言律诗","c":["鸾皇止阿阁，鰋鲤出清川。","夫子衮衣日，而多白屋贤。","从容命词赋，顾盻生云烟。","未忍罗浮去，徘徊玉麈前。"]},{"t":"赠某大司马 其二","f":"五言律诗","c":["一代持风雅，宗臣道自优。","离骚多讽谏，比兴即春秋。","空翠浮槎落，微茫淝水流。","后生师典则，不向杜陵求。"]},{"t":"赠某大司马 其三","f":"五言律诗","c":["汉代才华合，西京乐府开。","人传大司马，诗冠柏梁台。","我有朱弦曲，思陈清庙来。","楚声俄变乱，挟瑟待公裁。"]},{"t":"送赵生就婚庆阳","f":"五言律诗","c":["羔雁经河岳，威仪尔敬兹。","先生桑梓地，君子瑟琴时。","祖德同瓜瓞，天休是兔丝。","兢兢秦士会，莫忘述昏诗。"]},{"t":"高奴客舍作","f":"五言律诗","c":["今夜宿高奴，天寒尊酒无。","风惊闻堕雁，月出见吹箛。","紫塞难障汉，黄河不限胡。","千秋无定水，呜咽为扶苏。"]},{"t":"别王十二杜五之作","f":"五言律诗","c":["万里为兄弟，交情岂偶然。","欢娱曾几日，契阔又穷边。","紫阁悬斜照，樊川起暮烟。","离忧尝似醉，不必酒杯传。"]},{"t":"流曲访张孝廉文谷","f":"五言律诗","c":["一代遗民在，平生海岳求。","同心漆沮客，招手荆山楼。","黄帝鼎边月，武皇祠畔秋。","秦人怀白露，应问此河洲。"]},{"t":"泾阳访王大春","f":"五言律诗","c":["之子复何事，泾阳方灌园。","三峰开瓠口，二水出寒门。","薇蕨先公节，桑麻郑子村。","相过秋色好，清绝似仙源。"]},{"t":"携姬游华山赋赠","f":"五言律诗","c":["谁知玉井里，亦复有鸳鸯。","玉女洗头罢，莲花无数香。","更怜毛女好，于此素琴张。","风捲水帘雪，愁卿罗袂凉。"]},{"t":"渡渭","f":"五言律诗","c":["秦川涵帝泽，渭水像天河。","襟带雄三辅，朝宗鼓大波。","含泾清自在，宜黍力偏多。","有客扁舟渡，苍茫发棹歌。"]},{"t":"送吴子归河中","f":"五言律诗","c":["昔年上泰华，遥望薰风台。","一片苍梧恨，茫茫天外来。","君今蒲坂去，门对首阳开。","并向夷齐墓，松间扫绿苔。"]},{"t":"怀悬公","f":"古风","c":["闻尔莲花客，新栖铜井山。","飞泉为玉麈，明月满松?。","戎马时方急，罗浮我欲还。","相思蓬海隔，流泪损朱颜。"]},{"t":"望三涂","f":"五言律诗","c":["壁立如天阙，三涂险在前。","陆浑云晻暧，伊水雪潺湲。","逐兔过双涧，弯弓落一鞭。","当时辛有泪，沾洒为东迁。"]},{"t":"挽王安生 其一","f":"五言律诗","c":["雄臣驰骛日，慷慨咏扶风。","赴节人谁力，谋军尔匪躬。","千笳沉白帝，一矢落冥鸿。","遂使王孙草，迷离朔漠东。"]},{"t":"挽王安生 其二","f":"五言律诗","c":["飘零军祭酒，老向雁门营。","北海羝难语，南枝鹊易惊。","鲁连无玉貌，辅嗣有金声。","潦倒笙歌里，何知后世名。"]},{"t":"挽王安生 其三","f":"五言律诗","c":["寿命非金石，边州历苦辛。","怜才多走卒，洒泪更羁臣。","龙性驯何补，松枝脆有因。","遗音幸不坠，骚雅与同伦。"]},{"t":"河套 其一","f":"五言律诗","c":["三面黄河阻，千群铁骑飞。","受降城已没，白马将无归。","风乱哀笳曲，霜生利剑威。","赫连台上望，杀气接金微。"]},{"t":"河套 其二","f":"五言律诗","c":["长城那足恃，绝壁彼能攀。","卫卒虚分戍，边人苦卖关。","贺兰天失险，花马地成閒。","一片延绥草，谁寻白骨还。"]},{"t":"河套 其三","f":"五言律诗","c":["草迷元昊国，山绕卫青城。","海子黄云散，盐池皎月生。","防秋稀宿将，媒卤尽游兵。","坐使三秦困，边功竟不成。"]},{"t":"河套 其四","f":"五言律诗","c":["一片长城暮，边声不可闻。","羌儿秋月下，笳吹动成群。","榆柳迷青海，牛羊下黑云。","今年高太白，努力汉将军。"]},{"t":"河套 其五","f":"五言律诗","c":["属国无三卫，中华有一墙。","阉人分锁钥，债帅作金汤。","地产边才少，天行劫运长。","六骡殊未遁，出没在沙场。"]},{"t":"巢父墓","f":"五言律诗","c":["却笑箕山客，幽光使帝知。","至人无物累，天下有尧治。","饮犊临清涧，悬瓢在上枝。","高风何处溯，遗墓草离离。"]},{"t":"颍桥谒颍考叔祠墓作","f":"五言律诗","c":["颍桥临颍谷，纯孝忆封人。","绕墓慈乌夕，缘祠蔓草春。","远游乖子职，明发愧天伦。","菽水求无处，艰难万里身。"]},{"t":"将从潞河南还赋别刘吏部","f":"五言律诗","c":["平生在五岳，晚作京华游。","欲共山公醉，竹林无处求。","仙人隐声色，远思凝沧洲。","送我兰桡去，情同河水流。"]},{"t":"天津夜泊","f":"五言律诗","c":["九河归帝甸，二海出天津。","潮气凝风雨，灯光见鬼神。","孤舟今夜冷，月明异乡亲。","回忆承平日，笙歌两岸春。"]},{"t":"寄何子","f":"五言律诗","c":["病里知秋早，凉风生鬓丝。","梦随林叶落，心与海云迟。","明月不长满，青山空有期。","斜阳在南浦，每忆送君时。"]},{"t":"送杨职方使安南","f":"五言律诗","c":["尔建相如节，宣威象郡中。","从来神武策，不用羽林戎。","早晚歌钟赐，西南战垒空。","功名归使者，勒石伏波宫。"]},{"t":"送陈氏兄弟还清苑 其一","f":"五言律诗","c":["送君桑梓路，蹀躞塞门霜。","拒马河桥滑，飞狐磴道长。","兰膏调夕膳，玉树发春堂。","不共弹棋戏，相思殊未央。"]},{"t":"送陈氏兄弟还清苑 其二","f":"五言律诗","c":["平城挥手别，无计挽鸾镳。","鸿雁三云隔，参商一水遥。","趋庭过岳渎，戏赋入云霄。","愁绝将军饯，铙歌合短箫。"]},{"t":"送陈氏兄弟还清苑 其三","f":"五言律诗","c":["别绪萦春柳，离心逐玉鞭。","黄云愁朔漠，白日惨幽燕。","歌舞思凫藻，楼台惜绮钱。","王孙招不远，望尔小山篇。"]},{"t":"送陈氏兄弟还清苑 其四","f":"五言律诗","c":["凫雁怀梁藻，松杉爱菟丝。","壶觞心贶后，歌舞目成时。","雨过平川入，云来垒嶂移。","晨葩侔处子，采撷得连枝。"]},{"t":"咏唐晋王","f":"五言律诗","c":["当年频请讨，知罪总春秋。","谁忍窥神器，惟知壮帝猷。","英雄多汗马，王霸有箕裘。","憔悴宫边柳，烟含五代秋。"]},{"t":"寿榆林赵侯 其一","f":"五言律诗","c":["旗偃黄花岭，笳沉白草沟。","武安勤飨士，太尉暇登楼。","霸气沙陀早，军声阴馆秋。","无须黄老术，儒将自风流。"]},{"t":"寿榆林赵侯 其二","f":"五言律诗","c":["幕府依严武，溪堂筑浣花。","雄才惊不世，浪迹托为家。","岳吐孤生竹，天含五色霞。","年年持献寿，忠信是丹砂。"]},{"t":"别阮亭 其一","f":"五言律诗","c":["今代青云客，渔洋丽句多。","芙蓉开晓日，鳷鹊漾金波。","拥传扬州去，回鞭上苑过。","玉钩斜畔月，水调奈君何。"]},{"t":"别阮亭 其二","f":"五言律诗","c":["昔年寻白社，君赠庐山谣。","以我栖禅寂，相思不见招。","今来望宫阙，又欲返东樵。","喜尔容台上，殷勤玉佩要。"]},{"t":"别阮亭 其三","f":"五言律诗","c":["不堪人老大，种柳已成围。","羽翼中朝少，埙数故国稀。","微言及庄老，散带临芳菲。","莫惜閒书札，雁门多雁飞。"]},{"t":"怀同岑","f":"五言律诗","c":["空翠洞庭阴，松风吹满林。","白云不可见，日与数峰深。","闻在毛女洞，时时拂素琴。","秋来摘朱橘，霜露湿衣襟。"]},{"t":"送陈五黄门访药禅师 其一","f":"五言律诗","c":["白头陈给事，五岳去何迟。","君父真无所，神仙亦后时。","折梅过大庾，炊黍忆东菑。","此日宜高卧，浮山与尔期。"]},{"t":"送陈五黄门访药禅师 其二","f":"五言律诗","c":["丈夫殊未遇，努力食嗟来。","况有青琴在，那忧白发催。","吴山朝步马，越水暮流杯。","不有三禅客，谁怜一代才。"]},{"t":"张文献公祠","f":"五言律诗","c":["南人初作相，始自曲江公。","风度朝廷肃，文章岭海雄。","开元多事业，大庾有祠宫。","一自陈金鉴，君王念不穷。"]},{"t":"东莞伯","f":"五言律诗","c":["往时雄保障，功在祝融墟。","带砺盟犹在，山河胙已除。","不称南武号，频上窦融书。","此日知王命，英雄总不如。"]},{"t":"送王鍊师","f":"五言律诗","c":["片言为宝剑，赠尔壮游人。","儿女非无泪，英雄自有神。","黄冠辞百粤，白马入三秦。","谈笑取卿相，归来复养真。"]},{"t":"哭从弟孚士 其一","f":"五言律诗","c":["往日趋行在，忠贞有我兄。","六龙随扈从，双凤独功名。","泪洒兰仓水，心悬缅甸城。","家中凭第五，水菽苦经营。"]},{"t":"哭从弟孚士 其二","f":"五言律诗","c":["吾宗荆子姓，人重楚王孙。","与弟成嘉遁，惟兄在白园。","情将同被笃，道以采薇尊。","今日人琴丧，悲酸不可言。"]},{"t":"哭从弟孚士 其三","f":"五言律诗","c":["嗟汝年虽少，英姿已绝伦。","士龙真俊弟，仲武始成人。","膂力难为用，才华易致贫。","紫荆凋一干，痛绝是天亲。"]},{"t":"哭从弟孚士 其四","f":"五言律诗","c":["奔墓君无及，招魂尔不归。","池塘谁入梦，花萼旧相辉。","一女生弥月，三兄泪满衣。","不知朝与暮，何以慰慈帏。"]},{"t":"哭从弟孚士 其五","f":"五言律诗","c":["未有遗孤在，弥令寡妇悲。","慈乌啼欲绝，孝竹槁多时。","康乐诗频献，离骚学不迟。","灵床尽一恸，泉下可能知。"]},{"t":"壬子春日弄雏轩作 其一","f":"五言律诗","c":["弱柳垂烟重，夭桃破雪新。","一身佣作苦，十口隐居贫。","性拙鸠无屋，机閒鹿近人。","罗浮多笋蕨，采采及青春。"]},{"t":"壬子春日弄雏轩作 其二","f":"五言律诗","c":["日迟无一事，清啸和泉音。","水国春难暖，茆斋昼已阴。","娱亲惟彩笔，学道有青琴。","慈孝怜多竹，枝枝带露深。"]},{"t":"壬子春日弄雏轩作 其三","f":"五言律诗","c":["少妾能调管，贤妻喜读书。","花沾红袖湿，月映碧窗虚。","食尽思干谒，身危屡卜居。","缠绵殊未已，小别亦愁予。"]},{"t":"壬子春日弄雏轩作 其四","f":"五言律诗","c":["未厌妆奁戏，帷房日弄姿。","中郎书幼妇，莱子作婴儿。","供养多春酒，欢娱更画眉。","茶煎萱草带，相对月明时。"]},{"t":"壬子春日弄雏轩作 其五","f":"五言律诗","c":["楚俗多哀怨，三闾曲最高。","未曾生汉武，谁解爱离骚。","托意惟男女，凌虚少羽毛。","相思泉下友，泪湿旧檀槽。"]},{"t":"壬子春日弄雏轩作 其六","f":"五言律诗","c":["自愧单家子，疏巾折节年。","人肝分盗蹠，马革失文渊。","花落又将尽，河清殊未然。","终知不得志，白首作神仙。"]},{"t":"壬子春日弄雏轩作 其七","f":"五言律诗","c":["清狂亦自厌，老大欲谁亲。","未敢求知己，犹然愧古人。","雨中微见月，花里好留春。","晚计惟儿女，家庭道不贫。"]},{"t":"壬子春日弄雏轩作 其八","f":"五言律诗","c":["自怜书著就，亦是一春秋。","受业文宣母，横经大石楼。","少年娱黄老，中岁赖穷愁。","绝学江门在，吾曾夙夜求。"]},{"t":"赋答莞中梁子 其一","f":"五言律诗","c":["万里孤征日，三朝痛哭人。","还家如紫塞，见尔即青春。","犬马难酬主，鸡豚幸及亲。","白头得知己，感激更沾巾。"]},{"t":"赋答莞中梁子 其二","f":"五言律诗","c":["丈夫时命薄，不幸作神仙。","梅福监门日，安期卖药年。","道须高士得，书必后人传。","岁晏多风雪，松枝好自坚。"]},{"t":"赋答莞中梁子 其三","f":"五言律诗","c":["与子复何事，千秋一采薇。","自惊鸾鹤贵，不必稻粱肥。","海气楼台结，溪声水石飞。","庞公我兄事，床下拜无违。"]},{"t":"赋答莞中梁子 其四","f":"五言律诗","c":["沧浪歌自逸，渔父即三闾。","哀怨复何益，芬芳难久居。","月华含霜湿，泉响入风虚。","吾道远游好，从君恣所如。"]},{"t":"赋答莞中梁子 其五","f":"五言律诗","c":["时无衰凤在，谁与楚狂言。","将子知音好，从兹古道敦。","鸳鸯元共命，兰蕙亦同根。","寡过相须甚，时时一讨论。"]},{"t":"舂山草堂感怀 其一","f":"五言律诗","c":["地因滨海湿，人以著书贫。","况复多风雨，弥令叹苦辛。","半生游侠误，一代逸民真。","菽水劳妻子，窗间刺绣频。"]},{"t":"舂山草堂感怀 其二","f":"五言律诗","c":["辛苦朝那女，随予万里鞭。","还家犹是客，事母未经年。","兰麝馀妆阁，松楸满墓田。","可怜清夜泪，滴滴到黄泉。"]},{"t":"舂山草堂感怀 其三","f":"五言律诗","c":["客心伤已尽，黄鸟苦流声。","一水穿云直，孤花吐日明。","东西家未定，四十道无成。","何以蠲忧疾，文章送此生。"]},{"t":"舂山草堂感怀 其四","f":"五言律诗","c":["卧病江皋久，空悬渔父期。","秋风不可触，一夕鬓成丝。","海暗鸿声疾，山寒日影迟。","祗应与黄菊，荣落在东篱。"]},{"t":"舂山草堂感怀 其五","f":"五言律诗","c":["故国松楸里，君臣几杜鹃。","卧龙成白首，跃马已黄泉。","风雨悲寒食，干戈失墓田。","先人薇蕨在，采采暮云边。"]},{"t":"舂山草堂感怀 其六","f":"五言律诗","c":["失志今如此，吾生安所成。","但能饮美酒，自可得高名。","孔雀春多翠，黄花晚有英。","九歌谁忍续，绮靡但伤情。"]},{"t":"舂山草堂感怀 其七","f":"五言律诗","c":["慷慨空长啸，无心爱好春。","愁多生白发，命薄失佳人。","海燕成巢屡，安榴结子频。","纤纤银系爪，犹忆搊弹新。"]},{"t":"舂山草堂感怀 其八","f":"五言律诗","c":["松子和枝落，萧疏见鹤巢。","秋声多在竹，露气半含梢。","寂寞通先哲，饥寒答素交。","年来无可用，惭愧似空匏。"]},{"t":"舂山草堂感怀 其九","f":"五言律诗","c":["隐忍身将老，英豪世不知。","梁鸿元烈士，鲁肃本狂儿。","阴市名刀久，横行匹马迟。","朝来频揽镜，叹息鬓边丝。"]},{"t":"舂山草堂感怀 其十","f":"五言律诗","c":["未能诛淖齿，何以见慈亲。","市井堪呼战，君王已属人。","倚闾从白发，报国及青春。","去去提双剑，男儿自有神。"]},{"t":"舂山草堂感怀 其十一","f":"五言律诗","c":["几夕松间石，披衣坐忍寒。","啸声空外答，心影月中看。","果落惊山鸟，风来堕箨冠。","凄凉殊不寐，更上步虚坛。"]},{"t":"舂山草堂感怀 其十二","f":"五言律诗","c":["慷慨干戈里，文章任杀身。","尊周存信史，讨贼托词人。","素发垂三楚，愁心历九春。","桃花风雨后，和泪共沾巾。"]},{"t":"舂山草堂感怀 其十三","f":"五言律诗","c":["白发同秋草，愁心似落花。","君王频殉国，将帅祗为家。","蓟北瞻丹极，滇南想翠华。","无才扶日月，流落任天涯。"]},{"t":"舂山草堂感怀 其十四","f":"五言律诗","c":["衣服烧丹尽，图书换米馀。","养亲生计薄，求道世情疏。","儿女催华发，亲朋笑索居。","黄花寒不落，岁晏欲何如。"]},{"t":"舂山草堂感怀 其十五","f":"五言律诗","c":["隐几长忘世，扶痾始觉身。","死生元不厌，药饵且相亲。","明月已云满，桃花那再春。","浩歌聊自送，去作北邙尘。"]},{"t":"舂山草堂感怀 其十六","f":"五言律诗","c":["几欲从军旅，其如白发人。","有家难委弟，无策可娱亲。","作士诗书贱，为农陇亩贫。","终然将七尺，去作玉关尘。"]},{"t":"舂山草堂感怀 其十七","f":"五言律诗","c":["平生梁雪窦，是我最知音。","一自斯人没，三年不鼓琴。","文章藏禹井，涕泪满山阴。","向夕闻悲篥，魂应起壮心。"]},{"t":"游蒲涧","f":"五言律诗","c":["我慕安期子，菖蒲涧上来。","言寻赤玉舄，更上鹤舒台。","古寺临秋水，当窗见早梅。","苍苍一洞口，不得水帘开。"]},{"t":"答人惠药","f":"五言律诗","c":["蝴蝶作庄周，佯狂世上游。","有身惟殉道，无地可埋忧。","月出先微雨，梅开后素秋。","承君念寒疾，药石重相投。"]},{"t":"罗生以角弓赠行","f":"五言律诗","c":["丈夫求一饭，不到孟尝前。","贫贱多知己，飘零及壮年。","亲劳角弓赠，申以紫骝篇。","此去非游猎，烟尘满朔天。"]},{"t":"重寄姚石埭 其一","f":"五言律诗","c":["闻君挹丹溜，日夕讼堂閒。","人道罗浮月，飞来天柱间。","子安有黄鹄，肯送故人还。","还及梅花发，朱明更掩关。"]},{"t":"重寄姚石埭 其二","f":"五言律诗","c":["信陵去已久，高义在夫君。","我亦屠沽者，诸侯莫不闻。","昔劳赠长剑，今岂若浮云。","歧路怀知己，踟蹰向夕曛。"]},{"t":"逢陆冰修","f":"五言律诗","c":["平生爱吴越，山水足登临。","有友皆高尚，如君最素心。","钱唐昔相见，蓟北此招寻。","惠我新诗好，洋洋被玉琴。"]},{"t":"频阳纪梦作 其一","f":"五言律诗","c":["湘累魂越散，端赖美人招。","故国无三秀，佳期有二姚。","神光离复合，幽梦暮还朝。","不道襄王惑，频将玉佩要。"]},{"t":"频阳纪梦作 其二","f":"五言律诗","c":["南楚来萍实，西秦遇蕣英。","舞惊王剪里，歌掩美原城。","薄梦为媒妁，多情愧友生。","思为连理木，枝叶向冬荣。"]},{"t":"频阳纪梦作 其三","f":"五言律诗","c":["风吹珠海月，月照弄珠人。","窈窕匏瓜匹，徘徊子夜春。","惊鸿翩欲举，堕马艳无伦。","太白金陵子，风流继后尘。"]},{"t":"答定上人","f":"五言律诗","c":["乞食元吾道，萧然似古狂。","九歌惊市井，一笑受壶浆。","世态从轻薄，仙源自渺茫。","逢君人外赏，把臂竹林傍。"]},{"t":"题戴务旃水田图","f":"五言律诗","c":["与君沮溺心，农事怀江阴。","昨梦水田鹭，飞过青竹林。","朝来作图画，春色东皋深。","安得耦耕去，还为桑者吟。"]},{"t":"赠兖州朱十四 其一","f":"五言律诗","c":["少小逐游侠，骄行白鼻騧。","昔逢宋如意，今得鲁朱家。","拂剑舞秋月，开樽临暮霞。","高堂有歌管，斟酌曲中花。"]},{"t":"赠兖州朱十四 其二","f":"五言律诗","c":["嗟君闾里侠，金尽欲如何。","乱后田园少，愁中鼓角多。","将军无细柳，渔父且沧波。","怀有遗书在，行行避紫驼。"]},{"t":"以鹤顶杯赠潘峋蝼时翁年八十矣","f":"五言律诗","c":["金应收骏骨，珠莫买蛾眉。","况此飞仙物，堪娱绮皓姿。","闻翁春酒熟，正值杏花时。","将我鹤杯饮，千龄定可期。"]},{"t":"过清远诸滩","f":"五言律诗","c":["一百重滩水，篙篙与石争。","风雷随地转，岩壑逐人行。","舟子寒相怨，沙禽暮亦惊。","何当归旧隐，高卧掩柴荆。"]},{"t":"冬日英州山中","f":"五言律诗","c":["山山黄叶尽，残雪响枫林。","天入群峰小，泉归一壑深。","高松寒立影，明月正栖心。","冉冉岁华暮，谁来问玉琴。"]},{"t":"浈阳舟中","f":"五言律诗","c":["离乡曾几日，不断梦庭闱。","自是慈恩重，非关道力微。","空江过宿雨，细草媚朝晖。","未忍寻山水，秋深定卜归。"]},{"t":"度腊岭","f":"五言律诗","c":["一径穿红树，千盘堕白云。","衡湘林外出，交广岭头分。","流水如人语，回峰似雁群。","间关何所事，荡子去从军。"]},{"t":"任嚣城","f":"五言律诗","c":["泷口高城在，将军旧启疆。","观星知越霸，绝道待秦亡。","虎豹三关踞，旌旗五岭扬。","保民功不小，祠庙遍炎方。"]},{"t":"度骑田作","f":"五言律诗","c":["鞍马不遑息，行行栈阁间。","天寒风落木，日暮雨连山。","摺岭通三楚，郴江下百蛮。","遗民思义帝，伏腊泪痕斑。"]},{"t":"乳源出水岩采雪花赠高士周孝廉诩","f":"五言律诗","c":["乳山多异卉，岁晏发寒林。","不作冰霜色，谁知草木心。","幽香盈石室，素影傍瑶琴。","迟暮吾何惜，凭将答所钦。"]},{"t":"梅花?水","f":"古风","c":["梅花?水地，幽绝可逃秦。","耕凿无馀事，衣冠在野人。","人人持鹿铁，处处见熊伸。","徭女歌声好，风吹听不真。"]},{"t":"过泷 其一","f":"五言律诗","c":["水出五禽岭，飞腾作六泷。","蹴天过万嶂，驱石落三江。","舟楫惊相战，蛟龙怒不降。","汉时周太守，疏凿奠吾邦。"]},{"t":"过泷 其二","f":"五言律诗","c":["险绝过泷水，舟飞沸鼎中。","死生随白浪，出没信狂风。","沉璧祈河伯，开山叹鬼工。","单船如一叶，片片落秋空。"]},{"t":"过泷 其三","f":"五言律诗","c":["性命悬三老，舟行若转蓬。","心安过一石，身小束千峰。","猿啸梅花里，人栖竹叶中。","年年白头浪，送客欲成翁。"]},{"t":"过泷 其四","f":"五言律诗","c":["舟从九渊出，势挟蛟龙强。","巨崖皆辟易，白浪共飞扬。","忠信豚鱼格，高深孝子伤。","生还天地意，从此戒垂堂。"]},{"t":"乐昌水涨","f":"五言律诗","c":["春水三泷发，惊流两壁飞。","蹴天过叠嶂，洒雪乱晴晖。","树影连城暗，猿声出浦微。","几时捐世事，来此坐渔矶。"]},{"t":"烟霞峰寻李邺侯故居","f":"五言律诗","c":["中峰多翠微，隐者旧光辉。","日月开黄石，风云绕白衣。","书台春木秀，啸馆暮烟霏。","今日瞻灵武，何人扈六飞。"]},{"t":"望桂宫 其一","f":"五言律诗","c":["秀丽湖湘地，神灵岣嵝峰。","夏王刑白马，南岳降真龙。","日月三年辟，风云万国从。","峨峨朱邸在，还见剪桐封。"]},{"t":"望桂宫 其二","f":"五言律诗","c":["缥缈灵光殿，云开紫翠重。","遥瞻天子气，正绕祝融峰。","南狩过炎海，中兴在亢龙。","衡湘诸父老，血胤忆神宗。"]},{"t":"望桂宫 其三","f":"五言律诗","c":["我后生南岳，神兵扫北畿。","威灵群帝接，光耀八龙飞。","紫盖留金殿，朱陵望玉旂。","几时从大隗，还驾五云归。"]},{"t":"望回雁峰","f":"五言律诗","c":["峰势如回雁，高高出楚天。","云含衡岳雪，树带碧湘烟。","异日藏神剑，今宵系画船。","乾坤犹震荡，未可挟飞仙。"]},{"t":"天岳","f":"五言律诗","c":["秋气高无极，峰峰积雨凉。","白云吞七泽，红叶满三湘。","禹迹留盘石，仙宫傍夕阳。","蛟龙多蛰此，吾亦隐文章。"]},{"t":"湘阴作","f":"五言律诗","c":["青草三闾墓，黄陵二女祠。","风清闻玉佩，云暗见兰旗。","湖口潇湘阔，天边鸿雁迟。","容颜殊姣好，公子未曾知。"]},{"t":"黄陵怅望","f":"五言律诗","c":["二妃埋玉处，山压洞庭波。","野外苍梧远，祠边斑竹多。","佳期愆北渚，离恨满云和。","灵降先风雨，来听众嫭歌。"]},{"t":"豆叶坪病起","f":"五言律诗","c":["山静长如夕，微微樵牧踪。","有时闻远瀑，终日对高松。","久病悲欢尽，新寒衣衲重。","他宵秋月满，应上汉阳峰。"]},{"t":"五老峰背观三叠泉 其一","f":"五言律诗","c":["我爱匡庐瀑，无如三叠泉。","高高从五老，飞落蠡湖边。","石上洒明月，日中含绿烟。","海风吹忽断，一半入空天。"]},{"t":"五老峰背观三叠泉 其二","f":"五言律诗","c":["面面峰峦绝，横天铁壁青。","飞泉若烟雾，白昼走雷霆。","激石成三叠，穿云出九屏。","无人知此胜，来往水精灵。"]},{"t":"雨过坐三峡桥望石人峰流水","f":"五言律诗","c":["雨馀一片水，壁立白云端。","流过三峡乱，声入万松寒。","复有石桥月，宜人秋夜看。","羽人渺何处，相忆玉琴弹。"]},{"t":"玉川门精舍春日","f":"五言律诗","c":["三叠泉边阁，春云映雪明。","听松忘日永，采药喜天晴。","谷暖兰先吐，林幽鸟不鸣。","寥寥人境外，一病入无生。"]},{"t":"人日秦淮上值孟王生辰赋赠 其一","f":"五言律诗","c":["万里从关塞，相将负戴来。","为怜桃叶渡，未凝海殊回。","生日逢人日，妆台倚凤台。","梅花频采采，为子汎春杯。"]},{"t":"人日秦淮上值孟王生辰赋赠 其二","f":"五言律诗","c":["旅食江南日，相依幸不孤。","慰情凭弱女，养志及慈姑。","雨雪侵云鬓，莺花待玉壶。","年年人日好，白首此欢娱。"]},{"t":"吴江赠顾茂伦 其一","f":"五言律诗","c":["月出采香洲，吴娘唱柂楼。","垂虹杨柳暗，莺脰白蘋秋。","故国苍茫别，美人迟暮愁。","夫君若萱草，一见即忘忧。"]},{"t":"吴江赠顾茂伦 其二","f":"五言律诗","c":["吴下要离子，相逢意气存。","千金生壮士，一饭死王孙。","返马亡秦塞，维舟破楚门。","他时功业就，痛饮在中原。"]},{"t":"舟入阊门","f":"五言律诗","c":["曲折木兰桡，穿城四百桥。","锦帆风未散，茂苑雨初消。","烟火含春树，人家逐暮潮。","相思明月夜，歌管为谁骄。"]},{"t":"望天坪","f":"五言律诗","c":["天平青不断，雪尽数峰分。","表里皆奇石，朝昏在白云。","楼台横水出，钟磬隔花闻。","采药吾将往，相随麋鹿群。"]},{"t":"怀山阴祁六","f":"五言律诗","c":["贺监湖边月，风流忆舞筵。","星河花外转，楼阁镜中悬。","长袖纷留客，清歌但采莲。","此时君见赠，西子沼吴篇。"]},{"t":"灵岩春日与李侍御灌溪游览作","f":"五言律诗","c":["春光如有意，先到馆娃宫。","石响佳人屧，花衔使者骢。","湖吞三郡白，水落半山红。","七十二峰里，梅花望不穷。"]},{"t":"江东别朱生 其一","f":"五言律诗","c":["彭蠡水茫茫，东流控马当。","孤帆悬细雨，故国隐斜阳。","知己白门少，思君秋夜长。","殷勤南蒲送，何日慰参商。"]},{"t":"江东别朱生 其二","f":"五言律诗","c":["分手横江馆，烟波一片愁。","天门青两岸，春草绿中洲。","相许有长剑，所欢非五侯。","交情贫贱好，岁晚莫悠悠。"]},{"t":"江东别朱生 其三","f":"五言律诗","c":["五岭横韶石，三泷下桂阳。","北门秦锁钥，南服越封疆。","战垒秋旗满，津楼晚角长。","期君如陆贾，游说得金装。"]},{"t":"舟至焦山","f":"五言律诗","c":["惊涛起东海，千里雪山来。","飞楫过天堑，狂歌把玉杯。","云迷三诏洞，月出八公台。","草草齐梁代，兴亡总可哀。"]},{"t":"赠金陵李子 其一","f":"五言律诗","c":["先帝无双士，熊罴勇擅场。","时穷能绕指，天巧必穿杨。","栖托仙坛近，游盘御苑长。","兽肥春草短，为母猎无荒。"]},{"t":"赠金陵李子 其二","f":"五言律诗","c":["国初传尔祖，采石建奇勋。","方略高堂授，威名大将分。","虎头今有种，凤臆旧空群。","他日交河战，还期再冠军。"]},{"t":"赠金陵李子 其三","f":"五言律诗","c":["凤冠加四翅，帝钖太夫人。","教子仁为将，从龙智绝伦。","慈孙宜继志，大孝在扬亲。","莫使王陵母，卖声奕世湮。"]},{"t":"赠金陵李子 其四","f":"五言律诗","c":["三北嗟曹沫，偷生为母慈。","精勤黄石术，隐忍战争时。","友谊河梁见，天心草莽知。","金陵形胜国，叹我卜居迟。"]},{"t":"过翁子山房赋别 其一","f":"五言律诗","c":["翁子中吴秀，诗歌起洞庭。","今修震泽志，足补禹王经。","露引双桐翠，烟含万壑青。","何时及秋月，胥口共扬舲。"]},{"t":"过翁子山房赋别 其二","f":"五言律诗","c":["乍见如芝草，临分恋玉杯。","情同莫釐月，送出姑苏台。","白鹤自兹去，梅花谁为开。","一峰歌一曲，早寄相思来。"]},{"t":"横塘寄徐昭法","f":"五言律诗","c":["雨过横塘水，人家湿暮烟。","湖山深竹里，鸡犬落花边。","昔至杨梅熟，今来莲叶圆。","相思胥口月，之子在渔船。"]},{"t":"濠州作","f":"五言律诗","c":["赤龙飞作汉，玄鸟降生商。","帝统还中夏，皇灵恋故乡。","光华金镜在，精爽玉衣扬。","终古枌榆社，人祠太上皇。"]},{"t":"登观象台","f":"五言律诗","c":["钦天山峻极，西接独龙冈。","树色迷长乐，钟声似景阳。","帝王空有庙，星宿不成行。","此日观乾象，愁心黯未央。"]},{"t":"访钱牧斋宗伯芙蓉庄作","f":"五言律诗","c":["四面烟波绕，藏书有一楼。","兴亡元老在，文献美人留。","桥细穿荷叶，舟轻及素鸥。","爱予初命笔，交脊有春秋。"]},{"t":"于忠肃墓","f":"五言律诗","c":["一代勋猷在，千秋涕泪多。","玉门归日月，金券赐山河。","暮雨灵旗捲，阴风突骑过。","墓前频拜手，愿借鲁汤戈。"]},{"t":"谒谢皋羽墓 其一","f":"五言律诗","c":["君事文丞相，曾蒙国士知。","漆身追豫让，埋骨傍要离。","露夕鹤巢冷，风秋猿啸悲。","墓前谁拜手，露滴白杨枝。"]},{"t":"谒谢皋羽墓 其二","f":"五言律诗","c":["孤臣馀犬马，后死亦徒然。","血泪长江泻，愁心朔漠悬。","千秋兰麝土，万里虎狼天。","留得冬青树，凌霜自宋年。"]},{"t":"谒谢皋羽墓 其三","f":"五言律诗","c":["六帝攒宫没，孤臣撮土留。","可怜秦望月，不及富春洲。","旧恨啼黄鸟，新悲值素秋。","精灵依钓濑，长与客星游。"]},{"t":"渡江","f":"五言律诗","c":["渡江神惨淡，去国意苍茫。","白首成遗老，青春过异乡。","山开京口阔，水落海门长。","战后黄云满，旌旗更几行。"]},{"t":"李骠骑置酒长干招同陈氏兄弟送予与杜子游太华即事赋 其一","f":"五言律诗","c":["强弩将军在，千秋肘法传。","骅骝悲失路，雕鹗想横天。","探道丹书里，承欢白发前。","朋来因孝友，尽醉凤台边。"]},{"t":"李骠骑置酒长干招同陈氏兄弟送予与杜子游太华即事赋 其二","f":"五言律诗","c":["紫髯何飒爽，词客杜陵来。","四座风流映，三峰气象开。","将予寻白帝，别尔上云台。","江左飞龙地，明秋鼓棹回。"]},{"t":"李骠骑置酒长干招同陈氏兄弟送予与杜子游太华即事赋 其三","f":"五言律诗","c":["萧条陈孺子，黄老学多年。","贫贱非轻世，精诚自格天。","鸾刀挥社日，翎羽拂春烟。","既醉骊驹驾，欢娱惜此筵。"]},{"t":"李骠骑置酒长干招同陈氏兄弟送予与杜子游太华即事赋 其四","f":"五言律诗","c":["如意堂前筑，今宵变羽声。","悲风吹木叶，落月满江城。","争博同勾践，飞觞属庆卿。","丈夫穷不惜，大器晚方成。"]},{"t":"临淮道中","f":"五言律诗","c":["南望家临海，西征路向关。","为奴居广柳，寄母有刀环。","积气浮淮浦，穷阴覆楚山。","岁寒难自保，风雪损朱颜。"]},{"t":"郏县道中 其一","f":"五言律诗","c":["雪晴行郏县，山色扑征鞍。","大道风沙暗，孤城烟火寒。","苍茫瞻少室，迢递入西安。","腊酒襄阳美，无嗟行路难。"]},{"t":"郏县道中 其二","f":"五言律诗","c":["岁晚征衣薄，天寒朔气深。","庭闱思觐省，河岳厌登临。","细马僵春雪，慈乌盻暮林。","故园诸弟妹，遥寄采兰吟。"]},{"t":"尹太学新婚有赠 其一","f":"五言律诗","c":["尔祖趋朝日，谋猷动至尊。","孝须承谏草，忠可继天垣。","花萼枝枝好，鹓雏一一存。","述昏新有作，文藻亚诸昆。"]},{"t":"尹太学新婚有赠 其二","f":"五言律诗","c":["良人新葛勃，国子旧仇香。","二月迎桃李，三星下凤凰。","读书陪刺绣，采藻及芬芳。","警戒鸡鸣好，先人德业长。"]},{"t":"送人之甘州","f":"五言律诗","c":["饮马渥洼川，水肥春草鲜。","蕃姬来劝酒，汉将去屯田。","风起呜沙碛，云迷张掖天。","少年思奋武，无泪洒穷边。"]},{"t":"送周子之京口","f":"五言律诗","c":["形胜南徐好，英雄往迹存。","为龙思帝子，跃马笑公孙。","浮玉当京口，松寥是海门。","君行有长笛，吹向莫愁村。"]},{"t":"荆门","f":"五言律诗","c":["巴水吞三峡，荆门控百蛮。","山连夔子国，天作虎牙关。","白帝朝云里，明妃夜月间。","行人怜古柳，多向楚宫攀。"]},{"t":"玉河亭宴集","f":"五言律诗","c":["玉河城阙外，源出玉泉高。","穿宫为太液，步马即兰皋。","楼台尽杨柳，尊俎有蒲桃。","相将梁苑客，抽管赋春涛。"]},{"t":"佳人","f":"五言律诗","c":["佳人回鹘装，衣带内家香。","一曲飞龙引，思君泪数行。","箜篌悲夜月，眉黛落秋霜。","辛苦良家子，年年向战场。"]},{"t":"覆舟山下作","f":"五言律诗","c":["千年龙虎国，怅望一平芜。","六代频兴废，中华更有无。","大江流王气，遗殿怨栖乌。","玉树歌良苦，英雄莫据吴。"]},{"t":"与客游阳明洞","f":"五言律诗","c":["阳明仙洞口，与客共攀登。","注酒秦皇瓮，探书大禹陵。","山开苍树出，泉落白云崩。","散带虽人外，沈冥愧未曾。"]},{"t":"入云门作","f":"五言律诗","c":["平生山水兴，最在浣纱洲。","更入云门去，无穷是素秋。","风含清磬度，水带落花流。","白乳泉边坐，清泠足久留。"]},{"t":"赠刘生 其一","f":"五言律诗","c":["英雄多失路，四十未功名。","慷慨一杯酒，飞扬万里征。","文章新豹变，汗血旧龙争。","莫即辞贫贱，君才晚更成。"]},{"t":"赠刘生 其二","f":"五言律诗","c":["平生一宝剑，持以结交亲。","不恨相知晚，惟期白首新。","卧龙殊未老，飞兔更无伦。","异日沙场上，挥鞭逐后尘。"]},{"t":"送友 其一","f":"五言律诗","c":["中年须学道，五岳更寻师。","早得青莲法，来归紫水湄。","天边双瀑布，谷口一茅茨。","与子栖閒去，人烟不可知。"]},{"t":"送友 其二","f":"五言律诗","c":["守道虽无悔，遭时未免愁。","何因入泉石，不敢负春秋。","岂以妻孥累，而为黄老谋。","行行聊乞食，升斗为亲求。"]},{"t":"三水县访朱丈","f":"五言律诗","c":["地控三江口，城开白塔村。","市桥春雨滑，渔艇暮潮喧。","肄水清浮县，昆都翠映门。","停桡访知己，相见恋琴尊。"]},{"t":"鸬鹚石","f":"五言律诗","c":["望望鸬鹚似，双飞直至今。","细微元地胏，浮定总波心。","势得三江险，根应百丈深。","不须过滟滪，舟楫已沉吟。"]},{"t":"大芦峡","f":"五言律诗","c":["牂柯从此出，浩淼到厓门。","二水吞孤峡，三江控一村。","鱼花多下步，橘子满中园。","潮势秋来大，微微岛屿存。"]},{"t":"空翠","f":"五言律诗","c":["乍染芙蓉湿，苍苍不是烟。","有无秋色外，明灭暮岚边。","影人眉间黛，光生镜里天。","天边数鸿雁，飞处有馀妍。"]},{"t":"乱帆","f":"五言律诗","c":["乱帆争落日，十幅总云轻。","势定知风小，飞低与水平。","纷纷无近远，片片在空明。","中有楚渔父，沧浪歌几声。"]},{"t":"赠查子","f":"五言律诗","c":["之子求佳丽，珠娘得小家。","芙蓉春有子，茉莉夜开花。","眉写山山翠，衣飘片片霞。","载归勾越去，妒杀浣溪纱。"]},{"t":"柳花 其一","f":"五言律诗","c":["一夕垂杨树，花飞入杳冥。","无风已如雪，有水即为萍。","未忍吹长笛，生憎种短亭。","莺衔馀几片，掩映数枝青。"]},{"t":"柳花 其二","f":"五言律诗","c":["一春风上下，飞去欲谁家。","未肯污泥水，惟知作雪花。","条长攀易得，枝弱舞休斜。","几点多情甚，依依在鬓华。"]},{"t":"送榷关使君","f":"五言律诗","c":["复作沉香浦，人钦子大夫。","明朝共兰楫，祗有石家珠。","越鸟声多好，蛮花色太朱。","木棉携得否，绝胜女珊瑚。"]},{"t":"钱烈女哀词 其一","f":"五言律诗","c":["佳人能独立，不肯嫁乌孙。","九死传闺烈，三春吊墓门。","珠归天帝掌，花逐雒妃魂。","词客题黄绢，丰碑照古原。"]},{"t":"钱烈女哀词 其二","f":"五言律诗","c":["一代汉宗臣，衣冠冢与邻。","兰心忧社稷，漆室抱经纶。","惨淡扬州月，萧条邗水春。","东南佳丽尽，馀尔露筋人。"]},{"t":"钱烈女哀词 其三","f":"五言律诗","c":["芜城经百战，血满玉勾斜。","死畏留青冢，生忧玷白华。","缇萦能代父，蔡琰不宜家。","玉石同焚后，芳声振海涯。"]},{"t":"韩烈女哀词 其一","f":"五言律诗","c":["佳人何侠烈，玉碎向重围。","血溅花门骑，魂随雾縠衣。","神光离复合，仙貌是耶非。","兰桂千秋操，芬芳知者希。"]},{"t":"韩烈女哀词 其二","f":"五言律诗","c":["白刃血纷纷，佳人化彩云。","可怜明月魄，犹恋石榴裙。","鹑首天方醉，蛾眉世不闻。","哀笳三百弄，总是慰昭君。"]},{"t":"韩烈女哀词 其三","f":"五言律诗","c":["轻云含片月，光彩乍阴阳。","诗礼为良会，人神有大纲。","胭脂羞北地，菡萏喜西方。","金母知相待，瑶池路不长。"]},{"t":"哀麦氏诸烈 其一","f":"五言律诗","c":["葡萄惟汉地，孔雀不胡天。","岂有罗敷洁，而求老上怜。","明珠沉合浦，美玉葬雄田。","不使金笳引，飞来角枕边。"]},{"t":"哀麦氏诸烈 其二","f":"五言律诗","c":["丹井水泱泱，含君明月光。","落花封玉屧，飞叶满银床。","白璧还慈母，黄沙谢峭王。","从来贞烈性，尽在紫鸳鸯。"]},{"t":"张节妇 其一","f":"五言律诗","c":["金垆爇沉水，一气绪双霞。","死作经天月，生为向日花。","兔丝虽已断，鸾镜庶无瑕。","持此酬君子，床空莫怨嗟。"]},{"t":"张节妇 其二","f":"五言律诗","c":["风惊边地草，白兔失其雄。","血染呼韩箭，魂飞汉帝宫。","不随青冢月，去照黑山戎。","妾自怀贞洁，长将兰桂同。"]},{"t":"赵门二节妇 其一","f":"五言律诗","c":["汉女元龙种，萧郎是凤俦。","身随天柱折，泪逐帝星流。","皦日从来誓，高霞不可求。","应同青鸟去，梧野作珠丘。"]},{"t":"赵门二节妇 其二","f":"五言律诗","c":["自有闺中月，清光照越州。","天狼难至曙，塞马不长秋。","翁主徒污国，娥亲定报仇。","容华虽已毁，英爽卒无休。"]},{"t":"赵门二节妇 其三","f":"五言律诗","c":["慷慨穹庐下，抽刀割玉颜。","血含天上日，魂绕汉时关。","凤翼无人托，龙髯有女攀。","月明弹锦瑟，缥缈洞庭还。"]},{"t":"赵门二节妇 其四","f":"五言律诗","c":["激烈箜篌引，千秋怨渡河。","秦城崩欲尽，齐国旱应多。","比翼沉青鸟，同心折玉荷。","冯夷如见念，当为斩鼋鼍。"]},{"t":"赵门二节妇 其五","f":"五言律诗","c":["无端河伯怒，秋水决丘岑。","不见黄龙负，徒劳白马沉。","提壶公竟渡，衔石妾何任。","终古烟波上，彭咸知此心。"]},{"t":"周烈妇","f":"五言律诗","c":["鬒发斩如云，黄泉下殉君。","尚馀鸾凤啸，堪扫虎狼群。","肉酪谁能饮，芦笳不可闻。","何当种连理，为尔作高坟。"]},{"t":"李烈妇","f":"五言律诗","c":["皎皎良家子，乌桓不可求。","月沉精卫海，花堕懊侬楼。","阿母嗟无养，良人惧不仇。","肯辞麻枲贱，去带绮罗羞。"]},{"t":"李六烈妇 其一","f":"五言律诗","c":["小姑弹宝瑟，大姊织流黄。","独立朝霞里，双流白日光。","何曾窥宋玉，不肯作王嫱。","一代红颜尽，高楼恨未央。"]},{"t":"李六烈妇 其二","f":"五言律诗","c":["双燕归何处，楼台久不春。","云疑飞髻女，月是弄珠人。","玉佩捐湘浦，罗衣绝塞尘。","琵琶弹马上，嗟彼去和亲。"]},{"t":"许二烈女 其一","f":"五言律诗","c":["双雏随阿母，游戏在芝田。","正鼓湘灵瑟，俄惊老上弦。","银瓶齐坠井，玉镜不当天。","百尺寒浆里，连枝产白莲。"]},{"t":"许二烈女 其二","f":"五言律诗","c":["雉子斑斑好，同栖春陇傍。","一朝矜意气，双翼碎文章。","蔡琰何能侠，明妃实不祥。","可怜龙塞去，眉黛拂秋霜。"]},{"t":"吊莫节妇 其一","f":"五言律诗","c":["螓首丘山重，蛾眉日月光。","帘帷生不捲，巾帨死犹防。","切玉刀方利，焚兰火亦香。","花门天所命，使尔烈名扬。"]},{"t":"吊莫节妇 其二","f":"五言律诗","c":["汉将投戈遁，蕃兵喋血游。","一丝孀妇命，九鼎美人头。","但使乌鸢食，无为犬马求。","恭姜多苦节，与尔共千秋。"]},{"t":"何烈妇","f":"五言律诗","c":["贱妾难衔石，狂夫竟渡河。","哭声沉白日，孀影逐清波。","蒲苇依盘石，鸳鸯别绣窠。","当知天帝悯，以尔属湘娥。"]},{"t":"送别祺公先生 其一","f":"五言律诗","c":["父老讴歌惜，关河节钺无。","安危谁可寄，出处道同孤。","露冷边庭草，霜啼宪府乌。","自今公宴罢，文采尽穷途。"]},{"t":"送别祺公先生 其二","f":"五言律诗","c":["七路关山险，藩侯清啸边。","翠屏开大漠，丹嶂夹高天。","一腋狐裘助，三杯剑术传。","同心兔丝草，岁晚更缠绵。"]},{"t":"送别祺公先生 其三","f":"五言律诗","c":["滹沱呜咽水，双泪共东流。","蒲苇依盘石，云霞媚素秋。","干人因老母，越礼愧诸侯。","君独容狂简，图书慰远游。"]},{"t":"送别祺公先生 其四","f":"五言律诗","c":["拔剑凉风出，雌雄傍尔飞。","灵含爱子魄，光助霸王威。","一日悲歌合，平生游侠非。","殷勤解相赠，凭此报恩晖。"]},{"t":"送别祺公先生 其五","f":"五言律诗","c":["秋来离别尽，知己更情伤。","感激因屠钓，飘零为稻粱。","园葵犹待日，朔雁已违霜。","明岁重开府，招寻定不忘。"]},{"t":"愁","f":"五言律诗","c":["养生苦不早，四十更情深。","亲在宁言老，愁多欲废吟。","天长迷朔雁，月冷急秋砧。","泪向他乡尽，将归更满襟。"]},{"t":"送天生 其一","f":"五言律诗","c":["万里求知己，从君旅雁门。","佳期那再得，歧路竟何言。","高尚难为客，屠沽易感恩。","相思若春草，处处逐王孙。"]},{"t":"送天生 其二","f":"五言律诗","c":["白云来市井，为母一吹箫。","马度关山险，帆归涨海遥。","壶浆渔父与，玉佩美人要。","羡尔南陔去，春风兰杜饶。"]},{"t":"送天生 其三","f":"五言律诗","c":["不断丹青树，终南地络阴。","道随春草长，人与白云深。","麋鹿鸣相召，羲皇梦可寻。","时时望黄鹄，一寄岁寒心。"]},{"t":"别田约生 其一","f":"五言律诗","c":["凄凄秋夜月，万古玉关愁。","云汉随天转，霜华逐水流。","高堂悬海岳，绝塞托旃裘。","又别同怀子，骊歌欲白头。"]},{"t":"别田约生 其二","f":"五言律诗","c":["慷慨风人度，飞文鞍马边。","羽声悲不止，剑击气无前。","别绪萦春草，离心逐玉鞭。","河梁频执手，日暮两凄然。"]},{"t":"别田约生 其三","f":"五言律诗","c":["君家近漆沮，垂钓日多鱼。","汤沐先王旧，杯捲孝子馀。","儿童催白发，君父托遗书。","早晚还桑梓，萧然赋乐居。"]},{"t":"忻口","f":"五言律诗","c":["忻口孤城在，横当晋上游。","上包宁武戍，河绕秀容楼。","设伏宜天险，防边及早秋。","太原此门户，诸将莫轻裘。"]},{"t":"军中","f":"五言律诗","c":["白日消毬猎，军中一事无。","花骢盘雨雪，塞女泻酡酥。","人向黄云老，春将白草苏。","平生王霸略，尽与酒家胡。"]},{"t":"赠内","f":"五言律诗","c":["接舆既高洁，妻子亦冰清。","白首堪偕隐，青山不用名。","依人愁雁塞，将母忆羊城。","万里车同挽，明当故国行。"]},{"t":"别倪生","f":"五言律诗","c":["乱离为客早，与尔一浮云。","母在身难许，年衰道未闻。","离筵临广武，歧路指横汾。","努力还桑梓，天南有雁群。"]},{"t":"马陵","f":"五言律诗","c":["俯挹中州尽，河山表里来。","天悬句注险，水划孟门开。","一笑雄图失，长歌故国回。","遥从狐突庙，直下马陵台。"]},{"t":"白发","f":"五言律诗","c":["白发羞明镜，青春老异乡。","醉过边草绿，梦怯海天长。","音信乖鸿雁，庭闱傍战场。","寒衣谁与授，凄绝玉门霜。"]},{"t":"冬夜宴赵将军宅","f":"五言律诗","c":["胭脂边女艳，雨雪地炉红。","小队银筝合，深情玉盏通。","歌长愁落月，发白愧惊鸿。","明日城西猎，还将舞袖同。"]},{"t":"偏头关作","f":"五言律诗","c":["往议搜河套，谁令飞渡频。","三关元犄角，诸将故逡巡。","市口黄云满，岢岚白草新。","降羌休弄管，流泪有征人。"]},{"t":"席上赋得梅花为陈正子寿 其一","f":"五言律诗","c":["雁门长至候，春色早惊梅。","解渴如琼树，冲寒向玉杯。","舞迎流雪态，歌倚掞天才。","橘柚无华实，须君羽翼来。"]},{"t":"席上赋得梅花为陈正子寿 其二","f":"五言律诗","c":["一夕花光动，三春草昧开。","美人未迟暮，羌笛莫徘徊。","蓟北飞香去，江南却月来。","枝高难出手，留照岁寒杯。"]},{"t":"别锡鬯","f":"五言律诗","c":["日落黄花晚，风高白雁秋。","三关无鼓角，万里尽旃裘。","歌管年华送，文章霸气收。","相将游猎好，无奈隔云州。"]},{"t":"边思","f":"五言律诗","c":["他乡琼树老，故国翠蛾颦。","最是闺中月，能销塞上人。","轻生随一剑，惜别向三春。","戎马平生志，如何怨苦辛。"]},{"t":"过夷门","f":"五言律诗","c":["侯嬴年七十，方报信陵恩。","意气繇来重，功名非所论。","驱车过梁苑，酾酒吊夷门。","今日屠沽客，谁为公子言。"]},{"t":"答毛子霞 其一","f":"五言律诗","c":["岂意秋蓬转，重逢在晋阳。","解忧如玉树，含垢亦龙章。","乌鹊虚惊月，芙蓉不拒霜。","相看疑梦寐，高咏慰参商。"]},{"t":"答毛子霞 其二","f":"五言律诗","c":["离亭愁执手，嘉会不崇朝。","假食歌声苦，从军塞路遥。","文章沉白草，膂力尽秋雕。","三奏金笳罢，胡骢惨不骄。"]},{"t":"扬州感旧","f":"五言律诗","c":["往日芜城困，君臣总不知。","频飞丞相疏，不遣靖南师。","蓟北天崩后，江南穴斗时。","血书三四纸，读罢泪如丝。"]},{"t":"梅花岭吊史相国墓","f":"五言律诗","c":["往者江南北，谁分上相忧。","自从开四镇，不复问中州。","精爽凭飞将，衣冠在古丘。","梅花春不发，碧血满枝头。"]},{"t":"通州望海","f":"五言律诗","c":["狼山秋草满，鱼海暮云黄。","日月相吞吐，乾坤自混茫。","乘槎无汉使，鞭石有秦皇。","万里扶桑客，何时返故乡。"]},{"t":"呈周栎园 其一","f":"五言律诗","c":["平生五岳游，今上谢公楼。","楼里多山水，空濛云气流。","故乡在南海，夫子有罗浮。","置我丹青上，芙蓉四百秋。"]},{"t":"呈周栎园 其二","f":"五言律诗","c":["泰华双毛女，秦时一丈夫。","相逢白云际，共结合欢襦。","予亦同妻子，鸳鸯玉井俱。","高堂隔梅峤，归去为亲娱。"]},{"t":"呈周栎园 其三","f":"五言律诗","c":["皎皎白华姿，公为处子师。","补亡同束皙，教我在笙诗。","将母愁无计，干人已后时。","乌啼空自苦，日夕白门枝。"]},{"t":"赠文及先丈","f":"五言律诗","c":["往日商山皓，相知有子房。","英雄如女子，高尚亦君王。","今代无芝草，此翁惟羽觞。","行年过八十，亦足傲淮阳。"]},{"t":"寄姚六","f":"五言律诗","c":["昔向三关去，今从五岳归。","红颜辞子女，白首见庭闱。","任侠成何事，游仙亦觉非。","岁寒行役苦，将子念无衣。"]},{"t":"赠余鸿","f":"五言律诗","c":["岁寒雁门雁，来及江南春。","向尔池塘里，双双栖白蘋。","高堂在南海，少妇自西秦。","万里宁亲去，从君一问津。"]},{"t":"答陆冰修 其一","f":"五言律诗","c":["五岳初求道，高堂两鬓霜。","自从居市井，不敢薄词章。","翡翠空毛羽，云霞自混茫。","夫君一知己，感激未能忘。"]},{"t":"答陆冰修 其二","f":"五言律诗","c":["尔爱沉香浦，苍茫多夕晖。","蚌含明月出，鹏负碧天飞。","欲访难移棹，临分重揽衣。","白沙栖隐处，吾自玩芳菲。"]},{"t":"答钟广汉","f":"五言律诗","c":["梁鸾颂高士，最爱采芝翁。","一出安鸿鹄，还栖林屋东。","子孙洞庭口，耕作上皇风。","我亦能遗世，年年桂树丛。"]},{"t":"送王汾仲还新安因访石埭姚明府 其一","f":"五言律诗","c":["白云归白岳，道过陵阳峰。","为我期仙令，何时驾白龙。","愁随一片月，挂在九华松。","早晚思携手，冶城春酒浓。"]},{"t":"送王汾仲还新安因访石埭姚明府 其二","f":"五言律诗","c":["相思似春水，一路送渔舟。","自此临流别，湖名非莫愁。","庭闱君自恋，京雒我空游。","珍重南陔去，崇兰正可求。"]},{"t":"题龚柴丈园 其一","f":"五言律诗","c":["频年远游去，鸾鹤恨无群。","采药难供母，逢山便忆君。","平生无素业，万里一浮云。","爱尔丘园好，徘徊至夕曛。"]},{"t":"题龚柴丈园 其二","f":"五言律诗","c":["清凉山翠滴，花药绕閒居。","半亩松杉外，一春雨雪馀。","人传高士颂，地接远公卢。","迟我为沮溺，相将此荷锄。"]},{"t":"白纻曲","f":"五言律诗","c":["翠幌开春夜，琼楼敞碧天。","美人似明月，飞过彩霞边。","举袖当花客，扬歌应凤弦。","芳心君不见，徒为拾珠钿。"]},{"t":"望天都峰","f":"五言律诗","c":["缥缈丹台上，轩辕拥二仙。","玉壶甘露泻，珠盖彩霞悬。","日月生黄海，笙歌满碧天。","龙髯攀莫及，怅望泪潸然。"]},{"t":"五人墓作","f":"五言律诗","c":["吴风多好剑，轻死自当时。","以有要离子，长为烈士师。","恩仇无不报，市井亦何知。","慷慨五人者，英名复在兹。"]},{"t":"胥口逢梅里诸子","f":"五言律诗","c":["一出太湖口，芙蓉万叠斜。","飞来天外翠，散作镜中霞。","之子梅溪至，相逢渔父家。","包山有禅客，招手人寒花。"]},{"t":"题翁子东洞庭山馆","f":"五言律诗","c":["东西两洞庭，吾爱莫釐青。","往日鸱夷子，回舟此翠屏。","君今胥母住，门对太湖扃。","旦夕怀仙意，长歌入杳冥。"]},{"t":"从洞庭还柬瞿止","f":"五言律诗","c":["芙蓉青翠里，昨谒洞庭君。","玉柱开天阙，龙威导白云。","灵书人外读，仙乐夜深闻。","明共扁舟去，还寻鸾鹤群。"]},{"t":"姑苏秋夕与余丈广霞坐京兆杜子寓楼","f":"五言律诗","c":["嗟尔姑苏客，萧然含暮愁。","相思二华月，独立五湖秋。","吴俗轻高节，秦风急好仇。","今宵共樽酒，感激典貂裘。"]},{"t":"春湖曲","f":"五言律诗","c":["士女春游早，梅花折满船。","飞来玄墓雪，香散太湖天。","渔父歌明月，夷光出紫烟。","鸳鸯谁似汝，长在浣纱边。"]},{"t":"消夏湾","f":"五言律诗","c":["吴王消夏处，玉沼太湖通。","万古芙蓉发，西施在镜中。","白云迷故国，春草失离宫。","一对鸳鸯鸟，时来戏碧空。"]},{"t":"木渎","f":"五言律诗","c":["漭漭五湖口，荷花远接天。","巴陵通地道，林屋隐人烟。","楼阁波涛里，帆樯空翠边。","名峰七十二，争向镜中妍。"]},{"t":"范蠡宅作","f":"五言律诗","c":["羡尔浮西子，扁舟湖海间。","芙蓉三万树，种满洞庭山。","石上留香屧，烟中有翠鬟。","狂吟水仙曲，惊起一双鹇。"]},{"t":"正气祠作","f":"五言律诗","c":["元老忠贞竭，中朝历数屯。","十年荒社稷，一夜尽君臣。","野月寒难曙，江花惨不春。","精魂应杀贼，莫但作星辰。"]},{"t":"钱塘观潮 其一","f":"五言律诗","c":["子胥乘白马，天上涌潮来。","雷破江门出，风吹地轴回。","孤舟凌喷薄，长笛引凄哀。","欲作枚乘赋，先挥张翰杯。"]},{"t":"钱塘观潮 其二","f":"五言律诗","c":["千里江潮势，奔腾禹穴前。","蛟龙争水国，雷雨战空天。","长剑中流拔，孤帆落日悬。","谁言天堑险，飞渡有苻坚。"]},{"t":"韬光寺楼晓望","f":"五言律诗","c":["朝来凭阁望，峰顶大江浮。","日出天鸡口，潮飞澥蜃楼。","苍苍会稽树，渺渺富春洲。","不见同怀子，相思万壑秋。"]},{"t":"子陵祠下夜坐","f":"五言律诗","c":["万里秋云尽，天空只客星。","光含明月冷，影人绛河冥。","双瀑为长带，千峰是翠屏。","临风一舒啸，冉冉下仙灵。"]},{"t":"题许剑亭","f":"五言律诗","c":["一剑君谁许，燕中就义人。","剖心悬日月，披发上星辰。","故国浮云暝，荒亭古木春。","嗟予犹隐忍，何以报三仁。"]},{"t":"寄桐岑子","f":"五言律诗","c":["雨雪悲年暮，山川爱浙东。","平生一明月，飞入镜湖中。","白拂悬天柱，青琴响碧空。","期君扬帆至，相接有樵风。"]},{"t":"禹庙","f":"五言律诗","c":["龙蛇盘禹穴，窈窕万峰连。","玉简藏何处，梅梁失几年。","双圭开日月，九鼎奠山川。","终古思明德，讴歌俎豆前。"]},{"t":"寄王丈予安","f":"五言律诗","c":["闻君在天目，服食黄精花。","玉乳吸阳窦，花龛开暮霞。","我怜若耶水，新作钓鱼槎。","日日芙蓉里，看人出浣纱。"]},{"t":"登香炉峰","f":"五言律诗","c":["香炉峰万仞，吾度鹊桥来。","明月随霜簟，天河接玉杯。","花间禹穴出，霞外赤城开。","长啸凌沧海，仙人安在哉。"]},{"t":"经铸浦","f":"五言律诗","c":["当年欧冶子，此地铸龙泉。","一雪君王耻，雌雄飞入渊。","云消天镜出，风起石帆悬。","谁见登临客，高歌忆古贤。"]},{"t":"耶溪夜游","f":"五言律诗","c":["杨柳覆长堤，芙蓉开欲齐。","美人化明月，飞出浣纱溪。","吹笛鸳鸯起，回舟珠斗低。","白云遥送客，直至镜湖西。"]},{"t":"别王于一往雁宕","f":"五言律诗","c":["拂衣西雁荡，濯足大龙湫。","岂敢为高尚，孤云无所求。","芙蓉开太白，瀑布挂飞楼。","君有怀仙曲，因风寄十洲。"]},{"t":"忆天台有寄","f":"五言律诗","c":["石梁横碧天，上有百重泉。","昨梦随明月，同君蹑紫烟。","闻箫桐柏下，拂剑斗牛边。","孤鹤飞何处，回看阻霅川。"]},{"t":"戏赠朱十","f":"五言律诗","c":["君爱耶溪好，扁舟去不归。","荷花天上落，明月镜中飞。","浣女歌新曲，鸳鸯起钓矶。","鸳鸯不可得，弄水湿罗衣。"]},{"t":"奉题方尔止戊申年正月初四日恭谒孝陵感怀诗后","f":"五言律诗","c":["亦有春秋在，书王未敢传。","可怜正月泪，重洒戊申年。","白发陪宫使，青山拂御筵。","威灵空想像，拜手玉衣前。"]},{"t":"题朱朗诣遗集 其一","f":"五言律诗","c":["匹夫能慕义，咫尺亦贤豪。","天地存沟壑，风尘惜羽毛。","家临梅福市，门对伍胥涛。","哀怨平生曲，行将续楚骚。"]},{"t":"题朱朗诣遗集 其二","f":"五言律诗","c":["千金破家产，四世受朝恩。","草野羞亡命，沙场誓丧元。","悲歌留乐府，歧路失王孙。","阴雨空山夕，期君入梦魂。"]},{"t":"顾云美六十 其一","f":"五言律诗","c":["寂寞松风寝，先皇御翰留。","心飞天寿月，泪尽海棠秋。","故国谁高卧，斯人更远游。","乱离过六十，知己在沧洲。"]},{"t":"顾云美六十 其二","f":"五言律诗","c":["汝婿忠臣子，初生端水时。","两宫犀带赐，三岁羽林儿。","丧乱孤谁托，艰贞尔独知。","遗民今日少，珍重鬓如丝。"]},{"t":"中宿峡","f":"五言律诗","c":["天上猿千树，声含秋雨哀。","二禺峰窈窕，三峡水潆洄。","帝子吹箫去，仙人采竹来。","夕阳烟翠满，愁见望夫台。"]},{"t":"从大小鸬鹚诸滩上郴州题莲子精舍","f":"五言律诗","c":["山水频开阖，仙源不可寻。","水帘飞四壁，花雨散双林。","猿鸟声相乱，蛟龙气自深。","扁舟今已矣，渔父最知音。"]},{"t":"赣州 其一","f":"五言律诗","c":["日落虎头城，风飘龙角声。","天威馀细柳，地利失阴平。","盗贼纷何在，英雄凛若生。","襄皇能养士，沟壑荷恩深。"]},{"t":"赣州 其二","f":"五言律诗","c":["义士魂何去，沙场一放招。","黄衣归朔漠，碧血满南朝。","山枕孤城峻，江通百粤遥。","天生形胜地，空助虎狼骄。"]},{"t":"风门山","f":"五言律诗","c":["壁立青天上，千峰接祝融。","风门人不度，石栈马才通。","射虎随蛮俗，椎牛会小戎。","平生军旅事，辛苦桂阳东。"]},{"t":"八尺洪","f":"五言律诗","c":["春来滩水急，喷壑万松间。","风雨时驱石，雷霆忽破山。","柳深黄鸟乱，花落白猿閒。","渐至苏耽岭，寻仙拟不还。"]},{"t":"耒阳观诸葛武侯碑","f":"五言律诗","c":["武侯擒孟获，刻石耒阳川。","威震华夷日，心劳将相年。","三分留正统，二表格皇天。","终古英雄客，看碑泪泫然。"]},{"t":"郴江口","f":"五言律诗","c":["惊涛出江口，一片雪山飞。","舟与雷霆斗，人为鱼鳖归。","偷生惭有剑，卒岁叹无衣。","历尽人间险，吾今解息机。"]},{"t":"南岳 其一","f":"五言律诗","c":["峰绕祝融尊，湖湘映岳门。","香炉云梦气，瀑布洞庭源。","雨霁分秋色，林开见晓暾。","青苍一千里，望似阵云屯。"]},{"t":"南岳 其二","f":"五言律诗","c":["伊昔洪荒世，衡山佐禹功。","巨灵分一掌，明德继重瞳。","岣嵝悬神碣，莲花落古宫。","千秋金简气，龙虎郁无穷。"]},{"t":"南岳 其三","f":"五言律诗","c":["烈气流珠海，真形隐玉壶。","云霞相变化，日月自虚无。","紫盖削千仞，朱天开一隅。","飘飘鸾鹤上，高揖列仙儒。"]},{"t":"南岳 其四","f":"五言律诗","c":["山随湘水长，转转向清湘。","九面芙蓉翠，中天紫盖张。","峰峰朝赤帝，树树带衡阳。","万古香炉气，氤氲桂邸旁。"]},{"t":"岳庙 其一","f":"五言律诗","c":["肃肃朱陵庙，怀柔忆我皇。","乾坤归火德，日月起南方。","秩礼遵虞典，斋心启夏王。","千秋巡狩迹，想像辟鸿荒。"]},{"t":"岳庙 其二","f":"五言律诗","c":["先皇钟鼓在，肃穆百神朝。","凤管流清殿，霓旌捲碧霄。","坤舆虽北陷，天柱尚南标。","维岳司休命，无疆钖帝尧。"]},{"t":"贾太傅故宅","f":"五言律诗","c":["长沙南纪外，迁客九疑边。","皇帝虚前席，书生实少年。","岳云高冠日，湘水远连天。","故宅馀春车，行人重怆然。"]},{"t":"题招屈亭","f":"五言律诗","c":["楚人端午日，招屈向湘沅。","河伯空交手，巫阳不予魂。","蛟龙侵水屋，风雨蔽天门。","掩泣纷歌舞，思君不可谖。"]},{"t":"夜憩江楼","f":"五言律诗","c":["八月潇湘客，三更乌鹊楼。","天随珠斗转，雪抱玉盘流。","远望惟京阙，相思若女牛。","同心栀子苦，欲寄隔炎洲。"]},{"t":"浮湘 其一","f":"五言律诗","c":["五年游五岳，三度下三湘。","今夕衡阳宿，依然风露凉。","钟愁回雁落，歌爱采菱长。","木叶萧萧下，如何客异乡。"]},{"t":"浮湘 其二","f":"五言律诗","c":["湘水清且浅，粼粼白石分。","青浮南岳影，红摺暮天纹。","九面芙蓉绕，中流兰杜薰。","溪边渔父好，竟夕棹歌闻。"]},{"t":"浮湘 其三","f":"五言律诗","c":["不断湘江岸，青青兰竹丛。","泪痕光晓露，哀响乱秋风。","岳与千帆转，天归一镜空。","明朝洞庭上，萧瑟对丹枫。"]},{"t":"浮湘 其四","f":"五言律诗","c":["水凉朝有气，日出渐成烟。","林寂鸟多语，山深人亦田。","岳痕青出岸，波影绿摇天。","清绝湖南地，浮湘自可怜。"]},{"t":"浮湘 其五","f":"五言律诗","c":["帆投渔火宿，浦口暮烟迷。","催客虫声乱，依人鸟影齐。","林穿黄月细，花压碧天低。","疏磬知何处，茅茨隔一溪。"]},{"t":"浮湘 其六","f":"五言律诗","c":["岳云青不断，湘水与之长。","湘至湘阴尽，沿洄殊未央。","鹧鸪催客起，斑竹拂船凉。","山髻时明灭，林烟一带苍。"]},{"t":"浮湘 其七","f":"五言律诗","c":["两日随兰桨，青青紫盖峰。","五峰江倒映，水底尽芙蓉。","苍翠楚天好，微茫湖口重。","洲边采香草，湘女暮相从。"]},{"t":"浮湘 其八","f":"五言律诗","c":["水口皆湘浦，花阴有岳门。","帆低红树罥，舟小白波吞。","戍鼓传双峡，渔灯绕一村。","溪清多漏石，月照更潺湲。"]},{"t":"浮湘 其九","f":"五言律诗","c":["青恐峰峦尽，红愁木叶多。","鱼梁争截水，浣女乱穿荷。","雨气含黄日，霞光激素波。","虚无瑶瑟响，怅望是湘娥。"]},{"t":"浮湘 其十","f":"五言律诗","c":["江至长沙阔，湖将岳麓浮。","茫茫迷五渚，隐隐见双洲。","才子伤卑湿，骚人怨早秋。","熊湘高阁在，欲上写离忧。"]},{"t":"浮湘 其十一","f":"五言律诗","c":["戍亭纤月上，吹角断行舟。","葭菼风多夕，潇湘水易秋。","天开洞庭口，波捲岳阳楼。","帝子此离别，微茫一片愁。"]},{"t":"浮湘 其十二","f":"五言律诗","c":["高高天岳出，雨后白云多。","望与衡山似，愁如秋色何。","人家连碧树，禹迹在寒萝。","忆访莓苔字，年时鼓棹过。"]},{"t":"浮湘 其十三","f":"五言律诗","c":["水清鱼不少，一路有罾塘。","山映涟漪绿，日含烟雨黄。","人为今屈子，地是古中湘。","兰芷亦青草，如何独有芳。"]},{"t":"浮湘 其十四","f":"五言律诗","c":["石浅水流难，舟人苦叫滩。","水萤当昼乱，山鸟及秋寒。","故国烽烟隔，他乡岁月残。","闺中寄霜叶，点点泪痕丹。"]},{"t":"浮湘 其十五","f":"五言律诗","c":["三闾憔悴日，自作大招辞。","万古哀时命，遗声在本支。","美人殊未作，宗国已频移。","谁忍为渔父，烟波任所之。"]},{"t":"南岳顶观日","f":"五言律诗","c":["中宵登岳望，阊阖赤霞边。","光采频迎日，空濛不见天。","苍梧龙驭失，紫盖凤楼迁。","万古湘累泪，东皇太乙前。"]},{"t":"拜三闾大夫墓","f":"五言律诗","c":["三闾蝉蜕后，玉佩葬湘川。","披发重华侧，扬灵太乙前。","墓田滋杜若，宗国委寒烟。","词赋开苗裔，千秋哀怨传。"]},{"t":"长沙","f":"五言律诗","c":["熊绎开南楚，长沙应小星。","城临湘水碧，苑接岳山青。","帝子留笙鹤，娥皇隔洞庭。","徘徊秋月夜，玉殿见流萤。"]},{"t":"汉阳除夕和伍子","f":"五言律诗","c":["汉阳江上客，寂寞度残年。","晞发无朝日，沉身有太川。","独醒渔父笑，同病大夫怜。","此夕逢除夕，清樽涕泪边。"]},{"t":"湖中有怀 其一","f":"五言律诗","c":["江从湖口阔，浩淼浸长沙。","天外青惟水，空中白是花。","乱鸿惊岳市，疏柳落渔家。","寂寂推篷坐，相思为月华。"]},{"t":"湖中有怀 其二","f":"五言律诗","c":["月出水天分，微茫不见云。","芦花千万里，如雪落纷纷。","似我愁心乱，风吹不到君。","更怜洞庭雁，栖宿暮无群。"]},{"t":"出湖作 其一","f":"五言律诗","c":["澧注湘川左，湖开汇口西。","天从南楚尽，岳至洞庭低。","波捲青山去，云含白雁嘶。","二妃时出入，风雨冷凄凄。"]},{"t":"出湖作 其二","f":"五言律诗","c":["向夕从湖汉，东浮发棹歌。","雪将春水满，花与白云多。","五渚连青嶂，三湘间绿莎。","君山何处是，欲往阻风波。"]},{"t":"次沅江作","f":"五言律诗","c":["西从桥口入，一水最潆回。","自过沅江县，微茫湖欲来。","不知青草外，可有碧天开。","月落帆须宿，津人且莫催。"]},{"t":"自排山经熊罴岭至祁阳作","f":"五言律诗","c":["百里藤萝路，阴森万木中。","山寒多宿雨，叶尽少悲风。","岭峤千盘入，湖湘一线通。","楚南香草地，处处见兰丛。"]},{"t":"自零陵至兴安道中","f":"五言律诗","c":["苍松三百里，不尽复枫林。","一路白云暗，千峰红叶深。","山空自多响，水落亦成吟。","薄暮停车坐，萧萧馀片心。"]},{"t":"零陵道中晓行 其一","f":"五言律诗","c":["啼鸟晓纷纷，人烟乱白云。","江声双浦合，山色九峰分。","斑竹枝枝泪，重瞳处处坟。","苍梧秋雨暗，咫尺阻湘君。"]},{"t":"零陵道中晓行 其二","f":"五言律诗","c":["试上蒲洲望，峰峰列翠屏。","潇从湘口合，陵是九疑零。","柳映长桥绿，松浮远岸青。","暮投何处宿，灯火起官亭。"]},{"t":"全州道中","f":"五言律诗","c":["五日松林引，三朝谷口迷。","孤村阴雨外，古道白云西。","风定分泉响，山深少鸟啼。","故乡不可望，千里草萋萋。"]},{"t":"灵渠","f":"五言律诗","c":["开陡船争上，灵渠水满时。","穿来自秦汉，流出注湘漓。","片雨添三尺，千峰绕一丝。","相思如此水，南北不相知。"]},{"t":"灵川道中眺望建陵诸峰","f":"五言律诗","c":["横斜千万笋，不似一峰峰。","苍润含秋雨，巉岩出古松。","孤根争自立，落势不相从。","百里烟云外，漓江绕几重。"]},{"t":"虞山望虞帝祠","f":"五言律诗","c":["云气尝如象，盘旋玉殿间。","匏笙祠二帝，铜鼓镇诸蛮。","地接苍梧近，林多古竹斑。","千秋骚些客，怅望是天颜。"]},{"t":"建陵秋望","f":"五言律诗","c":["日暖翠微浓，山包桂水重。","楼台悬一笋，井邑散诸峰。","肃杀流东极，玄黄战大冬。","疮痍新满路，不忍视军容。"]},{"t":"野宿荔浦作","f":"五言律诗","c":["夜宿帐房小，天寒多野风。","卧看珠斗落，吟使绿尊空。","欲战愁兵少，将归望路通。","故乡怜有母，辛苦忆军中。"]},{"t":"宿平南县村中作","f":"五言律诗","c":["野宿寒依火，高栏在翠微。","山霞晴已吐，水雾湿犹飞。","地广夷樵少，村荒士马饥。","无金市牛酒，怅望射生归。"]},{"t":"夜上横州作","f":"五言律诗","c":["夜分催荡桨，乘月上横州。","烟雾含渔火，星河挂戍楼。","身忘银甲重，手得角弓柔。","不寐思军事，疏钟起渡头。"]},{"t":"自五屯所至永安州舟中作 其一","f":"五言律诗","c":["冬木寒逾秀，苍苍雪霁时。","风开多柳叶，冰压少松枝。","水积春前气，山添雨后姿。","新晴人就暖，解带步迟迟。"]},{"t":"自五屯所至永安州舟中作 其二","f":"五言律诗","c":["落木寒泉路，朝烟暮雨人。","乡山归不得，母子梦相亲。","石乱初无口，滩平渐有身。","篙师愁欲绝，此水最艰辛。"]},{"t":"自五屯所至永安州舟中作 其三","f":"五言律诗","c":["水打村村碓，风烧岸岸田。","鸟声时出谷，云气忽沉天。","路尽无烟处，人寒欲雪前。","岁残无一可，兵马苦颠连。"]},{"t":"自五屯所至永安州舟中作 其四","f":"五言律诗","c":["天寒生白雾，日出见平原。","卧入千峰雪，吟随万壑猿。","一身家国重，七尺死生尊。","安得功成去，丘中复闭门。"]},{"t":"自五屯所至永安州舟中作 其五","f":"五言律诗","c":["叶落知枫树，千林冬不黄。","松晴初出雪，梅早已浮香。","事共年华去，愁随春水长。","兼旬未窥镜，白发恐如霜。"]},{"t":"宿高田","f":"五言律诗","c":["夜久林风息，溪声静欲无。","流萤知客冷，宿鸟似人孤。","拂石难为卧，鸣琴亦自娱。","高楼怜有女，此夕听啼乌。"]},{"t":"自滑山至骆家道中","f":"五言律诗","c":["平田千石笋，一笋一人家。","荫壁全生竹，流溪半是花。","山山通乳窦，树树有渔槎。","匹马行将晚，前村隔暮霞。"]},{"t":"阳朔","f":"五言律诗","c":["城里奇峰满，人烟在石林。","家家为虎落，户户有猿吟。","水脱诸滩浅，江通一井深。","客舟纷向驿，月出奏箫音。"]},{"t":"生日同诸将郊行作","f":"五言律诗","c":["细蹀花骢出，麾幢拂晓云。","葛巾汉名士，毛扇蜀将军。","节制凭儒术，忠诚致大勋。","自矜年四十，于道亦曾闻。"]},{"t":"昭江夜行作","f":"五言律诗","c":["江天寒色惨，初月不成黄。","未夕已生雾，将春始有霜。","无能酬父老，不敢忆家乡。","终岁劳军事，徒令白发长。"]},{"t":"阳朔道中","f":"五言律诗","c":["半天青是石，石出辄成峰。","一路平田上，参差间古松。","人声喧野水，鸟影下寒钟。","径口迎车马，欢然有老农。"]},{"t":"暇日出癸水门眺望 其一","f":"五言律诗","c":["雌雄双石笋，竞秀出城中。","一洞峰峰入，千泉树树通。","水花纷似雾，山响不因风。","胜日幽探去，无人识玉骢。"]},{"t":"暇日出癸水门眺望 其二","f":"五言律诗","c":["苍苍一片石，削出万峰青。","插水皆浮玉，围天是翠屏。","人随飞瀑下，心与白云冥。","稍待麇麚入，岩扉雨不扃。"]},{"t":"风洞寺晚眺 其一","f":"五言律诗","c":["水冷多秋雨，山寒少暮霞。","馀霜犹在叶，初雪未成花。","寺与飞崖落，城随叠嶂斜。","寂寥无物虑，相伴有林鸦。"]},{"t":"风洞寺晚眺 其二","f":"五言律诗","c":["一洞穿山背，逶迤不可寻。","交垂千尺乳，乱落百泉音。","黄叶静方脱，碧潭寒更深。","暮风吹浙沥，猿鸟亦惊心。"]},{"t":"岁暮客建陵作 其一","f":"五言律诗","c":["岁寒何所有，一片白头霜。","共是无衣客，偏知此夜长。","数奇惭部曲，金尽失肝肠。","岂必成功业，归来策亦良。"]},{"t":"岁暮客建陵作 其二","f":"五言律诗","c":["一壁横天尽，千峰压水斜。","飞楼在乔木，倒影满平沙。","叶落偏惊客，莺啼正忆家。","纷纷帘幕外，风雪自成花。"]},{"t":"岁暮客建陵作 其三","f":"五言律诗","c":["朔雪初兼雨，南风已合冰。","穷阴千里积，杀气一冬凝。","水冻难张罟，天寒可放鹰。","梅花何处有，采采兴堪乘。"]},{"t":"岁暮客建陵作 其四","f":"五言律诗","c":["冰雪融将尽，春人已袷衣。","鱼吹新水出，鸟拂落花飞。","驿路枫林引，人家石壁围。","羔裘持易酒，日暮醉忘归。"]},{"t":"赠别查韬荒 其一","f":"五言律诗","c":["海岳多精液，生君俊异才。","文从六经出，学自二人来。","白首天犹困，狂歌日已哀。","艰难相羽翼，岁晏且樽罍。"]},{"t":"赠别查韬荒 其二","f":"五言律诗","c":["汝昨云南去，昆明涉倒流。","滇王惊大笔，汉将赠轻裘。","兵法儿曾学，权书父所留。","莫徒工草檄，厮养已封侯。"]},{"t":"赠别查韬荒 其三","f":"五言律诗","c":["膏物吴江足，文禽越峤多。","羽毛君不妒，音响自相和。","海气朝成市，潮田暮涌波。","亦知奇道否，郁水接牂柯。"]},{"t":"赠别查韬荒 其四","f":"五言律诗","c":["莞香多血结，端砚有花痕。","相赠无馀物，相知祗二言。","才高偏下俗，气侠不惭恩。","沉湎谁能似，生涯在绿樽。"]},{"t":"赠别查韬荒 其五","f":"五言律诗","c":["去踏梅花岭，斑骓似陆郎。","无才除左纛，不敢问金装。","赣石诸滩险，浔江九派长。","舟中如有作，一一记炎方。"]},{"t":"赠别查韬荒 其六","f":"五言律诗","c":["山枝工蜜渍，水熟解兰薰。","归赠楼中妇，香应日夕闻。","书从闺阁著，情以友朋分。","时作熊经好，遵生贵在勤。"]},{"t":"赠别查韬荒 其七","f":"五言律诗","c":["弹筝纤手子，送尔曲难终。","斫鲙鲥鱼白，调齑豆蔻红。","道成方好色，才在不知穷。","金石期相保，千秋业在躬。"]},{"t":"赠别查韬荒 其八","f":"五言律诗","c":["越草多灵药，蛮花半大丹。","神仙宁有种，服食不曾难。","葛令遗书古，浮丘静夜寒。","留君偏未得，涕泪落江干。"]},{"t":"赠别查韬荒 其九","f":"五言律诗","c":["岂敢多求友，交君已不孤。","谗言从贝锦，清鉴自冰壶。","菡萏双峰出，云霞一气敷。","繇来不离别，有道在虚无。"]},{"t":"赠吕化州 其一","f":"五言律诗","c":["复阐先公道，为邦孝友馀。","世为臣子鹄，人读使君书。","德感金芝草，恩随白鹿车。","我怀阴雨好，欲向化州居。"]},{"t":"赠吕化州 其二","f":"五言律诗","c":["太傅忠诚在，平生一孝经。","先朝安社稷，后裔重朝廷。","为政劳州牧，书名冠御屏。","拂衣归莫早，公辅待仪型。"]},{"t":"赠吕化州 其三","f":"五言律诗","c":["尚书谁特笔，忠冠烈皇朝。","我有春秋志，公为列传标。","削心遗令子，披发逐神尧。","讨贼文章在，书生未寂寥。"]},{"t":"赠吕化州 其四","f":"五言律诗","c":["经年苦行役，事向石龙回。","为有微言在，频趋太守来。","三川家学大，两世道宗开。","往日芝泉院，还期辟草莱。"]},{"t":"有忆","f":"五言律诗","c":["裙为留仙绉，香缘却死熏。","无情飞入月，有梦去为云。","义甲姬人得，遗书弟子分。","当时娇玉步，彷佛屧声闻。"]},{"t":"命子","f":"五言律诗","c":["渊明初命子，安石始教儿。","白发惭闺阁，青云望羽仪。","新篁开雨叶，乳燕拂晴丝。","感念先公德，皇天或我私。"]},{"t":"赵尉台下作","f":"五言律诗","c":["赵尉台前草，空馀狐兔骄。","三年屯朔骑，一月作南朝。","牛黍秋初熟，蝉枝晚未凋。","自怜英霸诺，寂寞在东樵。"]},{"t":"读陈岩野先生政要","f":"五言律诗","c":["往日陈都谏，谋猷信有馀。","初闻哀痛诏，即上治安书。","丞相劳相嫉，君王叹不如。","可怜捐七尺，地下奉銮舆。"]},{"t":"秋郊燕集作","f":"五言律诗","c":["披发空行乞，凄凉去国身。","龙蛇无四海，日月在孤臣。","泪洒秋江满，愁随白草新。","相逢聊取醉，莫作别离人。"]},{"t":"春日喜从弟无极至东莞赋赠 其一","f":"五言律诗","c":["我学老莱子，婆娑膝下时。","弄雏殊未已，采药更何之。","汝自圭峰曲，来寻莞水湄。","林中无所有，祗赠白华枝。"]},{"t":"春日喜从弟无极至东莞赋赠 其二","f":"五言律诗","c":["与子传家学，离骚廿五篇。","楚人元善怨，渔父岂为仙。","以道娱萱草，于春返药田。","紫荆花一树，知为弟兄妍。"]},{"t":"赠郭皋旭 其一","f":"五言律诗","c":["之子当湖彦，风流亦可宗。","豪雄似翁伯，博雅比弘农。","来作花田乐，归期锦石封。","大才应晚达，冠剑且雍容。"]},{"t":"赠郭皋旭 其二","f":"五言律诗","c":["双瞳犹点漆，五十学书年。","老觉黄金贵，愁令彩笔妍。","浮家因范蠡，破产为韩嫣。","携手高凉路，相将咏甫田。"]},{"t":"赠郭皋旭 其三","f":"五言律诗","c":["少小持胎素，行将服海霞。","心珠同皎月，意蕊即丹砂。","合浦探鲛室，罗浮御凤车。","多情如陆贾，爱杀素馨花。"]},{"t":"赠郭皋旭 其四","f":"五言律诗","c":["鹧鸪元越客，茉莉是蛮花。","南翥聊同妾，西飞莫忆家。","蚌生珠子树，龙织海人纱。","自可成豪富，无令金谷誇。"]},{"t":"赠郭皋旭 其五","f":"五言律诗","c":["涨海精华盛，真人沐浴多。","命须红粉绩，吟奈白头何。","素女师宜早，清琴曲贵和。","凤毛行冉冉，宜子是交娥。"]},{"t":"赠郭皋旭 其六","f":"五言律诗","c":["我似青黄橘，须君羽翼来。","蝶生元凤子，螺长即珠胎。","瘴海多珍物，炎天少异才。","无人知宝惜，零落委蒿莱。"]},{"t":"赠郭皋旭 其七","f":"五言律诗","c":["知音君最善，不负此朱弦。","鸾羽吾方铩，蛾眉世不怜。","云炉吸丹气，玉液漱飞泉。","虎豹姿如此，那堪便学仙。"]},{"t":"赠郭皋旭 其八","f":"五言律诗","c":["与君结交早，不忘久要言。","道以文章重，情将骨肉敦。","天心归草莽，世事在丘园。","何以蠲忧疾，兰房更树萱。"]},{"t":"赠谭天水 其一","f":"五言律诗","c":["谭子丹青妙，尤工写宓妃。","凌波纨扇出，拾羽玉屏飞。","昔诵陈王赋，尝嗟丽色希。","兹焉图画里，日日对容辉。"]},{"t":"赠谭天水 其二","f":"五言律诗","c":["尔得惊鸾势，飞毫作隶书。","风云起纤指，妖冶把轻裾。","鲁酒花相映，齐纨雪不如。","兴酣追草圣，日与世情疏。"]},{"t":"寄李将军","f":"五言律诗","c":["三翼雄苍兕，将军有战船。","凭陵南海郡，训练九真天。","白马封侯晚，黄龙负帝先。","伏波原大器，一挫莫颓然。"]},{"t":"浮丘","f":"五言律诗","c":["闻与罗浮岳，朱明一洞通。","石床流水上，丹灶落花中。","时有大蝴蝶，来从四百峰。","惭予学仙久，羽化未凌空。"]},{"t":"郑子画白鸥送予赋以答之","f":"五言律诗","c":["之子赠将归，丹青世所希。","以予为海客，故写白鸥飞。","毛羽亦知惜，稻粱安可依。","沧洲自今别，相忆寄芳菲。"]},{"t":"二石楼下有怀","f":"五言律诗","c":["天边二石楼，水帘不上钩。","玉女窗如月，白云开向秋。","悠悠紫芝唱，处处羽觞流。","不见王孙返，猿声万壑愁。"]},{"t":"寄陆太守 其一","f":"五言律诗","c":["今代怜才者，当湖子大夫。","以予骚圣后，狂简一时无。","奖借多诗笔，追随许酒垆。","报恩惭海客，慷慨泣明珠。"]},{"t":"寄陆太守 其二","f":"五言律诗","c":["谢公为郡日，数上会稽山。","坐啸君无事，丹霞亦往还。","文章奋禅藻，氛祲息台关。","一道飞泉水，无生说未閒。"]},{"t":"别稚女 其一","f":"五言律诗","c":["膝下方娇小，非男亦胜无。","可怜频失乳，未得复将雏。","一月行边上，三龄向海隅。","黄泉有慈母，念尔泪如珠。"]},{"t":"别稚女 其二","f":"五言律诗","c":["自失餔糜妇，家中日益贫。","东门如复出，黄口托何人。","况此桑榆日，尤须菽水身。","此行惟数月，即返莞江滨。"]},{"t":"悔不","f":"五言律诗","c":["悔不从卿死，欢娱向夜台。","空闺形影在，白日梦魂来。","夕鸟惊风叶，秋虫泣露苔。","人间今已矣，何处是蓬莱。"]},{"t":"舍弟刈稻赠以诗","f":"五言律诗","c":["今年风雨好，汝稼满堂阴。","十亩妻孥力，千秋沮溺心。","自兹有鸡黍，可以弄书琴。","求禄胡为者，高堂白发侵。"]},{"t":"兰陔即事 其一","f":"五言律诗","c":["当轩皆古木，绕屋是寒塘。","石笋穿云乱，花须拂水长。","虽然多菡萏，尚未足鸳鸯。","小妓拿舟至，风吹珠翠香。"]},{"t":"兰陔即事 其二","f":"五言律诗","c":["夜宴多银烛，春眠少象床。","近愁碧玉女，不嫁汝南王。","白马穿花去，黄莺入柳藏。","可能端午日，来唱荔枝香。"]},{"t":"兰陔即事 其三","f":"五言律诗","c":["花里藏丘壑，幽深人不知。","水光连碧甲，山势接黄旗。","欲雨云生石，方晴月满枝。","小童呼孔雀，双影暮归迟。"]},{"t":"兰陔即事 其四","f":"五言律诗","c":["行行花路断，桥接水中亭。","山色含烟绿，天光入镜青。","黄公采芝咏，范蠡养鱼经。","父子多高逸，朋来亦客星。"]},{"t":"兰陔即事 其五","f":"五言律诗","c":["杨柳秋含蕊，芙蓉暮敛花。","林声全似雨，海气半成霞。","鸟宿烟村寂，人归石路斜。","月明思一醉，随意向渔家。"]},{"t":"送陈明敬游吴因访秀州诸子 其一","f":"五言律诗","c":["之子三吴去，为予过秀州。","故人尽高卧，空谷可相求。","梅里山多雪，鸳湖水易秋。","几宵魂梦好，随尔木兰舟。"]},{"t":"送陈明敬游吴因访秀州诸子 其二","f":"五言律诗","c":["故人如有问，新住珊瑚洲。","西望江连海，东观罗与浮。","家贫少生计，人静多春愁。","知己日零落，相思空秀州。"]},{"t":"奉赠高士周以濂先生","f":"五言律诗","c":["白发垂霜雪，端居岳麓峰。","客星光隐现，王命论从容。","薇蕨留饥凤，风云待伏龙。","天人多秘策，授我定尧封。"]},{"t":"赠卜者陈生","f":"五言律诗","c":["往日松山战，而翁出汉家。","主恩酬马革，臣节著龙沙。","令子悲流落，炎天度岁华。","将军馀碧血，滴滴在金笳。"]},{"t":"寄龚柴丈","f":"五言律诗","c":["我友惟龚胜，曾同辟谷来。","人间无不可，鸾鹤莫相催。","待奉白头母，兼之浮峤梅。","遥遥向江左，共住清凉台。"]},{"t":"喜陈元孝举第三子","f":"五言律诗","c":["四十惭华发，怀中一子无。","为君频缓带，有妇即生珠。","清庙琳琅器，沙场汗血驹。","先公忠可悯，天意在诸孤。"]},{"t":"合澜洲","f":"五言律诗","c":["合澜洲上望，蜃气雨中多。","潮起三门海，风翻十丈波。","盐田朝放水，沙潬晚收禾。","鱼米兹焉贱，时时鼓棹过。"]},{"t":"端州感怀 其一","f":"五言律诗","c":["地扼东西粤，中丞作镇雄。","崧台曾驻辇，锦石有行宫。","两载偏安业，孤臣再造功。","可怜天运去，仓卒六军空。"]},{"t":"端州感怀 其二","f":"五言律诗","c":["苍梧西咫尺，终古哭重华。","水接牂柯阔，云开石室斜。","天孙频此夕，帝子久无家。","不分浮生苦，飘零信海槎。"]},{"t":"七星岩","f":"五言律诗","c":["玲珑数岩穴，明灭一烟霞。","石乳凝为石，花光散作花。","莓苔多绿字，蝙蝠是丹砂。","散带寻仙迹，行行磴道斜。"]},{"t":"入新兴江路","f":"五言律诗","c":["一水湾环好，扬帆入万峰。","滩声驱乱石，山影落寒松。","青草馀春瘴，疏花隐暮钟。","大风频拔木，知是涧中龙。"]},{"t":"太平驿","f":"五言律诗","c":["树里空城在，藤萝暗女墙。","野烟连水白，樵火满山香。","已产蛮夷地，还投瘴疠乡。","仆夫频见笑，衣食失清狂。"]},{"t":"次观珠塘同郭子作","f":"五言律诗","c":["榕阴行不尽，夹路鹧鸪啼。","树树包青嶂，山山出一溪。","虎过风叶乱，蝉立露枝低。","于役虽云苦，林泉得共携。"]},{"t":"黄泥湾道中","f":"五言律诗","c":["树树藤萝挂，峰峰洞穴通。","人家依石壁，客棹转花宫。","竹密愁无路，松多啸有风。","鸡声莫唱早，乡梦正禺东。"]},{"t":"阳春道中 其一","f":"五言律诗","c":["群松围石笋，一水蔽岩扉。","苍翠含秋色，阴森散夕霏。","采菱人未罢，食稻蟹初肥。","百里云峰路，愁中望欲微。"]},{"t":"阳春道中 其二","f":"五言律诗","c":["孤舟行不得，最恨鹧鸪声。","峡暗三秋雨，林开一日晴。","相思生白发，独往忆青城。","不有神仙术，那消婉娈情。"]},{"t":"阳春道中 其三","f":"五言律诗","c":["朝穿魑魅影，暮入虎狼群。","林木阴多惨，烟岚毒更薰。","野人毛布与，樵女蜜房分。","喜向空山曲，茅茨宿白云。"]},{"t":"阳春道中 其四","f":"五言律诗","c":["芙蕖愁少水，乌鹊恨无枝。","草野原吾分，皇天不我私。","鲍焦垂槁日，桑户返真时。","所恨无甘旨，归为老母怡。"]},{"t":"东安舟中","f":"五言律诗","c":["秋水流何急，鱼梁欲上难。","风雷争一石，烟雨失诸滩。","渡口鸣蝉乱，人家落木寒。","青山千万转，不得见东安。"]},{"t":"福禄咫尺边界停车怅望有作 其一","f":"五言律诗","c":["水族随潮至，居人捕蟹多。","客愁消七箸，乡梦畏关河。","树作长边界，风呜小港波。","萧萧一茅宇，双泪滴蛮歌。"]},{"t":"福禄咫尺边界停车怅望有作 其二","f":"五言律诗","c":["万里干戈路，间关真可怜。","心从天北死，眼向日南穿。","杨仆楼船在，唐蒙策略传。","牂柯春水涨，直至石门边。"]},{"t":"福禄咫尺边界停车怅望有作 其三","f":"五言律诗","c":["未夕茅茨宿，临溪置一床。","海鲜沙白美，山果木威香。","妇子朝成市，牛羊晚入庄。","风前一偃卧，亦足傲羲皇。"]},{"t":"福禄咫尺边界停车怅望有作 其四","f":"五言律诗","c":["雨急不成瀑，林高知有山。","拨花寻径口，攀竹上天关。","儿女穿黎锦，生涯鬻白鹇。","晚来飞騕马，投宿有欢颜。"]},{"t":"福禄咫尺边界停车怅望有作 其五","f":"五言律诗","c":["狼水惟蓬远，徭山是白梅。","妻孥多射猎，虎豹少蒿莱。","风俗歌村好，烟光伏峒开。","乱峰盘鸟道，行客意迟回。"]},{"t":"石城旅店","f":"五言律诗","c":["繇来乌鹊好，绝胜凤凰飞。","野草偏多艳，含花露不晞。","与姑炊午黍，为客组春衣。","皎皎茅茨月，良人樵采归。"]},{"t":"送黄生扶其父丽农隐君榇还吴兴 其一","f":"五言律诗","c":["汝父先朝露，人悲失首丘。","伯鸾频客死，梅福早仙游。","返葬关河杳，招魂弟子愁。","艰难扶衬去，嗟尔孝无俦。"]}]};